export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 20
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  waveform: WaveformType;
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;
  filterCutoff: number; // Hz
  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: number; // Pointer ID
  nodeId: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import { SynthPreset, WaveformType } from '../types';
import { BASE_FREQUENCY } from '../constants';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private dryGain: GainNode | null = null;

  private voices: Map<number, { osc: OscillatorNode; gain: GainNode; filter: BiquadFilterNode; startRatio: number }> = new Map();
  private maxPolyphony: number = 10;
  private activePreset: SynthPreset;

  constructor(preset: SynthPreset) {
    this.activePreset = preset;
  }

  public init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
        latencyHint: 'interactive',
      });

      // Master Gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 1.0; 
      this.masterGain.connect(this.ctx.destination);

      // Reverb Setup
      this.reverbNode = this.ctx.createConvolver();
      this.reverbNode.buffer = this.createImpulseResponse(2.5, 2.0); // 2.5s duration, 2.0 decay

      this.reverbGain = this.ctx.createGain();
      this.reverbGain.gain.value = this.activePreset.reverbMix;

      this.dryGain = this.ctx.createGain();
      this.dryGain.gain.value = 1.0 - this.activePreset.reverbMix;

      // Routing
      // Voice -> Dry -> Master
      this.dryGain.connect(this.masterGain);

      // Voice -> ReverbGain -> Reverb -> Master
      this.reverbGain.connect(this.reverbNode);
      this.reverbNode.connect(this.masterGain);
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    const sampleRate = this.ctx!.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx!.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        // Simple noise decay
        left[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
        right[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
    }
    return impulse;
  }

  public setPolyphony(count: number) {
    this.maxPolyphony = count;
  }

  public setMasterVolume(val: number) {
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(val, this.ctx.currentTime, 0.05);
    }
  }

  public setPreset(preset: SynthPreset) {
    this.activePreset = preset;

    // Update Effects if initialized
    if (this.ctx) {
        if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(preset.reverbMix, this.ctx.currentTime, 0.1);
        if (this.dryGain) this.dryGain.gain.setTargetAtTime(1.0 - preset.reverbMix, this.ctx.currentTime, 0.1);
    }
  }

  public startVoice(pointerId: number, ratio: number) {
    this.init();
    if (!this.ctx || !this.dryGain || !this.reverbGain) return;

    // Voice stealing
    if (this.voices.size >= this.maxPolyphony) {
      // Find the oldest voice (first key) and kill it
      const firstKey = this.voices.keys().next().value;
      if (firstKey !== undefined) this.stopVoice(firstKey, true); // True = immediate
    }

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();

    osc.type = this.activePreset.waveform;
    osc.frequency.value = BASE_FREQUENCY * ratio;

    // Filter
    filter.type = 'lowpass';
    filter.frequency.value = this.activePreset.filterCutoff;
    filter.Q.value = 1;

    // Envelope Attack
    const now = this.ctx.currentTime;

    // Gain Envelope
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(this.activePreset.gain, now + this.activePreset.attack);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.001, this.activePreset.gain * this.activePreset.sustain), now + this.activePreset.attack + this.activePreset.decay);

    // Connect Graph
    osc.connect(filter);
    filter.connect(gain);

    // Fan out to Dry and Wet busses
    gain.connect(this.dryGain);
    gain.connect(this.reverbGain);

    osc.start();

    this.voices.set(pointerId, { osc, gain, filter, startRatio: ratio });
  }

  public stopVoice(pointerId: number, immediate: boolean = false) {
    if (!this.ctx) return;
    const voice = this.voices.get(pointerId);
    if (voice) {
      const now = this.ctx.currentTime;

      voice.gain.gain.cancelScheduledValues(now);
      voice.gain.gain.setValueAtTime(voice.gain.gain.value, now);

      const releaseTime = immediate ? 0.05 : this.activePreset.release;

      voice.gain.gain.exponentialRampToValueAtTime(0.001, now + releaseTime);

      voice.osc.stop(now + releaseTime + 0.1);
      setTimeout(() => {
        voice.osc.disconnect();
        voice.gain.disconnect();
        voice.filter.disconnect();
      }, (releaseTime + 0.2) * 1000);

      this.voices.delete(pointerId);
    }
  }

  public bendVoice(pointerId: number, detuneCents: number) {
    const voice = this.voices.get(pointerId);
    if (voice && this.ctx) {
      const multiplier = Math.pow(2, detuneCents / 1200);
      const baseFreq = BASE_FREQUENCY * voice.startRatio;
      voice.osc.frequency.setTargetAtTime(baseFreq * multiplier, this.ctx.currentTime, 0.05);
    }
  }

  public glideVoice(pointerId: number, newRatio: number, glideTime: number = 0.1) {
    const voice = this.voices.get(pointerId);
    if (voice && this.ctx) {
       const newFreq = BASE_FREQUENCY * newRatio;
       voice.osc.frequency.setTargetAtTime(newFreq, this.ctx.currentTime, glideTime);
       voice.startRatio = newRatio; 
    }
  }

  public stopAll() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Hard Panic: Disconnect everything immediately
    this.voices.forEach((voice) => {
        try {
            voice.gain.gain.cancelScheduledValues(now);
            voice.gain.gain.setValueAtTime(0, now);
            voice.osc.stop();
            voice.osc.disconnect();
            voice.gain.disconnect();
            voice.filter.disconnect();
        } catch (e) {
            console.error("Error stopping voice in panic", e);
        }
    });
    this.voices.clear();
  }
}

export default AudioEngine;

import React, { useRef, useState } from 'react';
import { AppSettings, ButtonShape } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
  onSave: () => void;
  onLoad: (file: File) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings, onSave, onLoad }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleLimitToggle = (limit: 7 | 11 | 13) => {
    updateSettings({
      ...settings,
      enabledLimits: {
        ...settings.enabledLimits,
        [limit]: !settings.enabledLimits[limit]
      }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-[200] flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-800 p-6 rounded-xl w-[90%] max-w-2xl max-h-[90vh] overflow-y-auto text-slate-200 shadow-2xl border border-slate-700 flex flex-col">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-white">Lattice Configuration</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white">✕</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Dimensions & Limits */}
            <div className="space-y-6">
                <h3 className="font-semibold text-blue-400 border-b border-slate-700 pb-1">Dimensions</h3>

                <div>
                    <label className="block text-sm font-semibold mb-2">Lattice Depth (Shells)</label>
                    <div className="flex items-center gap-4">
                        <input 
                            type="range" min="1" max="20" step="1" 
                            value={settings.latticeShells}
                            onChange={(e) => handleChange('latticeShells', parseInt(e.target.value))}
                            className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                        <span className="text-xl font-bold min-w-[2ch]">{settings.latticeShells}</span>
                    </div>
                </div>

                <div>
                    <label className="block text-sm font-semibold mb-2">Complexity Limit (Max N/D)</label>
                    <div className="flex items-center gap-4">
                        <input 
                            type="range" min="100" max="10000" step="100" 
                            value={settings.maxND}
                            onChange={(e) => handleChange('maxND', parseInt(e.target.value))}
                            className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                        <span className="text-sm font-bold min-w-[4ch]">{settings.maxND}</span>
                    </div>
                </div>

                 <div>
                    <label className="block text-sm font-semibold mb-2">Polyphony (Voices)</label>
                    <div className="flex items-center gap-4">
                        <input 
                            type="range" min="1" max="10" step="1" 
                            value={settings.polyphony}
                            onChange={(e) => handleChange('polyphony', parseInt(e.target.value))}
                            className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                        <span className="text-xl font-bold min-w-[2ch]">{settings.polyphony}</span>
                    </div>
                </div>

                <div>
                    <label className="block text-sm font-semibold mb-2">Button Spacing ({settings.buttonSpacingScale.toFixed(1)}x)</label>
                    <input 
                        type="range" min="0.5" max="5.0" step="0.1" 
                        value={settings.buttonSpacingScale}
                        onChange={(e) => handleChange('buttonSpacingScale', parseFloat(e.target.value))}
                        className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                    />
                </div>

                <div>
                    <label className="block text-sm font-semibold mb-2">Canvas Size</label>
                    <select 
                        value={settings.canvasSize}
                        onChange={(e) => handleChange('canvasSize', parseInt(e.target.value))}
                        className="w-full bg-slate-700 border border-slate-600 rounded p-2 text-white"
                    >
                        <option value={3000}>Small (3000px)</option>
                        <option value={4000}>Medium (4000px)</option>
                        <option value={6000}>Large (6000px)</option>
                        <option value={8000}>Extra Large (8000px)</option>
                    </select>
                </div>

                <div className="space-y-2">
                    <span className="block text-sm font-semibold">Additional Limits</span>
                    <div className="flex flex-col gap-2">
                        <label className="flex items-center space-x-3 bg-slate-900/50 p-2 rounded cursor-pointer border border-transparent hover:border-slate-600 transition">
                            <input 
                                type="checkbox" 
                                checked={settings.enabledLimits[7]} 
                                onChange={() => handleLimitToggle(7)}
                                className="w-5 h-5 rounded border-slate-600 text-green-500 focus:ring-green-500"
                            />
                            <span>Enable 7-Limit Axis</span>
                        </label>
                        <label className="flex items-center space-x-3 bg-slate-900/50 p-2 rounded cursor-pointer border border-transparent hover:border-slate-600 transition">
                            <input 
                                type="checkbox" 
                                checked={settings.enabledLimits[11]} 
                                onChange={() => handleLimitToggle(11)}
                                className="w-5 h-5 rounded border-slate-600 text-purple-500 focus:ring-purple-500"
                            />
                            <span>Enable 11-Limit Axis</span>
                        </label>
                        <label className="flex items-center space-x-3 bg-slate-900/50 p-2 rounded cursor-pointer border border-transparent hover:border-slate-600 transition">
                            <input 
                                type="checkbox" 
                                checked={settings.enabledLimits[13]} 
                                onChange={() => handleLimitToggle(13)}
                                className="w-5 h-5 rounded border-slate-600 text-orange-500 focus:ring-orange-500"
                            />
                            <span>Enable 13-Limit Axis</span>
                        </label>
                    </div>
                </div>
            </div>

            {/* Visuals & Colors */}
            <div className="space-y-6">
                <h3 className="font-semibold text-purple-400 border-b border-slate-700 pb-1">Behavior</h3>

                 <div>
                     <label className="flex items-center space-x-2 mb-2 p-2 bg-slate-900/50 rounded border border-teal-500/30">
                        <input type="checkbox" checked={settings.isLatchModeEnabled} onChange={(e) => handleChange('isLatchModeEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-teal-500 focus:ring-teal-500" />
                        <span className="font-semibold text-teal-300">Latch Mode</span>
                    </label>
                    <div className={`transition-opacity pl-4 border-l-2 border-slate-700 ${settings.isLatchModeEnabled ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                        <label className="block text-xs mb-1 text-slate-400">Latch Limit (Harmonic Distance)</label>
                        <div className="flex gap-2 items-center">
                            <input 
                                type="range" min="1" max="10" step="1" 
                                value={settings.latchShellLimit}
                                onChange={(e) => handleChange('latchShellLimit', parseInt(e.target.value))}
                                className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                            />
                            <span className="text-xs font-mono">{settings.latchShellLimit}</span>
                        </div>
                        <p className="text-[10px] text-slate-500 mt-1">1=Octaves, 2=Fifths, 3=Thirds...</p>
                    </div>
                </div>

                 <div className="opacity-50 pointer-events-none grayscale">
                     <label className="flex items-center space-x-2 mb-2 p-2 bg-slate-900/50 rounded border border-slate-600">
                        <input type="checkbox" checked={settings.isMomentumEnabled} readOnly className="w-5 h-5 rounded border-slate-600" />
                        <span className="font-semibold text-slate-400">Momentum (Deprecated)</span>
                    </label>
                </div>

                <div>
                    <label className="flex items-center space-x-2 mb-2 p-2 bg-slate-900/50 rounded border border-indigo-500/30">
                        <input type="checkbox" checked={settings.isVoiceLeadingEnabled} onChange={(e) => handleChange('isVoiceLeadingEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500 focus:ring-indigo-500" />
                        <span className="font-semibold text-indigo-300">Voice Leading Visuals</span>
                    </label>
                    <div className={`transition-opacity ${settings.isVoiceLeadingEnabled ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                        <label className="block text-xs mb-1 text-slate-400">Falloff Strength</label>
                         <input 
                            type="range" min="0.1" max="1.0" step="0.05" 
                            value={settings.voiceLeadingStrength}
                            onChange={(e) => handleChange('voiceLeadingStrength', parseFloat(e.target.value))}
                            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                </div>

                <div className="border-t border-slate-700 pt-4">
                    <label className="block text-sm mb-1">Button Size ({settings.buttonSizeScale.toFixed(1)}x)</label>
                    <input 
                        type="range" min="0.5" max="2.0" step="0.1" 
                        value={settings.buttonSizeScale}
                        onChange={(e) => handleChange('buttonSizeScale', parseFloat(e.target.value))}
                        className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                    />
                </div>

                <div>
                     <label className="block text-sm mb-1">Button Shape</label>
                     <div className="flex gap-2">
                       <button 
                         onClick={() => handleChange('buttonShape', ButtonShape.CIRCLE)}
                         className={`px-3 py-1 rounded ${settings.buttonShape === ButtonShape.CIRCLE ? 'bg-indigo-600' : 'bg-slate-700'}`}
                       >Circle</button>
                       <button 
                         onClick={() => handleChange('buttonShape', ButtonShape.DIAMOND)}
                         className={`px-3 py-1 rounded ${settings.buttonShape === ButtonShape.DIAMOND ? 'bg-indigo-600' : 'bg-slate-700'}`}
                       >Diamond</button>
                     </div>
                </div>

                 <div className="grid grid-cols-2 gap-2 text-sm">
                 <label className="flex items-center space-x-2">
                   <input type="checkbox" checked={settings.isPitchBendEnabled} onChange={(e) => handleChange('isPitchBendEnabled', e.target.checked)} />
                   <span>Bend Animations</span>
                 </label>
              </div>

            </div>
        </div>

        {/* Persistence Actions */}
        <div className="mt-8 flex gap-4 border-t border-slate-700 pt-4">
          <button onClick={onSave} className="flex-1 bg-green-600 hover:bg-green-700 py-2 rounded font-semibold transition shadow-lg">
            Export Config
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex-1 bg-slate-600 hover:bg-slate-700 py-2 rounded font-semibold transition shadow-lg">
            Import Config
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept=".xml" 
            onChange={(e) => {
              if (e.target.files?.[0]) onLoad(e.target.files[0]);
            }} 
          />
        </div>

      </div>
    </div>
  );
};

export default SettingsModal;

import React from 'react';
import { SynthPreset, WaveformType } from '../types';

interface Props {
  preset: SynthPreset;
  onChange: (p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

const SynthControls: React.FC<Props> = ({ preset, onChange, isOpen, onClose }) => {
  if (!isOpen) return null;

  const update = (key: keyof SynthPreset, val: any) => {
    onChange({ ...preset, [key]: val });
  };

  return (
    <div className="fixed top-0 right-0 h-full w-80 bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-6 overflow-y-auto border-l border-slate-700">
        <div className="flex justify-between mb-6">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white">Close</button>
        </div>

        <div className="space-y-6">
            <div>
                <label className="block text-sm mb-2 text-slate-400">Waveform</label>
                <div className="grid grid-cols-2 gap-2">
                    {Object.values(WaveformType).map(w => (
                        <button 
                            key={w}
                            onClick={() => update('waveform', w)}
                            className={`px-2 py-2 text-sm rounded border ${preset.waveform === w ? 'bg-indigo-600 border-indigo-500' : 'bg-slate-700 border-slate-600'}`}
                        >
                            {w}
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-4">
                <h3 className="text-sm font-semibold text-slate-400">Filter & FX</h3>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Cutoff Freq</span> <span>{preset.filterCutoff}Hz</span></label>
                    <input type="range" min="20" max="10000" step="10" value={preset.filterCutoff} onChange={(e) => update('filterCutoff', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                </div>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Reverb Mix</span> <span>{(preset.reverbMix * 100).toFixed(0)}%</span></label>
                    <input type="range" min="0" max="1" step="0.01" value={preset.reverbMix} onChange={(e) => update('reverbMix', parseFloat(e.target.value))} className="w-full h-1 bg-blue-600 rounded appearance-none" />
                </div>
            </div>

            <div className="space-y-4">
                <h3 className="text-sm font-semibold text-slate-400">Envelope</h3>

                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Attack</span> <span>{preset.attack.toFixed(2)}s</span></label>
                    <input type="range" min="0.01" max="10.0" step="0.01" value={preset.attack} onChange={(e) => update('attack', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Decay</span> <span>{preset.decay.toFixed(2)}s</span></label>
                    <input type="range" min="0.01" max="10.0" step="0.01" value={preset.decay} onChange={(e) => update('decay', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Sustain Level</span> <span>{preset.sustain}</span></label>
                    <input type="range" min="0.0" max="1.0" step="0.01" value={preset.sustain} onChange={(e) => update('sustain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Release</span> <span>{preset.release.toFixed(2)}s</span></label>
                    <input type="range" min="0.01" max="10.0" step="0.01" value={preset.release} onChange={(e) => update('release', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
            </div>

            <div>
                <label className="flex justify-between text-xs mb-1"><span>Preset Gain</span> <span>{(preset.gain * 100).toFixed(0)}%</span></label>
                <input type="range" min="0.0" max="1.0" step="0.01" value={preset.gain} onChange={(e) => update('gain', parseFloat(e.target.value))} className="w-full h-1 bg-green-900 rounded appearance-none" />
            </div>

            <div className="pt-4 border-t border-slate-700">
                <p className="text-xs text-slate-500 text-center">Changes apply to current slot</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

import React, { useState } from 'react';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  onPanic: () => void;
  pitchOffLocked: boolean;
  volumeLocked: boolean;
}

const FloatingControls: React.FC<Props> = ({ volume, setVolume, onPanic, pitchOffLocked, volumeLocked }) => {
  const [panicPos, setPanicPos] = useState({ x: window.innerWidth - 120, y: window.innerHeight - 100 });
  const [volPos, setVolPos] = useState({ x: window.innerWidth / 2 - 100, y: window.innerHeight - 80 });

  const handleDrag = (e: React.PointerEvent, setPos: any, locked: boolean) => {
    if (locked) return;
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);

    const onMove = (evt: PointerEvent) => {
       setPos({ x: evt.clientX - el.clientWidth/2, y: evt.clientY - el.clientHeight/2 });
    };

    const onUp = () => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  return (
    <>
      {/* Volume Slider */}
      <div 
        className={`absolute bg-slate-800/80 p-3 rounded-full flex items-center gap-2 backdrop-blur border border-white/10 ${volumeLocked ? '' : 'cursor-move'}`}
        style={{ left: volPos.x, top: volPos.y, width: 200, zIndex: 150 }}
        onPointerDown={(e) => handleDrag(e, setVolPos, volumeLocked)}
      >
        <span className="text-xs font-bold text-slate-400">VOL</span>
        <input 
          type="range" min="0" max="1" step="0.01" 
          value={volume}
          onChange={(e) => setVolume(parseFloat(e.target.value))}
          className="w-full h-2 bg-slate-600 rounded-lg appearance-none cursor-pointer"
          onPointerDown={(e) => e.stopPropagation()} // Allow slider interaction without drag
        />
      </div>

      {/* Panic Button */}
      <button
        className={`absolute w-20 h-20 rounded-full bg-red-600/20 border-2 border-red-500 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-red-600/40 active:bg-red-600 active:text-white transition-all shadow-[0_0_15px_rgba(239,68,68,0.4)] ${pitchOffLocked ? '' : 'cursor-move'}`}
        style={{ left: panicPos.x, top: panicPos.y, zIndex: 150 }}
        onClick={onPanic}
        onPointerDown={(e) => handleDrag(e, setPanicPos, pitchOffLocked)}
      >
        Off
      </button>
    </>
  );
};

export default FloatingControls;

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveTouch {
  id: number;
  nodeId: string; // The "Anchor" node for the current bend
  startX: number;
  startY: number;
  currentX: number;
  currentY: number;

  // Simplified bend state
  currentRatio: number;
}

const TonalityDiamond: React.FC<Props> = ({ settings, audioEngine, onLimitInteraction }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [activeTouches, setActiveTouches] = useState<Map<number, ActiveTouch>>(new Map());
  const [latchedVoices, setLatchedVoices] = useState<Map<string, number>>(new Map()); // nodeId -> voiceId

  const [hasCentered, setHasCentered] = useState(false);

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();

    // Tap to stop Latched Voice
    if (latchedVoices.has(node.id)) {
        const voiceId = latchedVoices.get(node.id)!;
        audioEngine.stopVoice(voiceId);
        setLatchedVoices(prev => {
            const next = new Map(prev);
            next.delete(node.id);
            return next;
        });
        return;
    }

    onLimitInteraction(node.maxPrime);

    // Check Latch Logic
    if (settings.isLatchModeEnabled) {
      // Calculate harmonic distance from origin (1/1)
      const dist = getHarmonicDistance(node.coords);

      // Settings.latchShellLimit: 1 = Octaves (dist 0), 2 = Fifths (dist 1)
      // So maxDist = settings.latchShellLimit - 1
      const maxDist = settings.latchShellLimit - 1;

      if (dist <= maxDist) {
        audioEngine.startVoice(e.pointerId, node.ratio);
        setLatchedVoices(prev => {
          const next = new Map(prev);
          next.set(node.id, e.pointerId);
          return next;
        });
        // We don't add to activeTouches because latching doesn't support bending/moving
        return; 
      }
    }

    // Standard Momentary Play
    audioEngine.startVoice(e.pointerId, node.ratio);
    setActiveTouches(prev => {
      const newMap = new Map(prev);
      newMap.set(e.pointerId, {
        id: e.pointerId,
        nodeId: node.id,
        startX: e.clientX,
        startY: e.clientY,
        currentX: e.clientX,
        currentY: e.clientY,
        currentRatio: node.ratio
      });
      return newMap;
    });
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeTouches.has(e.pointerId)) return;
    const touch = activeTouches.get(e.pointerId)!;

    // Simplified Bend / Animation Logic
    // We just track position to draw the lines to neighbors.
    // We allow a slide if pitch bend is enabled, but without locking.

    if (settings.isPitchBendEnabled) {
      // Calculate delta Y for pitch bend (basic vertical control)
      // Or simply allow dragging towards neighbors.
      // Based on prompt: "simplify bend... control animations... connections between nodes".

      setActiveTouches(prev => {
         const newMap = new Map(prev);
         newMap.set(e.pointerId, {
             ...touch,
             currentX: e.clientX,
             currentY: e.clientY,
         });
         return newMap;
      });

      // Optional: If we wanted to bend audio based on Y position (Vertical Pitch Axis)
      // we could do it here, but PrismaTonal's Y axis is already logarithmic pitch.
      // So moving Y up (smaller pixels) increases pitch.
      const dy = e.clientY - touch.startY;
      const PITCH_SCALE = 200; // Pixels per octave (matches Generation)
      const octaveShift = -dy / PITCH_SCALE;
      const ratioMultiplier = Math.pow(2, octaveShift);

      const anchorNode = data.nodes.find(n => n.id === touch.nodeId);
      if (anchorNode) {
          audioEngine.glideVoice(e.pointerId, anchorNode.ratio * ratioMultiplier, 0.05);
      }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeTouches.has(e.pointerId)) {
        audioEngine.stopVoice(e.pointerId);
        setActiveTouches(prev => {
          const newMap = new Map(prev);
          newMap.delete(e.pointerId);
          return newMap;
        });
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const touches: ActiveTouch[] = Array.from(activeTouches.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Set of all nodes currently sounding (latched or held)
  const activeNodeIds = new Set([...touches.map(t => t.nodeId), ...latchedVoices.keys()]);
  const activeNodes = data.nodes.filter(n => activeNodeIds.has(n.id));

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
            }}
        >
            {/* SVG Layer for Lines */}
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;
                    const color = getColor(line.limit);

                    // Voice Leading Visualization for Lines
                    // Highlight if this line connects two active nodes
                    // OR if it connects an active node to a close neighbor

                    const isLineActive = (activeNodeIds.has(line.id.split('-')[0]) || activeNodeIds.has(line.id.split('-')[1])); // Approximate ID check
                    // More accurate check:
                    // Find endpoints
                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;

                    if (n1 && n2) {
                        const n1Active = activeNodeIds.has(n1.id);
                        const n2Active = activeNodeIds.has(n2.id);

                        if (n1Active && n2Active) {
                             lineOpacity = 1.0;
                             lineWidth = 6;
                        } else if (n1Active || n2Active) {
                             lineOpacity = 0.6;
                             lineWidth = 3;
                        } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                             // Dim lines far away
                             lineOpacity = 0.05;
                        }
                    }

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={lineWidth}
                            strokeOpacity={lineOpacity}
                            strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                        />
                    );
                })}

                {/* Drag Indicators (Simplified Bend) */}
                {touches.map(touch => {
                    const node = data.nodes.find(n => n.id === touch.nodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;

                    return (
                         <line 
                           key={`drag-${touch.id}`}
                           x1={nx} y1={ny} x2={touch.currentX + scrollContainerRef.current!.scrollLeft} y2={touch.currentY + scrollContainerRef.current!.scrollTop}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.3}
                         />
                    );
                })}
            </svg>

            {/* Nodes Layer */}
            {data.nodes.map((node) => {
                const activeTouch = touches.find(t => t.nodeId === node.id);
                const isLatched = latchedVoices.has(node.id);
                const isActive = !!activeTouch || isLatched;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                // Lower Z-index range to avoid covering menus (Menu z-index is 200)
                // Nodes range from 10 to 60. Active nodes 80.
                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = 1.3;
                        opacity = 1.0;
                    } else {
                        // Calculate minimum harmonic distance to ANY active node
                        let minDist = Infinity;
                        for (const activeNode of activeNodes) {
                            const d = getHarmonicDistance(node.coords, activeNode.coords);
                            if (d < minDist) minDist = d;
                        }

                        const falloff = settings.voiceLeadingStrength; 
                        const visibility = Math.max(0.15, 1 - (minDist * falloff));
                        scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                        opacity = visibility;
                    }
                } else {
                    scale = isActive ? 1.3 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isActive ? `0 0 35px white` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: opacity,
                            border: isLatched ? '3px solid white' : (isActive ? '2px solid white' : '2px solid rgba(255,255,255,0.3)'),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

export default TonalityDiamond;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 20
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  waveform: WaveformType;
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;
  filterCutoff: number; // Hz
  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import { SynthPreset, WaveformType } from '../types';
import { BASE_FREQUENCY } from '../constants';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private dryGain: GainNode | null = null;

  // Changed key to string to support 'node-ID' and 'cursor-ID'
  private voices: Map<string, { osc: OscillatorNode; gain: GainNode; filter: BiquadFilterNode; startRatio: number }> = new Map();
  private maxPolyphony: number = 10;
  private activePreset: SynthPreset;

  constructor(preset: SynthPreset) {
    this.activePreset = preset;
  }

  public init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
        latencyHint: 'interactive',
      });

      // Master Gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 1.0; 
      this.masterGain.connect(this.ctx.destination);

      // Reverb Setup
      this.reverbNode = this.ctx.createConvolver();
      this.reverbNode.buffer = this.createImpulseResponse(2.5, 2.0); // 2.5s duration, 2.0 decay

      this.reverbGain = this.ctx.createGain();
      this.reverbGain.gain.value = this.activePreset.reverbMix;

      this.dryGain = this.ctx.createGain();
      this.dryGain.gain.value = 1.0 - this.activePreset.reverbMix;

      // Routing
      // Voice -> Dry -> Master
      this.dryGain.connect(this.masterGain);

      // Voice -> ReverbGain -> Reverb -> Master
      this.reverbGain.connect(this.reverbNode);
      this.reverbNode.connect(this.masterGain);
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    const sampleRate = this.ctx!.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx!.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        // Simple noise decay
        left[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
        right[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
    }
    return impulse;
  }

  public setPolyphony(count: number) {
    this.maxPolyphony = count;
  }

  public setMasterVolume(val: number) {
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(val, this.ctx.currentTime, 0.05);
    }
  }

  public setPreset(preset: SynthPreset) {
    this.activePreset = preset;

    // Update Effects if initialized
    if (this.ctx) {
        if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(preset.reverbMix, this.ctx.currentTime, 0.1);
        if (this.dryGain) this.dryGain.gain.setTargetAtTime(1.0 - preset.reverbMix, this.ctx.currentTime, 0.1);
    }
  }

  public startVoice(id: string, ratio: number) {
    this.init();
    if (!this.ctx || !this.dryGain || !this.reverbGain) return;

    // Check if voice already exists (restart it)
    if (this.voices.has(id)) {
        this.stopVoice(id, true);
    }

    // Voice stealing
    if (this.voices.size >= this.maxPolyphony) {
      // Find the oldest voice (first key) and kill it
      const firstKey = this.voices.keys().next().value;
      if (firstKey !== undefined) this.stopVoice(firstKey, true); // True = immediate
    }

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();

    osc.type = this.activePreset.waveform;
    osc.frequency.value = BASE_FREQUENCY * ratio;

    // Filter
    filter.type = 'lowpass';
    filter.frequency.value = this.activePreset.filterCutoff;
    filter.Q.value = 1;

    // Envelope Attack
    const now = this.ctx.currentTime;

    // Gain Envelope
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(this.activePreset.gain, now + this.activePreset.attack);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.001, this.activePreset.gain * this.activePreset.sustain), now + this.activePreset.attack + this.activePreset.decay);

    // Connect Graph
    osc.connect(filter);
    filter.connect(gain);

    // Fan out to Dry and Wet busses
    gain.connect(this.dryGain);
    gain.connect(this.reverbGain);

    osc.start();

    this.voices.set(id, { osc, gain, filter, startRatio: ratio });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.ctx) return;
    const voice = this.voices.get(id);
    if (voice) {
      const now = this.ctx.currentTime;

      voice.gain.gain.cancelScheduledValues(now);
      voice.gain.gain.setValueAtTime(voice.gain.gain.value, now);

      const releaseTime = immediate ? 0.05 : this.activePreset.release;

      voice.gain.gain.exponentialRampToValueAtTime(0.001, now + releaseTime);

      voice.osc.stop(now + releaseTime + 0.1);
      setTimeout(() => {
        voice.osc.disconnect();
        voice.gain.disconnect();
        voice.filter.disconnect();
      }, (releaseTime + 0.2) * 1000);

      this.voices.delete(id);
    }
  }

  public bendVoice(id: string, detuneCents: number) {
    const voice = this.voices.get(id);
    if (voice && this.ctx) {
      const multiplier = Math.pow(2, detuneCents / 1200);
      const baseFreq = BASE_FREQUENCY * voice.startRatio;
      voice.osc.frequency.setTargetAtTime(baseFreq * multiplier, this.ctx.currentTime, 0.05);
    }
  }

  public glideVoice(id: string, newRatio: number, glideTime: number = 0.1) {
    const voice = this.voices.get(id);
    if (voice && this.ctx) {
       const newFreq = BASE_FREQUENCY * newRatio;
       voice.osc.frequency.setTargetAtTime(newFreq, this.ctx.currentTime, glideTime);
       // We update startRatio so subsequent bends are relative to the new note? 
       // Actually, standard glissando replaces the base frequency.
       voice.startRatio = newRatio; 
    }
  }

  public stopAll() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // Hard Panic: Disconnect everything immediately
    this.voices.forEach((voice) => {
        try {
            voice.gain.gain.cancelScheduledValues(now);
            voice.gain.gain.setValueAtTime(0, now);
            voice.osc.stop();
            voice.osc.disconnect();
            voice.gain.disconnect();
            voice.filter.disconnect();
        } catch (e) {
            console.error("Error stopping voice in panic", e);
        }
    });
    this.voices.clear();
  }
}

export default AudioEngine;

import React, { useEffect, useRef, useState, useLayoutEffect } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const TonalityDiamond: React.FC<Props> = ({ settings, audioEngine, onLimitInteraction }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes by their ID (independent of pointers)
  const [latchedNodeIds, setLatchedNodeIds] = useState<Set<string>>(new Set());

  // Track active pointers (cursors) for bending and "drawing"
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodeIds(prev => {
        const newSet = new Set(prev);
        if (newSet.has(nodeId)) {
            // Unlatch
            newSet.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            // Latch
            newSet.add(nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio);
        }
        return newSet;
    });
  };

  const latchOn = (nodeId: string, ratio: number) => {
      setLatchedNodeIds(prev => {
          if (prev.has(nodeId)) return prev; // Already latched
          const newSet = new Set(prev);
          newSet.add(nodeId);
          audioEngine.startVoice(`node-${nodeId}`, ratio);
          return newSet;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    // 1. Toggle Latch State for this specific node
    // Note: If Latch Mode is disabled, we treat "latch" as momentary (handled in pointer up)
    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        // Momentary Play
        latchOn(node.id, node.ratio);
    }

    // 2. Start Cursor Voice (The "Bending" Voice)
    // This allows bending *simultaneously* with the latched grid note.
    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    // Update Cursor Position
    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        // 1. Calculate Bend Pitch based on absolute Y position
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        // Convert screen coordinates to canvas coordinates
        const canvasX = e.clientX + scrollLeft; 
        const canvasY = e.clientY + scrollTop;

        const relY = canvasY - centerOffset;

        // PITCH_SCALE is 200px/octave (defined in LatticeService generation)
        const PITCH_SCALE = 200; 
        // y = -(Math.log2(ratio) * PITCH_SCALE)  ->  ratio = 2 ^ (-y / PITCH_SCALE)
        const bentRatio = Math.pow(2, -relY / PITCH_SCALE);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, 0.05);

        // 2. "Draw" Chords: Check collision with other nodes
        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;
            // Scan visible nodes
            // Optimization: Only check nodes somewhat near the viewport? 
            // For now, iterate data.nodes is fine (~200 nodes is cheap)

            for (const node of data.nodes) {
                // Determine node screen position
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                // Collision Radius (roughly button size)
                const radius = (60 * settings.buttonSizeScale) / 2;

                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist < radius) {
                    // Check Logic:
                    // 1. Is not already latched?
                    // 2. Is harmonically close enough to the origin node? (Latch Limit)
                    if (!latchedNodeIds.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const hDist = getHarmonicDistance(node.coords, originNode.coords);
                             // latchShellLimit 1=Octave(0 dist), 2=Fifth(1 dist)
                             if (hDist <= (settings.latchShellLimit - 1)) {
                                 // Latch it!
                                 latchOn(node.id, node.ratio);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    // Stop Cursor Voice
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    // If NOT Latch Mode, dragging off or lifting up should stop the momentary notes
    if (!settings.isLatchModeEnabled) {
        // Stop all voices that were triggered by this interaction
        // However, in momentary mode, we likely only triggered one node-voice per finger
        // But if we implemented "Drawing" in momentary mode too, we'd need to track which pointers started which nodes.
        // For simplicity: In momentary mode, we just clear everything associated with this interaction?
        // Actually, easiest is: Iterate all nodes, if any match the cursor origin, stop it.
        // But we might have drawn multiple.

        // Simpler Momentary Logic:
        // We just clear ALL latched nodes because "latchedNodeIds" acts as "Active Notes" in momentary mode.
        // But we must be careful not to kill other fingers' notes.
        // Since we don't map Pointer -> Node Set in state, we might just clear specifically if we can find them.
        // Given the request focused on Latch Mode fixes, we'll implement a safe clear for momentary:

        // Fix: In momentary mode, "latchedNodeIds" contains currently held notes.
        // We can't easily distinguish which pointer held which if we don't track it.
        // But usually momentary is 1-to-1.

        // Let's iterate active cursors to see if we can identify what to stop.
        // Actually, checking the target of the event or the originNodeId is safer.
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             // Stop the origin node
             if (latchedNodeIds.has(cursor.originNodeId)) {
                 setLatchedNodeIds(prev => {
                     const next = new Set(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Set of all nodes currently sounding (latched or held)
  const activeNodes = data.nodes.filter(n => latchedNodeIds.has(n.id));

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
            }}
        >
            {/* SVG Layer for Lines */}
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;
                    const color = getColor(line.limit);

                    // Voice Leading Visualization
                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;

                    if (n1 && n2) {
                        const n1Active = latchedNodeIds.has(n1.id);
                        const n2Active = latchedNodeIds.has(n2.id);

                        if (n1Active && n2Active) {
                             lineOpacity = 1.0;
                             lineWidth = 6;
                        } else if (n1Active || n2Active) {
                             lineOpacity = 0.6;
                             lineWidth = 3;
                        } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                             lineOpacity = 0.05;
                        }
                    }

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={lineWidth}
                            strokeOpacity={lineOpacity}
                            strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                        />
                    );
                })}

                {/* Drag Indicators (Cursor Voice Visuals) */}
                {cursors.map(cursor => {
                    // Find origin node to draw line from
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;

                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);

                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {/* Nodes Layer */}
            {data.nodes.map((node) => {
                const isLatched = latchedNodeIds.has(node.id);
                // Check if a cursor is hovering this node
                // (Visual feedback for "about to latch" or "origin")
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = 1.3;
                        opacity = 1.0;
                    } else {
                        // Calculate minimum harmonic distance to ANY active node
                        let minDist = Infinity;
                        for (const activeNode of activeNodes) {
                            const d = getHarmonicDistance(node.coords, activeNode.coords);
                            if (d < minDist) minDist = d;
                        }

                        const falloff = settings.voiceLeadingStrength; 
                        const visibility = Math.max(0.15, 1 - (minDist * falloff));
                        scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                        opacity = visibility;
                    }
                } else {
                    scale = isActive ? 1.3 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isLatched ? `0 0 35px white` : (isHovered ? `0 0 15px white` : '0 4px 6px rgba(0,0,0,0.6)'),
                            zIndex: zIndex,
                            opacity: opacity,
                            border: isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)'),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
};

