export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import AudioEngine from './services/AudioEngine';
import { AppSettings, SynthPreset } from './types';
import { DEFAULT_COLORS, DEFAULT_SETTINGS, DEFAULT_PRESET } from './constants';

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [preset, setPreset] = useState<SynthPreset>(DEFAULT_PRESET);
  const [masterVolume, setMasterVolume] = useState(0.8);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Audio Engine Singleton Ref
  const engineRef = useRef<AudioEngine>(new AudioEngine(DEFAULT_PRESET));
  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Init Engine updates
  useEffect(() => {
    engineRef.current.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    engineRef.current.setPreset(preset);
  }, [preset]);

  const handleLimitInteraction = (limit: number) => {
    // Move touched limit to the end of the array (front)
    // Only if it's not already at the front
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      setSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    engineRef.current.stopAll();
    diamondRef.current?.clearLatches();
  };

  // XML Handlers
  const saveSettingsToXML = () => {
    const data = {
      settings,
      preset,
    };
    const xml = `
      <PrismaTonalConfig>
        <Settings>${JSON.stringify(settings)}</Settings>
        <Preset>${JSON.stringify(preset)}</Preset>
      </PrismaTonalConfig>
    `;
    const blob = new Blob([xml], { type: 'text/xml' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'prismatonal_config.xml';
    a.click();
    URL.revokeObjectURL(url);
  };

  const loadSettingsFromXML = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      // Basic extraction (Assuming valid format from save)
      try {
        // Regex hack for simplicity in this demo environment, ideally use DOMParser
        const settingsMatch = text.match(/<Settings>(.*?)<\/Settings>/);
        const presetMatch = text.match(/<Preset>(.*?)<\/Preset>/);

        if (settingsMatch && settingsMatch[1]) {
           const parsedSettings = JSON.parse(settingsMatch[1]);
           // Ensure colors are merged correctly to avoid missing keys
           setSettings({ ...parsedSettings, colors: { ...DEFAULT_COLORS, ...parsedSettings.colors } });
        }
        if (presetMatch && presetMatch[1]) {
           setPreset(JSON.parse(presetMatch[1]));
        }
        setIsSettingsOpen(false);
      } catch (err) {
        alert("Failed to parse XML config file.");
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-center z-40 pointer-events-none">
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Synth
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Settings
          </button>
        </div>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings} 
        audioEngine={engineRef.current} 
        onLimitInteraction={handleLimitInteraction}
      />

      {/* Floating UI */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        onPanic={handlePanic}
        pitchOffLocked={settings.pitchOffLocked}
        volumeLocked={settings.volumeLocked}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={setSettings}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={setSettings}
        onSave={saveSettingsToXML}
        onLoad={loadSettingsFromXML}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        preset={preset}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic for generation bounds
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

export const generateLattice = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const baseNodes: Map<string, { coords: number[], ratio: Fraction }> = new Map();
  const queue: { coords: number[], ratio: Fraction }[] = [];

  // 1. Generate Base Set (Normalized 1-2)
  const originCoords = [0, 0, 0, 0, 0];
  const originFrac = new Fraction(1, 1);
  queue.push({ coords: originCoords, ratio: originFrac });
  baseNodes.set(originCoords.join(','), { coords: originCoords, ratio: originFrac });

  const MAX_NODES = 2000;
  let processedCount = 0;

  while (queue.length > 0 && processedCount < MAX_NODES) {
    const current = queue.shift()!;
    processedCount++;
    const { coords, ratio } = current;

    PRIMES.forEach((prime, idx) => {
      if (prime === 7 && !settings.enabledLimits[7]) return;
      if (prime === 11 && !settings.enabledLimits[11]) return;
      if (prime === 13 && !settings.enabledLimits[13]) return;

      [1, -1].forEach(dir => {
        const nextPos = [...coords];
        nextPos[idx] += dir;
        const posKey = nextPos.join(',');

        if (!baseNodes.has(posKey)) {
          const dist = getHarmonicDistance(nextPos);
          if (dist < settings.latticeShells) {
             let nextRatio: Fraction;
             const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
             if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
             else {
                const invRatio = new Fraction(pRat.d, pRat.n);
                nextRatio = ratio.mul(invRatio).normalize();
             }

             if (nextRatio.n <= settings.maxND && nextRatio.d <= settings.maxND) {
                baseNodes.set(posKey, { coords: nextPos, ratio: nextRatio });
                queue.push({ coords: nextPos, ratio: nextRatio });
             }
          }
        }
      });
    });
  }

  // 2. Expand Vertically (Octaves)
  const OCTAVE_RANGE = 2; 
  const nodes: LatticeNode[] = [];
  const nodesMap: Map<string, LatticeNode> = new Map();

  baseNodes.forEach((data, key) => {
      for (let oct = -OCTAVE_RANGE; oct <= OCTAVE_RANGE; oct++) {
          const shiftedRatio = data.ratio.shiftOctave(oct);
          const absoluteRatio = shiftedRatio.n / shiftedRatio.d;

          const id = `${key}:${oct}`;

          let x = 0;
          x += data.coords[0] * X_VECTORS[3];
          x += data.coords[1] * X_VECTORS[5];
          x += data.coords[2] * X_VECTORS[7];
          x += data.coords[3] * X_VECTORS[11];
          x += data.coords[4] * X_VECTORS[13];

          const PITCH_SCALE = 200; // Pixels per octave
          const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

          const limitTop = getMaxPrime(shiftedRatio.n);
          const limitBottom = getMaxPrime(shiftedRatio.d);
          const maxPrime = Math.max(limitTop, limitBottom);

          const node: LatticeNode = {
              id,
              coords: data.coords,
              ratio: absoluteRatio,
              n: shiftedRatio.n,
              d: shiftedRatio.d,
              label: `${shiftedRatio.n}/${shiftedRatio.d}`,
              x,
              y,
              limitTop,
              limitBottom,
              maxPrime,
              octave: oct
          };
          nodes.push(node);
          nodesMap.set(id, node);
      }
  });

  // 3. Generate Lines
  const lines: LatticeLine[] = [];

  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors
      PRIMES.forEach((prime, idx) => {
          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const key = neighborCoords.join(',');

          if (baseNodes.has(key)) {
             const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

             // Iterate nearby octaves
             for(let o = node.octave - 1; o <= node.octave + 1; o++) {
                 const targetId = `${key}:${o}`;
                 const target = nodesMap.get(targetId);

                 if (target) {
                      // Check for power-of-2 relationship relative to prime
                      // ratio / basePrimeRatio = 2^k
                      const ratio = target.ratio / node.ratio;
                      const test = ratio / basePrimeRatio;
                      const log2 = Math.log2(test);

                      // Allow small epsilon error
                      if (Math.abs(log2 - Math.round(log2)) < 0.001) {
                          lines.push({
                            id: `${node.id}-${target.id}`,
                            x1: node.x,
                            y1: node.y,
                            x2: target.x,
                            y2: target.y,
                            limit: prime
                          });
                      }
                 }
             }
          }
      });

      // Vertical Octave Connections
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1 // Octave "limit"
          });
      }
  });

  return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes: Key = NodeID, Value = OriginNodeID (The note that caused the latch)
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers (cursors) for bending and "drawing"
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;

        const visibleNodeMap = new Map(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);

            // Check 1: Is the node still visible/existent in the new grid?
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            // Check 2: Latch Limit Constraint (Unified Logic)
            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
            }}
        >
            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;
                    const color = getColor(line.limit);

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;

                    if (n1 && n2) {
                        const n1Active = latchedNodes.has(n1.id);
                        const n2Active = latchedNodes.has(n2.id);

                        if (n1Active && n2Active) {
                             lineOpacity = 1.0;
                             lineWidth = 6;
                        } else if (n1Active || n2Active) {
                             lineOpacity = 0.6;
                             lineWidth = 3;
                        } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                             lineOpacity = 0.05;
                        }
                    }

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={color}
                            strokeWidth={lineWidth}
                            strokeOpacity={lineOpacity}
                            strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                        />
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = 1.3;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        // Check if node is within the current "Harmonic Reach" (Latch Limit)
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? 1.3 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isLatched ? `0 0 35px white` : (isHovered ? `0 0 15px white` : '0 4px 6px rgba(0,0,0,0.6)'),
                            zIndex: zIndex,
                            opacity: opacity,
                            border: isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)'),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

