                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Decay</span> <span>{preset.decay.toFixed(2)}s</span></label>
                    <input type="range" min="0.01" max="10.0" step="0.01" value={preset.decay} onChange={(e) => update('decay', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Sustain Level</span> <span>{preset.sustain}</span></label>
                    <input type="range" min="0.0" max="1.0" step="0.01" value={preset.sustain} onChange={(e) => update('sustain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
                <div>
                    <label className="flex justify-between text-xs mb-1"><span>Release</span> <span>{preset.release.toFixed(2)}s</span></label>
                    <input type="range" min="0.01" max="10.0" step="0.01" value={preset.release} onChange={(e) => update('release', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                </div>
            </div>

            <div>
                <label className="flex justify-between text-xs mb-1"><span>Preset Gain</span> <span>{(preset.gain * 100).toFixed(0)}%</span></label>
                <input type="range" min="0.0" max="1.0" step="0.01" value={preset.gain} onChange={(e) => update('gain', parseFloat(e.target.value))} className="w-full h-1 bg-green-900 rounded appearance-none" />
            </div>

            <div className="pt-4 border-t border-slate-700">
                <p className="text-xs text-slate-500 text-center">Changes apply to current slot</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 20
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingContrast: number; // 0.0 to 1.0 (Strength of Light/Dark shift)
  voiceLeadingAnimationSpeed: number; // seconds

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2Detune: number; // Cents
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';

  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Robust Color Blending function
const blendColor = (color: string, amount: number) => {
    // amount: -1 (black) to 1 (white)
    // Ensures hex string is valid before parsing
    const c = color.startsWith('#') ? color.slice(1) : color;
    const num = parseInt(c, 16);
    const r = (num >> 16) & 255;
    const g = (num >> 8) & 255;
    const b = num & 255;

    // If darkening, blend towards black. If lightening, blend towards white.
    // However, prevent going full black to ensure visibility on dark background.
    // For "darker", we might want to reduce brightness but maybe desaturate slightly or keep some hue?
    // Let's use simple lerp.

    let target = amount > 0 ? 255 : 0;
    // Cap darkness blend to avoid invisible lines on dark background
    // If amount < 0, effective target might be higher than 0?
    // Let's just trust the contrast slider.

    const strength = Math.abs(amount);

    const nr = Math.round(r + (target - r) * strength);
    const ng = Math.round(g + (target - g) * strength);
    const nb = Math.round(b + (target - b) * strength);

    const rr = nr.toString(16).padStart(2, '0');
    const gg = ng.toString(16).padStart(2, '0');
    const bb = nb.toString(16).padStart(2, '0');

    return `#${rr}${gg}${bb}`;
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes pulseLineOtonal {
                0% { stroke-opacity: 0.8; stroke-width: 4px; filter: drop-shadow(0 0 2px rgba(255,255,255,0.2)); }
                50% { stroke-opacity: 1.0; stroke-width: 7px; filter: drop-shadow(0 0 8px rgba(255,255,255,0.9)); }
                100% { stroke-opacity: 0.8; stroke-width: 4px; filter: drop-shadow(0 0 2px rgba(255,255,255,0.2)); }
              }
              @keyframes pulseLineUtonal {
                0% { stroke-opacity: 0.8; stroke-width: 4px; filter: drop-shadow(0 0 2px rgba(0,0,0,0.5)); }
                50% { stroke-opacity: 1.0; stroke-width: 7px; filter: drop-shadow(0 0 10px rgba(0,0,0,1.0)); }
                100% { stroke-opacity: 0.8; stroke-width: 4px; filter: drop-shadow(0 0 2px rgba(0,0,0,0.5)); }
              }
              .animate-pulse-otonal {
                animation: pulseLineOtonal ${settings.voiceLeadingAnimationSpeed}s infinite ease-in-out;
              }
              .animate-pulse-utonal {
                animation: pulseLineUtonal ${settings.voiceLeadingAnimationSpeed}s infinite ease-in-out;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    if (!n1 || !n2) return null;

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isAnimating = false;
                    let animationClass = '';

                    const n1Active = latchedNodes.has(n1.id);
                    const n2Active = latchedNodes.has(n2.id);

                    if (n1Active && n2Active) {
                        // Voice Leading Connection
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        isAnimating = settings.isVoiceLeadingAnimationEnabled;

                        // Otonal vs Utonal logic based on Coordinate Sum relative to "center of lattice" heuristic.
                        let coordSum = 0;
                        for(let c of n1.coords) coordSum += c;
                        for(let c of n2.coords) coordSum += c;

                        const contrast = settings.voiceLeadingContrast;

                        if (coordSum >= 0) {
                            // Otonal (Lighter)
                            strokeColor = blendColor(limitColor, contrast); 
                            if (isAnimating) animationClass = 'animate-pulse-otonal';
                        } else {
                            // Utonal (Darker)
                            // Use -contrast, but cap the blend to ensure visibility
                            strokeColor = blendColor(limitColor, -contrast);
                            if (isAnimating) animationClass = 'animate-pulse-utonal';
                        }

                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                        lineOpacity = 0.05;
                    }

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={strokeColor}
                            strokeWidth={lineWidth}
                            strokeOpacity={lineOpacity}
                            strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                            className={animationClass}
                        />
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = 1.3;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? 1.3 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                // Colored Illumination calculation
                let boxShadowColor = 'white';
                let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');

                if (settings.isColoredIlluminationEnabled) {
                     const phase = (top % rainbowPeriod) / rainbowPeriod;
                     const hue = (settings.rainbowOffset + phase * 360) % 360;

                     if (isLatched || isHovered) {
                         // Force deep saturation matching the rainbow or default max
                         const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
                         // Reduce lightness slightly to deepen the color appearance in glow
                         boxShadowColor = `hsl(${hue}, ${sat}%, 60%)`; 
                         borderColor = `hsl(${hue}, ${sat}%, 85%)`;
                     }
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isLatched ? `0 0 35px ${boxShadowColor}` : (isHovered ? `0 0 15px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)'),
                            zIndex: zIndex,
                            opacity: opacity,
                            border: settings.isColoredIlluminationEnabled && (isLatched || isHovered) ? `3px solid ${borderColor}` : (isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)')),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes pulseLineOtonal {
                0% { stroke-opacity: 0.9; stroke-width: 4px; filter: brightness(1.2) drop-shadow(0 0 2px white); }
                50% { stroke-opacity: 1.0; stroke-width: 7px; filter: brightness(2.0) drop-shadow(0 0 8px white); }
                100% { stroke-opacity: 0.9; stroke-width: 4px; filter: brightness(1.2) drop-shadow(0 0 2px white); }
              }
              @keyframes pulseLineUtonal {
                0% { stroke-opacity: 0.4; stroke-width: 4px; filter: brightness(0.6); }
                50% { stroke-opacity: 0.8; stroke-width: 6px; filter: brightness(0.3); }
                100% { stroke-opacity: 0.4; stroke-width: 4px; filter: brightness(0.6); }
              }
              .animate-pulse-otonal {
                animation: pulseLineOtonal ${settings.voiceLeadingAnimationSpeed}s infinite ease-in-out;
              }
              .animate-pulse-utonal {
                animation: pulseLineUtonal ${settings.voiceLeadingAnimationSpeed}s infinite ease-in-out;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    const x1 = line.x1 * spacing + centerOffset;
                    const y1 = line.y1 * spacing + centerOffset;
                    const x2 = line.x2 * spacing + centerOffset;
                    const y2 = line.y2 * spacing + centerOffset;

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    if (!n1 || !n2) return null;

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isAnimating = false;
                    let animationClass = '';
                    let lineStyle = {};

                    const n1Active = latchedNodes.has(n1.id);
                    const n2Active = latchedNodes.has(n2.id);

                    if (n1Active && n2Active) {
                        // Voice Leading Connection
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        isAnimating = settings.isVoiceLeadingAnimationEnabled;

                        // Intelligent Polarity Logic:
                        // Instead of using global coordinates, we look at the relative step 
                        // on the specific Prime Axis of this line.
                        // Ideally, moving "positive" in the lattice (Right/Up) is Otonal.
                        // Moving "negative" (Left/Down) is Utonal.
                        // We check the midpoint of the prime coordinate.

                        const axisIndex = LIMIT_TO_INDEX[line.limit];
                        let isOtonal = true; // Default

                        if (axisIndex !== undefined) {
                            // Sum the specific prime coordinates
                            const sum = n1.coords[axisIndex] + n2.coords[axisIndex];
                            // If sum is >= 0, we are in the "Positive" (Otonal) half relative to origin/center
                            // If sum < 0, we are in the "Negative" (Utonal) half
                            if (sum < 0) isOtonal = false;
                        }

                        // Apply Contrast
                        // Otonal = Brighter, Utonal = Darker/Dimmer
                        // We use Opacity and Filters to achieve this instead of just color hex manipulation
                        // to ensure visibility against the dark background.

                        if (isOtonal) {
                             // Otonal Style: Bright, Projecting
                             animationClass = isAnimating ? 'animate-pulse-otonal' : '';
                             lineStyle = { 
                                filter: `brightness(${1 + settings.voiceLeadingContrast})`,
                             };
                        } else {
                             // Utonal Style: Deep, Receding
                             // We lower opacity slightly and reduce brightness, but not to black.
                             lineOpacity = Math.max(0.3, 1.0 - settings.voiceLeadingContrast); 
                             animationClass = isAnimating ? 'animate-pulse-utonal' : '';
                             lineStyle = {
                                filter: `brightness(${Math.max(0.4, 1.0 - settings.voiceLeadingContrast)}) saturate(0.8)`,
                             };
                        }

                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                        lineOpacity = 0.05;
                    }

                    return (
                        <line 
                            key={line.id}
                            x1={x1} y1={y1} x2={x2} y2={y2}
                            stroke={strokeColor}
                            strokeWidth={lineWidth}
                            strokeOpacity={lineOpacity}
                            strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                            className={animationClass}
                            style={lineStyle}
                        />
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = 1.3;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? 1.3 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                // Colored Illumination calculation
                let boxShadowColor = 'white';
                let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');

                if (settings.isColoredIlluminationEnabled) {
                     const phase = (top % rainbowPeriod) / rainbowPeriod;
                     const hue = (settings.rainbowOffset + phase * 360) % 360;

                     if (isLatched || isHovered) {
                         // Force deep saturation matching the rainbow or default max
                         const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
                         // Reduce lightness slightly to deepen the color appearance in glow
                         boxShadowColor = `hsl(${hue}, ${sat}%, 60%)`; 
                         borderColor = `hsl(${hue}, ${sat}%, 85%)`;
                     }
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isLatched ? `0 0 35px ${boxShadowColor}` : (isHovered ? `0 0 15px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)'),
                            zIndex: zIndex,
                            opacity: opacity,
                            border: settings.isColoredIlluminationEnabled && (isLatched || isHovered) ? `3px solid ${borderColor}` : (isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)')),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 20
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingAnimationSpeed: number; // seconds

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2Detune: number; // Cents
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';

  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -20; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    if (!n1 || !n2) return null;

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;

                    const n1Active = latchedNodes.has(n1.id);
                    const n2Active = latchedNodes.has(n2.id);

                    if (n1Active && n2Active) {
                        // Voice Leading Connection Active
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        strokeColor = 'white'; // Uniform bright color as requested
                        isVoiceLeadingActive = true;

                        // Directional Logic
                        // Determine flow direction based on coordinate magnitude on the prime axis
                        const axisIndex = LIMIT_TO_INDEX[line.limit];
                        if (axisIndex !== undefined) {
                            const c1 = n1.coords[axisIndex];
                            const c2 = n2.coords[axisIndex];

                            // Default: Low -> High (e.g. 1/1 -> 3/2)
                            let swap = c1 > c2;

                            // Handle Inversion setting
                            if (settings.voiceLeadingReverseDir) {
                                swap = !swap;
                            }

                            if (swap) {
                                // Swap coordinates to reverse SVG draw direction
                                const tempX = x1; const tempY = y1;
                                x1 = x2; y1 = y2;
                                x2 = tempX; y2 = tempY;
                            }
                        }

                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                        lineOpacity = 0.05;
                    }

                    return (
                        <g key={line.id}>
                            {/* Base Line */}
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                            />
                            {/* Animation Overlay */}
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={lineWidth}
                                    strokeOpacity={0.8}
                                    strokeDasharray="4 16" // Moving dots/spots
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = 1.3;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? 1.3 : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                // Colored Illumination calculation
                let boxShadowColor = 'white';
                let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');

                if (settings.isColoredIlluminationEnabled) {
                     const phase = (top % rainbowPeriod) / rainbowPeriod;
                     const hue = (settings.rainbowOffset + phase * 360) % 360;

                     if (isLatched || isHovered) {
                         // Force deep saturation matching the rainbow or default max
                         const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
                         // Reduce lightness slightly to deepen the color appearance in glow
                         boxShadowColor = `hsl(${hue}, ${sat}%, 60%)`; 
                         borderColor = `hsl(${hue}, ${sat}%, 85%)`;
                     }
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isLatched ? `0 0 35px ${boxShadowColor}` : (isHovered ? `0 0 15px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)'),
                            zIndex: zIndex,
                            opacity: opacity,
                            border: settings.isColoredIlluminationEnabled && (isLatched || isHovered) ? `3px solid ${borderColor}` : (isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)')),
                            filter: isActive ? 'brightness(1.3)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 20
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingAnimationSpeed: number; // seconds

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2Detune: number; // Cents
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';

  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -40; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    if (!n1 || !n2) return null;

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    const n1Active = latchedNodes.has(n1.id);
                    const n2Active = latchedNodes.has(n2.id);

                    if (n1Active && n2Active) {
                        // Voice Leading Connection Active
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        strokeColor = limitColor; // Keep limit color
                        isVoiceLeadingActive = true;

                        // Brighten effect for active lines
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };

                        // Directional Logic
                        // Determine flow direction based on coordinate magnitude on the prime axis
                        const axisIndex = LIMIT_TO_INDEX[line.limit];
                        if (axisIndex !== undefined) {
                            const c1 = n1.coords[axisIndex];
                            const c2 = n2.coords[axisIndex];

                            // Default: Low -> High (e.g. 1/1 -> 3/2)
                            let swap = c1 > c2;

                            // Handle Inversion setting
                            if (settings.voiceLeadingReverseDir) {
                                swap = !swap;
                            }

                            if (swap) {
                                // Swap coordinates to reverse SVG draw direction
                                const tempX = x1; const tempY = y1;
                                x1 = x2; y1 = y2;
                                x2 = tempX; y2 = tempY;
                            }
                        }

                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                        lineOpacity = 0.05;
                    }

                    return (
                        <g key={line.id}>
                            {/* Base Line - Colored */}
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {/* Animation Overlay - White moving pulses */}
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={lineWidth * 0.6}
                                    strokeOpacity={0.8}
                                    strokeLinecap="round"
                                    strokeDasharray="5 35" // "moving bright pulses" - short dash, long gap
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = settings.latchedZoomScale;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? settings.latchedZoomScale : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                // Colored Illumination calculation
                let boxShadowColor = 'white';
                let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');
                let borderStyle = isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)');

                if (settings.isColoredIlluminationEnabled) {
                     const phase = (top % rainbowPeriod) / rainbowPeriod;
                     const hue = (settings.rainbowOffset + phase * 360) % 360;
                     // Use settings saturation or max if rainbow mode off, but usually settings makes sense if consistent
                     const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;

                     // Visible active color for Outline
                     const activeColor = `hsl(${hue}, ${sat}%, 60%)`;

                     if (isActive) {
                        borderColor = activeColor;
                        // Tight matching shadow, not diffuse glow
                        boxShadowColor = activeColor;
                        borderStyle = `4px solid ${borderColor}`;
                     }
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isActive ? `0 0 10px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: opacity,
                            border: borderStyle,
                            filter: isActive ? 'brightness(1.1)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

