```javascript
import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import AudioEngine from './services/AudioEngine';
import { AppSettings, SynthPreset } from './types';
import { DEFAULT_COLORS, DEFAULT_SETTINGS, DEFAULT_PRESET } from './constants';

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [preset, setPreset] = useState<SynthPreset>(DEFAULT_PRESET);
  const [masterVolume, setMasterVolume] = useState(0.8);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Audio Engine Singleton Ref
  const engineRef = useRef<AudioEngine>(new AudioEngine(DEFAULT_PRESET));
  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Init Engine updates
  useEffect(() => {
    engineRef.current.setMasterVolume(masterVolume);
  }, [masterVolume]);

  const handleSettingsChange = (newSettings: AppSettings) => {
    setSettings(newSettings);
    // You'll need to update the TonalityDiamond here if the settings affect its behavior
    // For example, if 'settings.baseFrequency' changes, you might need to call diamondRef.current.updateBaseFrequency(newSettings.baseFrequency);
  };

  const handlePresetChange = (newPreset: SynthPreset) => {
    setPreset(newPreset);
    engineRef.current.setActivePreset(newPreset);
  };

  // UI Event Handlers
  const openSettings = () => setIsSettingsOpen(true);
  const closeSettings = () => setIsSettingsOpen(false);
  const openSynth = () => setIsSynthOpen(true);
  const closeSynth = () => setIsSynthOpen(false);
  const handleMasterVolumeChange = (newVolume: number) => {
    setMasterVolume(newVolume);
    engineRef.current.setMasterVolume(newVolume);
  };

  return (
    <div style={{ position: 'relative', width: '100vw', height: '100vh', overflow: 'hidden' }}>
      <SettingsModal isOpen={isSettingsOpen} onClose={closeSettings} settings={settings} onSettingsChange={handleSettingsChange} />
      <SynthControls isOpen={isSynthOpen} onClose={closeSynth} preset={preset} onPresetChange={handlePresetChange} />
      <TonalityDiamond
        ref={diamondRef}
        settings={settings}
        preset={preset}
        masterVolume={masterVolume}
        onMasterVolumeChange={handleMasterVolumeChange}
      />
      <FloatingControls
        openSettings={openSettings}
        openSynth={openSynth}
        masterVolume={masterVolume}
        onMasterVolumeChange={handleMasterVolumeChange}
      />
      <LimitLayerControls settings={settings} onSettingsChange={handleSettingsChange} />
    </div>
  );
};

export default App;
```

