export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface AppSettings {
  latticeShells: number; // 1 to 5
  enabledLimits: {
    7: boolean;
    11: boolean;
    13: boolean;
  };
  // Visible toggle for lower limits
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  maxND: number; // Complexity limit: Maximum Numerator or Denominator

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingAnimationSpeed: number; // seconds

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2Detune: number; // Cents
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';

  reverbMix: number; // 0 to 1
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import { SynthPreset, WaveformType } from '../types';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private dryGain: GainNode | null = null;

  // Voice map stores the graph for each active note
  private voices: Map<string, { 
    osc1: OscillatorNode; 
    osc2: OscillatorNode; 
    lfo: OscillatorNode;
    gain: GainNode; 
    filter: BiquadFilterNode; 
    startRatio: number 
  }> = new Map();

  private maxPolyphony: number = 12;
  private activePreset: SynthPreset;

  constructor(preset: SynthPreset) {
    this.activePreset = preset;
  }

  public init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
        latencyHint: 'interactive',
      });

      // Master Gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 1.0; 
      this.masterGain.connect(this.ctx.destination);

      // Reverb Setup
      this.reverbNode = this.ctx.createConvolver();
      this.reverbNode.buffer = this.createImpulseResponse(2.5, 2.0); // 2.5s duration, 2.0 decay

      this.reverbGain = this.ctx.createGain();
      this.reverbGain.gain.value = this.activePreset.reverbMix;

      this.dryGain = this.ctx.createGain();
      this.dryGain.gain.value = 1.0 - this.activePreset.reverbMix;

      // Routing
      // Voice -> Dry -> Master
      this.dryGain.connect(this.masterGain);

      // Voice -> ReverbGain -> Reverb -> Master
      this.reverbGain.connect(this.reverbNode);
      this.reverbNode.connect(this.masterGain);
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    const sampleRate = this.ctx!.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx!.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        // Simple noise decay
        left[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
        right[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
    }
    return impulse;
  }

  public setPolyphony(count: number) {
    this.maxPolyphony = count;
  }

  public setMasterVolume(val: number) {
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(val, this.ctx.currentTime, 0.05);
    }
  }

  public setPreset(preset: SynthPreset) {
    this.activePreset = preset;

    // Update Effects if initialized
    if (this.ctx) {
        if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(preset.reverbMix, this.ctx.currentTime, 0.1);
        if (this.dryGain) this.dryGain.gain.setTargetAtTime(1.0 - preset.reverbMix, this.ctx.currentTime, 0.1);
    }
  }

  public startVoice(id: string, ratio: number, baseFrequency: number) {
    this.init();
    if (!this.ctx || !this.dryGain || !this.reverbGain) return;

    // Restart logic
    if (this.voices.has(id)) {
        this.stopVoice(id, true);
    }

    // Voice stealing
    if (this.voices.size >= this.maxPolyphony) {
      const firstKey = this.voices.keys().next().value;
      if (firstKey !== undefined) this.stopVoice(firstKey, true); 
    }

    const now = this.ctx.currentTime;
    const baseFreq = baseFrequency * ratio;

    // --- Audio Graph Construction ---

    const masterVoiceGain = this.ctx.createGain(); // Envelope applied here
    const filter = this.ctx.createBiquadFilter();

    // Oscillator 1
    const osc1 = this.ctx.createOscillator();
    osc1.type = this.activePreset.waveform;
    osc1.frequency.value = baseFreq;

    // Oscillator 2
    const osc2 = this.ctx.createOscillator();
    osc2.type = this.activePreset.osc2Waveform;
    // Calculate Detune frequency
    // cents to ratio: 2^(cents/1200)
    const detuneMultiplier = Math.pow(2, this.activePreset.osc2Detune / 1200);
    osc2.frequency.value = baseFreq * detuneMultiplier;

    const osc2Gain = this.ctx.createGain();
    osc2Gain.gain.value = this.activePreset.osc2Mix;

    // LFO
    const lfo = this.ctx.createOscillator();
    lfo.type = 'sine';
    lfo.frequency.value = this.activePreset.lfoRate;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = this.activePreset.lfoDepth;

    // Connections
    osc1.connect(filter);

    osc2.connect(osc2Gain);
    osc2Gain.connect(filter);

    // Filter Settings
    filter.type = 'lowpass';
    filter.frequency.value = this.activePreset.filterCutoff;
    filter.Q.value = this.activePreset.filterResonance;

    filter.connect(masterVoiceGain);

    // LFO Routing
    if (this.activePreset.lfoTarget === 'pitch') {
        lfo.connect(lfoGain);
        lfoGain.connect(osc1.frequency);
        lfoGain.connect(osc2.frequency);
    } else if (this.activePreset.lfoTarget === 'filter') {
        lfo.connect(lfoGain);
        lfoGain.connect(filter.frequency);
    } else if (this.activePreset.lfoTarget === 'tremolo') {
        lfo.connect(lfoGain);
        lfoGain.connect(masterVoiceGain.gain);
    }

    // Output Routing
    masterVoiceGain.connect(this.dryGain);
    masterVoiceGain.connect(this.reverbGain);

    // --- Envelope Control ---
    masterVoiceGain.gain.setValueAtTime(0, now);
    masterVoiceGain.gain.linearRampToValueAtTime(this.activePreset.gain, now + this.activePreset.attack);
    masterVoiceGain.gain.exponentialRampToValueAtTime(Math.max(0.001, this.activePreset.gain * this.activePreset.sustain), now + this.activePreset.attack + this.activePreset.decay);

    // Start Oscillators
    osc1.start(now);
    osc2.start(now);
    lfo.start(now);

    this.voices.set(id, { osc1, osc2, lfo, gain: masterVoiceGain, filter, startRatio: ratio });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.ctx) return;
    const voice = this.voices.get(id);
    if (voice) {
      const now = this.ctx.currentTime;

      voice.gain.gain.cancelScheduledValues(now);
      voice.gain.gain.setValueAtTime(voice.gain.gain.value, now);

      const releaseTime = immediate ? 0.05 : this.activePreset.release;

      voice.gain.gain.exponentialRampToValueAtTime(0.001, now + releaseTime);

      // Cleanup schedule
      const stopTime = now + releaseTime + 0.1;
      voice.osc1.stop(stopTime);
      voice.osc2.stop(stopTime);
      voice.lfo.stop(stopTime);

      setTimeout(() => {
        // Disconnect everything to avoid memory leaks
        try {
            voice.osc1.disconnect();
            voice.osc2.disconnect();
            voice.lfo.disconnect();
            voice.gain.disconnect();
            voice.filter.disconnect();
        } catch(e) {
            // ignore disconnect errors if already disconnected
        }
      }, (releaseTime + 0.2) * 1000);

      this.voices.delete(id);
    }
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number, glideTime: number = 0.1) {
    const voice = this.voices.get(id);
    if (voice && this.ctx) {
       const newFreq = baseFrequency * newRatio;
       voice.osc1.frequency.setTargetAtTime(newFreq, this.ctx.currentTime, glideTime);

       const detuneMultiplier = Math.pow(2, this.activePreset.osc2Detune / 1200);
       voice.osc2.frequency.setTargetAtTime(newFreq * detuneMultiplier, this.ctx.currentTime, glideTime);

       voice.startRatio = newRatio; 
    }
  }

  public stopAll() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    this.voices.forEach((voice) => {
        try {
            voice.gain.gain.cancelScheduledValues(now);
            voice.gain.gain.setValueAtTime(0, now);
            voice.osc1.stop();
            voice.osc2.stop();
            voice.lfo.stop();
            voice.gain.disconnect();
        } catch (e) {
            console.error("Error stopping voice in panic", e);
        }
    });
    this.voices.clear();
  }
}

export default AudioEngine;

import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic for generation bounds
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

export const generateLattice = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const baseNodes: Map<string, { coords: number[], ratio: Fraction }> = new Map();
  const queue: { coords: number[], ratio: Fraction }[] = [];

  // 1. Generate Base Set (Normalized 1-2)
  const originCoords = [0, 0, 0, 0, 0];
  const originFrac = new Fraction(1, 1);
  queue.push({ coords: originCoords, ratio: originFrac });
  baseNodes.set(originCoords.join(','), { coords: originCoords, ratio: originFrac });

  const MAX_NODES = 2000;
  let processedCount = 0;

  while (queue.length > 0 && processedCount < MAX_NODES) {
    const current = queue.shift()!;
    processedCount++;
    const { coords, ratio } = current;

    PRIMES.forEach((prime, idx) => {
      if (prime === 7 && !settings.enabledLimits[7]) return;
      if (prime === 11 && !settings.enabledLimits[11]) return;
      if (prime === 13 && !settings.enabledLimits[13]) return;

      [1, -1].forEach(dir => {
        const nextPos = [...coords];
        nextPos[idx] += dir;
        const posKey = nextPos.join(',');

        if (!baseNodes.has(posKey)) {
          const dist = getHarmonicDistance(nextPos);
          if (dist < settings.latticeShells) {
             let nextRatio: Fraction;
             const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
             if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
             else {
                const invRatio = new Fraction(pRat.d, pRat.n);
                nextRatio = ratio.mul(invRatio).normalize();
             }

             if (nextRatio.n <= settings.maxND && nextRatio.d <= settings.maxND) {
                baseNodes.set(posKey, { coords: nextPos, ratio: nextRatio });
                queue.push({ coords: nextPos, ratio: nextRatio });
             }
          }
        }
      });
    });
  }

  // 2. Expand Vertically (Octaves)
  const OCTAVE_RANGE = 2; 
  const nodes: LatticeNode[] = [];
  const nodesMap: Map<string, LatticeNode> = new Map();

  baseNodes.forEach((data, key) => {
      for (let oct = -OCTAVE_RANGE; oct <= OCTAVE_RANGE; oct++) {
          const shiftedRatio = data.ratio.shiftOctave(oct);
          const absoluteRatio = shiftedRatio.n / shiftedRatio.d;

          const id = `${key}:${oct}`;

          let x = 0;
          x += data.coords[0] * X_VECTORS[3];
          x += data.coords[1] * X_VECTORS[5];
          x += data.coords[2] * X_VECTORS[7];
          x += data.coords[3] * X_VECTORS[11];
          x += data.coords[4] * X_VECTORS[13];

          // Apply Aspect Ratio Stretch/Squish
          // If Ratio is 2.0 (Squished), we divide X by 2.
          // If Ratio is 0.5 (Stretched), we divide X by 0.5 (Multiply by 2).
          x = x * (1.0 / settings.latticeAspectRatio);

          const PITCH_SCALE = 200; // Pixels per octave
          const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

          const limitTop = getMaxPrime(shiftedRatio.n);
          const limitBottom = getMaxPrime(shiftedRatio.d);
          const maxPrime = Math.max(limitTop, limitBottom);

          const node: LatticeNode = {
              id,
              coords: data.coords,
              ratio: absoluteRatio,
              n: shiftedRatio.n,
              d: shiftedRatio.d,
              label: `${shiftedRatio.n}/${shiftedRatio.d}`,
              x,
              y,
              limitTop,
              limitBottom,
              maxPrime,
              octave: oct
          };
          nodes.push(node);
          nodesMap.set(id, node);
      }
  });

  // 3. Generate Lines
  const lines: LatticeLine[] = [];

  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors
      PRIMES.forEach((prime, idx) => {
          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const key = neighborCoords.join(',');

          if (baseNodes.has(key)) {
             const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

             // Iterate nearby octaves
             for(let o = node.octave - 1; o <= node.octave + 1; o++) {
                 const targetId = `${key}:${o}`;
                 const target = nodesMap.get(targetId);

                 if (target) {
                      // Check for power-of-2 relationship relative to prime
                      // ratio / basePrimeRatio = 2^k
                      const ratio = target.ratio / node.ratio;
                      const test = ratio / basePrimeRatio;
                      const log2 = Math.log2(test);

                      // Allow small epsilon error
                      if (Math.abs(log2 - Math.round(log2)) < 0.001) {
                          lines.push({
                            id: `${node.id}-${target.id}`,
                            x1: node.x,
                            y1: node.y,
                            x2: target.x,
                            y2: target.y,
                            limit: prime
                          });
                      }
                 }
             }
          }
      });

      // Vertical Octave Connections
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1 // Octave "limit"
          });
      }
  });

  return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);
    const visibleNodes = result.nodes.filter(n => !settings.hiddenLimits.includes(n.maxPrime));
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));
    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio, settings.baseFrequency);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio, settings.baseFrequency);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio, settings.baseFrequency);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -40; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    if (!n1 || !n2) return null;

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    const n1Active = latchedNodes.has(n1.id);
                    const n2Active = latchedNodes.has(n2.id);

                    if (n1Active && n2Active) {
                        // Voice Leading Connection Active
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        strokeColor = limitColor; // Keep limit color
                        isVoiceLeadingActive = true;

                        // Brighten effect for active lines
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };

                        // Directional Logic
                        // Determine flow direction based on coordinate magnitude on the prime axis
                        const axisIndex = LIMIT_TO_INDEX[line.limit];
                        if (axisIndex !== undefined) {
                            const c1 = n1.coords[axisIndex];
                            const c2 = n2.coords[axisIndex];

                            // Default: Low -> High (e.g. 1/1 -> 3/2)
                            let swap = c1 > c2;

                            // Handle Inversion setting
                            if (settings.voiceLeadingReverseDir) {
                                swap = !swap;
                            }

                            if (swap) {
                                // Swap coordinates to reverse SVG draw direction
                                const tempX = x1; const tempY = y1;
                                x1 = x2; y1 = y2;
                                x2 = tempX; y2 = tempY;
                            }
                        }

                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                        lineOpacity = 0.05;
                    }

                    return (
                        <g key={line.id}>
                            {/* Base Line - Colored */}
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {/* Animation Overlay - White moving pulses */}
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={lineWidth * 0.6}
                                    strokeOpacity={0.8}
                                    strokeLinecap="round"
                                    strokeDasharray="5 35" // "moving bright pulses" - short dash, long gap
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = settings.latchedZoomScale;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? settings.latchedZoomScale : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                // Colored Illumination calculation
                let boxShadowColor = 'white';
                let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');
                let borderStyle = isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)');

                if (settings.isColoredIlluminationEnabled) {
                     const phase = (top % rainbowPeriod) / rainbowPeriod;
                     const hue = (settings.rainbowOffset + phase * 360) % 360;
                     // Use settings saturation or max if rainbow mode off, but usually settings makes sense if consistent
                     const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;

                     // Visible active color for Outline
                     const activeColor = `hsl(${hue}, ${sat}%, 60%)`;

                     if (isActive) {
                        borderColor = activeColor;
                        // Tight matching shadow, not diffuse glow
                        boxShadowColor = activeColor;
                        borderStyle = `4px solid ${borderColor}`;
                     }
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isActive ? `0 0 10px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: opacity,
                            border: borderStyle,
                            filter: isActive ? 'brightness(1.1)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useState } from 'react';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  onPanic: () => void;
  onCenter: () => void;
  pitchOffLocked: boolean;
  volumeLocked: boolean;
}

const FloatingControls: React.FC<Props> = ({ volume, setVolume, onPanic, onCenter, pitchOffLocked, volumeLocked }) => {
  const [panicPos, setPanicPos] = useState({ x: window.innerWidth - 120, y: window.innerHeight - 100 });
  const [volPos, setVolPos] = useState({ x: window.innerWidth / 2 - 100, y: window.innerHeight - 80 });
  const [centerPos, setCenterPos] = useState({ x: window.innerWidth / 2 - 25, y: 100 }); // Top center default

  const handleDrag = (e: React.PointerEvent, setPos: any, locked: boolean) => {
    if (locked) return;
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);

    const onMove = (evt: PointerEvent) => {
       setPos({ x: evt.clientX - el.clientWidth/2, y: evt.clientY - el.clientHeight/2 });
    };

    const onUp = () => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  return (
    <>
      {/* Volume Slider */}
      <div 
        className={`absolute bg-slate-800/80 p-3 rounded-full flex items-center gap-2 backdrop-blur border border-white/10 ${volumeLocked ? '' : 'cursor-move'}`}
        style={{ left: volPos.x, top: volPos.y, width: 200, zIndex: 150 }}
        onPointerDown={(e) => handleDrag(e, setVolPos, volumeLocked)}
      >
        <span className="text-xs font-bold text-slate-400">VOL</span>
        <input 
          type="range" min="0" max="1" step="0.01" 
          value={volume}
          onChange={(e) => setVolume(parseFloat(e.target.value))}
          className="w-full h-2 bg-slate-600 rounded-lg appearance-none cursor-pointer"
          onPointerDown={(e) => e.stopPropagation()} // Allow slider interaction without drag
        />
      </div>

      {/* Panic Button */}
      <button
        className={`absolute w-20 h-20 rounded-full bg-red-600/20 border-2 border-red-500 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-red-600/40 active:bg-red-600 active:text-white transition-all shadow-[0_0_15px_rgba(239,68,68,0.4)] ${pitchOffLocked ? '' : 'cursor-move'}`}
        style={{ left: panicPos.x, top: panicPos.y, zIndex: 150 }}
        onClick={onPanic}
        onPointerDown={(e) => handleDrag(e, setPanicPos, pitchOffLocked)}
      >
        Off
      </button>

      {/* Center View Button */}
      <button
        className={`absolute w-12 h-12 rounded bg-yellow-600/20 border-2 border-yellow-500 flex items-center justify-center text-yellow-500 font-bold backdrop-blur hover:bg-yellow-600/40 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.4)] cursor-move`}
        style={{ left: centerPos.x, top: centerPos.y, zIndex: 150 }}
        onClick={onCenter}
        onPointerDown={(e) => handleDrag(e, setCenterPos, false)}
        title="Center Display"
      >
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
          <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" />
        </svg>
      </button>
    </>
  );
};

export default FloatingControls;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import AudioEngine from './services/AudioEngine';
import { AppSettings, SynthPreset } from './types';
import { DEFAULT_COLORS, DEFAULT_SETTINGS, DEFAULT_PRESET } from './constants';

const App: React.FC = () => {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [preset, setPreset] = useState<SynthPreset>(DEFAULT_PRESET);
  const [masterVolume, setMasterVolume] = useState(0.8);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Audio Engine Singleton Ref
  const engineRef = useRef<AudioEngine>(new AudioEngine(DEFAULT_PRESET));
  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Init Engine updates
  useEffect(() => {
    engineRef.current.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    engineRef.current.setPreset(preset);
  }, [preset]);

  const handleLimitInteraction = (limit: number) => {
    // Move touched limit to the end of the array (front)
    // Only if it's not already at the front
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      setSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    engineRef.current.stopAll();
    diamondRef.current?.clearLatches();
  };

  const handleCenter = () => {
      diamondRef.current?.centerView();
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-center z-40 pointer-events-none">
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Synth
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Settings
          </button>
        </div>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings} 
        audioEngine={engineRef.current} 
        onLimitInteraction={handleLimitInteraction}
      />

      {/* Floating UI */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        onPanic={handlePanic}
        onCenter={handleCenter}
        pitchOffLocked={settings.pitchOffLocked}
        volumeLocked={settings.volumeLocked}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={setSettings}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={setSettings}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        preset={preset}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { AppSettings } from '../types';

interface Props {
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const LIMITS = [1, 3, 5, 7, 11, 13];

const LimitLayerControls: React.FC<Props> = ({ settings, updateSettings }) => {

  const isVisible = (limit: number) => {
    if (limit === 7) return settings.enabledLimits[7];
    if (limit === 11) return settings.enabledLimits[11];
    if (limit === 13) return settings.enabledLimits[13];
    return !settings.hiddenLimits.includes(limit);
  };

  const toggleVisibility = (limit: number) => {
    // Prevent hiding if only 2 or fewer limits are currently visible
    const activeCount = LIMITS.filter(l => isVisible(l)).length;

    // Check if we are trying to turn OFF a currently visible limit
    if (isVisible(limit)) {
        if (activeCount <= 2) return; // Prevent action
    }

    // For 7, 11, 13, we toggle 'enabledLimits' which affects generation (structure)
    if (limit === 7 || limit === 11 || limit === 13) {
      updateSettings({
        ...settings,
        enabledLimits: {
          ...settings.enabledLimits,
          [limit]: !settings.enabledLimits[limit as 7 | 11 | 13]
        }
      });
      return;
    }

    // For 1, 3, 5 we toggle 'hiddenLimits' which affects visual rendering
    const isHidden = settings.hiddenLimits.includes(limit);
    let newHidden = [...settings.hiddenLimits];
    if (isHidden) {
      newHidden = newHidden.filter(l => l !== limit);
    } else {
      newHidden.push(limit);
    }
    updateSettings({ ...settings, hiddenLimits: newHidden });
  };

  const bringToFront = (limit: number) => {
    const newOrder = settings.layerOrder.filter(l => l !== limit);
    newOrder.push(limit);
    updateSettings({ ...settings, layerOrder: newOrder });
  };

  return (
    <div className="absolute right-4 top-1/2 transform -translate-y-1/2 flex flex-col gap-3 z-40 bg-slate-900/50 p-2 rounded-xl backdrop-blur-sm border border-slate-700/50">
      {LIMITS.map(limit => {
        const visible = isVisible(limit);
        const color = settings.colors[limit];
        // Check if this limit is currently at the top of the stack
        const isTop = settings.layerOrder[settings.layerOrder.length - 1] === limit;

        // Disable toggle button visual state if strictly needed, though logic prevents it
        const activeCount = LIMITS.filter(l => isVisible(l)).length;
        const isDisabled = visible && activeCount <= 2;

        return (
          <div key={limit} className="flex items-center gap-2 group">
            {/* Visibility Toggle */}
            <button 
              onClick={() => toggleVisibility(limit)}
              disabled={isDisabled}
              className={`w-6 h-6 flex items-center justify-center rounded text-xs transition-colors ${visible ? (isDisabled ? 'text-slate-500 cursor-not-allowed' : 'text-white') : 'text-slate-600'} hover:bg-white/10`}
              title={isDisabled ? "Minimum 2 limits required" : `Toggle ${limit}-Limit`}
            >
               {visible ? (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                   <path d="M10 12.5a2.5 2.5 0 100-5 2.5 2.5 0 000 5z" />
                   <path fillRule="evenodd" d="M.664 10.59a1.651 1.651 0 010-1.186A10.004 10.004 0 0110 3c4.257 0 8.201 2.372 9.336 6.41.147.527.147 1.074 0 1.601C18.201 14.628 14.257 17 10 17c-4.257 0-8.201-2.372-9.336-6.41zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                 </svg>
               ) : (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                   <path fillRule="evenodd" d="M3.28 2.22a.75.75 0 00-1.06 1.06l14.5 14.5a.75.75 0 101.06-1.06l-1.745-1.745A10.029 10.029 0 0018 10c-1.135-4.038-5.079-6.41-9.336-6.41a9.982 9.982 0 00-4.636 1.135L3.28 2.22zm12.98 12.98l-3.212-3.212a3.003 3.003 0 00-4.244-4.244L5.68 4.62A11.967 11.967 0 00.664 9.41a1.651 1.651 0 010 1.18c1.135 4.038 5.079 6.41 9.336 6.41 2.053 0 4.008-.584 5.688-1.613l.572.572z" clipRule="evenodd" />
                   <path d="M10.983 7.796a1.5 1.5 0 012.122 2.122l-2.122-2.122z" />
                 </svg>
               )}
            </button>

            {/* Color/Select Layer Button */}
            <button 
              onClick={() => bringToFront(limit)}
              className={`w-10 h-10 rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-xs text-shadow`}
              style={{ 
                backgroundColor: color, 
                borderColor: isTop ? 'white' : 'transparent',
                boxShadow: isTop ? '0 0 10px rgba(255,255,255,0.5)' : 'none',
                opacity: visible ? 1 : 0.2
              }}
            >
              {limit}
            </button>
          </div>
        );
      })}
    </div>
  );
};

export default LimitLayerControls;

import React from 'react';
import { AppSettings } from '../types';

interface Props {
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const LIMITS = [1, 3, 5, 7, 11, 13];

const LimitLayerControls: React.FC<Props> = ({ settings, updateSettings }) => {

  const isVisible = (limit: number) => {
    // 1-Limit is always visible
    if (limit === 1) return true;
    if (limit === 7) return settings.enabledLimits[7];
    if (limit === 11) return settings.enabledLimits[11];
    if (limit === 13) return settings.enabledLimits[13];
    return !settings.hiddenLimits.includes(limit);
  };

  const toggleVisibility = (limit: number) => {
    // Prevent hiding 1-Limit
    if (limit === 1) return;

    // For 7, 11, 13, we toggle 'enabledLimits' which affects generation (structure)
    if (limit === 7 || limit === 11 || limit === 13) {
      updateSettings({
        ...settings,
        enabledLimits: {
          ...settings.enabledLimits,
          [limit]: !settings.enabledLimits[limit as 7 | 11 | 13]
        }
      });
      return;
    }

    // For 3, 5 we toggle 'hiddenLimits' which affects strict filtering
    const isHidden = settings.hiddenLimits.includes(limit);
    let newHidden = [...settings.hiddenLimits];
    if (isHidden) {
      newHidden = newHidden.filter(l => l !== limit);
    } else {
      newHidden.push(limit);
    }
    updateSettings({ ...settings, hiddenLimits: newHidden });
  };

  const bringToFront = (limit: number) => {
    const newOrder = settings.layerOrder.filter(l => l !== limit);
    newOrder.push(limit);
    updateSettings({ ...settings, layerOrder: newOrder });
  };

  return (
    <div className="absolute right-4 top-1/2 transform -translate-y-1/2 flex flex-col gap-3 z-40 bg-slate-900/50 p-2 rounded-xl backdrop-blur-sm border border-slate-700/50">
      {LIMITS.map(limit => {
        const visible = isVisible(limit);
        const color = settings.colors[limit];
        const isTop = settings.layerOrder[settings.layerOrder.length - 1] === limit;

        // 1-Limit cannot be toggled off
        const isLocked = limit === 1;

        return (
          <div key={limit} className="flex items-center gap-2 group">
            {/* Visibility Toggle */}
            <button 
              onClick={() => toggleVisibility(limit)}
              disabled={isLocked}
              className={`w-6 h-6 flex items-center justify-center rounded text-xs transition-colors ${visible ? (isLocked ? 'text-slate-500 cursor-default opacity-50' : 'text-white') : 'text-slate-600'} hover:bg-white/10`}
              title={isLocked ? "1-Limit is always enabled" : `Toggle ${limit}-Limit`}
            >
               {visible ? (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                   <path d="M10 12.5a2.5 2.5 0 100-5 2.5 2.5 0 000 5z" />
                   <path fillRule="evenodd" d="M.664 10.59a1.651 1.651 0 010-1.186A10.004 10.004 0 0110 3c4.257 0 8.201 2.372 9.336 6.41.147.527.147 1.074 0 1.601C18.201 14.628 14.257 17 10 17c-4.257 0-8.201-2.372-9.336-6.41zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                 </svg>
               ) : (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                   <path fillRule="evenodd" d="M3.28 2.22a.75.75 0 00-1.06 1.06l14.5 14.5a.75.75 0 101.06-1.06l-1.745-1.745A10.029 10.029 0 0018 10c-1.135-4.038-5.079-6.41-9.336-6.41a9.982 9.982 0 00-4.636 1.135L3.28 2.22zm12.98 12.98l-3.212-3.212a3.003 3.003 0 00-4.244-4.244L5.68 4.62A11.967 11.967 0 00.664 9.41a1.651 1.651 0 010 1.18c1.135 4.038 5.079 6.41 9.336 6.41 2.053 0 4.008-.584 5.688-1.613l.572.572z" clipRule="evenodd" />
                   <path d="M10.983 7.796a1.5 1.5 0 012.122 2.122l-2.122-2.122z" />
                 </svg>
               )}
            </button>

            {/* Color/Select Layer Button */}
            <button 
              onClick={() => bringToFront(limit)}
              className={`w-10 h-10 rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-xs text-shadow`}
              style={{ 
                backgroundColor: color, 
                borderColor: isTop ? 'white' : 'transparent',
                boxShadow: isTop ? '0 0 10px rgba(255,255,255,0.5)' : 'none',
                opacity: visible ? 1 : 0.2
              }}
            >
              {limit}
            </button>
          </div>
        );
      })}
    </div>
  );
};

export default LimitLayerControls;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track latched nodes
  const [latchedNodes, setLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  const [hasCentered, setHasCentered] = useState(false);

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    }
  }));

  useEffect(() => {
    const result = generateLattice(settings);

    // Strict Filtering Logic
    const visibleNodes = result.nodes.filter(n => {
        // Limit 3 (Index 0): Hide if settings say hide 3 AND node has a 3-component
        if (settings.hiddenLimits.includes(3) && n.coords[0] !== 0) return false;

        // Limit 5 (Index 1): Hide if settings say hide 5 AND node has a 5-component
        if (settings.hiddenLimits.includes(5) && n.coords[1] !== 0) return false;

        // Note: 7, 11, 13 are handled by enabledLimits in generation, preventing creation.
        // Limit 1 is always enabled.

        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings]);

  // Reactive Delatching Logic
  useEffect(() => {
    setLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                audioEngine.stopVoice(`node-${nodeId}`);
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     audioEngine.stopVoice(`node-${nodeId}`);
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes, audioEngine]);


  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
            audioEngine.stopVoice(`node-${nodeId}`);
        } else {
            newMap.set(nodeId, nodeId);
            audioEngine.startVoice(`node-${nodeId}`, ratio, settings.baseFrequency);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          audioEngine.startVoice(`node-${nodeId}`, ratio, settings.baseFrequency);
          return newMap;
      });
  };

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio, settings.baseFrequency);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: node.id
            });
            return next;
        });
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!latchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (latchedNodes.has(cursor.originNodeId)) {
                 setLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                     return next;
                 });
             }
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => latchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -40; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.1 && Math.abs(n.y - line.y1) < 0.1);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.1 && Math.abs(n.y - line.y2) < 0.1);

                    if (!n1 || !n2) return null;

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    const n1Active = latchedNodes.has(n1.id);
                    const n2Active = latchedNodes.has(n2.id);

                    if (n1Active && n2Active) {
                        // Voice Leading Connection Active
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        strokeColor = limitColor; // Keep limit color
                        isVoiceLeadingActive = true;

                        // Brighten effect for active lines
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };

                        // Directional Logic
                        // Determine flow direction based on coordinate magnitude on the prime axis
                        const axisIndex = LIMIT_TO_INDEX[line.limit];
                        if (axisIndex !== undefined) {
                            const c1 = n1.coords[axisIndex];
                            const c2 = n2.coords[axisIndex];

                            // Default: Low -> High (e.g. 1/1 -> 3/2)
                            let swap = c1 > c2;

                            // Handle Inversion setting
                            if (settings.voiceLeadingReverseDir) {
                                swap = !swap;
                            }

                            if (swap) {
                                // Swap coordinates to reverse SVG draw direction
                                const tempX = x1; const tempY = y1;
                                x1 = x2; y1 = y2;
                                x2 = tempX; y2 = tempY;
                            }
                        }

                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                        lineOpacity = 0.05;
                    }

                    return (
                        <g key={line.id}>
                            {/* Base Line - Colored */}
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {/* Animation Overlay - White moving pulses */}
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={lineWidth * 0.6}
                                    strokeOpacity={0.8}
                                    strokeLinecap="round"
                                    strokeDasharray="5 35" // "moving bright pulses" - short dash, long gap
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}

                {cursors.map(cursor => {
                    const node = data.nodes.find(n => n.id === cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = latchedNodes.has(node.id);
                const isHovered = cursors.some(c => c.originNodeId === node.id); 
                const isActive = isLatched || isHovered;

                const left = node.x * spacing + centerOffset;
                const top = node.y * spacing + centerOffset;

                const cTop = getColor(node.limitTop);
                const cBottom = getColor(node.limitBottom);
                const background = `linear-gradient(to bottom, ${cTop} 50%, ${cBottom} 50%)`;

                const layerIndex = settings.layerOrder.indexOf(node.maxPrime);
                const zIndex = isActive ? 80 : (10 + layerIndex);

                let scale = 1.0;
                let opacity = 0.95;

                if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                    if (isActive) {
                        scale = settings.latchedZoomScale;
                        opacity = 1.0;
                    } else {
                        // Unified Voice Leading Logic
                        const allowedMaxIndex = settings.latchShellLimit - 2; 
                        let isCompatible = false;
                        let minDist = Infinity;

                        for (const activeNode of activeNodes) {
                             let valid = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                                 if (hDist > 0) valid = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         valid = false;
                                         break;
                                     }
                                 }
                             }

                             if (valid) {
                                isCompatible = true;
                                const d = getHarmonicDistance(node.coords, activeNode.coords);
                                if (d < minDist) minDist = d;
                             }
                        }

                        if (!isCompatible) {
                            opacity = 0.15; 
                            scale = 0.4;
                        } else {
                             const falloff = settings.voiceLeadingStrength; 
                             const visibility = Math.max(0.15, 1 - (minDist * falloff));
                             scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                             opacity = visibility;
                        }
                    }
                } else {
                    scale = isActive ? settings.latchedZoomScale : 1.0;
                    opacity = isActive ? 1.0 : 0.95;
                }

                // Colored Illumination calculation
                let boxShadowColor = 'white';
                let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');
                let borderStyle = isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)');

                if (settings.isColoredIlluminationEnabled) {
                     const phase = (top % rainbowPeriod) / rainbowPeriod;
                     const hue = (settings.rainbowOffset + phase * 360) % 360;
                     // Use settings saturation or max if rainbow mode off, but usually settings makes sense if consistent
                     const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;

                     // Visible active color for Outline
                     const activeColor = `hsl(${hue}, ${sat}%, 60%)`;

                     if (isActive) {
                        borderColor = activeColor;
                        // Tight matching shadow, not diffuse glow
                        boxShadowColor = activeColor;
                        borderStyle = `4px solid ${borderColor}`;
                     }
                }

                return (
                    <div
                        key={node.id}
                        className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
                        style={{
                            left: `${left}px`,
                            top: `${top}px`,
                            width: `${baseSize}px`,
                            height: `${baseSize}px`,
                            background: background,
                            borderRadius: settings.buttonShape,
                            transform: `translate(-50%, -50%) scale(${scale})`,
                            boxShadow: isActive ? `0 0 10px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)',
                            zIndex: zIndex,
                            opacity: opacity,
                            border: borderStyle,
                            filter: isActive ? 'brightness(1.1)' : 'none'
                        }}
                        onPointerDown={(e) => handlePointerDown(e, node)}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                        onPointerCancel={handlePointerUp}
                    >
                        <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                            <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                            <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
                        </div>
                    </div>
                );
            })}
        </div>
    </div>
  );
});

