import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic for generation bounds
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

export const generateLattice = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const baseNodes: Map<string, { coords: number[], ratio: Fraction }> = new Map();
  const queue: { coords: number[], ratio: Fraction }[] = [];

  // 1. Generate Base Set (Normalized 1-2)
  const originCoords = [0, 0, 0, 0, 0];
  const originFrac = new Fraction(1, 1);
  queue.push({ coords: originCoords, ratio: originFrac });
  baseNodes.set(originCoords.join(','), { coords: originCoords, ratio: originFrac });

  const MAX_NODES = 2500;
  let processedCount = 0;

  while (queue.length > 0 && processedCount < MAX_NODES) {
    const current = queue.shift()!;
    processedCount++;
    const { coords, ratio } = current;

    PRIMES.forEach((prime, idx) => {
      // Check depth for this specific prime axis (Coordinate bounds)
      const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
      if (depthLimit <= 0) return;

      // Check complexity limit for this specific prime axis (Ratio bounds)
      const complexityLimit = settings.limitComplexities[prime as 3|5|7|11|13];

      [1, -1].forEach(dir => {
        const nextPos = [...coords];
        nextPos[idx] += dir;

        // Strict axis checking:
        // Do not generate if we exceeded the depth for this specific axis relative to origin (0)
        if (Math.abs(nextPos[idx]) > depthLimit) return;

        const posKey = nextPos.join(',');

        if (!baseNodes.has(posKey)) {
             let nextRatio: Fraction;
             const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
             if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
             else {
                const invRatio = new Fraction(pRat.d, pRat.n);
                nextRatio = ratio.mul(invRatio).normalize();
             }

             // Enforce per-limit complexity
             if (nextRatio.n <= complexityLimit && nextRatio.d <= complexityLimit) {
                baseNodes.set(posKey, { coords: nextPos, ratio: nextRatio });
                queue.push({ coords: nextPos, ratio: nextRatio });
             }
        }
      });
    });
  }

  // 2. Expand Vertically (Octaves)
  const OCTAVE_RANGE = 2; 
  const nodes: LatticeNode[] = [];
  const nodesMap: Map<string, LatticeNode> = new Map();

  baseNodes.forEach((data, key) => {
      for (let oct = -OCTAVE_RANGE; oct <= OCTAVE_RANGE; oct++) {
          const shiftedRatio = data.ratio.shiftOctave(oct);
          const absoluteRatio = shiftedRatio.n / shiftedRatio.d;

          const id = `${key}:${oct}`;

          let x = 0;
          x += data.coords[0] * X_VECTORS[3];
          x += data.coords[1] * X_VECTORS[5];
          x += data.coords[2] * X_VECTORS[7];
          x += data.coords[3] * X_VECTORS[11];
          x += data.coords[4] * X_VECTORS[13];

          // Apply Aspect Ratio Stretch/Squish
          x = x * (1.0 / settings.latticeAspectRatio);

          const PITCH_SCALE = 200; // Pixels per octave
          const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

          const limitTop = getMaxPrime(shiftedRatio.n);
          const limitBottom = getMaxPrime(shiftedRatio.d);
          const maxPrime = Math.max(limitTop, limitBottom);

          const node: LatticeNode = {
              id,
              coords: data.coords,
              ratio: absoluteRatio,
              n: shiftedRatio.n,
              d: shiftedRatio.d,
              label: `${shiftedRatio.n}/${shiftedRatio.d}`,
              x,
              y,
              limitTop,
              limitBottom,
              maxPrime,
              octave: oct
          };
          nodes.push(node);
          nodesMap.set(id, node);
      }
  });

  // 3. Generate Lines
  const lines: LatticeLine[] = [];

  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors
      PRIMES.forEach((prime, idx) => {
          // If the limit is "disabled" via depth 0, don't draw lines for it
          if (settings.limitDepths[prime as 3|5|7|11|13] <= 0) return;

          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const key = neighborCoords.join(',');

          if (baseNodes.has(key)) {
             const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

             // Iterate nearby octaves
             for(let o = node.octave - 1; o <= node.octave + 1; o++) {
                 const targetId = `${key}:${o}`;
                 const target = nodesMap.get(targetId);

                 if (target) {
                      const ratio = target.ratio / node.ratio;
                      const test = ratio / basePrimeRatio;
                      const log2 = Math.log2(test);

                      if (Math.abs(log2 - Math.round(log2)) < 0.001) {
                          lines.push({
                            id: `${node.id}-${target.id}`,
                            x1: node.x,
                            y1: node.y,
                            x2: target.x,
                            y2: target.y,
                            limit: prime
                          });
                      }
                 }
             }
          }
      });

      // Vertical Octave Connections
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1 // Octave "limit"
          });
      }
  });

  return { nodes, lines };
};

import React, { useRef, useState } from 'react';
import { AppSettings, ButtonShape } from '../types';
import { DEFAULT_COLORS } from '../constants';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'behavior' | 'color'>('general');

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleLimitDepthChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitDepths: {
        ...settings.limitDepths,
        [limit]: val
      }
    });
  };

  const handleLimitComplexityChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitComplexities: {
        ...settings.limitComplexities,
        [limit]: val
      }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

  const resetColors = () => {
    updateSettings({ ...settings, colors: { ...DEFAULT_COLORS } });
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const pairLimitColors = () => {
     const ratios: {[key: number]: number} = {
         1: 1,
         3: 1.5,
         5: 1.25,
         7: 7/8,
         11: 11/8,
         13: 13/8
     };

     const newColors = { ...settings.colors };
     const offset = settings.rainbowOffset;

     Object.keys(ratios).forEach(k => {
         const key = parseInt(k);
         const ratio = ratios[key];
         const shift = -Math.log2(ratio) * 360;
         let hue = (offset + shift) % 360;
         if (hue < 0) hue += 360;

         newColors[key] = hslToHex(hue, 70, 60); 
     });

     updateSettings({ ...settings, colors: newColors });
  };

  const canvasSizes = Array.from({length: 15}, (_, i) => 1000 + i * 500);

  return (
    <div className="fixed inset-0 bg-black/80 z-[200] flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-800 rounded-xl w-[95%] max-w-4xl max-h-[90vh] overflow-hidden text-slate-200 shadow-2xl border border-slate-700 flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-slate-700 bg-slate-800">
          <h2 className="text-2xl font-bold text-white">Lattice Configuration</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white px-3 py-1 bg-slate-700 rounded transition">Close</button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-700 bg-slate-900/50">
           <button 
             onClick={() => setActiveTab('general')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'general' ? 'text-blue-400 border-b-2 border-blue-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Dimensions
           </button>
           <button 
             onClick={() => setActiveTab('behavior')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'behavior' ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Behavior
           </button>
           <button 
             onClick={() => setActiveTab('color')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'color' ? 'text-pink-400 border-b-2 border-pink-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Color
           </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto flex-1 bg-slate-800">

            {/* --- General Tab --- */}
            {activeTab === 'general' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-300">
                  <div className="space-y-6">
                      <h3 className="font-semibold text-blue-400 border-b border-slate-700 pb-1">Grid Structure</h3>

                      <div>
                          <label className="block text-sm font-semibold mb-2">Base Frequency (1/1)</label>
                          <div className="flex items-center gap-4">
                              <input 
                                  type="range" min="20" max="15000" step="1" 
                                  value={settings.baseFrequency}
                                  onChange={(e) => handleChange('baseFrequency', parseFloat(e.target.value))}
                                  className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                              />
                              <span className="text-sm font-mono min-w-[5ch]">{settings.baseFrequency}Hz</span>
                          </div>
                      </div>

                      <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3">
                          <label className="block text-sm font-semibold text-slate-300">Lattice Depths (Coordinate Bounds)</label>
