// LatticeService.ts
const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

const lcm = (a: number, b: number): number => (a * b) / gcd(a, b);

// Function to find the greatest common factor and the least common multiple of a given array of numbers.
// In this case, we're not using any array, but we are keeping the type signature for compatibility
// (not calling it directly from this file)
const getCommonFactorAndMultiple = (numbers: number[]): { commonFactor: number; commonMultiple: number } => {
    let commonFactor = numbers[0];
    let commonMultiple = numbers[0];

    for (let i = 1; i < numbers.length; i++) {
        commonFactor = gcd(commonFactor, numbers[i]);
        commonMultiple = lcm(commonMultiple, numbers[i]);
    }

    return { commonFactor, commonMultiple };
};

// Function to find prime factors of a number
const primeFactors = (num: number): number[] => {
    const factors: number[] = [];
    let divisor = 2;

    while (num >= 2) {
        if (num % divisor === 0) {
            factors.push(divisor);
            num = num / divisor;
        } else {
            divisor++;
        }
    }
    return factors;
};

// Function to get all unique prime factors from a set of numbers
const getUniquePrimeFactors = (numbers: number[]): number[] => {
    const allFactors: number[] = numbers.reduce((acc, num) => {
        return acc.concat(primeFactors(num));
    }, []);

    // Remove duplicates using Set and convert back to array
    return [...new Set(allFactors)];
};

// Function to determine if a number is prime
const isPrime = (num: number): boolean => {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 === 0 || num % 3 === 0) return false;

    for (let i = 5; i * i <= num; i = i + 6) {
        if (num % i === 0 || num % (i + 2) === 0) return false;
    }
    return true;
};

// Function to find the maximum prime number in a set of numbers
export const getMaxPrime = (numbers: number[]): number | null => {
    let maxPrime: number | null = null;
    numbers.forEach((num) => {
        if (isPrime(num)) {
            if (maxPrime === null || num > maxPrime) {
                maxPrime = num;
            }
        }
    });
    return maxPrime;
};
