import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

export const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic for generation bounds
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

// Helper to calculate the absolute ratio of a coordinate set starting from 1/1
const calculateRatioFromCoords = (coords: number[]): Fraction => {
    let ratio = new Fraction(1, 1);

    PRIMES.forEach((prime, idx) => {
        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
        const val = coords[idx];
        if (val === 0) return;

        for(let i=0; i < Math.abs(val); i++) {
             if (val > 0) ratio = ratio.mul(pRat).normalize();
             else {
                 const invRatio = new Fraction(pRat.d, pRat.n);
                 ratio = ratio.mul(invRatio).normalize();
             }
        }
    });
    return ratio;
};

export const generateLattice = (settings: AppSettings, generationOrigins: number[][] = [[0,0,0,0,0]]): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  // We use a Map to aggregate nodes from all generation origins, keyed by their coordinate signature.
  // This handles overlap (nodes generated by multiple centers) automatically.
  const baseNodes: Map<string, { coords: number[], ratio: Fraction }> = new Map();

  // Iterate through each origin and generate a local lattice cluster
  generationOrigins.forEach(origin => {
      const queue: { coords: number[], ratio: Fraction }[] = [];
      const originFrac = calculateRatioFromCoords(origin);

      const originKey = origin.join(',');
      if (!baseNodes.has(originKey)) {
          baseNodes.set(originKey, { coords: origin, ratio: originFrac });
      }
      queue.push({ coords: origin, ratio: originFrac });

      const MAX_LOCAL_NODES = 1500; // Limit per cluster to prevent explosion
      let processedCount = 0;

      const visitedLocal = new Set<string>();
      visitedLocal.add(originKey);

      while (queue.length > 0 && processedCount < MAX_LOCAL_NODES) {
        const current = queue.shift()!;
        processedCount++;
        const { coords, ratio } = current;

        PRIMES.forEach((prime, idx) => {
          // Check depth for this specific prime axis (Coordinate bounds)
          const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
          if (depthLimit <= 0) return;

          // Check complexity limit for this specific prime axis (Ratio bounds)
          const complexityLimit = settings.limitComplexities[prime as 3|5|7|11|13];

          [1, -1].forEach(dir => {
            const nextPos = [...coords];
            nextPos[idx] += dir;

            // Strict axis checking RELATIVE to current local origin
            if (Math.abs(nextPos[idx] - origin[idx]) > depthLimit) return;

            const posKey = nextPos.join(',');

            if (!visitedLocal.has(posKey)) {
                visitedLocal.add(posKey);

                 let nextRatio: Fraction;
                 const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                 if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
                 else {
                    const invRatio = new Fraction(pRat.d, pRat.n);
                    nextRatio = ratio.mul(invRatio).normalize();
                 }

                 // Enforce per-limit complexity (Absolute check)
                 // Note: With "Increase Depth", high limits might exceed this complexity.
                 // However, we still enforce it to prevent the UI from freezing with massive numbers.
                 // Users can increase the complexity limit in settings if they want deeper exploration.
                 if (nextRatio.n <= complexityLimit && nextRatio.d <= complexityLimit) {
                    if (!baseNodes.has(posKey)) {
                        baseNodes.set(posKey, { coords: nextPos, ratio: nextRatio });
                    }
                    queue.push({ coords: nextPos, ratio: nextRatio });
                 }
            }
          });
        });
      }
  });

  // 2. Expand Vertically (Octaves)
  const OCTAVE_RANGE = 2; 
  const nodes: LatticeNode[] = [];
  const nodesMap: Map<string, LatticeNode> = new Map();

  baseNodes.forEach((data, key) => {
      for (let oct = -OCTAVE_RANGE; oct <= OCTAVE_RANGE; oct++) {
          const shiftedRatio = data.ratio.shiftOctave(oct);
          const absoluteRatio = shiftedRatio.n / shiftedRatio.d;

          const id = `${key}:${oct}`;

          let x = 0;
          x += data.coords[0] * X_VECTORS[3];
          x += data.coords[1] * X_VECTORS[5];
          x += data.coords[2] * X_VECTORS[7];
          x += data.coords[3] * X_VECTORS[11];
          x += data.coords[4] * X_VECTORS[13];

          // Apply Aspect Ratio Stretch/Squish
          x = x * (1.0 / settings.latticeAspectRatio);

          const PITCH_SCALE = 200; // Pixels per octave
          const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

          const limitTop = getMaxPrime(shiftedRatio.n);
          const limitBottom = getMaxPrime(shiftedRatio.d);
          const maxPrime = Math.max(limitTop, limitBottom);

          const node: LatticeNode = {
              id,
              coords: data.coords,
              ratio: absoluteRatio,
              n: shiftedRatio.n,
              d: shiftedRatio.d,
              label: `${shiftedRatio.n}/${shiftedRatio.d}`,
              x,
              y,
              limitTop,
              limitBottom,
              maxPrime,
              octave: oct
          };
          nodes.push(node);
          nodesMap.set(id, node);
      }
  });

  // 3. Generate Lines
  const lines: LatticeLine[] = [];

  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors
      PRIMES.forEach((prime, idx) => {
          // If the limit is "disabled" via depth 0, don't draw lines for it
          if (settings.limitDepths[prime as 3|5|7|11|13] <= 0) return;

          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const key = neighborCoords.join(',');

          if (baseNodes.has(key)) {
             const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

             // Iterate nearby octaves
             for(let o = node.octave - 1; o <= node.octave + 1; o++) {
                 const targetId = `${key}:${o}`;
                 const target = nodesMap.get(targetId);

                 if (target) {
                      const ratio = target.ratio / node.ratio;
                      const test = ratio / basePrimeRatio;
                      const log2 = Math.log2(test);

                      if (Math.abs(log2 - Math.round(log2)) < 0.001) {
                          lines.push({
                            id: `${node.id}-${target.id}`,
                            x1: node.x,
                            y1: node.y,
                            x2: target.x,
                            y2: target.y,
                            limit: prime
                          });
                      }
                 }
             }
          }
      });

      // Vertical Octave Connections
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1 // Octave "limit"
          });
      }
  });

  return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ChordDefinition } from '../types';
import { generateLattice, getHarmonicDistance, getMaxPrime } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

interface Transposition {
    ratio: number;
    sourceNodeId: string;
    targetNodeId: string;
}

interface ChordDriver {
  pointerId: number;
  startY: number; // Screen Y
  startRatio: number; // Transposition ratio at start
  currentTargetNodeId?: string;
}

const PITCH_SCALE = 200; // Pixels per octave

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track manually latched nodes (clicked by user)
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track the actual effective latched nodes (manual + chords)
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  // Track the origins for depth generation (Array of coordinate arrays)
  const [depthOrigins, setDepthOrigins] = useState<number[][]>([[0,0,0,0,0]]);

  // Track last touched node for Increasing Depth
  const [lastTouchedNodeCoords, setLastTouchedNodeCoords] = useState<number[] | null>(null);

  const [hasCentered, setHasCentered] = useState(false);

  const prevActiveChordIds = useRef<string[]>([]);

  // Chord Slide State Refs
  const chordTouchMap = useRef<Map<string, Set<number>>>(new Map()); // chordId -> Set<pointerId>
  const chordDriverMap = useRef<Map<string, ChordDriver>>(new Map());

  // Secondary Latch State: Stores the transposition for each chord
  const [chordTranspositions, setChordTranspositions] = useState<Map<string, Transposition>>(new Map());

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([[0,0,0,0,0]]);
            setLastTouchedNodeCoords(null);
        }

        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNodeCoords) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => o.every((val, i) => val === lastTouchedNodeCoords[i]));
                if (exists) return prev;
                return [...prev, [...lastTouchedNodeCoords]];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  useEffect(() => {
    // Pass the depthOrigins array to generation service
    const result = generateLattice(settings, depthOrigins);

    // Strict Filtering Logic based on hiddenLimits for VISIBILITY
    const visibleNodes = result.nodes.filter(n => {
        // Check all hidden limits
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings, depthOrigins]);

  // Clean up transpositions for deactivated chords
  useEffect(() => {
     setChordTranspositions(prev => {
         const next = new Map(prev);
         let changed = false;
         for (const key of next.keys()) {
             if (!activeChordIds.includes(key)) {
                 next.delete(key);
                 changed = true;
             }
         }
         return changed ? next : prev;
     });
  }, [activeChordIds]);

  // Combine Manual Latches + Active Chords to determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            const transposition = chordTranspositions.get(chordId)?.ratio || 1.0;

            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id); 
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     const ratioMult = chordTranspositions.get(chordId)?.ratio || 1.0;
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio * ratioMult, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency, chordTranspositions]);

  // Sync voices
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());

  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Start new notes
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   // Calculate if this node belongs to a transposed chord
                   let multiplier = 1.0;
                   const ownerChord = settings.savedChords.find(c => activeChordIds.includes(c.id) && c.nodes.some(cn => cn.id === nodeId));
                   if (ownerChord) {
                       multiplier = chordTranspositions.get(ownerChord.id)?.ratio || 1.0;
                   }

                   audioEngine.startVoice(`node-${nodeId}`, node.ratio * multiplier, settings.baseFrequency);
               }
          }
      });

      // Stop removed notes
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine, chordTranspositions, activeChordIds, settings.savedChords]);

  // Reactive Delatching Logic 
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Helpers ---

  const getActiveChordsForNode = (nodeId: string) => {
    return settings.savedChords.filter(c => 
        activeChordIds.includes(c.id) && c.nodes.some(n => n.id === nodeId)
    );
  };

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // --- Handlers ---

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNodeCoords(node.coords);

    // Track active cursors
    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    // --- Chord Slide Logic ---
    let suppressStandardInteraction = false;
    const activeChordsForNode = getActiveChordsForNode(node.id);

    if (settings.isChordSlideEnabled && activeChordsForNode.length > 0) {
        activeChordsForNode.forEach(chord => {
            let touches = chordTouchMap.current.get(chord.id);
            if (!touches) {
                touches = new Set();
                chordTouchMap.current.set(chord.id, touches);
            }
            touches.add(e.pointerId);

            const count = touches.size;

            if (count >= settings.chordSlideTrigger) {
                 suppressStandardInteraction = true;

                 if (!chordDriverMap.current.has(chord.id)) {
                     const currentTrans = chordTranspositions.get(chord.id)?.ratio || 1.0;
                     chordDriverMap.current.set(chord.id, { 
                         pointerId: e.pointerId, 
                         startY: e.clientY,
                         startRatio: currentTrans
                     });
                 }
            } else if (settings.fixLatchedChords) {
                 suppressStandardInteraction = true;
            }
        });
    }

    if (suppressStandardInteraction) return;

    // Toggle Logic
    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        let multiplier = 1.0;
        if (activeChordsForNode.length > 0) {
             const chordId = activeChordsForNode[0].id; 
             multiplier = chordTranspositions.get(chordId)?.ratio || 1.0;
        }
        audioEngine.startVoice(cursorId, node.ratio * multiplier, settings.baseFrequency);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    const spacing = settings.buttonSpacingScale;
    const centerOffset = settings.canvasSize / 2;
    const scrollLeft = scrollContainerRef.current?.scrollLeft || 0;
    const scrollTop = scrollContainerRef.current?.scrollTop || 0;

    // --- Chord Slide Move Logic ---
    let isDrivingChord = false;
    if (settings.isChordSlideEnabled) {
        chordDriverMap.current.forEach((driver, chordId) => {
            if (driver.pointerId === e.pointerId) {
                isDrivingChord = true;

                // Calculate absolute pitch ratio at finger location (matches regular pitch bend)
                const canvasY = e.clientY + scrollTop;
                const relY = canvasY - centerOffset;
                const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;

                // The pitch at the finger's tip on the absolute scale
                const fingerRatio = Math.pow(2, -relY / effectivePitchScale);

                // Find the source node (driver node) to determine how much to shift the WHOLE chord
                // The cursor tracks which node originated this interaction
                const activeCursor = (Array.from(activeCursors.values()) as ActiveCursor[]).find(c => c.pointerId === driver.pointerId);
                const sourceNode = data.nodes.find(n => n.id === activeCursor?.originNodeId);

                let totalRatio = driver.startRatio;

                if (sourceNode) {
                    // Shift = (Target Ratio where finger is) / (Original Ratio of dragged node)
                    totalRatio = fingerRatio / sourceNode.ratio;
                }

                // Secondary Latch Target Detection
                let hoveredNodeId: string | undefined = undefined;
                if ((settings as any).isSecondaryChordLatchEnabled) {
                     // Check if dragging finger is over a node
                     const radiusSq = Math.pow((60 * settings.buttonSizeScale) / 2, 2);
                     for (const node of data.nodes) {
                         const nx = (node.x * spacing + centerOffset) - scrollLeft;
                         const ny = (node.y * spacing + centerOffset) - scrollTop;
                         const dx = e.clientX - nx;
                         const dy = e.clientY - ny;
                         if (dx*dx + dy*dy < radiusSq) {
                             hoveredNodeId = node.id;
                             break;
                         }
                     }
                }

                driver.currentTargetNodeId = hoveredNodeId;
                // Force re-render for ghost line
                setActiveCursors(prev => new Map(prev)); 

                // Apply audio bend to all nodes in chord
                const chordDef = settings.savedChords.find(c => c.id === chordId);
                if (chordDef) {
                    chordDef.nodes.forEach(cn => {
                         const fullNode = data.nodes.find(n => n.id === cn.id);
                         if (fullNode) {
                            audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * totalRatio, settings.baseFrequency, 0.05);
                         }
                    });
                }
            }
        });
    }

    if (isDrivingChord) return;

    if (settings.isPitchBendEnabled) {
        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNodeCoords(node.coords);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (settings.isChordSlideEnabled) {
        const spacing = settings.buttonSpacingScale;
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current?.scrollLeft || 0;
        const scrollTop = scrollContainerRef.current?.scrollTop || 0;
        const radiusSq = Math.pow((60 * settings.buttonSizeScale) / 2, 2);

        chordTouchMap.current.forEach((touches, chordId) => {
            if (touches.has(e.pointerId)) {
                touches.delete(e.pointerId);

                const driver = chordDriverMap.current.get(chordId);
                if (driver && driver.pointerId === e.pointerId) {
                    chordDriverMap.current.delete(chordId);

                    let newTranspositionRatio = driver.startRatio; 
                    let foundTarget = false;
                    let sourceNodeId = '';
                    let targetNodeId = '';

                    if ((settings as any).isSecondaryChordLatchEnabled) {
                        // Find the source node (where drag started)
                        const cursor = (Array.from(activeCursors.values()) as ActiveCursor[]).find((c: ActiveCursor) => c.pointerId === e.pointerId);

                        if (cursor) {
                            const originNode = data.nodes.find(n => n.id === cursor.originNodeId);

                            // Find target node (where dropped)
                            for (const node of data.nodes) {
                                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                                const ny = (node.y * spacing + centerOffset) - scrollTop;
                                const dx = e.clientX - nx;
                                const dy = e.clientY - ny;

                                if (dx*dx + dy*dy < radiusSq) {
                                    if (originNode) {
                                        newTranspositionRatio = node.ratio / originNode.ratio;
                                        foundTarget = true;
                                        sourceNodeId = cursor.originNodeId;
                                        targetNodeId = node.id;
                                    }
                                    break;
                                }
                            }
                        }
                    }

                    if (foundTarget) {
                        setChordTranspositions(prev => {
                            const next = new Map(prev);
                            next.set(chordId, { ratio: newTranspositionRatio, sourceNodeId, targetNodeId });
                            return next;
                        });

                        // Set final ratio
                        const chordDef = settings.savedChords.find(c => c.id === chordId);
                        if (chordDef) {
                            chordDef.nodes.forEach(cn => {
                                 const fullNode = data.nodes.find(n => n.id === cn.id);
                                 if (fullNode) {
                                    audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * newTranspositionRatio, settings.baseFrequency, 0.1);
                                 }
                            });
                        }
                    } else {
                        // Snap back
                        const chordDef = settings.savedChords.find(c => c.id === chordId);
                        if (chordDef) {
                            chordDef.nodes.forEach(cn => {
                                 const fullNode = data.nodes.find(n => n.id === cn.id);
                                 if (fullNode) {
                                    audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * driver.startRatio, settings.baseFrequency, 0.1);
                                 }
                            });
                        }
                    }
                }
            }
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor && manualLatchedNodes.has(cursor.originNodeId)) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  const activeNodes = data.nodes.filter(n => effectiveLatchedNodes.has(n.id));

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full" style={{ zIndex: 0 }} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                         <feMergeNode in="SourceGraphic"/>
                      </feMerge>
                   </filter>
                   <filter id="red-aura" x="-50%" y="-50%" width="200%" height="200%">
                       <feGaussianBlur stdDeviation="6" result="coloredBlur"/>
                       <feFlood floodColor="red" floodOpacity="0.8" result="glowColor" />
                       <feComposite in="glowColor" in2="coloredBlur" operator="in" result="coloredBlur" />
                       <feMerge>
                           <feMergeNode in="coloredBlur" />
                           <feMergeNode in="SourceGraphic" />
                       </feMerge>
                   </filter>
                </defs>

                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    if (x1 < 0 || x1 > settings.canvasSize || y1 < 0 || y1 > settings.canvasSize ||
                        x2 < 0 || x2 > settings.canvasSize || y2 < 0 || y2 > settings.canvasSize) {
                        return null;
                    }

                    // Strict matching for rendering lines only between actual nodes
                    // Since nodes are filtered by limitDepths now, we can rely on data.nodes logic?
                    // data.lines comes from data.nodes, so this is safe.

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    const n1 = data.nodes.find(n => Math.abs(n.x - line.x1) < 0.01 && Math.abs(n.y - line.y1) < 0.01);
                    const n2 = data.nodes.find(n => Math.abs(n.x - line.x2) < 0.01 && Math.abs(n.y - line.y2) < 0.01);

                    if (n1 && n2) {
                        const n1Active = effectiveLatchedNodes.has(n1.id);
                        const n2Active = effectiveLatchedNodes.has(n2.id);

                        if (n1Active && n2Active) {
                            lineOpacity = 1.0;
                            lineWidth = 5;
                            isVoiceLeadingActive = true;
                            lineStyle = { 
                                filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                            };
                        } else if (n1Active || n2Active) {
                            lineOpacity = 0.6;
                            lineWidth = 3;
                        } else if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                            lineOpacity = 0.05;
                        }
                    }

                    const glowWidthMultiplier = 1 + (settings.voiceLeadingGlowAmount * 3); 
                    const animStrokeWidth = lineWidth * glowWidthMultiplier; 

                    return (
                        <g key={line.id}>
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={animStrokeWidth}
                                    strokeOpacity={0.9}
                                    strokeLinecap="round" 
                                    strokeDasharray={`0 100`} 
                                    filter="url(#glow)"
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}

                {/* Persistent Secondary Latch Lines */}
                {Array.from(chordTranspositions.values()).map((trans: Transposition, i) => {
                    const source = data.nodes.find(n => n.id === trans.sourceNodeId);
                    const target = data.nodes.find(n => n.id === trans.targetNodeId);
                    if (!source || !target) return null;

                    const sx = source.x * spacing + centerOffset;
                    const sy = source.y * spacing + centerOffset;
                    const tx = target.x * spacing + centerOffset;
                    const ty = target.y * spacing + centerOffset;

                    // Logic: Is there a natural lattice line between source and target?
                    const existingLine = data.lines.find(l => 
                        (Math.abs(l.x1 - source.x) < 0.01 && Math.abs(l.y1 - source.y) < 0.01 && Math.abs(l.x2 - target.x) < 0.01 && Math.abs(l.y2 - target.y) < 0.01) ||
                        (Math.abs(l.x2 - source.x) < 0.01 && Math.abs(l.y2 - source.y) < 0.01 && Math.abs(l.x1 - target.x) < 0.01 && Math.abs(l.y1 - target.y) < 0.01)
                    );

                    let strokeColor = 'red';
                    let dashed = "4 4";

                    if (existingLine) {
                         strokeColor = getColor(existingLine.limit);
                         dashed = "0";
                    } else {
                         // Check for Octave (Limit 1) manually if line generation didn't catch it
                         let diffs = 0;
                         for(let k=0; k<5; k++) diffs += Math.abs(source.coords[k] - target.coords[k]);
                         if (diffs === 0 && source.octave !== target.octave) {
                             strokeColor = getColor(1);
                             dashed = "5,5";
                         }
                    }

                    return (
                        <line 
                            key={`trans-${i}`}
                            x1={sx} y1={sy} x2={tx} y2={ty}
                            stroke={strokeColor}
                            strokeWidth={4}
                            strokeDasharray={dashed}
                            filter="url(#red-aura)"
                        />
                    );
                })}

                {/* Temporary Ghost Line while dragging to Latch */}
                {Array.from(chordDriverMap.current.values()).map((driver: ChordDriver) => {
                    // We need the Source Node and the Hovered Node
                    if (!driver.currentTargetNodeId) return null;

                    // Find source from activeCursors matching pointer
                    const cursor = cursors.find(c => c.pointerId === driver.pointerId);
                    if (!cursor) return null;

                    const source = data.nodes.find(n => n.id === cursor.originNodeId);
                    const target = data.nodes.find(n => n.id === driver.currentTargetNodeId);

                    if (!source || !target) return null;

                    const sx = source.x * spacing + centerOffset;
                    const sy = source.y * spacing + centerOffset;
                    const tx = target.x * spacing + centerOffset;
                    const ty = target.y * spacing + centerOffset;

                    const existingLine = data.lines.find(l => 
                        (Math.abs(l.x1 - source.x) < 0.01 && Math.abs(l.y1 - source.y) < 0.01 && Math.abs(l.x2 - target.x) < 0.01 && Math.abs(l.y2 - target.y) < 0.01) ||
                        (Math.abs(l.x2 - source.x) < 0.01 && Math.abs(l.y2 - source.y) < 0.01 && Math.abs(l.x1 - target.x) < 0.01 && Math.abs(l.y1 - target.y) < 0.01)
                    );

                    let strokeColor = 'red';
                    let dashed = "4 4";
                    if (existingLine) {
                        strokeColor = getColor(existingLine.limit);
                        dashed = "0";
                    }

                    return (
                        <line 
                            key={`ghost-${driver.pointerId}`}
                            x1={sx} y1={sy} x2={tx} y2={ty}
                            stroke={strokeColor}
                            strokeWidth={4}
                            strokeDasharray={dashed}
                            filter="url(#red-aura)"
                            opacity={0.6}
                        />
                    );
                })}

                {/* Active Cursors Visualization */}
                {cursors.map(c => {
                    if (!scrollContainerRef.current) return null;
                    const rect = scrollContainerRef.current.getBoundingClientRect();
                    const rx = c.currentX - rect.left + scrollContainerRef.current.scrollLeft;
                    const ry = c.currentY - rect.top + scrollContainerRef.current.scrollTop;

                    return (
                        <circle 
                            key={c.pointerId}
                            cx={rx}
                            cy={ry}
                            r={15}
                            fill="transparent"
                            stroke="white"
                            strokeWidth={2}
                            strokeDasharray="2,2"
                            pointerEvents="none"
                        />
                    );
                })}

                {/* Nodes */}
                {data.nodes.map(node => {
                    const isActive = effectiveLatchedNodes.has(node.id);
                    const color = getColor(node.maxPrime);

                    const cx = node.x * spacing + centerOffset;
                    const cy = node.y * spacing + centerOffset;

                    if (cx < -50 || cx > settings.canvasSize + 50 || cy < -50 || cy > settings.canvasSize + 50) return null;

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${cx}, ${cy})`}
                            onPointerDown={(e) => handlePointerDown(e, node)}
                            className="cursor-pointer"
                            style={{ pointerEvents: 'all' }}
                        >
                            {/* Halo for active nodes */}
                            {isActive && (
                                <circle r={baseSize * 0.8} fill={color} fillOpacity={0.3} className="animate-pulse" />
                            )}

                            {/* Main Button */}
                            <circle 
                                r={baseSize / 2} 
                                fill={isActive ? color : '#1e293b'} 
                                stroke={color}
                                strokeWidth={isActive ? 0 : 2}
                                className="transition-all duration-200"
                            />

                            {/* Text Label */}
                            <text 
                                dy=".3em" 
                                textAnchor="middle" 
                                fill={isActive ? '#000' : '#94a3b8'} 
                                fontSize={baseSize * 0.4} 
                                fontWeight="bold" 
                                pointerEvents="none"
                            >
                                {node.n}/{node.d}
                            </text>

                             {isActive && (
                                <text 
                                    dy="1.6em" 
                                    textAnchor="middle" 
                                    fill={color} 
                                    fontSize={baseSize * 0.25} 
                                    pointerEvents="none"
                                >
                                    {node.ratio.toFixed(2)}
                                </text>
                             )}
                        </g>
                    );
                })}
            </svg>
        </div>
    </div>
  );
});

export default TonalityDiamond;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
  // Minimal data needed to reconstruct/identify
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Screen position of shortcut
}

export interface AppSettings {
  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Chord Slide Settings
  isChordSlideEnabled: boolean;
  chordSlideTrigger: 1 | 2 | 3; // Number of fingers to trigger
  fixLatchedChords: boolean; // If true, ignore interactions below trigger count

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2Detune: number; // Cents
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';

  // Effects
  reverbMix: number; // 0 to 1
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import { LatticeNode, LatticeLine, AppSettings } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);

export const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic for generation bounds
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

// Helper to calculate the absolute ratio of a coordinate set starting from 1/1
const calculateRatioFromCoords = (coords: number[]): Fraction => {
    let ratio = new Fraction(1, 1);

    PRIMES.forEach((prime, idx) => {
        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
        const val = coords[idx];
        if (val === 0) return;

        for(let i=0; i < Math.abs(val); i++) {
             if (val > 0) ratio = ratio.mul(pRat).normalize();
             else {
                 const invRatio = new Fraction(pRat.d, pRat.n);
                 ratio = ratio.mul(invRatio).normalize();
             }
        }
    });
    return ratio;
};

export const generateLattice = (settings: AppSettings, generationOrigins: number[][] = [[0,0,0,0,0]]): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  // We use a Map to aggregate nodes from all generation origins, keyed by their coordinate signature.
  // This handles overlap (nodes generated by multiple centers) automatically.
  const baseNodes: Map<string, { coords: number[], ratio: Fraction }> = new Map();

  // Iterate through each origin and generate a local lattice cluster
  generationOrigins.forEach(origin => {
      const queue: { coords: number[], ratio: Fraction }[] = [];
      const originFrac = calculateRatioFromCoords(origin);

      const originKey = origin.join(',');
      if (!baseNodes.has(originKey)) {
          baseNodes.set(originKey, { coords: origin, ratio: originFrac });
      }
      queue.push({ coords: origin, ratio: originFrac });

      const MAX_LOCAL_NODES = 1500; // Limit per cluster to prevent explosion
      let processedCount = 0;

      const visitedLocal = new Set<string>();
      visitedLocal.add(originKey);

      while (queue.length > 0 && processedCount < MAX_LOCAL_NODES) {
        const current = queue.shift()!;
        processedCount++;
        const { coords, ratio } = current;

        PRIMES.forEach((prime, idx) => {
          // Check depth for this specific prime axis (Coordinate bounds)
          const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
          if (depthLimit <= 0) return;

          // Check complexity limit for this specific prime axis (Ratio bounds)
          const complexityLimit = settings.limitComplexities[prime as 3|5|7|11|13];

          [1, -1].forEach(dir => {
            const nextPos = [...coords];
            nextPos[idx] += dir;

            // Strict axis checking RELATIVE to current local origin
            if (Math.abs(nextPos[idx] - origin[idx]) > depthLimit) return;

            const posKey = nextPos.join(',');

            if (!visitedLocal.has(posKey)) {
                visitedLocal.add(posKey);

                 let nextRatio: Fraction;
                 const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                 if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
                 else {
                    const invRatio = new Fraction(pRat.d, pRat.n);
                    nextRatio = ratio.mul(invRatio).normalize();
                 }

                 // Enforce per-limit complexity (Absolute check)
                 // Note: With "Increase Depth", high limits might exceed this complexity.
                 // However, we still enforce it to prevent the UI from freezing with massive numbers.
                 // Users can increase the complexity limit in settings if they want deeper exploration.
                 if (nextRatio.n <= complexityLimit && nextRatio.d <= complexityLimit) {
                    if (!baseNodes.has(posKey)) {
                        baseNodes.set(posKey, { coords: nextPos, ratio: nextRatio });
                    }
                    queue.push({ coords: nextPos, ratio: nextRatio });
                 }
            }
          });
        });
      }
  });

  // 2. Expand Vertically (Octaves)
  const OCTAVE_RANGE = 2; 
  const nodes: LatticeNode[] = [];
  const nodesMap: Map<string, LatticeNode> = new Map();

  baseNodes.forEach((data, key) => {
      for (let oct = -OCTAVE_RANGE; oct <= OCTAVE_RANGE; oct++) {
          const shiftedRatio = data.ratio.shiftOctave(oct);
          const absoluteRatio = shiftedRatio.n / shiftedRatio.d;

          const id = `${key}:${oct}`;

          let x = 0;
          x += data.coords[0] * X_VECTORS[3];
          x += data.coords[1] * X_VECTORS[5];
          x += data.coords[2] * X_VECTORS[7];
          x += data.coords[3] * X_VECTORS[11];
          x += data.coords[4] * X_VECTORS[13];

          // Apply Aspect Ratio Stretch/Squish
          x = x * (1.0 / settings.latticeAspectRatio);

          const PITCH_SCALE = 200; // Pixels per octave
          const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

          const limitTop = getMaxPrime(shiftedRatio.n);
          const limitBottom = getMaxPrime(shiftedRatio.d);
          const maxPrime = Math.max(limitTop, limitBottom);

          const node: LatticeNode = {
              id,
              coords: data.coords,
              ratio: absoluteRatio,
              n: shiftedRatio.n,
              d: shiftedRatio.d,
              label: `${shiftedRatio.n}/${shiftedRatio.d}`,
              x,
              y,
              limitTop,
              limitBottom,
              maxPrime,
              octave: oct
          };
          nodes.push(node);
          nodesMap.set(id, node);
      }
  });

  // 3. Generate Lines
  const lines: LatticeLine[] = [];

  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors
      PRIMES.forEach((prime, idx) => {
          // If the limit is "disabled" via depth 0, don't draw lines for it
          if (settings.limitDepths[prime as 3|5|7|11|13] <= 0) return;

          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const key = neighborCoords.join(',');

          if (baseNodes.has(key)) {
             const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

             // Iterate nearby octaves
             for(let o = node.octave - 1; o <= node.octave + 1; o++) {
                 const targetId = `${key}:${o}`;
                 const target = nodesMap.get(targetId);

                 if (target) {
                      const ratio = target.ratio / node.ratio;
                      const test = ratio / basePrimeRatio;
                      const log2 = Math.log2(test);

                      if (Math.abs(log2 - Math.round(log2)) < 0.001) {
                          lines.push({
                            id: `${node.id}-${target.id}`,
                            x1: node.x,
                            y1: node.y,
                            x2: target.x,
                            y2: target.y,
                            limit: prime,
                            sourceId: node.id,
                            targetId: target.id
                          });
                      }
                 }
             }
          }
      });

      // Vertical Octave Connections
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1, // Octave "limit"
              sourceId: node.id,
              targetId: octUpNode.id
          });
      }
  });

  return { nodes, lines };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

interface ChordDriver {
  pointerId: number;
  startY: number; // Screen Y
  startRatio: number; // Transposition ratio at start
}

const PITCH_SCALE = 200; // Pixels per octave

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track manually latched nodes (clicked by user)
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track the actual effective latched nodes (manual + chords)
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  // Track the origins for depth generation (Array of coordinate arrays)
  const [depthOrigins, setDepthOrigins] = useState<number[][]>([[0,0,0,0,0]]);

  // Track last touched node for Increasing Depth
  const [lastTouchedNodeCoords, setLastTouchedNodeCoords] = useState<number[] | null>(null);

  const [hasCentered, setHasCentered] = useState(false);

  const prevActiveChordIds = useRef<string[]>([]);

  // Chord Slide State Refs
  const chordTouchMap = useRef<Map<string, Set<number>>>(new Map()); // chordId -> Set<pointerId>
  const chordDriverMap = useRef<Map<string, ChordDriver>>(new Map());
  const [chordPitchOffsets, setChordPitchOffsets] = useState<Map<string, number>>(new Map()); // chordId -> ratio multiplier

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([[0,0,0,0,0]]);
            setLastTouchedNodeCoords(null);
        }

        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNodeCoords) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => o.every((val, i) => val === lastTouchedNodeCoords[i]));
                if (exists) return prev;
                return [...prev, [...lastTouchedNodeCoords]];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  useEffect(() => {
    // Pass the depthOrigins array to generation service
    const result = generateLattice(settings, depthOrigins);

    // Strict Filtering Logic based on hiddenLimits for VISIBILITY
    const visibleNodes = result.nodes.filter(n => {
        // Check all hidden limits
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    // Create a Set for fast lookup of visible IDs
    const visibleNodeIds = new Set(visibleNodes.map(n => n.id));

    // Filter lines: Limit must be visible AND both endpoints must be visible
    const visibleLines = result.lines.filter(l => 
        !settings.hiddenLimits.includes(l.limit) && 
        visibleNodeIds.has(l.sourceId) && 
        visibleNodeIds.has(l.targetId)
    );

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings, depthOrigins]);

  // Clean up pitch offsets for deactivated chords
  useEffect(() => {
     setChordPitchOffsets(prev => {
         const next = new Map(prev);
         let changed = false;
         for (const key of next.keys()) {
             if (!activeChordIds.includes(key)) {
                 next.delete(key);
                 changed = true;
             }
         }
         return changed ? next : prev;
     });
  }, [activeChordIds]);

  // Combine Manual Latches + Active Chords to determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id); 
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     const ratioMult = chordPitchOffsets.get(chordId) || 1.0;
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio * ratioMult, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency, chordPitchOffsets]);

  // Sync voices
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());

  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Start new notes
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   // Calculate if this node belongs to a transposed chord
                   let multiplier = 1.0;
                   const ownerChord = settings.savedChords.find(c => activeChordIds.includes(c.id) && c.nodes.some(cn => cn.id === nodeId));
                   if (ownerChord) {
                       multiplier = chordPitchOffsets.get(ownerChord.id) || 1.0;
                   }

                   audioEngine.startVoice(`node-${nodeId}`, node.ratio * multiplier, settings.baseFrequency);
               }
          }
      });

      // Stop removed notes
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine, chordPitchOffsets, activeChordIds, settings.savedChords]);

  // Reactive Delatching Logic 
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Helpers ---

  const getActiveChordsForNode = (nodeId: string) => {
    return settings.savedChords.filter(c => 
        activeChordIds.includes(c.id) && c.nodes.some(n => n.id === nodeId)
    );
  };

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // --- Handlers ---

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNodeCoords(node.coords);

    // Track active cursors
    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    // --- Chord Slide Logic ---
    let suppressStandardInteraction = false;
    const activeChordsForNode = getActiveChordsForNode(node.id);

    if (settings.isChordSlideEnabled && activeChordsForNode.length > 0) {
        activeChordsForNode.forEach(chord => {
            let touches = chordTouchMap.current.get(chord.id);
            if (!touches) {
                touches = new Set();
                chordTouchMap.current.set(chord.id, touches);
            }
            touches.add(e.pointerId);

            const count = touches.size;

            if (count >= settings.chordSlideTrigger) {
                 suppressStandardInteraction = true;

                 if (!chordDriverMap.current.has(chord.id)) {
                     const currentOffset = chordPitchOffsets.get(chord.id) || 1.0;
                     chordDriverMap.current.set(chord.id, { 
                         pointerId: e.pointerId, 
                         startY: e.clientY,
                         startRatio: currentOffset
                     });
                 }
            } else if (settings.fixLatchedChords) {
                 suppressStandardInteraction = true;
            }
        });
    }

    if (suppressStandardInteraction) return;

    // Toggle Logic
    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        let multiplier = 1.0;
        if (activeChordsForNode.length > 0) {
             const chordId = activeChordsForNode[0].id; 
             multiplier = chordPitchOffsets.get(chordId) || 1.0;
        }
        audioEngine.startVoice(cursorId, node.ratio * multiplier, settings.baseFrequency);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    const centerOffset = settings.canvasSize / 2;
    const scrollLeft = scrollContainerRef.current?.scrollLeft || 0;
    const scrollTop = scrollContainerRef.current?.scrollTop || 0;

    // --- Chord Slide Move Logic ---
    let isDrivingChord = false;
    if (settings.isChordSlideEnabled) {
        chordDriverMap.current.forEach((driver, chordId) => {
            if (driver.pointerId === e.pointerId) {
                isDrivingChord = true;

                // Calculate absolute pitch ratio at finger location (matches regular pitch bend)
                const canvasY = e.clientY + scrollTop;
                const relY = canvasY - centerOffset;
                const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;

                // The pitch at the finger's tip on the absolute scale
                const fingerRatio = Math.pow(2, -relY / effectivePitchScale);

                // Find the source node (driver node) to determine how much to shift the WHOLE chord
                const activeCursor = (Array.from(activeCursors.values()) as ActiveCursor[]).find(c => c.pointerId === driver.pointerId);
                const sourceNode = data.nodes.find(n => n.id === activeCursor?.originNodeId);

                let totalRatio = driver.startRatio;

                if (sourceNode) {
                    // Shift = (Target Ratio where finger is) / (Original Ratio of dragged node)
                    totalRatio = fingerRatio / sourceNode.ratio;
                }

                // Visual update only (ghost lines removed)
                setChordPitchOffsets(prev => new Map(prev).set(chordId, totalRatio));

                // Apply audio bend to all nodes in chord
                const chordDef = settings.savedChords.find(c => c.id === chordId);
                if (chordDef) {
                    chordDef.nodes.forEach(cn => {
                         const fullNode = data.nodes.find(n => n.id === cn.id);
                         if (fullNode) {
                            audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * totalRatio, settings.baseFrequency, 0.05);
                         }
                    });
                }
            }
        });
    }

    if (isDrivingChord) return;

    if (settings.isPitchBendEnabled) {
        const spacing = settings.buttonSpacingScale;
        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNodeCoords(node.coords);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (settings.isChordSlideEnabled) {
        chordTouchMap.current.forEach((touches, chordId) => {
            if (touches.has(e.pointerId)) {
                touches.delete(e.pointerId);

                const driver = chordDriverMap.current.get(chordId);
                if (driver && driver.pointerId === e.pointerId) {
                    chordDriverMap.current.delete(chordId);

                    // On release, snap back or keep?
                    // "Matches regular pitch slide characteristics" -> snap back usually
                    // or just leave at offset?
                    // Standard keys snap back.
                    // Let's snap back for now unless "fix" is enabled.

                    if (!settings.fixLatchedChords) {
                        const chordDef = settings.savedChords.find(c => c.id === chordId);
                        if (chordDef) {
                            setChordPitchOffsets(prev => {
                                const next = new Map(prev);
                                next.delete(chordId);
                                return next;
                            });

                            chordDef.nodes.forEach(cn => {
                                 const fullNode = data.nodes.find(n => n.id === cn.id);
                                 if (fullNode) {
                                    audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * 1.0, settings.baseFrequency, 0.1);
                                 }
                            });
                        }
                    }
                }
            }
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor && manualLatchedNodes.has(cursor.originNodeId)) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Memoized set of effective latch keys for fast O(1) rendering lookups
  const effectiveLatchedSet = useMemo(() => new Set(effectiveLatchedNodes.keys()), [effectiveLatchedNodes]);

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full" style={{ zIndex: 0 }} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                         <feMergeNode in="SourceGraphic"/>
                      </feMerge>
                   </filter>
                </defs>

                {/* Render Lines - Optimized */}
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    // Viewport culling check
                    if (x1 < 0 || x1 > settings.canvasSize || y1 < 0 || y1 > settings.canvasSize ||
                        x2 < 0 || x2 > settings.canvasSize || y2 < 0 || y2 > settings.canvasSize) {
                        return null;
                    }

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    // Fast O(1) checks using ID maps/sets
                    const n1Active = effectiveLatchedSet.has(line.sourceId);
                    const n2Active = effectiveLatchedSet.has(line.targetId);

                    if (n1Active && n2Active) {
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        isVoiceLeadingActive = true;
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };
                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && effectiveLatchedSet.size > 0) {
                        lineOpacity = 0.05;
                    }

                    const glowWidthMultiplier = 1 + (settings.voiceLeadingGlowAmount * 3); 
                    const animStrokeWidth = lineWidth * glowWidthMultiplier; 

                    return (
                        <g key={line.id}>
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={animStrokeWidth}
                                    strokeOpacity={0.9}
                                    strokeLinecap="round" 
                                    strokeDasharray={`0 100`} 
                                    filter="url(#glow)"
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}


                {/* Active Cursors Visualization */}
                {cursors.map(c => {
                    if (!scrollContainerRef.current) return null;
                    const rect = scrollContainerRef.current.getBoundingClientRect();
                    const rx = c.currentX - rect.left + scrollContainerRef.current.scrollLeft;
                    const ry = c.currentY - rect.top + scrollContainerRef.current.scrollTop;

                    return (
                        <circle 
                            key={c.pointerId}
                            cx={rx}
                            cy={ry}
                            r={15}
                            fill="transparent"
                            stroke="white"
                            strokeWidth={2}
                            strokeDasharray="2,2"
                            pointerEvents="none"
                        />
                    );
                })}

                {/* Nodes */}
                {data.nodes.map(node => {
                    const isActive = effectiveLatchedSet.has(node.id);
                    const color = getColor(node.maxPrime);

                    const cx = node.x * spacing + centerOffset;
                    const cy = node.y * spacing + centerOffset;

                    if (cx < -50 || cx > settings.canvasSize + 50 || cy < -50 || cy > settings.canvasSize + 50) return null;

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${cx}, ${cy})`}
                            onPointerDown={(e) => handlePointerDown(e, node)}
                            className="cursor-pointer"
                            style={{ pointerEvents: 'all' }}
                        >
                            {/* Halo for active nodes */}
                            {isActive && (
                                <circle r={baseSize * 0.8} fill={color} fillOpacity={0.3} className="animate-pulse" />
                            )}

                            {/* Main Button */}
                            <circle 
                                r={baseSize / 2} 
                                fill={isActive ? color : '#1e293b'} 
                                stroke={color}
                                strokeWidth={isActive ? 0 : 2}
                                className="transition-all duration-200"
                            />

                            {/* Text Label */}
                            <text 
                                dy=".3em" 
                                textAnchor="middle" 
                                fill={isActive ? '#000' : '#94a3b8'} 
                                fontSize={baseSize * 0.4} 
                                fontWeight="bold" 
                                pointerEvents="none"
                            >
                                {node.n}/{node.d}
                            </text>

                             {isActive && (
                                <text 
                                    dy="1.6em" 
                                    textAnchor="middle" 
                                    fill={color} 
                                    fontSize={baseSize * 0.25} 
                                    pointerEvents="none"
                                >
                                    {node.ratio.toFixed(2)}
                                </text>
                             )}
                        </g>
                    );
                })}
            </svg>
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

interface ChordDriver {
  pointerId: number;
  startY: number; // Screen Y
  startRatio: number; // Transposition ratio at start
}

const PITCH_SCALE = 200; // Pixels per octave

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track manually latched nodes (clicked by user)
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track the actual effective latched nodes (manual + chords)
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  // Track the origins for depth generation (Array of coordinate arrays)
  const [depthOrigins, setDepthOrigins] = useState<number[][]>([[0,0,0,0,0]]);

  // Track last touched node for Increasing Depth
  const [lastTouchedNodeCoords, setLastTouchedNodeCoords] = useState<number[] | null>(null);

  const [hasCentered, setHasCentered] = useState(false);

  const prevActiveChordIds = useRef<string[]>([]);

  // Chord Slide State Refs
  const chordTouchMap = useRef<Map<string, Set<number>>>(new Map()); // chordId -> Set<pointerId>
  const chordDriverMap = useRef<Map<string, ChordDriver>>(new Map());
  const [chordPitchOffsets, setChordPitchOffsets] = useState<Map<string, number>>(new Map()); // chordId -> ratio multiplier

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([[0,0,0,0,0]]);
            setLastTouchedNodeCoords(null);
        }

        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNodeCoords) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => o.every((val, i) => val === lastTouchedNodeCoords[i]));
                if (exists) return prev;
                return [...prev, [...lastTouchedNodeCoords]];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  useEffect(() => {
    // Pass the depthOrigins array to generation service
    const result = generateLattice(settings, depthOrigins);

    // Strict Filtering Logic based on hiddenLimits for VISIBILITY
    const visibleNodes = result.nodes.filter(n => {
        // Check all hidden limits
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    // Create a Set for fast lookup of visible IDs
    const visibleNodeIds = new Set(visibleNodes.map(n => n.id));

    // Filter lines: Limit must be visible AND both endpoints must be visible
    const visibleLines = result.lines.filter(l => 
        !settings.hiddenLimits.includes(l.limit) && 
        visibleNodeIds.has(l.sourceId) && 
        visibleNodeIds.has(l.targetId)
    );

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings, depthOrigins]);

  // Clean up pitch offsets for deactivated chords
  useEffect(() => {
     setChordPitchOffsets(prev => {
         const next = new Map(prev);
         let changed = false;
         for (const key of next.keys()) {
             if (!activeChordIds.includes(key)) {
                 next.delete(key);
                 changed = true;
             }
         }
         return changed ? next : prev;
     });
  }, [activeChordIds]);

  // Combine Manual Latches + Active Chords to determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id); 
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     const ratioMult = chordPitchOffsets.get(chordId) || 1.0;
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio * ratioMult, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency, chordPitchOffsets]);

  // Sync voices
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());

  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Start new notes
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   // Calculate if this node belongs to a transposed chord
                   let multiplier = 1.0;
                   const ownerChord = settings.savedChords.find(c => activeChordIds.includes(c.id) && c.nodes.some(cn => cn.id === nodeId));
                   if (ownerChord) {
                       multiplier = chordPitchOffsets.get(ownerChord.id) || 1.0;
                   }

                   audioEngine.startVoice(`node-${nodeId}`, node.ratio * multiplier, settings.baseFrequency);
               }
          }
      });

      // Stop removed notes
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine, chordPitchOffsets, activeChordIds, settings.savedChords]);

  // Reactive Delatching Logic 
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Helpers ---

  const getActiveChordsForNode = (nodeId: string) => {
    return settings.savedChords.filter(c => 
        activeChordIds.includes(c.id) && c.nodes.some(n => n.id === nodeId)
    );
  };

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // --- Handlers ---

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNodeCoords(node.coords);

    // Track active cursors
    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    // --- Chord Slide Logic ---
    let suppressStandardInteraction = false;
    const activeChordsForNode = getActiveChordsForNode(node.id);

    if (settings.isChordSlideEnabled && activeChordsForNode.length > 0) {
        activeChordsForNode.forEach(chord => {
            let touches = chordTouchMap.current.get(chord.id);
            if (!touches) {
                touches = new Set();
                chordTouchMap.current.set(chord.id, touches);
            }
            touches.add(e.pointerId);

            const count = touches.size;

            if (count >= settings.chordSlideTrigger) {
                 suppressStandardInteraction = true;

                 if (!chordDriverMap.current.has(chord.id)) {
                     const currentOffset = chordPitchOffsets.get(chord.id) || 1.0;
                     chordDriverMap.current.set(chord.id, { 
                         pointerId: e.pointerId, 
                         startY: e.clientY,
                         startRatio: currentOffset
                     });
                 }
            } else if (settings.fixLatchedChords) {
                 suppressStandardInteraction = true;
            }
        });
    }

    if (suppressStandardInteraction) return;

    // Toggle Logic
    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        let multiplier = 1.0;
        if (activeChordsForNode.length > 0) {
             const chordId = activeChordsForNode[0].id; 
             multiplier = chordPitchOffsets.get(chordId) || 1.0;
        }
        audioEngine.startVoice(cursorId, node.ratio * multiplier, settings.baseFrequency);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    const centerOffset = settings.canvasSize / 2;
    const scrollLeft = scrollContainerRef.current?.scrollLeft || 0;
    const scrollTop = scrollContainerRef.current?.scrollTop || 0;

    // --- Chord Slide Move Logic ---
    let isDrivingChord = false;
    if (settings.isChordSlideEnabled) {
        chordDriverMap.current.forEach((driver, chordId) => {
            if (driver.pointerId === e.pointerId) {
                isDrivingChord = true;

                // Calculate absolute pitch ratio at finger location (matches regular pitch bend)
                const canvasY = e.clientY + scrollTop;
                const relY = canvasY - centerOffset;
                const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;

                // The pitch at the finger's tip on the absolute scale
                const fingerRatio = Math.pow(2, -relY / effectivePitchScale);

                // Find the source node (driver node) to determine how much to shift the WHOLE chord
                const activeCursor = (Array.from(activeCursors.values()) as ActiveCursor[]).find(c => c.pointerId === driver.pointerId);
                const sourceNode = data.nodes.find(n => n.id === activeCursor?.originNodeId);

                let totalRatio = driver.startRatio;

                if (sourceNode) {
                    // Shift = (Target Ratio where finger is) / (Original Ratio of dragged node)
                    totalRatio = fingerRatio / sourceNode.ratio;
                }

                // Visual update only (ghost lines removed)
                setChordPitchOffsets(prev => new Map(prev).set(chordId, totalRatio));

                // Apply audio bend to all nodes in chord
                const chordDef = settings.savedChords.find(c => c.id === chordId);
                if (chordDef) {
                    chordDef.nodes.forEach(cn => {
                         const fullNode = data.nodes.find(n => n.id === cn.id);
                         if (fullNode) {
                            audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * totalRatio, settings.baseFrequency, 0.05);
                         }
                    });
                }
            }
        });
    }

    if (isDrivingChord) return;

    if (settings.isPitchBendEnabled) {
        const spacing = settings.buttonSpacingScale;
        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNodeCoords(node.coords);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (settings.isChordSlideEnabled) {
        chordTouchMap.current.forEach((touches, chordId) => {
            if (touches.has(e.pointerId)) {
                touches.delete(e.pointerId);

                const driver = chordDriverMap.current.get(chordId);
                if (driver && driver.pointerId === e.pointerId) {
                    chordDriverMap.current.delete(chordId);

                    // On release, snap back or keep?
                    // "Matches regular pitch slide characteristics" -> snap back usually
                    // or just leave at offset?
                    // Standard keys snap back.
                    // Let's snap back for now unless "fix" is enabled.

                    if (!settings.fixLatchedChords) {
                        const chordDef = settings.savedChords.find(c => c.id === chordId);
                        if (chordDef) {
                            setChordPitchOffsets(prev => {
                                const next = new Map(prev);
                                next.delete(chordId);
                                return next;
                            });

                            chordDef.nodes.forEach(cn => {
                                 const fullNode = data.nodes.find(n => n.id === cn.id);
                                 if (fullNode) {
                                    audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * 1.0, settings.baseFrequency, 0.1);
                                 }
                            });
                        }
                    }
                }
            }
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor && manualLatchedNodes.has(cursor.originNodeId)) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Memoized set of effective latch keys for fast O(1) rendering lookups
  const effectiveLatchedSet = useMemo(() => new Set(effectiveLatchedNodes.keys()), [effectiveLatchedNodes]);

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full" style={{ zIndex: 0 }} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                         <feMergeNode in="SourceGraphic"/>
                      </feMerge>
                   </filter>
                </defs>

                {/* Render Lines - Optimized */}
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    // Viewport culling check
                    if (x1 < 0 || x1 > settings.canvasSize || y1 < 0 || y1 > settings.canvasSize ||
                        x2 < 0 || x2 > settings.canvasSize || y2 < 0 || y2 > settings.canvasSize) {
                        return null;
                    }

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    // Fast O(1) checks using ID maps/sets
                    const n1Active = effectiveLatchedSet.has(line.sourceId);
                    const n2Active = effectiveLatchedSet.has(line.targetId);

                    if (n1Active && n2Active) {
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        isVoiceLeadingActive = true;
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };
                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && effectiveLatchedSet.size > 0) {
                        lineOpacity = 0.05;
                    }

                    const glowWidthMultiplier = 1 + (settings.voiceLeadingGlowAmount * 3); 
                    const animStrokeWidth = lineWidth * glowWidthMultiplier; 

                    return (
                        <g key={line.id}>
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={animStrokeWidth}
                                    strokeOpacity={0.9}
                                    strokeLinecap="round" 
                                    strokeDasharray={`0 100`} 
                                    filter="url(#glow)"
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}


                {/* Active Cursors Visualization */}
                {cursors.map(c => {
                    if (!scrollContainerRef.current) return null;
                    const rect = scrollContainerRef.current.getBoundingClientRect();
                    const rx = c.currentX - rect.left + scrollContainerRef.current.scrollLeft;
                    const ry = c.currentY - rect.top + scrollContainerRef.current.scrollTop;

                    return (
                        <circle 
                            key={c.pointerId}
                            cx={rx}
                            cy={ry}
                            r={15}
                            fill="transparent"
                            stroke="white"
                            strokeWidth={2}
                            strokeDasharray="2,2"
                            pointerEvents="none"
                        />
                    );
                })}

                {/* Nodes */}
                {data.nodes.map(node => {
                    const isActive = effectiveLatchedSet.has(node.id);
                    const color = getColor(node.maxPrime);

                    const cx = node.x * spacing + centerOffset;
                    const cy = node.y * spacing + centerOffset;

                    // Viewport culling for nodes
                    if (cx < -baseSize || cx > settings.canvasSize + baseSize || cy < -baseSize || cy > settings.canvasSize + baseSize) return null;

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${cx}, ${cy})`}
                            onPointerDown={(e) => handlePointerDown(e, node)}
                            className="cursor-pointer"
                            style={{ pointerEvents: 'all' }}
                        >
                            {/* Halo for active nodes */}
                            {isActive && (
                                <circle r={baseSize * 0.8} fill={color} fillOpacity={0.3} className="animate-pulse" />
                            )}

                            {/* Main Button Shape */}
                            {settings.buttonShape === ButtonShape.DIAMOND ? (
                                <rect 
                                    x={-baseSize/2} 
                                    y={-baseSize/2} 
                                    width={baseSize} 
                                    height={baseSize}
                                    transform="rotate(45)"
                                    fill={color}
                                    fillOpacity={isActive ? 1 : 0.2}
                                    stroke={color}
                                    strokeWidth={isActive ? 0 : 2}
                                    className="transition-all duration-200"
                                />
                            ) : (
                                <circle 
                                    r={baseSize / 2} 
                                    fill={color}
                                    fillOpacity={isActive ? 1 : 0.2}
                                    stroke={color}
                                    strokeWidth={isActive ? 0 : 2}
                                    className="transition-all duration-200"
                                />
                            )}

                            {/* Text Label */}
                            <text 
                                dy=".3em" 
                                textAnchor="middle" 
                                fill={isActive ? '#000' : '#94a3b8'} 
                                fontSize={baseSize * 0.4} 
                                fontWeight="bold" 
                                pointerEvents="none"
                                style={{ textShadow: '0px 1px 2px rgba(0,0,0,0.8)' }}
                            >
                                {node.n}/{node.d}
                            </text>

                             {isActive && (
                                <text 
                                    dy="1.6em" 
                                    textAnchor="middle" 
                                    fill={color} 
                                    fontSize={baseSize * 0.25} 
                                    pointerEvents="none"
                                    style={{ textShadow: '0px 1px 2px rgba(0,0,0,0.8)' }}
                                >
                                    {node.ratio.toFixed(2)}
                                </text>
                             )}
                        </g>
                    );
                })}
            </svg>
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

interface ChordDriver {
  pointerId: number;
  startY: number; // Screen Y
  startRatio: number; // Transposition ratio at start
}

const PITCH_SCALE = 200; // Pixels per octave

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track manually latched nodes (clicked by user)
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track the actual effective latched nodes (manual + chords)
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  // Track the origins for depth generation (Array of coordinate arrays)
  const [depthOrigins, setDepthOrigins] = useState<number[][]>([[0,0,0,0,0]]);

  // Track last touched node for Increasing Depth
  const [lastTouchedNodeCoords, setLastTouchedNodeCoords] = useState<number[] | null>(null);

  const [hasCentered, setHasCentered] = useState(false);

  const prevActiveChordIds = useRef<string[]>([]);

  // Chord Slide State Refs
  const chordTouchMap = useRef<Map<string, Set<number>>>(new Map()); // chordId -> Set<pointerId>
  const chordDriverMap = useRef<Map<string, ChordDriver>>(new Map());
  const [chordPitchOffsets, setChordPitchOffsets] = useState<Map<string, number>>(new Map()); // chordId -> ratio multiplier

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([[0,0,0,0,0]]);
            setLastTouchedNodeCoords(null);
        }

        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNodeCoords) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => o.every((val, i) => val === lastTouchedNodeCoords[i]));
                if (exists) return prev;
                return [...prev, [...lastTouchedNodeCoords]];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  useEffect(() => {
    // Pass the depthOrigins array to generation service
    const result = generateLattice(settings, depthOrigins);

    // Strict Filtering Logic based on hiddenLimits for VISIBILITY
    const visibleNodes = result.nodes.filter(n => {
        // Check all hidden limits
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    // Create a Set for fast lookup of visible IDs
    const visibleNodeIds = new Set(visibleNodes.map(n => n.id));

    // Filter lines: Limit must be visible AND both endpoints must be visible
    const visibleLines = result.lines.filter(l => 
        !settings.hiddenLimits.includes(l.limit) && 
        visibleNodeIds.has(l.sourceId) && 
        visibleNodeIds.has(l.targetId)
    );

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings, depthOrigins]);

  // Clean up pitch offsets for deactivated chords
  useEffect(() => {
     setChordPitchOffsets(prev => {
         const next = new Map(prev);
         let changed = false;
         for (const key of next.keys()) {
             if (!activeChordIds.includes(key)) {
                 next.delete(key);
                 changed = true;
             }
         }
         return changed ? next : prev;
     });
  }, [activeChordIds]);

  // Combine Manual Latches + Active Chords to determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id); 
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     const ratioMult = chordPitchOffsets.get(chordId) || 1.0;
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio * ratioMult, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency, chordPitchOffsets]);

  // Sync voices
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());

  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Start new notes
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   // Calculate if this node belongs to a transposed chord
                   let multiplier = 1.0;
                   const ownerChord = settings.savedChords.find(c => activeChordIds.includes(c.id) && c.nodes.some(cn => cn.id === nodeId));
                   if (ownerChord) {
                       multiplier = chordPitchOffsets.get(ownerChord.id) || 1.0;
                   }

                   audioEngine.startVoice(`node-${nodeId}`, node.ratio * multiplier, settings.baseFrequency);
               }
          }
      });

      // Stop removed notes
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine, chordPitchOffsets, activeChordIds, settings.savedChords]);

  // Reactive Delatching Logic 
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Helpers ---

  const getActiveChordsForNode = (nodeId: string) => {
    return settings.savedChords.filter(c => 
        activeChordIds.includes(c.id) && c.nodes.some(n => n.id === nodeId)
    );
  };

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // --- Handlers ---

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNodeCoords(node.coords);

    // Track active cursors
    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    // --- Chord Slide Logic ---
    let suppressStandardInteraction = false;
    const activeChordsForNode = getActiveChordsForNode(node.id);

    if (settings.isChordSlideEnabled && activeChordsForNode.length > 0) {
        activeChordsForNode.forEach(chord => {
            let touches = chordTouchMap.current.get(chord.id);
            if (!touches) {
                touches = new Set();
                chordTouchMap.current.set(chord.id, touches);
            }
            touches.add(e.pointerId);

            const count = touches.size;

            if (count >= settings.chordSlideTrigger) {
                 suppressStandardInteraction = true;

                 if (!chordDriverMap.current.has(chord.id)) {
                     const currentOffset = chordPitchOffsets.get(chord.id) || 1.0;
                     chordDriverMap.current.set(chord.id, { 
                         pointerId: e.pointerId, 
                         startY: e.clientY,
                         startRatio: currentOffset
                     });
                 }
            } else if (settings.fixLatchedChords) {
                 suppressStandardInteraction = true;
            }
        });
    }

    if (suppressStandardInteraction) return;

    // Toggle Logic
    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        let multiplier = 1.0;
        if (activeChordsForNode.length > 0) {
             const chordId = activeChordsForNode[0].id; 
             multiplier = chordPitchOffsets.get(chordId) || 1.0;
        }
        audioEngine.startVoice(cursorId, node.ratio * multiplier, settings.baseFrequency);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    const centerOffset = settings.canvasSize / 2;
    const scrollLeft = scrollContainerRef.current?.scrollLeft || 0;
    const scrollTop = scrollContainerRef.current?.scrollTop || 0;

    // --- Chord Slide Move Logic ---
    let isDrivingChord = false;
    if (settings.isChordSlideEnabled) {
        chordDriverMap.current.forEach((driver, chordId) => {
            if (driver.pointerId === e.pointerId) {
                isDrivingChord = true;

                // Calculate absolute pitch ratio at finger location (matches regular pitch bend)
                const canvasY = e.clientY + scrollTop;
                const relY = canvasY - centerOffset;
                const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;

                // The pitch at the finger's tip on the absolute scale
                const fingerRatio = Math.pow(2, -relY / effectivePitchScale);

                // Find the source node (driver node) to determine how much to shift the WHOLE chord
                const activeCursor = (Array.from(activeCursors.values()) as ActiveCursor[]).find(c => c.pointerId === driver.pointerId);
                const sourceNode = data.nodes.find(n => n.id === activeCursor?.originNodeId);

                let totalRatio = driver.startRatio;

                if (sourceNode) {
                    // Shift = (Target Ratio where finger is) / (Original Ratio of dragged node)
                    totalRatio = fingerRatio / sourceNode.ratio;
                }

                // Visual update only (ghost lines removed)
                setChordPitchOffsets(prev => new Map(prev).set(chordId, totalRatio));

                // Apply audio bend to all nodes in chord
                const chordDef = settings.savedChords.find(c => c.id === chordId);
                if (chordDef) {
                    chordDef.nodes.forEach(cn => {
                         const fullNode = data.nodes.find(n => n.id === cn.id);
                         if (fullNode) {
                            audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * totalRatio, settings.baseFrequency, 0.05);
                         }
                    });
                }
            }
        });
    }

    if (isDrivingChord) return;

    if (settings.isPitchBendEnabled) {
        const spacing = settings.buttonSpacingScale;
        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNodeCoords(node.coords);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (settings.isChordSlideEnabled) {
        chordTouchMap.current.forEach((touches, chordId) => {
            if (touches.has(e.pointerId)) {
                touches.delete(e.pointerId);

                const driver = chordDriverMap.current.get(chordId);
                if (driver && driver.pointerId === e.pointerId) {
                    chordDriverMap.current.delete(chordId);

                    // On release, snap back or keep?
                    // "Matches regular pitch slide characteristics" -> snap back usually
                    // or just leave at offset?
                    // Standard keys snap back.
                    // Let's snap back for now unless "fix" is enabled.

                    if (!settings.fixLatchedChords) {
                        const chordDef = settings.savedChords.find(c => c.id === chordId);
                        if (chordDef) {
                            setChordPitchOffsets(prev => {
                                const next = new Map(prev);
                                next.delete(chordId);
                                return next;
                            });

                            chordDef.nodes.forEach(cn => {
                                 const fullNode = data.nodes.find(n => n.id === cn.id);
                                 if (fullNode) {
                                    audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * 1.0, settings.baseFrequency, 0.1);
                                 }
                            });
                        }
                    }
                }
            }
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor && manualLatchedNodes.has(cursor.originNodeId)) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Memoized set of effective latch keys for fast O(1) rendering lookups
  const effectiveLatchedSet = useMemo(() => new Set(effectiveLatchedNodes.keys()), [effectiveLatchedNodes]);

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full" style={{ zIndex: 0 }} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                         <feMergeNode in="SourceGraphic"/>
                      </feMerge>
                   </filter>
                </defs>

                {/* Render Lines - Optimized */}
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    // Viewport culling check
                    if (x1 < 0 || x1 > settings.canvasSize || y1 < 0 || y1 > settings.canvasSize ||
                        x2 < 0 || x2 > settings.canvasSize || y2 < 0 || y2 > settings.canvasSize) {
                        return null;
                    }

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    // Fast O(1) checks using ID maps/sets
                    const n1Active = effectiveLatchedSet.has(line.sourceId);
                    const n2Active = effectiveLatchedSet.has(line.targetId);

                    if (n1Active && n2Active) {
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        isVoiceLeadingActive = true;
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };
                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && effectiveLatchedSet.size > 0) {
                        lineOpacity = 0.05;
                    }

                    const glowWidthMultiplier = 1 + (settings.voiceLeadingGlowAmount * 3); 
                    const animStrokeWidth = lineWidth * glowWidthMultiplier; 

                    return (
                        <g key={line.id}>
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={animStrokeWidth}
                                    strokeOpacity={0.9}
                                    strokeLinecap="round" 
                                    strokeDasharray={`0 100`} 
                                    filter="url(#glow)"
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}


                {/* Active Cursors Visualization */}
                {cursors.map(c => {
                    if (!scrollContainerRef.current) return null;
                    const rect = scrollContainerRef.current.getBoundingClientRect();
                    const rx = c.currentX - rect.left + scrollContainerRef.current.scrollLeft;
                    const ry = c.currentY - rect.top + scrollContainerRef.current.scrollTop;

                    return (
                        <circle 
                            key={c.pointerId}
                            cx={rx}
                            cy={ry}
                            r={15}
                            fill="transparent"
                            stroke="white"
                            strokeWidth={2}
                            strokeDasharray="2,2"
                            pointerEvents="none"
                        />
                    );
                })}

                {/* Nodes */}
                {data.nodes.map(node => {
                    const isActive = effectiveLatchedSet.has(node.id);
                    const topColor = getColor(node.limitTop);
                    const bottomColor = getColor(node.limitBottom);
                    const outlineColor = getColor(node.maxPrime);
                    const fillOpacity = isActive ? 1 : 0.2;

                    const cx = node.x * spacing + centerOffset;
                    const cy = node.y * spacing + centerOffset;

                    // Viewport culling for nodes
                    if (cx < -baseSize || cx > settings.canvasSize + baseSize || cy < -baseSize || cy > settings.canvasSize + baseSize) return null;

                    const r = baseSize / 2;

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${cx}, ${cy})`}
                            onPointerDown={(e) => handlePointerDown(e, node)}
                            className="cursor-pointer"
                            style={{ pointerEvents: 'all' }}
                        >
                            {/* Halo for active nodes */}
                            {isActive && (
                                <circle r={baseSize * 0.8} fill={outlineColor} fillOpacity={0.3} className="animate-pulse" />
                            )}

                            {/* Main Button Shape */}
                            {settings.buttonShape === ButtonShape.DIAMOND ? (() => {
                                const R = r * Math.sqrt(2);
                                return (
                                    <g className="transition-all duration-200">
                                        {/* Top Triangle */}
                                        <polygon points={`0,-${R} ${R},0 -${R},0`} fill={topColor} fillOpacity={fillOpacity} />
                                        {/* Bottom Triangle */}
                                        <polygon points={`0,${R} ${R},0 -${R},0`} fill={bottomColor} fillOpacity={fillOpacity} />
                                        {/* Outline */}
                                        <rect 
                                            x={-r} y={-r} width={baseSize} height={baseSize} 
                                            transform="rotate(45)" 
                                            fill="none" 
                                            stroke={outlineColor} 
                                            strokeWidth={isActive ? 0 : 2} 
                                        />
                                    </g>
                                );
                            })() : (
                                <g className="transition-all duration-200">
                                    {/* Top Half */}
                                    <path d={`M -${r} 0 A ${r} ${r} 0 0 1 ${r} 0 Z`} fill={topColor} fillOpacity={fillOpacity} />
                                    {/* Bottom Half */}
                                    <path d={`M -${r} 0 A ${r} ${r} 0 0 0 ${r} 0 Z`} fill={bottomColor} fillOpacity={fillOpacity} />
                                    {/* Outline */}
                                    <circle 
                                        r={r} 
                                        fill="none"
                                        stroke={outlineColor}
                                        strokeWidth={isActive ? 0 : 2}
                                    />
                                </g>
                            )}

                            {/* Text Label */}
                            <text 
                                dy=".3em" 
                                textAnchor="middle" 
                                fill={isActive ? '#000' : '#94a3b8'} 
                                fontSize={baseSize * 0.4} 
                                fontWeight="bold" 
                                pointerEvents="none"
                                style={{ textShadow: '0px 1px 2px rgba(0,0,0,0.8)' }}
                            >
                                {node.n}/{node.d}
                            </text>

                             {isActive && (
                                <text 
                                    dy="1.6em" 
                                    textAnchor="middle" 
                                    fill={outlineColor} 
                                    fontSize={baseSize * 0.25} 
                                    pointerEvents="none"
                                    style={{ textShadow: '0px 1px 2px rgba(0,0,0,0.8)' }}
                                >
                                    {node.ratio.toFixed(2)}
                                </text>
                             )}
                        </g>
                    );
                })}
            </svg>
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

interface ChordDriver {
  pointerId: number;
  startY: number; // Screen Y
  startRatio: number; // Transposition ratio at start
}

const PITCH_SCALE = 200; // Pixels per octave

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Track manually latched nodes (clicked by user)
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track the actual effective latched nodes (manual + chords)
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Track active pointers
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());

  // Track the origins for depth generation (Array of coordinate arrays)
  const [depthOrigins, setDepthOrigins] = useState<number[][]>([[0,0,0,0,0]]);

  // Track last touched node for Increasing Depth
  const [lastTouchedNodeCoords, setLastTouchedNodeCoords] = useState<number[] | null>(null);

  const [hasCentered, setHasCentered] = useState(false);

  const prevActiveChordIds = useRef<string[]>([]);

  // Chord Slide State Refs
  const chordTouchMap = useRef<Map<string, Set<number>>>(new Map()); // chordId -> Set<pointerId>
  const chordDriverMap = useRef<Map<string, ChordDriver>>(new Map());
  const [chordPitchOffsets, setChordPitchOffsets] = useState<Map<string, number>>(new Map()); // chordId -> ratio multiplier

  // Expose methods to parent
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); // Visual clear
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([[0,0,0,0,0]]);
            setLastTouchedNodeCoords(null);
        }

        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNodeCoords) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => o.every((val, i) => val === lastTouchedNodeCoords[i]));
                if (exists) return prev;
                return [...prev, [...lastTouchedNodeCoords]];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  useEffect(() => {
    // Pass the depthOrigins array to generation service
    const result = generateLattice(settings, depthOrigins);

    // Strict Filtering Logic based on hiddenLimits for VISIBILITY
    const visibleNodes = result.nodes.filter(n => {
        // Check all hidden limits
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    // Create a Set for fast lookup of visible IDs
    const visibleNodeIds = new Set(visibleNodes.map(n => n.id));

    // Filter lines: Limit must be visible AND both endpoints must be visible
    const visibleLines = result.lines.filter(l => 
        !settings.hiddenLimits.includes(l.limit) && 
        visibleNodeIds.has(l.sourceId) && 
        visibleNodeIds.has(l.targetId)
    );

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings, depthOrigins]);

  // Clean up pitch offsets for deactivated chords
  useEffect(() => {
     setChordPitchOffsets(prev => {
         const next = new Map(prev);
         let changed = false;
         for (const key of next.keys()) {
             if (!activeChordIds.includes(key)) {
                 next.delete(key);
                 changed = true;
             }
         }
         return changed ? next : prev;
     });
  }, [activeChordIds]);

  // Combine Manual Latches + Active Chords to determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id); 
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     const ratioMult = chordPitchOffsets.get(chordId) || 1.0;
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio * ratioMult, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency, chordPitchOffsets]);

  // Sync voices
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());

  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Start new notes
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   // Calculate if this node belongs to a transposed chord
                   let multiplier = 1.0;
                   const ownerChord = settings.savedChords.find(c => activeChordIds.includes(c.id) && c.nodes.some(cn => cn.id === nodeId));
                   if (ownerChord) {
                       multiplier = chordPitchOffsets.get(ownerChord.id) || 1.0;
                   }

                   audioEngine.startVoice(`node-${nodeId}`, node.ratio * multiplier, settings.baseFrequency);
               }
          }
      });

      // Stop removed notes
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine, chordPitchOffsets, activeChordIds, settings.savedChords]);

  // Reactive Delatching Logic 
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Helpers ---

  const getActiveChordsForNode = (nodeId: string) => {
    return settings.savedChords.filter(c => 
        activeChordIds.includes(c.id) && c.nodes.some(n => n.id === nodeId)
    );
  };

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // --- Handlers ---

  const handlePointerDown = (e: React.PointerEvent, node: LatticeNode) => {
    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNodeCoords(node.coords);

    // Track active cursors
    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    // --- Chord Slide Logic ---
    let suppressStandardInteraction = false;
    const activeChordsForNode = getActiveChordsForNode(node.id);

    if (settings.isChordSlideEnabled && activeChordsForNode.length > 0) {
        activeChordsForNode.forEach(chord => {
            let touches = chordTouchMap.current.get(chord.id);
            if (!touches) {
                touches = new Set();
                chordTouchMap.current.set(chord.id, touches);
            }
            touches.add(e.pointerId);

            const count = touches.size;

            if (count >= settings.chordSlideTrigger) {
                 suppressStandardInteraction = true;

                 if (!chordDriverMap.current.has(chord.id)) {
                     const currentOffset = chordPitchOffsets.get(chord.id) || 1.0;
                     chordDriverMap.current.set(chord.id, { 
                         pointerId: e.pointerId, 
                         startY: e.clientY,
                         startRatio: currentOffset
                     });
                 }
            } else if (settings.fixLatchedChords) {
                 suppressStandardInteraction = true;
            }
        });
    }

    if (suppressStandardInteraction) return;

    // Toggle Logic
    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        let multiplier = 1.0;
        if (activeChordsForNode.length > 0) {
             const chordId = activeChordsForNode[0].id; 
             multiplier = chordPitchOffsets.get(chordId) || 1.0;
        }
        audioEngine.startVoice(cursorId, node.ratio * multiplier, settings.baseFrequency);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    const centerOffset = settings.canvasSize / 2;
    const scrollLeft = scrollContainerRef.current?.scrollLeft || 0;
    const scrollTop = scrollContainerRef.current?.scrollTop || 0;

    // --- Chord Slide Move Logic ---
    let isDrivingChord = false;
    if (settings.isChordSlideEnabled) {
        chordDriverMap.current.forEach((driver, chordId) => {
            if (driver.pointerId === e.pointerId) {
                isDrivingChord = true;

                // Calculate absolute pitch ratio at finger location (matches regular pitch bend)
                const canvasY = e.clientY + scrollTop;
                const relY = canvasY - centerOffset;
                const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;

                // The pitch at the finger's tip on the absolute scale
                const fingerRatio = Math.pow(2, -relY / effectivePitchScale);

                // Find the source node (driver node) to determine how much to shift the WHOLE chord
                const activeCursor = (Array.from(activeCursors.values()) as ActiveCursor[]).find(c => c.pointerId === driver.pointerId);
                const sourceNode = data.nodes.find(n => n.id === activeCursor?.originNodeId);

                let totalRatio = driver.startRatio;

                if (sourceNode) {
                    // Shift = (Target Ratio where finger is) / (Original Ratio of dragged node)
                    totalRatio = fingerRatio / sourceNode.ratio;
                }

                // Visual update only (ghost lines removed)
                setChordPitchOffsets(prev => new Map(prev).set(chordId, totalRatio));

                // Apply audio bend to all nodes in chord
                const chordDef = settings.savedChords.find(c => c.id === chordId);
                if (chordDef) {
                    chordDef.nodes.forEach(cn => {
                         const fullNode = data.nodes.find(n => n.id === cn.id);
                         if (fullNode) {
                            audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * totalRatio, settings.baseFrequency, 0.05);
                         }
                    });
                }
            }
        });
    }

    if (isDrivingChord) return;

    if (settings.isPitchBendEnabled) {
        const spacing = settings.buttonSpacingScale;
        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNodeCoords(node.coords);
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (settings.isChordSlideEnabled) {
        chordTouchMap.current.forEach((touches, chordId) => {
            if (touches.has(e.pointerId)) {
                touches.delete(e.pointerId);

                const driver = chordDriverMap.current.get(chordId);
                if (driver && driver.pointerId === e.pointerId) {
                    chordDriverMap.current.delete(chordId);

                    // On release, snap back or keep?
                    // "Matches regular pitch slide characteristics" -> snap back usually
                    // or just leave at offset?
                    // Standard keys snap back.
                    // Let's snap back for now unless "fix" is enabled.

                    if (!settings.fixLatchedChords) {
                        const chordDef = settings.savedChords.find(c => c.id === chordId);
                        if (chordDef) {
                            setChordPitchOffsets(prev => {
                                const next = new Map(prev);
                                next.delete(chordId);
                                return next;
                            });

                            chordDef.nodes.forEach(cn => {
                                 const fullNode = data.nodes.find(n => n.id === cn.id);
                                 if (fullNode) {
                                    audioEngine.glideVoice(`node-${cn.id}`, fullNode.ratio * 1.0, settings.baseFrequency, 0.1);
                                 }
                            });
                        }
                    }
                }
            }
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor && manualLatchedNodes.has(cursor.originNodeId)) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  const getColor = (limit: number): string => settings.colors[limit] || '#64748b';

  const baseSize = 60 * settings.buttonSizeScale;
  const cursors: ActiveCursor[] = Array.from(activeCursors.values());
  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Memoized set of effective latch keys for fast O(1) rendering lookups
  const effectiveLatchedSet = useMemo(() => new Set(effectiveLatchedNodes.keys()), [effectiveLatchedNodes]);

  // Rainbow Generation
  const rainbowPeriod = PITCH_SCALE * spacing;
  let rainbowBackgroundFixed: string | undefined = undefined;

  if (settings.isRainbowModeEnabled) {
      const stops: string[] = [];
      const steps = 6;
      for (let i = 0; i <= steps; i++) {
          const pct = i / steps;
          const px = pct * rainbowPeriod;
          const hue = (settings.rainbowOffset + i * 60); 
          stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
      }
      rainbowBackgroundFixed = `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
  }

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full" style={{ zIndex: 0 }} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                         <feMergeNode in="SourceGraphic"/>
                      </feMerge>
                   </filter>
                </defs>

                {/* Render Lines - Optimized */}
                {data.lines.map(line => {
                    let x1 = line.x1 * spacing + centerOffset;
                    let y1 = line.y1 * spacing + centerOffset;
                    let x2 = line.x2 * spacing + centerOffset;
                    let y2 = line.y2 * spacing + centerOffset;

                    // Viewport culling check
                    if (x1 < 0 || x1 > settings.canvasSize || y1 < 0 || y1 > settings.canvasSize ||
                        x2 < 0 || x2 > settings.canvasSize || y2 < 0 || y2 > settings.canvasSize) {
                        return null;
                    }

                    const limitColor = getColor(line.limit);

                    let strokeColor = limitColor;
                    let lineOpacity = 0.1;
                    let lineWidth = line.limit === 1 ? 4 : 2;
                    let isVoiceLeadingActive = false;
                    let lineStyle = {};

                    // Fast O(1) checks using ID maps/sets
                    const n1Active = effectiveLatchedSet.has(line.sourceId);
                    const n2Active = effectiveLatchedSet.has(line.targetId);

                    if (n1Active && n2Active) {
                        lineOpacity = 1.0;
                        lineWidth = 5;
                        isVoiceLeadingActive = true;
                        lineStyle = { 
                            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
                        };
                    } else if (n1Active || n2Active) {
                        lineOpacity = 0.6;
                        lineWidth = 3;
                    } else if (settings.isVoiceLeadingEnabled && effectiveLatchedSet.size > 0) {
                        lineOpacity = 0.05;
                    }

                    const glowWidthMultiplier = 1 + (settings.voiceLeadingGlowAmount * 3); 
                    const animStrokeWidth = lineWidth * glowWidthMultiplier; 

                    return (
                        <g key={line.id}>
                            <line 
                                x1={x1} y1={y1} x2={x2} y2={y2}
                                stroke={strokeColor}
                                strokeWidth={lineWidth}
                                strokeOpacity={lineOpacity}
                                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                                style={lineStyle}
                            />
                            {isVoiceLeadingActive && settings.isVoiceLeadingAnimationEnabled && (
                                <line 
                                    x1={x1} y1={y1} x2={x2} y2={y2}
                                    stroke="white"
                                    strokeWidth={animStrokeWidth}
                                    strokeOpacity={0.9}
                                    strokeLinecap="round" 
                                    strokeDasharray={`0 100`} 
                                    filter="url(#glow)"
                                    className="animate-flow"
                                />
                            )}
                        </g>
                    );
                })}


                {/* Active Cursors Visualization */}
                {cursors.map(c => {
                    if (!scrollContainerRef.current) return null;
                    const rect = scrollContainerRef.current.getBoundingClientRect();
                    const rx = c.currentX - rect.left + scrollContainerRef.current.scrollLeft;
                    const ry = c.currentY - rect.top + scrollContainerRef.current.scrollTop;

                    return (
                        <circle 
                            key={c.pointerId}
                            cx={rx}
                            cy={ry}
                            r={15}
                            fill="transparent"
                            stroke="white"
                            strokeWidth={2}
                            strokeDasharray="2,2"
                            pointerEvents="none"
                        />
                    );
                })}

                {/* Nodes */}
                {data.nodes.map(node => {
                    const isActive = effectiveLatchedSet.has(node.id);
                    const topColor = getColor(node.limitTop);
                    const bottomColor = getColor(node.limitBottom);
                    const outlineColor = getColor(node.maxPrime);

                    // Restore higher opacity for inactive nodes so colors are visible
                    const fillOpacity = isActive ? 1.0 : 0.5;

                    const cx = node.x * spacing + centerOffset;
                    const cy = node.y * spacing + centerOffset;

                    // Viewport culling for nodes
                    if (cx < -baseSize || cx > settings.canvasSize + baseSize || cy < -baseSize || cy > settings.canvasSize + baseSize) return null;

                    const r = baseSize / 2;
                    const R = r * Math.sqrt(2); // For diamond calculations

                    return (
                        <g 
                            key={node.id} 
                            transform={`translate(${cx}, ${cy})`}
                            onPointerDown={(e) => handlePointerDown(e, node)}
                            className="cursor-pointer"
                            style={{ pointerEvents: 'all' }}
                        >
                            {/* Halo / Colored Illumination for active nodes */}
                            {isActive && settings.isColoredIlluminationEnabled && (
                                settings.buttonShape === ButtonShape.DIAMOND ? (
                                    <rect 
                                        x={-r * 1.4} y={-r * 1.4} 
                                        width={baseSize * 1.4} height={baseSize * 1.4}
                                        transform="rotate(45)"
                                        fill={outlineColor} 
                                        fillOpacity={0.4} 
                                        filter="blur(8px)"
                                        className="animate-pulse" 
                                    />
                                ) : (
                                    <circle 
                                        r={baseSize * 0.8} 
                                        fill={outlineColor} 
                                        fillOpacity={0.4} 
                                        filter="blur(8px)"
                                        className="animate-pulse" 
                                    />
                                )
                            )}

                            {/* Main Button Shape */}
                            {settings.buttonShape === ButtonShape.DIAMOND ? (
                                <g className="transition-all duration-200">
                                    {/* Top Triangle */}
                                    <polygon points={`0,-${R} ${R},0 -${R},0`} fill={topColor} fillOpacity={fillOpacity} />
                                    {/* Bottom Triangle */}
                                    <polygon points={`0,${R} ${R},0 -${R},0`} fill={bottomColor} fillOpacity={fillOpacity} />
                                    {/* Outline */}
                                    <rect 
                                        x={-r} y={-r} width={baseSize} height={baseSize} 
                                        transform="rotate(45)" 
                                        fill="none" 
                                        stroke={outlineColor} 
                                        strokeWidth={isActive ? 0 : 2} 
                                    />
                                </g>
                            ) : (
                                <g className="transition-all duration-200">
                                    {/* Top Half */}
                                    <path d={`M -${r} 0 A ${r} ${r} 0 0 1 ${r} 0 Z`} fill={topColor} fillOpacity={fillOpacity} />
                                    {/* Bottom Half */}
                                    <path d={`M -${r} 0 A ${r} ${r} 0 0 0 ${r} 0 Z`} fill={bottomColor} fillOpacity={fillOpacity} />
                                    {/* Outline */}
                                    <circle 
                                        r={r} 
                                        fill="none"
                                        stroke={outlineColor}
                                        strokeWidth={isActive ? 0 : 2}
                                    />
                                </g>
                            )}

                            {/* Text Label - White, centered, shadow */}
                            <text 
                                dy=".3em" 
                                textAnchor="middle" 
                                fill="white"
                                fontSize={baseSize * 0.4} 
                                fontWeight="bold" 
                                pointerEvents="none"
                                style={{ 
                                    textShadow: '0px 1px 3px rgba(0,0,0,0.8)',
                                    opacity: isActive ? 1.0 : 0.8
                                }}
                            >
                                {node.n}/{node.d}
                            </text>

                        </g>
                    );
                })}
            </svg>
        </div>
    </div>
  );
});

export default TonalityDiamond;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
  // Minimal data needed to reconstruct/identify
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Screen position of shortcut
}

export interface AppSettings {
  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2Detune: number; // Cents
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';

  // Effects
  reverbMix: number; // 0 to 1
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

import React, { useRef, useState } from 'react';
import { AppSettings, ButtonShape, ChordDefinition } from '../types';
import { DEFAULT_COLORS } from '../constants';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'behavior' | 'color'>('general');

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleLimitDepthChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitDepths: {
        ...settings.limitDepths,
        [limit]: val
      }
    });
  };

  const handleLimitComplexityChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitComplexities: {
        ...settings.limitComplexities,
        [limit]: val
      }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

