}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

// --- Optimized Sub-Components ---

// Define VisualSettings interface to strictly control prop changes
interface VisualSettings {
  colors: AppSettings['colors'];
  layerOrder: AppSettings['layerOrder'];
  isVoiceLeadingEnabled: boolean;
  latchedZoomScale: number;
  latchShellLimit: number;
  voiceLeadingStrength: number;
  voiceLeadingGlowAmount: number;
  voiceLeadingAnimationSpeed: number;
  voiceLeadingReverseDir: boolean;
  isColoredIlluminationEnabled: boolean;
  rainbowOffset: number;
  rainbowSaturation: number;
  rainbowBrightness: number;
  isRainbowModeEnabled: boolean;
  buttonSizeScale: number;
  buttonSpacingScale: number;
  buttonShape: AppSettings['buttonShape'];
  canvasSize: number;
}

const NodeView = React.memo(({ 
    node, 
    visualSettings, 
    isLatched, 
    isHovered, 
    activeNodes, 
    // We pass spacing and centerOffset to avoid recalc
    spacing, 
    centerOffset,
    onPointerDown 
}: {
    node: LatticeNode, 
    visualSettings: VisualSettings, 
    isLatched: boolean, 
    isHovered: boolean, 
    activeNodes: LatticeNode[], 
    spacing: number, 
    centerOffset: number,
    onPointerDown: (e: React.PointerEvent, node: LatticeNode) => void
}) => {
    const left = node.x * spacing + centerOffset;
    const top = node.y * spacing + centerOffset;

    // Culling: If the node is outside the canvas area, do not render.
    if (left < -50 || left > visualSettings.canvasSize + 50 || top < -50 || top > visualSettings.canvasSize + 50) {
        return null;
    }

    const isActive = isLatched || isHovered;

    const getColor = (limit: number): string => visualSettings.colors[limit] || '#64748b';
    const cTop = getColor(node.limitTop);
    const cBottom = getColor(node.limitBottom);

    // Gradient fix: 180deg with strict stops and no-repeat prevents bleed
    const background = `linear-gradient(180deg, ${cTop} 50%, ${cBottom} 50%)`;

    const layerIndex = visualSettings.layerOrder.indexOf(node.maxPrime);
    const zIndex = isActive ? 80 : (10 + layerIndex);

    let scale = 1.0;
    let opacity = 0.95;

    if (visualSettings.isVoiceLeadingEnabled && activeNodes.length > 0) {
        if (isActive) {
            scale = visualSettings.latchedZoomScale;
            opacity = 1.0;
        } else {
            // Unified Voice Leading Logic
            const allowedMaxIndex = visualSettings.latchShellLimit - 2; 
            let isCompatible = false;
            let minDist = Infinity;

            for (const activeNode of activeNodes) {
                 let valid = true;
                 if (visualSettings.latchShellLimit === 1) {
                     const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                     if (hDist > 0) valid = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                         const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                         if (diff > 0 && i > allowedMaxIndex) {
                             valid = false;
                             break;
                         }
                     }
                 }

                 if (valid) {
                    isCompatible = true;
                    const d = getHarmonicDistance(node.coords, activeNode.coords);
                    if (d < minDist) minDist = d;
                 }
            }

            if (!isCompatible) {
                opacity = 0.15; 
                scale = 0.4;
            } else {
                 const falloff = visualSettings.voiceLeadingStrength; 
                 const visibility = Math.max(0.15, 1 - (minDist * falloff));
                 scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                 opacity = visibility;
            }
        }
    } else {
        scale = isActive ? visualSettings.latchedZoomScale : 1.0;
        opacity = isActive ? 1.0 : 0.95;
    }

    // Colored Illumination calculation
    let boxShadowColor = 'white';
    let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');
    let borderStyle = isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)');

    const rainbowPeriod = PITCH_SCALE * spacing;

    if (visualSettings.isColoredIlluminationEnabled) {
         const phase = (top % rainbowPeriod) / rainbowPeriod;
         const hue = (visualSettings.rainbowOffset + phase * 360) % 360;
         const sat = visualSettings.isRainbowModeEnabled ? visualSettings.rainbowSaturation : 100;

         const activeColor = `hsl(${hue}, ${sat}%, 60%)`;

         if (isActive) {
            borderColor = activeColor;
            boxShadowColor = activeColor;
            borderStyle = `4px solid ${borderColor}`;
         }
    }

    const baseSize = 60 * visualSettings.buttonSizeScale;

    return (
        <div
            className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
            style={{
                left: `${left}px`,
                top: `${top}px`,
                width: `${baseSize}px`,
                height: `${baseSize}px`,
                background: background,
                backgroundRepeat: 'no-repeat',
                backgroundSize: '100% 100%',
                backgroundPosition: 'center',
                borderRadius: visualSettings.buttonShape,
                transform: `translate(-50%, -50%) scale(${scale})`,
                boxShadow: isActive ? `0 0 10px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)',
                zIndex: zIndex,
                opacity: opacity,
                border: borderStyle,
                filter: isActive ? 'brightness(1.1)' : 'none'
            }}
            onPointerDown={(e) => onPointerDown(e, node)}
        >
            <div className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}>
                <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
            </div>
        </div>
    );
});

const LineView = React.memo(({ 
    line, 
    n1, n2, 
    visualSettings, 
    n1Active, 
    n2Active, 
    activeNodesCount, 
    activeNeighborCounts,
    spacing,
    centerOffset
}: any) => {
    let x1 = line.x1 * spacing + centerOffset;
    let y1 = line.y1 * spacing + centerOffset;
    let x2 = line.x2 * spacing + centerOffset;
    let y2 = line.y2 * spacing + centerOffset;

    // Culling
    if (x1 < 0 || x1 > visualSettings.canvasSize || y1 < 0 || y1 > visualSettings.canvasSize ||
        x2 < 0 || x2 > visualSettings.canvasSize || y2 < 0 || y2 > visualSettings.canvasSize) {
        return null;
    }

    const getColor = (limit: number): string => visualSettings.colors[limit] || '#64748b';
    const limitColor = getColor(line.limit);

    let strokeColor = limitColor;
    let lineOpacity = 0.1;
    let lineWidth = line.limit === 1 ? 4 : 2;
    let isVoiceLeadingActive = false;
    let lineStyle = {};

    if (n1Active && n2Active) {
        // Fully Active Connection
        lineOpacity = 1.0;
        lineWidth = 5;
        strokeColor = limitColor; 
        isVoiceLeadingActive = true;

        lineStyle = { 
            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
        };

        // Directional Logic
        const axisIndex = LIMIT_TO_INDEX[line.limit];
        if (axisIndex !== undefined && n1 && n2) {
            const c1 = n1.coords[axisIndex];
            const c2 = n2.coords[axisIndex];

            let swap = c1 > c2;
            if (visualSettings.voiceLeadingReverseDir) swap = !swap;

            if (swap) {
                const tempX = x1; const tempY = y1;
                x1 = x2; y1 = y2;
                x2 = tempX; y2 = tempY;
            }
        }

    } else if (n1Active || n2Active) {
        // One active, one inactive - Reinforcement Logic
        const inactiveNodeId = n1Active ? n2.id : n1.id;
        const activeCount = activeNeighborCounts.get(inactiveNodeId) || 0;

        if (activeCount >= 2) {
            // Reinforced Bridge Style
            lineOpacity = 0.85;
            lineWidth = 4;
            lineStyle = { 
                filter: `brightness(1.2)` 
            };
        } else {
            // Standard Neighbor Style
            lineOpacity = 0.6;
            lineWidth = 3;
        }

    } else if (visualSettings.isVoiceLeadingEnabled && activeNodesCount > 0) {
        lineOpacity = 0.05;
    }

    // "Animate Connections" Visual: Smaller, softer glow
    // Reduce size by 50% relative to line width to optimize processing and create "glow point" look
    const glowWidthMultiplier = (1 + (visualSettings.voiceLeadingGlowAmount * 3)) * 0.5; 
    const animStrokeWidth = Math.max(2, lineWidth * glowWidthMultiplier); 

    return (
        <g>
            {/* Base Line */}
            <line 
                x1={x1} y1={y1} x2={x2} y2={y2}
                stroke={strokeColor}
                strokeWidth={lineWidth}
                strokeOpacity={lineOpacity}
                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                style={lineStyle}
            />
            {/* Animation Overlay - Pure diffuse light via filter (No SourceGraphic) */}
            {isVoiceLeadingActive && visualSettings.isVoiceLeadingAnimationEnabled && (
                <line 
                    x1={x1} y1={y1} x2={x2} y2={y2}
                    stroke="white"
                    strokeWidth={animStrokeWidth}
                    strokeOpacity={0.8}
                    strokeLinecap="round" 
                    strokeDasharray={`0 100`} 
                    filter="url(#glow)"
                    className="animate-flow"
                />
            )}
        </g>
    );
});

// --- Main Component ---

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); 
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  // Create a stable VisualSettings object to separate visual updates from UI dragging updates (uiPositions)
  // This ensures NodeView and LineView do not re-render when UI buttons are dragged.
  const visualSettings: VisualSettings = useMemo(() => ({
    colors: settings.colors,
    layerOrder: settings.layerOrder,
    isVoiceLeadingEnabled: settings.isVoiceLeadingEnabled,
    latchedZoomScale: settings.latchedZoomScale,
    latchShellLimit: settings.latchShellLimit,
    voiceLeadingStrength: settings.voiceLeadingStrength,
    voiceLeadingGlowAmount: settings.voiceLeadingGlowAmount,
    voiceLeadingAnimationSpeed: settings.voiceLeadingAnimationSpeed,
    voiceLeadingReverseDir: settings.voiceLeadingReverseDir,
    isColoredIlluminationEnabled: settings.isColoredIlluminationEnabled,
    rainbowOffset: settings.rainbowOffset,
    rainbowSaturation: settings.rainbowSaturation,
    rainbowBrightness: settings.rainbowBrightness,
    isRainbowModeEnabled: settings.isRainbowModeEnabled,
    buttonSizeScale: settings.buttonSizeScale,
    buttonSpacingScale: settings.buttonSpacingScale,
    buttonShape: settings.buttonShape,
    canvasSize: settings.canvasSize,
  }), [
    settings.colors, settings.layerOrder, settings.isVoiceLeadingEnabled,
    settings.latchedZoomScale, settings.latchShellLimit, settings.voiceLeadingStrength,
    settings.voiceLeadingGlowAmount, settings.voiceLeadingAnimationSpeed,
    settings.voiceLeadingReverseDir, settings.isColoredIlluminationEnabled,
    settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness,
    settings.isRainbowModeEnabled, settings.buttonSizeScale, settings.buttonSpacingScale,
    settings.buttonShape, settings.canvasSize
  ]);

  // Lattice Generation
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  // Determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id);
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency]);

  // Audio Sync
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
               }
          }
      });

      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // Stable Handler using useCallback
  const handlePointerDown = useCallback((e: React.PointerEvent, node: LatticeNode) => {
    if (uiUnlocked) return; 

    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNode({ coords: node.coords, octave: node.octave });

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio, settings.baseFrequency);
    }
  }, [uiUnlocked, settings.isLatchModeEnabled, settings.isPitchBendEnabled, settings.baseFrequency, onLimitInteraction, audioEngine]);

  // Note: We use data.nodes inside move handler. We need it to be stable or up to date.
  // Since we are not passing this to NodeView, it's fine if it re-creates.
  // But to optimize the loop, we keep refs? No, logic depends on node positions.
  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;

    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNode({ coords: node.coords, octave: node.octave });
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (manualLatchedNodes.has(cursor.originNodeId)) {
                 setManualLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     return next;
                 });
             }
        }
    }
  };

  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Memoize activeNodes calculation
  const activeNodes = useMemo(() => {
      return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
  }, [data.nodes, effectiveLatchedNodes]);

  // Node Map O(1)
  const nodeMap = useMemo(() => {
      const map = new Map<string, LatticeNode>();
      data.nodes.forEach(n => map.set(n.id, n));
      return map;
  }, [data.nodes]);

  // Memoize Active Neighbor Counts
  const activeNeighborCounts = useMemo(() => {
      const counts = new Map<string, number>();
      if (settings.isVoiceLeadingEnabled) {
          data.lines.forEach(line => {
              const n1Active = effectiveLatchedNodes.has(line.sourceId);
              const n2Active = effectiveLatchedNodes.has(line.targetId);

              if (n1Active && !n2Active) {
                  counts.set(line.targetId, (counts.get(line.targetId) || 0) + 1);
              }
              if (!n1Active && n2Active) {
                  counts.set(line.sourceId, (counts.get(line.sourceId) || 0) + 1);
              }
          });
      }
      return counts;
  }, [settings.isVoiceLeadingEnabled, data.lines, effectiveLatchedNodes]);

  // Rainbow Background
  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * spacing;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness, spacing]);

  const cursors: ActiveCursor[] = Array.from(activeCursors.values());

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                      </feMerge>
                   </filter>
                </defs>

                {data.lines.map(line => {
                     const n1 = nodeMap.get(line.sourceId);
                     const n2 = nodeMap.get(line.targetId);
                     if (!n1 || !n2) return null;

                     return (
                         <LineView 
                            key={line.id}
                            line={line}
                            n1={n1}
                            n2={n2}
                            visualSettings={visualSettings}
                            n1Active={effectiveLatchedNodes.has(line.sourceId)}
                            n2Active={effectiveLatchedNodes.has(line.targetId)}
                            activeNodesCount={activeNodes.length}
                            activeNeighborCounts={activeNeighborCounts}
                            spacing={spacing}
                            centerOffset={centerOffset}
                         />
                     );
                })}

                {cursors.map(cursor => {
                    const node = nodeMap.get(cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = effectiveLatchedNodes.has(node.id);
                // We calculate isHovered here for the prop, but cursor updates trigger re-render of this list.
                // NodeView memoization prevents deep render if prop doesn't change.
                const isHovered = cursors.some(c => c.originNodeId === node.id); 

                return (
                    <NodeView 
                        key={node.id}
                        node={node}
                        visualSettings={visualSettings}
                        isLatched={isLatched}
                        isHovered={isHovered}
                        activeNodes={activeNodes}
                        spacing={spacing}
                        centerOffset={centerOffset}
                        onPointerDown={handlePointerDown}
                    />
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo, useCallback } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ChordDefinition, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

// --- Optimized Sub-Components ---

// Define VisualSettings interface to strictly control prop changes
interface VisualSettings {
  colors: AppSettings['colors'];
  layerOrder: AppSettings['layerOrder'];
  isVoiceLeadingEnabled: boolean;
  latchedZoomScale: number;
  latchShellLimit: number;
  voiceLeadingStrength: number;
  voiceLeadingGlowAmount: number;
  voiceLeadingAnimationSpeed: number;
  voiceLeadingReverseDir: boolean;
  isColoredIlluminationEnabled: boolean;
  rainbowOffset: number;
  rainbowSaturation: number;
  rainbowBrightness: number;
  isRainbowModeEnabled: boolean;
  buttonSizeScale: number;
  buttonSpacingScale: number;
  buttonShape: AppSettings['buttonShape'];
  canvasSize: number;
}

const NodeView = React.memo(({ 
    node, 
    visualSettings, 
    isLatched, 
    isHovered, 
    activeNodes, 
    spacing, 
    centerOffset,
    onPointerDown 
}: {
    node: LatticeNode, 
    visualSettings: VisualSettings, 
    isLatched: boolean, 
    isHovered: boolean, 
    activeNodes: LatticeNode[], 
    spacing: number, 
    centerOffset: number,
    onPointerDown: (e: React.PointerEvent, node: LatticeNode) => void
}) => {
    const left = node.x * spacing + centerOffset;
    const top = node.y * spacing + centerOffset;

    // Culling: If the node is outside the canvas area, do not render.
    if (left < -50 || left > visualSettings.canvasSize + 50 || top < -50 || top > visualSettings.canvasSize + 50) {
        return null;
    }

    const isActive = isLatched || isHovered;
    const isDiamond = visualSettings.buttonShape === ButtonShape.DIAMOND;

    const getColor = (limit: number): string => visualSettings.colors[limit] || '#64748b';
    const cTop = getColor(node.limitTop);
    const cBottom = getColor(node.limitBottom);

    // Gradient Angle: 180deg for standard, 135deg for rotated diamond to appear vertical on screen
    const gradientAngle = isDiamond ? '135deg' : '180deg';
    // Gradient fix: Strict stops, no-repeat, and padding-box clip to prevent border bleed
    const background = `linear-gradient(${gradientAngle}, ${cTop} 50%, ${cBottom} 50%)`;

    const layerIndex = visualSettings.layerOrder.indexOf(node.maxPrime);
    const zIndex = isActive ? 80 : (10 + layerIndex);

    let scale = 1.0;
    let opacity = 0.95;

    if (visualSettings.isVoiceLeadingEnabled && activeNodes.length > 0) {
        if (isActive) {
            scale = visualSettings.latchedZoomScale;
            opacity = 1.0;
        } else {
            // Unified Voice Leading Logic
            const allowedMaxIndex = visualSettings.latchShellLimit - 2; 
            let isCompatible = false;
            let minDist = Infinity;

            for (const activeNode of activeNodes) {
                 let valid = true;
                 if (visualSettings.latchShellLimit === 1) {
                     const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                     if (hDist > 0) valid = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                         const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                         if (diff > 0 && i > allowedMaxIndex) {
                             valid = false;
                             break;
                         }
                     }
                 }

                 if (valid) {
                    isCompatible = true;
                    const d = getHarmonicDistance(node.coords, activeNode.coords);
                    if (d < minDist) minDist = d;
                 }
            }

            if (!isCompatible) {
                opacity = 0.15; 
                scale = 0.4;
            } else {
                 const falloff = visualSettings.voiceLeadingStrength; 
                 const visibility = Math.max(0.15, 1 - (minDist * falloff));
                 scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                 opacity = visibility;
            }
        }
    } else {
        scale = isActive ? visualSettings.latchedZoomScale : 1.0;
        opacity = isActive ? 1.0 : 0.95;
    }

    // Colored Illumination calculation
    let boxShadowColor = 'white';
    let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');
    let borderStyle = isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)');

    const rainbowPeriod = PITCH_SCALE * spacing;

    if (visualSettings.isColoredIlluminationEnabled) {
         const phase = (top % rainbowPeriod) / rainbowPeriod;
         const hue = (visualSettings.rainbowOffset + phase * 360) % 360;
         const sat = visualSettings.isRainbowModeEnabled ? visualSettings.rainbowSaturation : 100;

         const activeColor = `hsl(${hue}, ${sat}%, 60%)`;

         if (isActive) {
            borderColor = activeColor;
            boxShadowColor = activeColor;
            borderStyle = `4px solid ${borderColor}`;
         }
    }

    const baseSize = 60 * visualSettings.buttonSizeScale;

    // Rotation logic for Diamond shape
    const transformRotate = isDiamond ? 'rotate(45deg)' : '';
    const transformScale = `scale(${scale})`;
    const transformTotal = `translate(-50%, -50%) ${transformRotate} ${transformScale}`;

    return (
        <div
            className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
            style={{
                left: `${left}px`,
                top: `${top}px`,
                width: `${baseSize}px`,
                height: `${baseSize}px`,
                background: background,
                backgroundRepeat: 'no-repeat',
                backgroundSize: '100% 100%',
                backgroundPosition: 'center',
                backgroundClip: 'padding-box', // Prevents background from bleeding into transparent borders
                borderRadius: visualSettings.buttonShape,
                transform: transformTotal,
                boxShadow: isActive ? `0 0 10px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)',
                zIndex: zIndex,
                opacity: opacity,
                border: borderStyle,
                filter: isActive ? 'brightness(1.1)' : 'none'
            }}
            onPointerDown={(e) => onPointerDown(e, node)}
        >
            {/* Counter-rotate content if diamond to keep text upright */}
            <div 
                className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}
                style={{ transform: isDiamond ? 'rotate(-45deg)' : 'none' }}
            >
                <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
            </div>
        </div>
    );
});

const LineView = React.memo(({ 
    line, 
    n1, n2, 
    visualSettings, 
    n1Active, 
    n2Active, 
    activeNodesCount, 
    activeNeighborCounts,
    spacing,
    centerOffset
}: any) => {
    let x1 = line.x1 * spacing + centerOffset;
    let y1 = line.y1 * spacing + centerOffset;
    let x2 = line.x2 * spacing + centerOffset;
    let y2 = line.y2 * spacing + centerOffset;

    // Culling
    if (x1 < 0 || x1 > visualSettings.canvasSize || y1 < 0 || y1 > visualSettings.canvasSize ||
        x2 < 0 || x2 > visualSettings.canvasSize || y2 < 0 || y2 > visualSettings.canvasSize) {
        return null;
    }

    const getColor = (limit: number): string => visualSettings.colors[limit] || '#64748b';
    const limitColor = getColor(line.limit);

    let strokeColor = limitColor;
    let lineOpacity = 0.1;
    let lineWidth = line.limit === 1 ? 4 : 2;
    let isVoiceLeadingActive = false;
    let lineStyle = {};

    if (n1Active && n2Active) {
        // Fully Active Connection
        lineOpacity = 1.0;
        lineWidth = 5;
        strokeColor = limitColor; 
        isVoiceLeadingActive = true;

        lineStyle = { 
            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
        };

        // Directional Logic
        const axisIndex = LIMIT_TO_INDEX[line.limit];
        if (axisIndex !== undefined && n1 && n2) {
            const c1 = n1.coords[axisIndex];
            const c2 = n2.coords[axisIndex];

            let swap = c1 > c2;
            if (visualSettings.voiceLeadingReverseDir) swap = !swap;

            if (swap) {
                const tempX = x1; const tempY = y1;
                x1 = x2; y1 = y2;
                x2 = tempX; y2 = tempY;
            }
        }

    } else if (n1Active || n2Active) {
        // One active, one inactive - Reinforcement Logic
        const inactiveNodeId = n1Active ? n2.id : n1.id;
        const activeCount = activeNeighborCounts.get(inactiveNodeId) || 0;

        if (activeCount >= 2) {
            // Reinforced Bridge Style
            lineOpacity = 0.85;
            lineWidth = 4;
            lineStyle = { 
                filter: `brightness(1.2)` 
            };
        } else {
            // Standard Neighbor Style
            lineOpacity = 0.6;
            lineWidth = 3;
        }

    } else if (visualSettings.isVoiceLeadingEnabled && activeNodesCount > 0) {
        lineOpacity = 0.05;
    }

    // "Animate Connections" Visual: Smaller, softer glow
    const glowWidthMultiplier = (1 + (visualSettings.voiceLeadingGlowAmount * 3)) * 0.5; 
    const animStrokeWidth = Math.max(2, lineWidth * glowWidthMultiplier); 

    return (
        <g>
            {/* Base Line */}
            <line 
                x1={x1} y1={y1} x2={x2} y2={y2}
                stroke={strokeColor}
                strokeWidth={lineWidth}
                strokeOpacity={lineOpacity}
                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                style={lineStyle}
            />
            {/* Animation Overlay - Pure diffuse light via filter (No SourceGraphic) */}
            {isVoiceLeadingActive && visualSettings.isVoiceLeadingAnimationEnabled && (
                <line 
                    x1={x1} y1={y1} x2={x2} y2={y2}
                    stroke="white"
                    strokeWidth={animStrokeWidth}
                    strokeOpacity={0.8}
                    strokeLinecap="round" 
                    strokeDasharray={`0 100`} 
                    filter="url(#glow)"
                    className="animate-flow"
                />
            )}
        </g>
    );
});

// --- Main Component ---

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => {
      setManualLatchedNodes(new Map()); 
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        if (scrollContainerRef.current) {
            const center = settings.canvasSize / 2;
            const viewportW = scrollContainerRef.current.clientWidth;
            const viewportH = scrollContainerRef.current.clientHeight;
            scrollContainerRef.current.scrollLeft = center - viewportW / 2;
            scrollContainerRef.current.scrollTop = center - viewportH / 2;
        }
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        const nodes: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const node = data.nodes.find(n => n.id === id);
            if (node) nodes.push(node);
        });
        return nodes;
    }
  }));

  // Create a stable VisualSettings object
  const visualSettings: VisualSettings = useMemo(() => ({
    colors: settings.colors,
    layerOrder: settings.layerOrder,
    isVoiceLeadingEnabled: settings.isVoiceLeadingEnabled,
    latchedZoomScale: settings.latchedZoomScale,
    latchShellLimit: settings.latchShellLimit,
    voiceLeadingStrength: settings.voiceLeadingStrength,
    voiceLeadingGlowAmount: settings.voiceLeadingGlowAmount,
    voiceLeadingAnimationSpeed: settings.voiceLeadingAnimationSpeed,
    voiceLeadingReverseDir: settings.voiceLeadingReverseDir,
    isColoredIlluminationEnabled: settings.isColoredIlluminationEnabled,
    rainbowOffset: settings.rainbowOffset,
    rainbowSaturation: settings.rainbowSaturation,
    rainbowBrightness: settings.rainbowBrightness,
    isRainbowModeEnabled: settings.isRainbowModeEnabled,
    buttonSizeScale: settings.buttonSizeScale,
    buttonSpacingScale: settings.buttonSpacingScale,
    buttonShape: settings.buttonShape,
    canvasSize: settings.canvasSize,
  }), [
    settings.colors, settings.layerOrder, settings.isVoiceLeadingEnabled,
    settings.latchedZoomScale, settings.latchShellLimit, settings.voiceLeadingStrength,
    settings.voiceLeadingGlowAmount, settings.voiceLeadingAnimationSpeed,
    settings.voiceLeadingReverseDir, settings.isColoredIlluminationEnabled,
    settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness,
    settings.isRainbowModeEnabled, settings.buttonSizeScale, settings.buttonSpacingScale,
    settings.buttonShape, settings.canvasSize
  ]);

  // Lattice Generation
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  // Determine Effective Latches
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) {
                    newEffective.set(n.id, n.id);
                }
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;

  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, audioEngine, settings.baseFrequency]);

  // Audio Sync
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
               }
          }
      });

      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency, audioEngine]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map<string, string>(prev);
        let changed = false;

        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) {
                next.delete(nodeId);
                changed = true;
                return;
            }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) {
                     next.delete(nodeId);
                     changed = true;
                     return;
                 }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) {
                            isAllowed = false;
                            break;
                        }
                     }
                 }

                 if (!isAllowed) {
                     next.delete(nodeId);
                     changed = true;
                 }
            }
        });

        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useLayoutEffect(() => {
    if (scrollContainerRef.current && !hasCentered) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;

        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
        setHasCentered(true);
    }
  }, [settings.canvasSize, hasCentered]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony, audioEngine]);

  // --- Logic Helpers ---

  const toggleLatch = (nodeId: string, ratio: number) => {
    setManualLatchedNodes(prev => {
        const newMap = new Map(prev);
        if (newMap.has(nodeId)) {
            newMap.delete(nodeId);
        } else {
            newMap.set(nodeId, nodeId);
        }
        return newMap;
    });
  };

  const latchOn = (nodeId: string, ratio: number, originId: string) => {
      setManualLatchedNodes(prev => {
          if (prev.has(nodeId)) return prev; 
          const newMap = new Map(prev);
          newMap.set(nodeId, originId);
          return newMap;
      });
  };

  // Stable Handler using useCallback
  const handlePointerDown = useCallback((e: React.PointerEvent, node: LatticeNode) => {
    if (uiUnlocked) return; 

    e.preventDefault();
    e.stopPropagation();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);

    onLimitInteraction(node.maxPrime);
    setLastTouchedNode({ coords: node.coords, octave: node.octave });

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: node.id
        });
        return next;
    });

    if (settings.isLatchModeEnabled) {
        toggleLatch(node.id, node.ratio);
    } else {
        latchOn(node.id, node.ratio, node.id);
    }

    if (settings.isPitchBendEnabled) {
        const cursorId = `cursor-${e.pointerId}`;
        audioEngine.startVoice(cursorId, node.ratio, settings.baseFrequency);
    }
  }, [uiUnlocked, settings.isLatchModeEnabled, settings.isPitchBendEnabled, settings.baseFrequency, onLimitInteraction, audioEngine]);

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;

    if (!activeCursors.has(e.pointerId)) return;
    const cursor = activeCursors.get(e.pointerId)!;

    setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(e.pointerId, {
            ...cursor,
            currentX: e.clientX,
            currentY: e.clientY
        });
        return next;
    });

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
        const centerOffset = settings.canvasSize / 2;
        const scrollLeft = scrollContainerRef.current.scrollLeft;
        const scrollTop = scrollContainerRef.current.scrollTop;

        const canvasY = e.clientY + scrollTop;
        const relY = canvasY - centerOffset;

        const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
        const bentRatio = Math.pow(2, -relY / effectivePitchScale);

        audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

        if (settings.isLatchModeEnabled) {
            const spacing = settings.buttonSpacingScale;

            for (const node of data.nodes) {
                if (node.id === cursor.originNodeId) continue;

                const nx = (node.x * spacing + centerOffset) - scrollLeft;
                const ny = (node.y * spacing + centerOffset) - scrollTop;

                const radius = (60 * settings.buttonSizeScale) / 2;
                const dx = e.clientX - nx;
                const dy = e.clientY - ny;
                const distSq = dx*dx + dy*dy;

                if (distSq < radius * radius) {
                    if (!manualLatchedNodes.has(node.id)) {
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (originNode) {
                             const allowedMaxIndex = settings.latchShellLimit - 2; 

                             let isAllowed = true;
                             if (settings.latchShellLimit === 1) {
                                 const hDist = getHarmonicDistance(node.coords, originNode.coords);
                                 if (hDist > 0) isAllowed = false;
                             } else {
                                 for(let i=0; i<node.coords.length; i++) {
                                     const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                     if (diff > 0 && i > allowedMaxIndex) {
                                         isAllowed = false;
                                         break;
                                     }
                                 }
                             }

                             if (isAllowed) {
                                 latchOn(node.id, node.ratio, cursor.originNodeId);
                                 setLastTouchedNode({ coords: node.coords, octave: node.octave });
                             }
                         }
                    }
                }
            }
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }

    if (!settings.isLatchModeEnabled) {
        const cursor = activeCursors.get(e.pointerId);
        if (cursor) {
             if (manualLatchedNodes.has(cursor.originNodeId)) {
                 setManualLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(cursor.originNodeId);
                     return next;
                 });
             }
        }
    }
  };

  const centerOffset = settings.canvasSize / 2;
  const spacing = settings.buttonSpacingScale;

  // Memoize activeNodes calculation
  const activeNodes = useMemo(() => {
      return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
  }, [data.nodes, effectiveLatchedNodes]);

  // Node Map O(1)
  const nodeMap = useMemo(() => {
      const map = new Map<string, LatticeNode>();
      data.nodes.forEach(n => map.set(n.id, n));
      return map;
  }, [data.nodes]);

  // Memoize Active Neighbor Counts
  const activeNeighborCounts = useMemo(() => {
      const counts = new Map<string, number>();
      if (settings.isVoiceLeadingEnabled) {
          data.lines.forEach(line => {
              const n1Active = effectiveLatchedNodes.has(line.sourceId);
              const n2Active = effectiveLatchedNodes.has(line.targetId);

              if (n1Active && !n2Active) {
                  counts.set(line.targetId, (counts.get(line.targetId) || 0) + 1);
              }
              if (!n1Active && n2Active) {
                  counts.set(line.sourceId, (counts.get(line.sourceId) || 0) + 1);
              }
          });
      }
      return counts;
  }, [settings.isVoiceLeadingEnabled, data.lines, effectiveLatchedNodes]);

  // Rainbow Background
  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * spacing;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness, spacing]);

  const cursors: ActiveCursor[] = Array.from(activeCursors.values());

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
            <style>{`
              @keyframes flowAnimation {
                to { stroke-dashoffset: -100; }
              }
              .animate-flow {
                animation: flowAnimation ${settings.voiceLeadingAnimationSpeed}s linear infinite;
              }
            `}</style>

            <svg className="absolute top-0 left-0 w-full h-full pointer-events-none" style={{ zIndex: 0 }}>
                <defs>
                   <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                      <feGaussianBlur stdDeviation={settings.voiceLeadingGlowAmount * 4} result="coloredBlur"/>
                      <feMerge>
                         <feMergeNode in="coloredBlur"/>
                      </feMerge>
                   </filter>
                </defs>

                {data.lines.map(line => {
                     const n1 = nodeMap.get(line.sourceId);
                     const n2 = nodeMap.get(line.targetId);
                     if (!n1 || !n2) return null;

                     return (
                         <LineView 
                            key={line.id}
                            line={line}
                            n1={n1}
                            n2={n2}
                            visualSettings={visualSettings}
                            n1Active={effectiveLatchedNodes.has(line.sourceId)}
                            n2Active={effectiveLatchedNodes.has(line.targetId)}
                            activeNodesCount={activeNodes.length}
                            activeNeighborCounts={activeNeighborCounts}
                            spacing={spacing}
                            centerOffset={centerOffset}
                         />
                     );
                })}

                {cursors.map(cursor => {
                    const node = nodeMap.get(cursor.originNodeId);
                    if (!node) return null;
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const cx = cursor.currentX + (scrollContainerRef.current?.scrollLeft || 0);
                    const cy = cursor.currentY + (scrollContainerRef.current?.scrollTop || 0);
                    return (
                         <line 
                           key={`drag-${cursor.pointerId}`}
                           x1={nx} y1={ny} x2={cx} y2={cy}
                           stroke="white"
                           strokeWidth={2}
                           strokeOpacity={0.5}
                         />
                    );
                })}
            </svg>

            {data.nodes.map((node) => {
                const isLatched = effectiveLatchedNodes.has(node.id);
                // We calculate isHovered here for the prop, but cursor updates trigger re-render of this list.
                // NodeView memoization prevents deep render if prop doesn't change.
                const isHovered = cursors.some(c => c.originNodeId === node.id); 

                return (
                    <NodeView 
                        key={node.id}
                        node={node}
                        visualSettings={visualSettings}
                        isLatched={isLatched}
                        isHovered={isHovered}
                        activeNodes={activeNodes}
                        spacing={spacing}
                        centerOffset={centerOffset}
                        onPointerDown={handlePointerDown}
                    />
                );
            })}
        </div>
    </div>
  );
});

export default TonalityDiamond;

import { SynthPreset, WaveformType } from '../types';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private limiter: DynamicsCompressorNode | null = null;

  // FX Nodes
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;
  private dryGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;

  // Voice map stores the graph for each active note
  private voices: Map<string, { 
    osc1: OscillatorNode; 
    osc2: OscillatorNode; 
    lfo?: OscillatorNode;
    gain: GainNode; 
    filter: BiquadFilterNode; 
    startRatio: number 
  }> = new Map();

  private maxPolyphony: number = 12;
  private activePreset: SynthPreset;

  constructor(preset: SynthPreset) {
    this.activePreset = preset;
  }

  public init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
        latencyHint: 'interactive',
      });

      // Limiter (DynamicsCompressor)
      this.limiter = this.ctx.createDynamicsCompressor();
      this.limiter.threshold.value = -1.0; 
      this.limiter.knee.value = 10;
      this.limiter.ratio.value = 20; 
      this.limiter.attack.value = 0.005; 
      this.limiter.release.value = 0.2;
      this.limiter.connect(this.ctx.destination);

      // Master Gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = this.currentMasterVol; 
      this.masterGain.connect(this.limiter); 

      // --- FX Bus Setup ---

      // Dry Bus
      this.dryGain = this.ctx.createGain();
      this.dryGain.gain.value = 1.0; 
      this.dryGain.connect(this.masterGain);

      // Reverb Bus
      this.reverbNode = this.ctx.createConvolver();
      this.reverbNode.buffer = this.createImpulseResponse(2.5, 2.0); // 2.5s duration, 2.0 decay
      this.reverbGain = this.ctx.createGain();
      this.reverbGain.connect(this.reverbNode);
      this.reverbNode.connect(this.masterGain);

      // Delay Bus
      this.delayNode = this.ctx.createDelay(5.0);
      this.delayFeedbackGain = this.ctx.createGain();
      this.delayOutputGain = this.ctx.createGain();

      // Send logic: Voice -> DelayOutputGain -> DelayNode -> Master
      // Feedback: DelayNode -> DelayFeedbackGain -> DelayNode

      this.delayOutputGain.connect(this.delayNode);
      this.delayNode.connect(this.masterGain);

      this.delayNode.connect(this.delayFeedbackGain);
      this.delayFeedbackGain.connect(this.delayNode);

      // Apply initial preset settings to FX
      this.updateFX();
    }

    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      // Update Gains
      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(this.activePreset.reverbMix, now, ramp);

      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(this.activePreset.delayMix, now, ramp);
      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(this.activePreset.delayTime, now, ramp);
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(this.activePreset.delayFeedback, now, ramp);

      // Update Dynamics (Compressor/Limiter)
      if (this.limiter) {
          // Default to sensible values if preset lacks new fields (during migration/dev)
          const thresh = this.activePreset.compressorThreshold ?? -1.0;
          const ratio = this.activePreset.compressorRatio ?? 20;
          const release = this.activePreset.compressorRelease ?? 0.2;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      // Dry attenuation
      if (this.dryGain) this.dryGain.gain.setTargetAtTime(Math.max(0.5, 1.0 - (this.activePreset.reverbMix * 0.3)), now, ramp);
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    const sampleRate = this.ctx!.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx!.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        left[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
        right[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
    }
    return impulse;
  }

  public setPolyphony(count: number) {
    this.maxPolyphony = count;
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(val, this.ctx.currentTime, 0.05);
    }
  }

  public setPreset(preset: SynthPreset) {
    this.activePreset = preset;
    this.updateFX();
  }

  public startVoice(id: string, ratio: number, baseFrequency: number) {
    this.init();
    if (!this.ctx || !this.dryGain || !this.reverbGain || !this.delayOutputGain) return;

    // Restart logic
    if (this.voices.has(id)) {
        this.stopVoice(id, true);
    }

    // Voice stealing
    if (this.voices.size >= this.maxPolyphony) {
      const firstKey = this.voices.keys().next().value;
      if (firstKey !== undefined) this.stopVoice(firstKey, true); 
    }

    const now = this.ctx.currentTime;
    const baseFreq = baseFrequency * ratio;

    // --- Audio Graph Construction ---

    const masterVoiceGain = this.ctx.createGain(); 
    const filter = this.ctx.createBiquadFilter();

    // Oscillator 1
    const osc1 = this.ctx.createOscillator();
    osc1.type = this.activePreset.waveform;
    osc1.frequency.value = baseFreq;

    // Oscillator 2
    const osc2 = this.ctx.createOscillator();
    osc2.type = this.activePreset.osc2Waveform;
    const detuneMultiplier = Math.pow(2, this.activePreset.osc2Detune / 1200);
    osc2.frequency.value = baseFreq * detuneMultiplier;

    const osc2Gain = this.ctx.createGain();
    osc2Gain.gain.value = this.activePreset.osc2Mix;

    // Connections
    osc1.connect(filter);
    osc2.connect(osc2Gain);
    osc2Gain.connect(filter);

    // Filter Settings
    filter.type = 'lowpass';
    filter.frequency.value = this.activePreset.filterCutoff;
    filter.Q.value = this.activePreset.filterResonance;

    filter.connect(masterVoiceGain);

    // LFO Setup (Conditional)
    let lfo: OscillatorNode | undefined;

    if (this.activePreset.lfoTarget !== 'none') {
        lfo = this.ctx.createOscillator();
        lfo.type = 'sine';
        lfo.frequency.value = this.activePreset.lfoRate;
        const lfoGain = this.ctx.createGain();

        // LFO Depth Scaling
        const rawDepth = this.activePreset.lfoDepth;
        let effectiveGain = 0;

        if (this.activePreset.lfoTarget === 'pitch') {
            effectiveGain = rawDepth; 
        } else if (this.activePreset.lfoTarget === 'filter') {
            effectiveGain = rawDepth * 20; 
        } else if (this.activePreset.lfoTarget === 'tremolo') {
            effectiveGain = (rawDepth / 100) * 0.5;
        }

        lfoGain.gain.value = effectiveGain;

        // LFO Routing
        lfo.connect(lfoGain);

        if (this.activePreset.lfoTarget === 'pitch') {
            lfoGain.connect(osc1.frequency);
            lfoGain.connect(osc2.frequency);
        } else if (this.activePreset.lfoTarget === 'filter') {
            lfoGain.connect(filter.frequency);
        } else if (this.activePreset.lfoTarget === 'tremolo') {
            lfoGain.connect(masterVoiceGain.gain);
        }

        lfo.start(now);
    }

    // Output Routing to Busses
    masterVoiceGain.connect(this.dryGain);
    masterVoiceGain.connect(this.reverbGain);
    masterVoiceGain.connect(this.delayOutputGain);

    // --- Envelope Control ---
    const voiceNormalization = 0.6; 
    const targetGain = this.activePreset.gain * voiceNormalization;

    masterVoiceGain.gain.setValueAtTime(0, now);
    masterVoiceGain.gain.linearRampToValueAtTime(targetGain, now + this.activePreset.attack);
    masterVoiceGain.gain.exponentialRampToValueAtTime(Math.max(0.001, targetGain * this.activePreset.sustain), now + this.activePreset.attack + this.activePreset.decay);

    // Start Oscillators
    osc1.start(now);
    osc2.start(now);

    this.voices.set(id, { osc1, osc2, lfo, gain: masterVoiceGain, filter, startRatio: ratio });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.ctx) return;
    const voice = this.voices.get(id);
    if (voice) {
      const now = this.ctx.currentTime;

      voice.gain.gain.cancelScheduledValues(now);
      voice.gain.gain.setValueAtTime(voice.gain.gain.value, now);

      const releaseTime = immediate ? 0.05 : this.activePreset.release;

      voice.gain.gain.exponentialRampToValueAtTime(0.001, now + releaseTime);

      const stopTime = now + releaseTime + 0.1;
      voice.osc1.stop(stopTime);
      voice.osc2.stop(stopTime);
      if (voice.lfo) voice.lfo.stop(stopTime);

      setTimeout(() => {
        try {
            voice.osc1.disconnect();
            voice.osc2.disconnect();
            if (voice.lfo) voice.lfo.disconnect();
            voice.gain.disconnect();
            voice.filter.disconnect();
        } catch(e) {}
      }, (releaseTime + 0.2) * 1000);

      this.voices.delete(id);
    }
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number, glideTime: number = 0.1) {
    const voice = this.voices.get(id);
    if (voice && this.ctx) {
       const newFreq = baseFrequency * newRatio;
       voice.osc1.frequency.setTargetAtTime(newFreq, this.ctx.currentTime, glideTime);

       const detuneMultiplier = Math.pow(2, this.activePreset.osc2Detune / 1200);
       voice.osc2.frequency.setTargetAtTime(newFreq * detuneMultiplier, this.ctx.currentTime, glideTime);

       voice.startRatio = newRatio; 
    }
  }

  public stopAll() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;

    // 1. Hard kill all active voices
    this.voices.forEach((voice) => {
        try {
            // Immediate stop, no release phase
            voice.osc1.stop();
            voice.osc2.stop();
            if (voice.lfo) voice.lfo.stop();
            voice.gain.disconnect();
        } catch (e) {
            console.error("Error hard-stopping voice", e);
        }
    });
    this.voices.clear();

    // 2. Kill FX Feedback loops immediately
    // This stops delay trails from regenerating
    if (this.delayFeedbackGain) {
        this.delayFeedbackGain.gain.cancelScheduledValues(now);
        this.delayFeedbackGain.gain.setValueAtTime(0, now);
    }

    // 3. Momentary Master Mute to clear buffer tails from speakers
    if (this.masterGain) {
        this.masterGain.gain.cancelScheduledValues(now);
        this.masterGain.gain.setValueAtTime(0, now);
    }

    // 4. Recover: Restore settings after short delay
    setTimeout(() => {
        if (!this.ctx || !this.masterGain) return;
        const recoveryTime = this.ctx.currentTime;

        // Ramp back up to current volume setting
        this.masterGain.gain.setTargetAtTime(this.currentMasterVol, recoveryTime, 0.2);

        // Restore FX feedback settings from preset
        this.updateFX();
    }, 200);
  }
}

export default AudioEngine;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface XYPos {
  x: number;
  y: number;
}

export interface AppSettings {
  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  buttonSizeScale: number; // 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;
  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;

  // UI Relocation
  uiUnlocked: boolean;
  uiPositions: {
    volume: XYPos;
    panic: XYPos;
    off: XYPos;
    center: XYPos;
    depth: XYPos;
    chords: XYPos;
    layers: XYPos;
  };
}

export interface SynthPreset {
  id: number;
  name: string;
  // Osc 1
  waveform: WaveformType;
  // Osc 2
  osc2Waveform: WaveformType;
  osc2CoarseDetune: number; // Cents -1200 to 1200
  osc2FineDetune: number; // Cents -25 to 25
  osc2Mix: number; // 0 (Silent) to 1 (Full)

  // Envelopes
  attack: number;
  decay: number;
  sustain: number;
  release: number;
  gain: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
