import { SynthPreset, WaveformType, OscillatorConfig } from '../types';

interface SubVoice {
    source: OscillatorNode;
    gain: GainNode; 
    filter: BiquadFilterNode;
    lfo?: OscillatorNode;
    lfoGain?: GainNode;
    config: OscillatorConfig;
}

interface ActiveVoice {
    masterGain: GainNode;
    subVoices: SubVoice[];
    startRatio: number;
}

class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private limiter: DynamicsCompressorNode | null = null;

  // FX Nodes
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;
  private dryGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;

  // Voice map stores the graph for each active note
  private voices: Map<string, ActiveVoice> = new Map();

  private maxPolyphony: number = 12;
  private activePreset: SynthPreset;

  constructor(preset: SynthPreset) {
    this.activePreset = preset;
  }

  public init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
        latencyHint: 'interactive',
      });

      // Limiter (DynamicsCompressor)
      this.limiter = this.ctx.createDynamicsCompressor();
      this.limiter.threshold.value = -1.0; 
      this.limiter.knee.value = 10;
      this.limiter.ratio.value = 20; 
      this.limiter.attack.value = 0.005; 
      this.limiter.release.value = 0.2;
      this.limiter.connect(this.ctx.destination);

      // Master Gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = this.currentMasterVol; 
      this.masterGain.connect(this.limiter); 

      // --- FX Bus Setup ---

      // Dry Bus
      this.dryGain = this.ctx.createGain();
      this.dryGain.gain.value = 1.0; 
      this.dryGain.connect(this.masterGain);

      // Reverb Bus
      this.reverbNode = this.ctx.createConvolver();
      this.reverbNode.buffer = this.createImpulseResponse(2.5, 2.0); // 2.5s duration, 2.0 decay
      this.reverbGain = this.ctx.createGain();
      this.reverbGain.connect(this.reverbNode);
      this.reverbNode.connect(this.masterGain);

      // Delay Bus
      this.delayNode = this.ctx.createDelay(5.0);
      this.delayFeedbackGain = this.ctx.createGain();
      this.delayOutputGain = this.ctx.createGain();

      // Send logic: Voice -> DelayOutputGain -> DelayNode -> Master
      // Feedback: DelayNode -> DelayFeedbackGain -> DelayNode

      this.delayOutputGain.connect(this.delayNode);
      this.delayNode.connect(this.masterGain);

      this.delayNode.connect(this.delayFeedbackGain);
      this.delayFeedbackGain.connect(this.delayNode);

      // Apply initial preset settings to FX
      this.updateFX();
    }

    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      // Update Gains
      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(this.activePreset.reverbMix, now, ramp);

      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(this.activePreset.delayMix, now, ramp);
      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(this.activePreset.delayTime, now, ramp);
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(this.activePreset.delayFeedback, now, ramp);

      // Update Dynamics (Compressor/Limiter)
      if (this.limiter) {
          const thresh = this.activePreset.compressorThreshold ?? -1.0;
          const ratio = this.activePreset.compressorRatio ?? 20;
          const release = this.activePreset.compressorRelease ?? 0.2;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      // Dry attenuation
      if (this.dryGain) this.dryGain.gain.setTargetAtTime(Math.max(0.5, 1.0 - (this.activePreset.reverbMix * 0.3)), now, ramp);
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    const sampleRate = this.ctx!.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx!.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        left[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
        right[i] = (Math.random() * 2 - 1) * Math.pow(1 - n, decay);
    }
    return impulse;
  }

  public setPolyphony(count: number) {
    this.maxPolyphony = count;
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(val, this.ctx.currentTime, 0.05);
    }
  }

  public setPreset(preset: SynthPreset) {
    this.activePreset = preset;
    this.updateFX();
  }

  private createSubVoice(config: OscillatorConfig, baseFreq: number, now: number): SubVoice {
      if (!this.ctx) throw new Error("Audio Context missing");

      const osc = this.ctx.createOscillator();
      osc.type = config.waveform;

      // Frequency Calculation
      const totalDetune = config.coarseDetune + config.fineDetune;
      const detuneMultiplier = Math.pow(2, totalDetune / 1200);
      osc.frequency.value = baseFreq * detuneMultiplier;

      const gain = this.ctx.createGain();
      const filter = this.ctx.createBiquadFilter();

      // Connections: Osc -> Filter -> Gain
      osc.connect(filter);
      filter.connect(gain);

      // Filter Config
      filter.type = 'lowpass';
      filter.frequency.value = config.filterCutoff;
      filter.Q.value = config.filterResonance;

      // LFO Config
      let lfo: OscillatorNode | undefined;
      let lfoGain: GainNode | undefined;

      if (config.lfoTarget !== 'none') {
          lfo = this.ctx.createOscillator();
          lfo.type = 'sine';
          lfo.frequency.value = config.lfoRate;
          lfoGain = this.ctx.createGain();

          const rawDepth = config.lfoDepth;
          let effectiveGain = 0;

          if (config.lfoTarget === 'pitch') {
             effectiveGain = rawDepth; // Hz deviation roughly
          } else if (config.lfoTarget === 'filter') {
             effectiveGain = rawDepth * 20; 
          } else if (config.lfoTarget === 'tremolo') {
             effectiveGain = (rawDepth / 100) * 0.5;
          }

          lfoGain.gain.value = effectiveGain;
          lfo.connect(lfoGain);

          if (config.lfoTarget === 'pitch') {
              lfoGain.connect(osc.frequency);
          } else if (config.lfoTarget === 'filter') {
              lfoGain.connect(filter.frequency);
          } else if (config.lfoTarget === 'tremolo') {
              lfoGain.connect(gain.gain);
          }

          lfo.start(now);
      }

      // Envelope Start
      const voiceNormalization = 0.5; // Avoid clipping with multiple oscillators
      const targetGain = config.gain * voiceNormalization * (this.activePreset.gain || 1.0); // Mix level * Master Preset Gain

      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(targetGain, now + config.attack);
      gain.gain.exponentialRampToValueAtTime(Math.max(0.001, targetGain * config.sustain), now + config.attack + config.decay);

      osc.start(now);

      return { source: osc, gain, filter, lfo, lfoGain, config };
  }

  public startVoice(id: string, ratio: number, baseFrequency: number) {
    this.init();
    if (!this.ctx || !this.dryGain || !this.reverbGain || !this.delayOutputGain) return;

    // Restart logic
    if (this.voices.has(id)) {
        this.stopVoice(id, true);
    }

    // Voice stealing
    if (this.voices.size >= this.maxPolyphony) {
      const firstKey = this.voices.keys().next().value;
      if (firstKey !== undefined) this.stopVoice(firstKey, true); 
    }

    const now = this.ctx.currentTime;
    const baseFreq = baseFrequency * ratio;

    // Create Master Gain for this voice (Bus)
    const masterVoiceGain = this.ctx.createGain();
    masterVoiceGain.gain.value = 1.0;

    // Output Routing to Global FX Busses
    masterVoiceGain.connect(this.dryGain);
    masterVoiceGain.connect(this.reverbGain);
    masterVoiceGain.connect(this.delayOutputGain);

    // Create Sub Voices
    const subVoices: SubVoice[] = [];

    const configs = [this.activePreset.osc1, this.activePreset.osc2, this.activePreset.osc3];

    configs.forEach(config => {
        if (config.enabled) {
            const sv = this.createSubVoice(config, baseFreq, now);
            sv.gain.connect(masterVoiceGain);
            subVoices.push(sv);
        }
    });

    this.voices.set(id, { masterGain: masterVoiceGain, subVoices, startRatio: ratio });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.ctx) return;
    const voice = this.voices.get(id);
    if (voice) {
      const now = this.ctx.currentTime;
      let maxRelease = 0;

      // Trigger release on all sub-voices
      voice.subVoices.forEach(sv => {
          // Cancel envelope scheduled events
          sv.gain.gain.cancelScheduledValues(now);
          sv.gain.gain.setValueAtTime(sv.gain.gain.value, now); // Anchor

          const releaseTime = immediate ? 0.05 : sv.config.release;
          if (releaseTime > maxRelease) maxRelease = releaseTime;

          sv.gain.gain.exponentialRampToValueAtTime(0.001, now + releaseTime);
      });

      // Cleanup
      const stopTime = now + maxRelease + 0.1;

      voice.subVoices.forEach(sv => {
          sv.source.stop(stopTime);
          if (sv.lfo) sv.lfo.stop(stopTime);
      });

      // Disconnect after release
      setTimeout(() => {
        try {
            voice.subVoices.forEach(sv => {
                sv.source.disconnect();
                if (sv.lfo) sv.lfo.disconnect();
                if (sv.lfoGain) sv.lfoGain.disconnect();
                sv.filter.disconnect();
                sv.gain.disconnect();
            });
            voice.masterGain.disconnect();
        } catch(e) {}
      }, (maxRelease + 0.2) * 1000);

      this.voices.delete(id);
    }
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number, glideTime: number = 0.1) {
    const voice = this.voices.get(id);
    if (voice && this.ctx) {
       const newBaseFreq = baseFrequency * newRatio;
       const now = this.ctx.currentTime;

       voice.subVoices.forEach(sv => {
           const totalDetune = sv.config.coarseDetune + sv.config.fineDetune;
           const detuneMultiplier = Math.pow(2, totalDetune / 1200);
           const targetFreq = newBaseFreq * detuneMultiplier;

           sv.source.frequency.setTargetAtTime(targetFreq, now, glideTime);
       });

       voice.startRatio = newRatio; 
    }
  }

  public stopAll() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;

    // 1. Hard kill all active voices
    this.voices.forEach((voice) => {
        voice.subVoices.forEach(sv => {
            try {
                sv.source.stop();
                if (sv.lfo) sv.lfo.stop();
                sv.gain.disconnect();
            } catch(e) {}
        });
        try { voice.masterGain.disconnect(); } catch(e) {}
    });
    this.voices.clear();

    // 2. Kill FX Feedback loops immediately
    if (this.delayFeedbackGain) {
        this.delayFeedbackGain.gain.cancelScheduledValues(now);
        this.delayFeedbackGain.gain.setValueAtTime(0, now);
    }

    // 3. Momentary Master Mute
    if (this.masterGain) {
        this.masterGain.gain.cancelScheduledValues(now);
        this.masterGain.gain.setValueAtTime(0, now);
    }

    // 4. Recover
    setTimeout(() => {
        if (!this.ctx || !this.masterGain) return;
        const recoveryTime = this.ctx.currentTime;
        this.masterGain.gain.setTargetAtTime(this.currentMasterVol, recoveryTime, 0.2);
        this.updateFX();
    }, 200);
  }
}

export default AudioEngine;

import React, { useState } from 'react';
import { SynthPreset, WaveformType, OscillatorConfig } from '../types';
import { PRESETS } from '../constants';

interface Props {
  preset: SynthPreset;
  onChange: (p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

const SynthControls: React.FC<Props> = ({ preset, onChange, isOpen, onClose }) => {
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'fx'>('osc1');

  if (!isOpen) return null;

  const updateGlobal = (key: keyof SynthPreset, val: any) => {
    onChange({ ...preset, [key]: val });
  };

  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...preset[oscKey], [key]: val };
      onChange({ ...preset, [oscKey]: newOsc });
  };

  const loadPreset = (p: SynthPreset) => {
      onChange({ ...p });
  };

  const renderOscillatorTab = (oscKey: 'osc1' | 'osc2' | 'osc3', label: string) => {
      const config = preset[oscKey];
      // Osc 1 is always enabled, others can be toggled
      const canToggle = oscKey !== 'osc1'; 

      return (
          <div className="space-y-6 animate-in fade-in duration-300">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-sm font-bold text-slate-300 uppercase">{label} Settings</h3>
                  {canToggle && (
                      <label className="flex items-center gap-2 cursor-pointer bg-slate-900/50 px-3 py-1 rounded border border-slate-600">
                          <input 
                              type="checkbox" 
                              checked={config.enabled} 
                              onChange={(e) => updateOsc(oscKey, 'enabled', e.target.checked)}
                              className="rounded border-slate-600 text-indigo-500 focus:ring-indigo-500"
                          />
                          <span className={`text-xs font-bold ${config.enabled ? 'text-white' : 'text-slate-500'}`}>
                              {config.enabled ? 'ENABLED' : 'DISABLED'}
                          </span>
                      </label>
                  )}
              </div>

              <div className={`space-y-6 ${!config.enabled ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                {/* Waveform & Mix */}
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <div className="grid grid-cols-4 gap-1 mb-4">
                        {Object.values(WaveformType).map(w => (
                            <button 
                                key={w}
                                onClick={() => updateOsc(oscKey, 'waveform', w)}
                                className={`px-1 py-1 text-[10px] rounded border ${config.waveform === w ? 'bg-indigo-600 border-indigo-500' : 'bg-slate-700 border-slate-600'}`}
                            >
                                {w}
                            </button>
                        ))}
                    </div>
                    <div className="space-y-3">
