import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo, useCallback } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ChordDefinition, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; // The node where the touch started
}

const PITCH_SCALE = 200; // Pixels per octave, matches LatticeService

// Map prime limits to their coordinate index in the coords array
const LIMIT_TO_INDEX: {[key: number]: number} = {
    3: 0,
    5: 1,
    7: 2,
    11: 3,
    13: 4
};

// --- Optimized Sub-Components ---

// Define VisualSettings interface to strictly control prop changes
interface VisualSettings {
  colors: AppSettings['colors'];
  layerOrder: AppSettings['layerOrder'];
  isVoiceLeadingEnabled: boolean;
  latchedZoomScale: number;
  latchShellLimit: number;
  voiceLeadingStrength: number;
  voiceLeadingGlowAmount: number;
  voiceLeadingAnimationSpeed: number;
  voiceLeadingReverseDir: boolean;
  isColoredIlluminationEnabled: boolean;
  isVoiceLeadingAnimationEnabled: boolean; // Ensure this is passed
  rainbowOffset: number;
  rainbowSaturation: number;
  rainbowBrightness: number;
  isRainbowModeEnabled: boolean;
  buttonSizeScale: number;
  buttonSpacingScale: number;
  buttonShape: AppSettings['buttonShape'];
  canvasSize: number;
}

const NodeView = React.memo(({ 
    node, 
    visualSettings, 
    isLatched, 
    isHovered, 
    activeNodes, 
    spacing, 
    centerOffset,
    onPointerDown 
}: {
    node: LatticeNode, 
    visualSettings: VisualSettings, 
    isLatched: boolean, 
    isHovered: boolean, 
    activeNodes: LatticeNode[], 
    spacing: number, 
    centerOffset: number,
    onPointerDown: (e: React.PointerEvent, node: LatticeNode) => void
}) => {
    const left = node.x * spacing + centerOffset;
    const top = node.y * spacing + centerOffset;

    // Culling: If the node is outside the canvas area, do not render.
    if (left < -50 || left > visualSettings.canvasSize + 50 || top < -50 || top > visualSettings.canvasSize + 50) {
        return null;
    }

    const isActive = isLatched || isHovered;
    const isDiamond = visualSettings.buttonShape === ButtonShape.DIAMOND;

    const getColor = (limit: number): string => visualSettings.colors[limit] || '#64748b';
    const cTop = getColor(node.limitTop);
    const cBottom = getColor(node.limitBottom);

    // Gradient Angle: 180deg for standard, 135deg for rotated diamond to appear vertical on screen
    const gradientAngle = isDiamond ? '135deg' : '180deg';
    // Gradient fix: Strict stops, no-repeat, and padding-box clip to prevent border bleed
    const background = `linear-gradient(${gradientAngle}, ${cTop} 50%, ${cBottom} 50%)`;

    const layerIndex = visualSettings.layerOrder.indexOf(node.maxPrime);
    const zIndex = isActive ? 80 : (10 + layerIndex);

    let scale = 1.0;
    let opacity = 0.95;

    if (visualSettings.isVoiceLeadingEnabled && activeNodes.length > 0) {
        if (isActive) {
            scale = visualSettings.latchedZoomScale;
            opacity = 1.0;
        } else {
            // Unified Voice Leading Logic
            const allowedMaxIndex = visualSettings.latchShellLimit - 2; 
            let isCompatible = false;
            let minDist = Infinity;

            for (const activeNode of activeNodes) {
                 let valid = true;
                 if (visualSettings.latchShellLimit === 1) {
                     const hDist = getHarmonicDistance(node.coords, activeNode.coords);
                     if (hDist > 0) valid = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                         const diff = Math.abs(node.coords[i] - activeNode.coords[i]);
                         if (diff > 0 && i > allowedMaxIndex) {
                             valid = false;
                             break;
                         }
                     }
                 }

                 if (valid) {
                    isCompatible = true;
                    const d = getHarmonicDistance(node.coords, activeNode.coords);
                    if (d < minDist) minDist = d;
                 }
            }

            if (!isCompatible) {
                opacity = 0.15; 
                scale = 0.4;
            } else {
                 const falloff = visualSettings.voiceLeadingStrength; 
                 const visibility = Math.max(0.15, 1 - (minDist * falloff));
                 scale = Math.max(0.4, 0.5 + (visibility * 0.5));
                 opacity = visibility;
            }
        }
    } else {
        scale = isActive ? visualSettings.latchedZoomScale : 1.0;
        opacity = isActive ? 1.0 : 0.95;
    }

    // Colored Illumination calculation
    let boxShadowColor = 'white';
    let borderColor = isLatched ? 'white' : (isHovered ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)');
    let borderStyle = isLatched ? '3px solid white' : (isHovered ? '2px solid rgba(255,255,255,0.8)' : '2px solid rgba(255,255,255,0.3)');

    const rainbowPeriod = PITCH_SCALE * spacing;

    if (visualSettings.isColoredIlluminationEnabled) {
         const phase = (top % rainbowPeriod) / rainbowPeriod;
         const hue = (visualSettings.rainbowOffset + phase * 360) % 360;
         const sat = visualSettings.isRainbowModeEnabled ? visualSettings.rainbowSaturation : 100;

         const activeColor = `hsl(${hue}, ${sat}%, 60%)`;

         if (isActive) {
            borderColor = activeColor;
            boxShadowColor = activeColor;
            borderStyle = `4px solid ${borderColor}`;
         }
    }

    const baseSize = 60 * visualSettings.buttonSizeScale;

    // Rotation logic for Diamond shape
    const transformRotate = isDiamond ? 'rotate(45deg)' : '';
    const transformScale = `scale(${scale})`;
    const transformTotal = `translate(-50%, -50%) ${transformRotate} ${transformScale}`;

    return (
        <div
            className="absolute flex items-center justify-center shadow-md cursor-pointer touch-none select-none transition-transform duration-100 ease-out"
            style={{
                left: `${left}px`,
                top: `${top}px`,
                width: `${baseSize}px`,
                height: `${baseSize}px`,
                background: background,
                backgroundRepeat: 'no-repeat',
                backgroundSize: '100% 100%',
                backgroundPosition: 'center',
                backgroundClip: 'padding-box', // Prevents background from bleeding into transparent borders
                borderRadius: visualSettings.buttonShape,
                transform: transformTotal,
                boxShadow: isActive ? `0 0 10px ${boxShadowColor}` : '0 4px 6px rgba(0,0,0,0.6)',
                zIndex: zIndex,
                opacity: opacity,
                border: borderStyle,
                filter: isActive ? 'brightness(1.1)' : 'none'
            }}
            onPointerDown={(e) => onPointerDown(e, node)}
        >
            {/* Counter-rotate content if diamond to keep text upright */}
            <div 
                className={`flex flex-col w-full h-full text-white font-bold leading-none text-shadow-sm transition-opacity ${scale < 0.6 ? 'opacity-0' : 'opacity-100'}`}
                style={{ transform: isDiamond ? 'rotate(-45deg)' : 'none' }}
            >
                <span className="flex-1 flex items-center justify-center pt-1" style={{ fontSize: '11px' }}>{node.n}</span>
                <span className="flex-1 flex items-center justify-center pb-1 border-t border-white/20" style={{ fontSize: '11px' }}>{node.d}</span>
            </div>
        </div>
    );
});

const LineView = React.memo(({ 
    line, 
    n1, n2, 
    visualSettings, 
    n1Active, 
    n2Active, 
    activeNodesCount, 
    activeNeighborCounts,
    spacing,
    centerOffset
}: any) => {
    let x1 = line.x1 * spacing + centerOffset;
    let y1 = line.y1 * spacing + centerOffset;
    let x2 = line.x2 * spacing + centerOffset;
    let y2 = line.y2 * spacing + centerOffset;

    // Culling
    if (x1 < 0 || x1 > visualSettings.canvasSize || y1 < 0 || y1 > visualSettings.canvasSize ||
        x2 < 0 || x2 > visualSettings.canvasSize || y2 < 0 || y2 > visualSettings.canvasSize) {
        return null;
    }

    const getColor = (limit: number): string => visualSettings.colors[limit] || '#64748b';
    const limitColor = getColor(line.limit);

    let strokeColor = limitColor;
    let lineOpacity = 0.1;
    let lineWidth = line.limit === 1 ? 4 : 2;
    let isVoiceLeadingActive = false;
    let lineStyle = {};

    if (n1Active && n2Active) {
        // Fully Active Connection
        lineOpacity = 1.0;
        lineWidth = 5;
        strokeColor = limitColor; 
        isVoiceLeadingActive = true;

        lineStyle = { 
            filter: `brightness(1.5) drop-shadow(0 0 5px ${limitColor})` 
        };

        // Directional Logic
        const axisIndex = LIMIT_TO_INDEX[line.limit];
        if (axisIndex !== undefined && n1 && n2) {
            const c1 = n1.coords[axisIndex];
            const c2 = n2.coords[axisIndex];

            let swap = c1 > c2;
            if (visualSettings.voiceLeadingReverseDir) swap = !swap;

            if (swap) {
                const tempX = x1; const tempY = y1;
                x1 = x2; y1 = y2;
                x2 = tempX; y2 = tempY;
            }
        }

    } else if (n1Active || n2Active) {
        // One active, one inactive - Reinforcement Logic
        const inactiveNodeId = n1Active ? n2.id : n1.id;
        const activeCount = activeNeighborCounts.get(inactiveNodeId) || 0;

        if (activeCount >= 2) {
            // Reinforced Bridge Style
            lineOpacity = 0.85;
            lineWidth = 4;
            lineStyle = { 
                filter: `brightness(1.2)` 
            };
        } else {
            // Standard Neighbor Style
            lineOpacity = 0.6;
            lineWidth = 3;
        }

    } else if (visualSettings.isVoiceLeadingEnabled && activeNodesCount > 0) {
        lineOpacity = 0.05;
    }

    // "Animate Connections" Visual: Smaller, softer glow
    const glowWidthMultiplier = (1 + (visualSettings.voiceLeadingGlowAmount * 3)) * 0.5; 
    const animStrokeWidth = Math.max(2, lineWidth * glowWidthMultiplier); 

    return (
        <g>
            {/* Base Line */}
            <line 
                x1={x1} y1={y1} x2={x2} y2={y2}
                stroke={strokeColor}
                strokeWidth={lineWidth}
                strokeOpacity={lineOpacity}
                strokeDasharray={line.limit === 1 ? "5,5" : "0"} 
                style={lineStyle}
            />
            {/* Animation Overlay - Pure diffuse light via filter (No SourceGraphic) */}
            {isVoiceLeadingActive && visualSettings.isVoiceLeadingAnimationEnabled && (
                <line 
                    x1={x1} y1={y1} x2={x2} y2={y2}
                    stroke="white"
                    strokeWidth={animStrokeWidth}
                    strokeOpacity={0.8}
                    strokeLinecap="round" 
                    strokeDasharray={`0 40`} 
                    filter="url(#glow)"
                    className="animate-flow"
                />
            )}
        </g>
    );
});

