class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private activePreset: SynthPreset;

  constructor(preset: SynthPreset) {
    this.activePreset = preset;
  }

  public async init() {
    if (this.ctx) return; // Already initialized

    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
      latencyHint: 'interactive',
    });

    // 1. Setup Worklet
    const blob = new Blob([WORKLET_CODE], { type: 'application/javascript' });
    const url = URL.createObjectURL(blob);

    try {
        await this.ctx.audioWorklet.addModule(url);
        this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
            numberOfInputs: 0,
            numberOfOutputs: 1,
            outputChannelCount: [2]
        });

        // Initial preset send
        this.workletNode.port.postMessage({ type: 'preset', data: this.activePreset });

    } catch (e) {
        console.error("Failed to load AudioWorklet", e);
        return;
    }

    // 2. Setup FX Chain
    this.setupFX();

    // 3. Connect Worklet -> Split -> FX
    if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
         this.workletNode.connect(this.dryGain);
         this.workletNode.connect(this.reverbGain);
         this.workletNode.connect(this.delayOutputGain);
    }

    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  private setupFX() {
    if (!this.ctx) return;

    // Limiter (Master Output)
    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -1.0;
    this.limiter.connect(this.ctx.destination);

    // Dry Bus
    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.limiter);

    // Reverb Bus
    this.reverbNode = this.ctx.createConvolver();
    this.reverbNode.buffer = this.createImpulseResponse(2.5, 2.0);
    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.limiter);

    // Delay Bus
    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.limiter); // Delay to Master
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode); // Feedback loop

    this.updateFX();
    this.setMasterVolume(this.currentMasterVol);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      // Update Gains
      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(this.activePreset.reverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(this.activePreset.delayMix, now, ramp);
      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(this.activePreset.delayTime, now, ramp);
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(this.activePreset.delayFeedback, now, ramp);

      // Update Dynamics (Compressor/Limiter)
      if (this.limiter) {
          const thresh = this.activePreset.compressorThreshold ?? -1.0;
          const ratio = this.activePreset.compressorRatio ?? 20;
          const release = this.activePreset.compressorRelease ?? 0.2;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      // Dry attenuation based on reverb mix to prevent total volume doubling
      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (this.activePreset.reverbMix * 0.4));
          this.dryGain.gain.setTargetAtTime(dryLevel * this.currentMasterVol, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        // Simple noise burst with exponential decay
        const amp = Math.pow(1 - n, decay);
        left[i] = (Math.random() * 2 - 1) * amp;
        right[i] = (Math.random() * 2 - 1) * amp;
    }
    return impulse;
  }

  public setPolyphony(count: number) {
      // Handled in worklet statically for now (16 voices), 
      // but we could send a config message to limit it dynamically if needed.
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setPreset(preset: SynthPreset) {
    this.activePreset = preset;
    this.updateFX(); // Update Main Thread FX

    // Update Worklet Synth Params
    if (this.workletNode) {
        this.workletNode.port.postMessage({ type: 'preset', data: preset });
    }
  }

  public async startVoice(id: string, ratio: number, baseFrequency: number) {
    await this.init();
    if (!this.workletNode) return;

    const freq = baseFrequency * ratio;
    this.workletNode.port.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq 
    });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.workletNode) return;
    // The Worklet handles the release envelope internally when it receives note_off
    this.workletNode.port.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number, glideTime: number = 0.1) {
    if (!this.workletNode) return;
    const freq = baseFrequency * newRatio;
    this.workletNode.port.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ type: 'stop_all' });
  }
}

export default AudioEngine;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useCallback } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
// fast lookups for "what node is at x,y?"
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  // Get nodes in the cell containing x,y and 8 neighbors
  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); // Cell size 150px

  // Interaction State
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map()); // Ref for animation loop access

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Chords Relatch Logic
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Sync Diff
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Note On
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      // Note Off
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching (Shell Limit)
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Spatial Hash Query
      const candidates = spatialHash.query(x, y);

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;

      // Find closest node within radius
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        // Update Cursor State
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX, // Screen relative for visual lines (if mapped) or just use canvas relative
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            activeCursorsRef.current = next;
            return next;
        });

        // Toggle Latch
        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        // Trigger Pitch Bend / Feedback Audio
        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    // Update cursor position
    setActiveCursors(prev => {
        const c = prev.get(e.pointerId)!;
        const next = new Map(prev);
        next.set(e.pointerId, { ...c, currentX: e.clientX, currentY: e.clientY });
        activeCursorsRef.current = next;
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    // Pitch Bend logic
    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         // Calculate relative Y from center of canvas
         // Canvas Y = (ClientY - RectTop) + ScrollTop
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

         // Drag Latch Logic
         if (settings.isLatchModeEnabled && canvasRef.current) {
             const canvasRect = canvasRef.current.getBoundingClientRect();
             const cx = e.clientX - canvasRect.left;
             const cy = e.clientY - canvasRect.top;

             const candidates = spatialHash.query(cx, cy);
             const spacing = settings.buttonSpacingScale;
             const radius = (60 * settings.buttonSizeScale) / 2;
             const radiusSq = radius * radius;

             for (const node of candidates) {
                 if (node.id === cursor.originNodeId) continue;
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const dx = cx - nx;
                 const dy = cy - ny;

                 if (dx*dx + dy*dy < radiusSq) {
                     // Hit a node while dragging
                     setManualLatchedNodes(prev => {
                         if (prev.has(node.id)) return prev;

                         // Check Shell Limit against Origin
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (!originNode) return prev;

                         const allowedMaxIndex = settings.latchShellLimit - 2;
                         let isAllowed = true;

                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                             }
                         }

                         if (isAllowed) {
                             const next = new Map(prev);
                             next.set(node.id, cursor.originNodeId);
                             setLastTouchedNode({ coords: node.coords, octave: node.octave });
                             return next;
                         }
                         return prev;
                     });
                 }
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            activeCursorsRef.current = next;
            return next;
        });

        // If not in latch mode, release the note
        if (!settings.isLatchModeEnabled) {
            const c = activeCursors.get(e.pointerId);
            if (c) {
                 setManualLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(c.originNodeId);
                     return next;
                 });
            }
        }
    }
  };

  // --- CANVAS RENDER LOOP ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); // alpha: false for performance if bg is opaque
    if (!ctx) return;

    // Handle High DPI
    const dpr = window.devicePixelRatio || 1;
    const size = settings.canvasSize;
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    // We style the canvas to be 'size' pixels via CSS, but internally it's size*dpr
    ctx.scale(dpr, dpr);

    // Cache some static values for the loop
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;
    const baseRadius = (60 * settings.buttonSizeScale) / 2;
    const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
    const lineDash = [0, 40];

    // Helper for Hex Colors
    const colorCache: {[key: number]: string} = settings.colors;

    const render = (time: number) => {
        // 1. Culling Viewport
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        // Padding for culling
        const pad = 100;

        // Clear Background
        // If rainbow mode, we rely on the container div's background and just clearRect (transparent)
        // But we set alpha:false, so we must draw the background. 
        // Actually, for performance with alpha:false, we need to draw the background color.
        // If Rainbow Mode is on, the canvas is on TOP of the div? No, transparent canvas is slower.
        // Let's stick to simple clearRect and use CSS background for the container, but change context to alpha: true (default)
        // Or draw the background on canvas. Drawing complex gradient on canvas every frame is expensive.
        // Best approach: Canvas is transparent, CSS handles background.
        ctx.clearRect(viewX, viewY, viewW, viewH);

        // --- DRAW LINES ---
        // Animation Offset
        const flowOffset = settings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * settings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // We can optimize by spatially hashing lines too, but simple bounding box check is okay
        for (const line of data.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            // Simple Culling
            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = effectiveLatchedNodes.has(line.sourceId);
            const active2 = effectiveLatchedNodes.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Voice Leading
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                // Glow/Flow Overlay
                if (settings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + settings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = settings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = settings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();

                     // Reset Shadow
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive
                const isVoiceLeading = settings.isVoiceLeadingEnabled && effectiveLatchedNodes.size > 0;
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;
                ctx.globalAlpha = isVoiceLeading ? 0.1 : 0.4;
                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // --- DRAW NODES ---
        const activeNodes = settings.isVoiceLeadingEnabled ? data.nodes.filter(n => effectiveLatchedNodes.has(n.id)) : [];
        const allowedMaxIndex = settings.latchShellLimit - 2;

        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            // Culling
            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = effectiveLatchedNodes.has(node.id);
            // Check hover (optimization: only check if cursors exist)
            let isHovered = false;
            if (activeCursorsRef.current.size > 0) {
                for (const c of activeCursorsRef.current.values()) {
                    if (c.originNodeId === node.id) { isHovered = true; break; }
                }
            }

            const isActive = isLatched || isHovered;

            // Voice Leading Opacity/Scale Calc
            let scale = 1.0;
            let opacity = 0.95;

            if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                 if (isActive) {
                     scale = settings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     // Check compatibility (Spatial/Harmonic distance)
                     // Since we are in a tight loop, we need to be fast.
                     // The logic mirrors previous React logic but localized.
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodes) {
                         // Fast check
                         if (Math.abs(an.x - node.x) > 2000) continue; // heuristic skip

                         let valid = true;
                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.2; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * settings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? settings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;

            // Draw Shape
            ctx.beginPath();
            if (isDiamond) {
                // Diamond path
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                // Circle
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            // Gradient Fill
            // Creating gradient object every frame is costly, but needed for per-node color
            // Optimization: Approximate with solid color or simple fill if fast, 
            // but for "High End" look we stick to gradient.
            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            // Outline / Illumination
            if (settings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (settings.rainbowOffset + phase * 360) % 360;
                 const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.shadowColor = ctx.strokeStyle;
                 ctx.shadowBlur = 10;
                 ctx.stroke();
                 ctx.shadowBlur = 0; // reset
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            // Text
            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = `bold ${11 * dpr}px sans-serif`; 
                // We use transform scale, so font size needs to match or we just draw normally
                // Since we manually scaled radius, we draw text at x,y

                // Numerator
                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                // Separator line
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                // Denominator
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        // Draw Drag Lines (Feedback)
        activeCursorsRef.current.forEach(c => {
            const node = data.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 // Cursor X/Y is screen relative, need canvas relative
                 // But wait, in handleMove we stored clientX. 
                 // We need to convert c.currentX to canvas space
                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [data, settings, effectiveLatchedNodes]);

  // --- Rainbow Background ---
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useCallback } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
// fast lookups for "what node is at x,y?"
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  // Get nodes in the cell containing x,y and 8 neighbors
  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>(({ settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked }, ref) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); // Cell size 150px

  // Interaction State
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map()); // Ref for animation loop access

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Chords Relatch Logic
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Sync Diff
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Note On
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      // Note Off
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching (Shell Limit)
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Spatial Hash Query
      const candidates = spatialHash.query(x, y);

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;

      // Find closest node within radius
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        // Update Cursor State
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX, // Screen relative for visual lines (if mapped) or just use canvas relative
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            activeCursorsRef.current = next;
            return next;
        });

        // Toggle Latch
        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        // Trigger Pitch Bend / Feedback Audio
        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    // Update cursor position
    setActiveCursors(prev => {
        const c = prev.get(e.pointerId)!;
        const next = new Map(prev);
        next.set(e.pointerId, { ...c, currentX: e.clientX, currentY: e.clientY });
        activeCursorsRef.current = next;
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    // Pitch Bend logic
    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         // Calculate relative Y from center of canvas
         // Canvas Y = (ClientY - RectTop) + ScrollTop
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

         // Drag Latch Logic
         if (settings.isLatchModeEnabled && canvasRef.current) {
             const canvasRect = canvasRef.current.getBoundingClientRect();
             const cx = e.clientX - canvasRect.left;
             const cy = e.clientY - canvasRect.top;

             const candidates: LatticeNode[] = spatialHash.query(cx, cy);
             const spacing = settings.buttonSpacingScale;
             const radius = (60 * settings.buttonSizeScale) / 2;
             const radiusSq = radius * radius;

             for (const node of candidates) {
                 if (node.id === cursor.originNodeId) continue;
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const dx = cx - nx;
                 const dy = cy - ny;

                 if (dx*dx + dy*dy < radiusSq) {
                     // Hit a node while dragging
                     setManualLatchedNodes(prev => {
                         if (prev.has(node.id)) return prev;

                         // Check Shell Limit against Origin
                         const originNode: LatticeNode | undefined = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (!originNode) return prev;

                         const allowedMaxIndex = settings.latchShellLimit - 2;
                         let isAllowed = true;

                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                             }
                         }

                         if (isAllowed) {
                             const next = new Map(prev);
                             next.set(node.id, cursor.originNodeId);
                             setLastTouchedNode({ coords: node.coords, octave: node.octave });
                             return next;
                         }
                         return prev;
                     });
                 }
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            activeCursorsRef.current = next;
            return next;
        });

        // If not in latch mode, release the note
        if (!settings.isLatchModeEnabled) {
            const c = activeCursors.get(e.pointerId);
            if (c) {
                 setManualLatchedNodes(prev => {
                     const next = new Map(prev);
                     next.delete(c.originNodeId);
                     return next;
                 });
            }
        }
    }
  };

  // --- CANVAS RENDER LOOP ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false }); // alpha: false for performance if bg is opaque
    if (!ctx) return;

    // Handle High DPI
    const dpr = window.devicePixelRatio || 1;
    const size = settings.canvasSize;
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    // We style the canvas to be 'size' pixels via CSS, but internally it's size*dpr
    ctx.scale(dpr, dpr);

    // Cache some static values for the loop
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;
    const baseRadius = (60 * settings.buttonSizeScale) / 2;
    const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
    const lineDash = [0, 40];

    // Helper for Hex Colors
    const colorCache: {[key: number]: string} = settings.colors;

    const render = (time: number) => {
        // 1. Culling Viewport
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        // Padding for culling
        const pad = 100;

        // Clear Background
        // If rainbow mode, we rely on the container div's background and just clearRect (transparent)
        // But we set alpha:false, so we must draw the background. 
        // Actually, for performance with alpha:false, we need to draw the background color.
        // If Rainbow Mode is on, the canvas is on TOP of the div? No, transparent canvas is slower.
        // Let's stick to simple clearRect and use CSS background for the container, but change context to alpha: true (default)
        // Or draw the background on canvas. Drawing complex gradient on canvas every frame is expensive.
        // Best approach: Canvas is transparent, CSS handles background.
        ctx.clearRect(viewX, viewY, viewW, viewH);

        // --- DRAW LINES ---
        // Animation Offset
        const flowOffset = settings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * settings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // We can optimize by spatially hashing lines too, but simple bounding box check is okay
        for (const line of data.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            // Simple Culling
            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = effectiveLatchedNodes.has(line.sourceId);
            const active2 = effectiveLatchedNodes.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Voice Leading
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                // Glow/Flow Overlay
                if (settings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + settings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = settings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = settings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();

                     // Reset Shadow
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive
                const isVoiceLeading = settings.isVoiceLeadingEnabled && effectiveLatchedNodes.size > 0;
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;
                ctx.globalAlpha = isVoiceLeading ? 0.1 : 0.4;
                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // --- DRAW NODES ---
        const activeNodes = settings.isVoiceLeadingEnabled ? data.nodes.filter(n => effectiveLatchedNodes.has(n.id)) : [];
        const allowedMaxIndex = settings.latchShellLimit - 2;

        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            // Culling
            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = effectiveLatchedNodes.has(node.id);
            // Check hover (optimization: only check if cursors exist)
            let isHovered = false;
            if (activeCursorsRef.current.size > 0) {
                for (const c of activeCursorsRef.current.values()) {
                    if (c.originNodeId === node.id) { isHovered = true; break; }
                }
            }

            const isActive = isLatched || isHovered;

            // Voice Leading Opacity/Scale Calc
            let scale = 1.0;
            let opacity = 0.95;

            if (settings.isVoiceLeadingEnabled && activeNodes.length > 0) {
                 if (isActive) {
                     scale = settings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     // Check compatibility (Spatial/Harmonic distance)
                     // Since we are in a tight loop, we need to be fast.
                     // The logic mirrors previous React logic but localized.
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodes) {
                         // Fast check
                         if (Math.abs(an.x - node.x) > 2000) continue; // heuristic skip

                         let valid = true;
                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.2; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * settings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? settings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;

            // Draw Shape
            ctx.beginPath();
            if (isDiamond) {
                // Diamond path
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                // Circle
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            // Gradient Fill
            // Creating gradient object every frame is costly, but needed for per-node color
            // Optimization: Approximate with solid color or simple fill if fast, 
            // but for "High End" look we stick to gradient.
            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            // Outline / Illumination
            if (settings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (settings.rainbowOffset + phase * 360) % 360;
                 const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.shadowColor = ctx.strokeStyle;
                 ctx.shadowBlur = 10;
                 ctx.stroke();
                 ctx.shadowBlur = 0; // reset
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            // Text
            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = `bold ${11 * dpr}px sans-serif`; 
                // We use transform scale, so font size needs to match or we just draw normally
                // Since we manually scaled radius, we draw text at x,y

                // Numerator
                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                // Separator line
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                // Denominator
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        // Draw Drag Lines (Feedback)
        activeCursorsRef.current.forEach(c => {
            const node = data.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 // Cursor X/Y is screen relative, need canvas relative
                 // But wait, in handleMove we stored clientX. 
                 // We need to convert c.currentX to canvas space
                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, [data, settings, effectiveLatchedNodes]);

  // --- Rainbow Background ---
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // Refs for Render Loop (Decoupled from React Render Cycle)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const latchedRef = useRef(effectiveLatchedNodes);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());

  // Keep Refs in sync
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { latchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Sync Diff
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Note On
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      // Note Off
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching (Shell Limit)
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        activeCursorsRef.current.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: hitNode.id
        });

        // Toggle Latch
        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    activeCursorsRef.current.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });

    if (settings.isPitchBendEnabled && scrollContainerRef.current && canvasRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

         if (settings.isLatchModeEnabled) {
             const canvasRect = canvasRef.current.getBoundingClientRect();
             const cx = e.clientX - canvasRect.left;
             const cy = e.clientY - canvasRect.top;

             const candidates = spatialHash.query(cx, cy);
             const spacing = settings.buttonSpacingScale;
             const radius = (60 * settings.buttonSizeScale) / 2;
             const radiusSq = radius * radius;

             for (const node of candidates) {
                 if (node.id === cursor.originNodeId) continue;
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const dx = cx - nx;
                 const dy = cy - ny;

                 if (dx*dx + dy*dy < radiusSq) {
                     setManualLatchedNodes(prev => {
                         if (prev.has(node.id)) return prev;
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (!originNode) return prev;

                         const allowedMaxIndex = settings.latchShellLimit - 2;
                         let isAllowed = true;

                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                             }
                         }

                         if (isAllowed) {
                             const next = new Map(prev);
                             next.set(node.id, cursor.originNodeId);
                             setLastTouchedNode({ coords: node.coords, octave: node.octave });
                             return next;
                         }
                         return prev;
                     });
                 }
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        activeCursorsRef.current.delete(e.pointerId);

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- CANVAS RENDER LOOP ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true }); // Enable Transparency for Rainbow Background
    if (!ctx) return;

    // Handle High DPI
    const dpr = window.devicePixelRatio || 1;
    // We only need to set width/height/scale once per resize, usually. 
    // But putting it in the loop or resizing event is safer.
    // For now, let's assume size changes trigger this effect cleanup via deps?
    // No, we removed deps. We must check size in loop or handle resize separately.
    // To keep it simple, we'll check size in loop.

    const lineDash = [0, 40];

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentLatched = latchedRef.current;
        const currentCursors = activeCursorsRef.current;

        const size = currentSettings.canvasSize;

        // Resize check
        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Culling Vars
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        // Clear
        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // DRAW LINES
        for (const line of currentData.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && currentLatched.size > 0;
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;
                // Correctly fade out lines if Voice Leading is active
                ctx.globalAlpha = isVoiceLeading ? 0.1 : 0.4;
                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        const activeNodesList = currentSettings.isVoiceLeadingEnabled ? currentData.nodes.filter(n => currentLatched.has(n.id)) : [];
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.2; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.shadowColor = ctx.strokeStyle;
                 ctx.shadowBlur = 10;
                 ctx.stroke();
                 ctx.shadowBlur = 0; 
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                // Font size fixed to 11px (not multiplied by dpr)
                ctx.font = `bold 11px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        // Draw Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // Refs for Render Loop (Decoupled from React Render Cycle)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const latchedRef = useRef(effectiveLatchedNodes);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());

  // Keep Refs in sync
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { latchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Sync Diff
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Note On
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      // Note Off
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching (Shell Limit)
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>();
        data.nodes.forEach(n => visibleNodeMap.set(n.id, n));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        activeCursorsRef.current.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: hitNode.id
        });

        // Toggle Latch
        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    activeCursorsRef.current.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });

    if (settings.isPitchBendEnabled && scrollContainerRef.current && canvasRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);

         if (settings.isLatchModeEnabled) {
             const canvasRect = canvasRef.current.getBoundingClientRect();
             const cx = e.clientX - canvasRect.left;
             const cy = e.clientY - canvasRect.top;

             const candidates = spatialHash.query(cx, cy);
             const spacing = settings.buttonSpacingScale;
             const radius = (60 * settings.buttonSizeScale) / 2;
             const radiusSq = radius * radius;

             for (const node of candidates) {
                 if (node.id === cursor.originNodeId) continue;
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const dx = cx - nx;
                 const dy = cy - ny;

                 if (dx*dx + dy*dy < radiusSq) {
                     setManualLatchedNodes(prev => {
                         if (prev.has(node.id)) return prev;
                         const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                         if (!originNode) return prev;

                         const allowedMaxIndex = settings.latchShellLimit - 2;
                         let isAllowed = true;

                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                             }
                         }

                         if (isAllowed) {
                             const next = new Map(prev);
                             next.set(node.id, cursor.originNodeId);
                             setLastTouchedNode({ coords: node.coords, octave: node.octave });
                             return next;
                         }
                         return prev;
                     });
                 }
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        activeCursorsRef.current.delete(e.pointerId);

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- CANVAS RENDER LOOP ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true }); // Enable Transparency for Rainbow Background
    if (!ctx) return;

    // Handle High DPI
    const dpr = window.devicePixelRatio || 1;
    // We only need to set width/height/scale once per resize, usually. 
    // But putting it in the loop or resizing event is safer.
    // For now, let's assume size changes trigger this effect cleanup via deps?
    // No, we removed deps. We must check size in loop or handle resize separately.
    // To keep it simple, we'll check size in loop.

    const lineDash = [0, 40];

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentLatched = latchedRef.current;
        const currentCursors = activeCursorsRef.current;

        const size = currentSettings.canvasSize;

        // Resize check
        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Culling Vars
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        // Clear
        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // DRAW LINES
        for (const line of currentData.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && currentLatched.size > 0;
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;
                // Correctly fade out lines if Voice Leading is active
                ctx.globalAlpha = isVoiceLeading ? 0.1 : 0.4;
                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        const activeNodesList = currentSettings.isVoiceLeadingEnabled ? currentData.nodes.filter(n => currentLatched.has(n.id)) : [];
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.2; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.shadowColor = ctx.strokeStyle;
                 ctx.shadowBlur = 10;
                 ctx.stroke();
                 ctx.shadowBlur = 0; 
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                // Font size fixed to 11px (not multiplied by dpr)
                ctx.font = `bold 11px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        // Draw Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // State for React Persistence (Chords, UI updates)
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for High-Freq Loop (The Source of Truth for Canvas/Audio)
  const manualLatchesRef = useRef<Map<string, string>>(new Map());
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeChordIdsRef = useRef(activeChordIds);

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeChordIdsRef.current = activeChordIds; }, [activeChordIds]);

  // Sync State -> Ref (for External Changes like Clear All)
  useEffect(() => {
      manualLatchesRef.current = new Map(manualLatchedNodes);
  }, [manualLatchedNodes]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => {
        setManualLatchedNodes(new Map());
        manualLatchesRef.current.clear();
        // Stop all voices that were manually latched
        // (AudioEngine handles its own state, but we should ensure consistency)
        // Ideally we iterate known latches, but engine.stopAll is safer for "Panic/Clear"
        // But for soft clear, we rely on the Diff logic in audio effect or direct calls.
        // Actually, we should iterate and stop them.
        manualLatchedNodes.forEach((_, nodeId) => audioEngine.stopVoice(`node-${nodeId}`));
    },
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => manualLatchesRef.current.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- External Chord Handling (Audio) ---
  // We keep this purely reactive as Chords come from parent props
  const prevActiveChordIds = useRef<string[]>([]);
  useEffect(() => {
     // Diff active chords to trigger audio
     const currentIds = activeChordIds;
     const prevIds = prevActiveChordIds.current;

     // Added
     currentIds.filter(id => !prevIds.includes(id)).forEach(id => {
         const chord = settings.savedChords.find(c => c.id === id);
         chord?.nodes.forEach(n => {
            // Find full node data for ratio
            // Optimization: Maybe cache node map?
            const fullNode = data.nodes.find(dn => dn.id === n.id);
            if(fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
         });
     });

     // Removed
     prevIds.filter(id => !currentIds.includes(id)).forEach(id => {
         const chord = settings.savedChords.find(c => c.id === id);
         chord?.nodes.forEach(n => {
            // Only stop if not manually latched!
            if (!manualLatchesRef.current.has(n.id)) {
                audioEngine.stopVoice(`node-${n.id}`);
            }
         });
     });

     // Relatch Check
     if (settings.chordsAlwaysRelatch) {
         // Logic handled above in "Added", but if we re-click a chord in UI?
         // The UI toggles ID, so it removes then adds. Logic holds.
     }

     prevActiveChordIds.current = currentIds;
  }, [activeChordIds, settings.savedChords, data.nodes, settings.baseFrequency]);


  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers (Direct Ref Manipulation) ---

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault(); // Prevent scroll/zoom

      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        activeCursorsRef.current.set(e.pointerId, {
            pointerId: e.pointerId,
            currentX: e.clientX,
            currentY: e.clientY,
            originNodeId: hitNode.id
        });

        // Manual Latch Logic
        const isLatched = manualLatchesRef.current.has(hitNode.id);

        if (settings.isLatchModeEnabled) {
            if (isLatched) {
                manualLatchesRef.current.delete(hitNode.id);
                audioEngine.stopVoice(`node-${hitNode.id}`);
            } else {
                manualLatchesRef.current.set(hitNode.id, hitNode.id);
                audioEngine.startVoice(`node-${hitNode.id}`, hitNode.ratio, settings.baseFrequency);
            }
        } else {
            // Momentary
            if (!isLatched) {
                manualLatchesRef.current.set(hitNode.id, hitNode.id);
                audioEngine.startVoice(`node-${hitNode.id}`, hitNode.ratio, settings.baseFrequency);
            }
        }

        // Sync State (Debounced or just fired, React will handle batching mostly, 
        // but since we only do this on Down/Up/BoundaryCross, it's fine)
        setManualLatchedNodes(new Map(manualLatchesRef.current));

        // Pitch Bend Voice Trigger
        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;

    // 1. Update Cursor Position (Ref only - No Render)
    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    activeCursorsRef.current.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });

    // 2. Audio Processing (Pitch Bend)
    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    // 3. Drag Latching (Spatial Hash Check)
    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue; // Don't re-trigger origin

             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 // Hit a new node!
                 if (!manualLatchesRef.current.has(node.id)) {
                     // Check Shell Limit
                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (originNode) {
                         const allowedMaxIndex = settings.latchShellLimit - 2;
                         let isAllowed = true;
                         if (settings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                             }
                         }

                         if (isAllowed) {
                             manualLatchesRef.current.set(node.id, cursor.originNodeId);
                             audioEngine.startVoice(`node-${node.id}`, node.ratio, settings.baseFrequency);
                             setLastTouchedNode({ coords: node.coords, octave: node.octave });

                             // Sync State
                             setManualLatchedNodes(new Map(manualLatchesRef.current));
                         }
                     }
                 }
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;

        // Stop Pitch Bend Voice
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        activeCursorsRef.current.delete(e.pointerId);

        // Momentary Release Logic
        if (!settings.isLatchModeEnabled) {
             if (manualLatchesRef.current.has(cursor.originNodeId)) {
                 manualLatchesRef.current.delete(cursor.originNodeId);
                 audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                 setManualLatchedNodes(new Map(manualLatchesRef.current));
             }
        }
    }
  };

  // --- CANVAS RENDER LOOP ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const lineDash = [0, 40];

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;

        // Calculate Effective Latched Set (Manual + Chords)
        // We do this every frame, but it's just set merging. Fast enough.
        const effectiveLatched = new Set(manualLatchesRef.current.keys());

        // Add Chords
        const activeChordIds = activeChordIdsRef.current;
        const savedChords = currentSettings.savedChords;
        if (activeChordIds.length > 0) {
            activeChordIds.forEach(id => {
                const c = savedChords.find(ch => ch.id === id);
                if (c) c.nodes.forEach(n => effectiveLatched.add(n.id));
            });
        }

        const size = currentSettings.canvasSize;

        // Resize check
        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Culling
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // Helper to check voice leading opacity
        const hasActiveNodes = effectiveLatched.size > 0;
        const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && hasActiveNodes;

        // Create visible node map for fast lookup during line drawing
        // This is O(N), might be slow if 5000 nodes.
        // Optimization: The Data object should probably have a Map lookup built-in or cached.
        // For now, we rely on array find/filter which is suboptimal but maybe ok for <2000 nodes.
        // Actually, we can just use effectiveLatched set for O(1) checks.

        // DRAW LINES
        for (const line of currentData.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            // Culling
            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = effectiveLatched.has(line.sourceId);
            const active2 = effectiveLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Line
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive Line
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;

                // Opacity Logic
                if (isVoiceLeading) {
                    ctx.globalAlpha = 0.05; // Very faint if focusing on active voice leading
                } else {
                    ctx.globalAlpha = 0.15; // Faint by default
                }

                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        // We need a list of active nodes for distance calculations
        // If Voice Leading is enabled, we need to iterate all nodes and check distance to active ones.
        // This is O(N * M) where N=VisibleNodes, M=ActiveNodes.
        // If M is small (usually <10), this is fast.

        let activeNodeObjects: LatticeNode[] = [];
        if (isVoiceLeading) {
            activeNodeObjects = currentData.nodes.filter(n => effectiveLatched.has(n.id));
        }

        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            // Culling
            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = effectiveLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (isVoiceLeading) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodeObjects) {
                         // Fast check
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.1; scale = 0.5; // Faded out
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.shadowColor = ctx.strokeStyle;
                 ctx.shadowBlur = 10;
                 ctx.stroke();
                 ctx.shadowBlur = 0; 
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = `bold 11px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        // Draw Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM (Retained for lookup performance) ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State (Restored to useState)
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio Sync ---
  // Calculates the "Effective" latched set (Manual + Chords)
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Handle Chord Retriggering
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing (Note On/Off)
  // This runs whenever effectiveLatchedNodes changes
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Note On
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      // Note Off
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching (Shell Limit Check)
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        // Update Cursor State
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        // Update Latch State
        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    // Update Cursor Position
    setActiveCursors(prev => {
        const next = new Map(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    // Pitch Bend Logic
    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    // Drag Latching (Latch Mode only)
    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     // Check shell limit
                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);

        const cursor = activeCursors.get(e.pointerId)!;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Canvas Rendering ---
  // Re-runs whenever data or visual state changes
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true }); // Important for background
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const size = settings.canvasSize;

    if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
        canvas.width = size * dpr;
        canvas.height = size * dpr;
        ctx.scale(dpr, dpr);
    }

    // Viewport Culling
    let viewX = 0, viewY = 0, viewW = size, viewH = size;
    if (scrollContainerRef.current) {
        viewX = scrollContainerRef.current.scrollLeft;
        viewY = scrollContainerRef.current.scrollTop;
        viewW = scrollContainerRef.current.clientWidth;
        viewH = scrollContainerRef.current.clientHeight;
    }
    const pad = 100;

    ctx.clearRect(viewX, viewY, viewW, viewH);

    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;
    const baseRadius = (60 * settings.buttonSizeScale) / 2;
    const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
    const colorCache = settings.colors;

    ctx.lineCap = 'round';

    // Helper: Identify Active Nodes for Voice Leading
    const activeNodesList = settings.isVoiceLeadingEnabled ? data.nodes.filter(n => effectiveLatchedNodes.has(n.id)) : [];
    const isVoiceLeading = settings.isVoiceLeadingEnabled && activeNodesList.length > 0;
    const allowedMaxIndex = settings.latchShellLimit - 2;

    // --- DRAW LINES ---
    for (const line of data.lines) {
        const x1 = line.x1 * spacing + centerOffset;
        const y1 = line.y1 * spacing + centerOffset;
        const x2 = line.x2 * spacing + centerOffset;
        const y2 = line.y2 * spacing + centerOffset;

        if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
            Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
            continue;
        }

        const active1 = effectiveLatchedNodes.has(line.sourceId);
        const active2 = effectiveLatchedNodes.has(line.targetId);
        const limitColor = colorCache[line.limit] || '#666';

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);

        if (active1 && active2) {
            // Active Line
            ctx.lineWidth = 5;
            ctx.strokeStyle = limitColor;
            ctx.setLineDash([]);
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            // Glow effect
            if (settings.isVoiceLeadingAnimationEnabled) {
                 ctx.shadowColor = limitColor;
                 ctx.shadowBlur = settings.voiceLeadingGlowAmount * 10;
                 ctx.strokeStyle = 'white';
                 ctx.globalAlpha = 0.5;
                 ctx.lineWidth = 2;
                 ctx.stroke();
                 ctx.shadowBlur = 0;
            }
        } else {
            // Inactive Line
            ctx.lineWidth = line.limit === 1 ? 4 : 2;
            ctx.strokeStyle = limitColor;

            // Faded logic
            if (isVoiceLeading) {
                ctx.globalAlpha = 0.05; // Faint if focusing on voice leading
            } else {
                ctx.globalAlpha = 0.15; // Standard inactive
            }

            ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
            ctx.stroke();
        }
    }

    // --- DRAW NODES ---
    for (const node of data.nodes) {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;

        if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

        const isLatched = effectiveLatchedNodes.has(node.id);
        let isHovered = false;
        for (const c of activeCursors.values()) {
            if (c.originNodeId === node.id) { isHovered = true; break; }
        }

        const isActive = isLatched || isHovered;
        let scale = 1.0;
        let opacity = 0.95;

        // Visual filtering for Voice Leading
        if (isVoiceLeading) {
             if (isActive) {
                 scale = settings.latchedZoomScale;
                 opacity = 1.0;
             } else {
                 let isCompatible = false;
                 let minDist = Infinity;

                 for (const an of activeNodesList) {
                     // Quick check
                     if (Math.abs(an.x - node.x) > 2000) continue; 

                     let valid = true;
                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - an.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                         }
                     }

                     if (valid) {
                         isCompatible = true;
                         const d = getHarmonicDistance(node.coords, an.coords);
                         if (d < minDist) minDist = d;
                     }
                 }

                 if (!isCompatible) {
                     opacity = 0.1; scale = 0.5; // Faded
                 } else {
                     const visibility = Math.max(0.2, 1 - (minDist * settings.voiceLeadingStrength));
                     scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                     opacity = visibility;
                 }
             }
        } else {
            scale = isActive ? settings.latchedZoomScale : 1.0;
            opacity = isActive ? 1.0 : 0.95;
        }

        const radius = baseRadius * scale;
        const cTop = colorCache[node.limitTop] || '#666';
        const cBottom = colorCache[node.limitBottom] || '#666';

        ctx.globalAlpha = opacity;
        ctx.beginPath();
        if (isDiamond) {
            ctx.moveTo(x, y - radius);
            ctx.lineTo(x + radius, y);
            ctx.lineTo(x, y + radius);
            ctx.lineTo(x - radius, y);
            ctx.closePath();
        } else {
            ctx.arc(x, y, radius, 0, Math.PI * 2);
        }

        const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
        grad.addColorStop(0.45, cTop);
        grad.addColorStop(0.55, cBottom);
        ctx.fillStyle = grad;
        ctx.fill();

        // Outline
        if (settings.isColoredIlluminationEnabled && isActive) {
             const rainbowPeriod = PITCH_SCALE * spacing;
             const phase = (y % rainbowPeriod) / rainbowPeriod;
             const hue = (settings.rainbowOffset + phase * 360) % 360;
             const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
             ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
             ctx.lineWidth = 4;
             ctx.stroke();
        } else if (isActive) {
             ctx.strokeStyle = 'white';
             ctx.lineWidth = 3;
             ctx.stroke();
        }

        // Text
        if (scale > 0.6) {
            ctx.fillStyle = 'white';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            // Scale font slightly with node, but keep legible limits
            const fontSize = Math.max(9, Math.min(14, 11 * scale));
            ctx.font = `bold ${fontSize}px sans-serif`; 

            ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
            ctx.beginPath();
            ctx.moveTo(x - (radius * 0.4), y);
            ctx.lineTo(x + (radius * 0.4), y);
            ctx.lineWidth = 1;
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.stroke();
            ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
        }
    }

    // --- DRAW CURSORS ---
    activeCursors.forEach(c => {
        const node = data.nodes.find(n => n.id === c.originNodeId);
        if(node) {
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;

             let cx = 0, cy = 0;
             if (scrollContainerRef.current) {
                 const r = scrollContainerRef.current.getBoundingClientRect();
                 cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                 cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
             }

             ctx.beginPath();
             ctx.moveTo(nx, ny);
             ctx.lineTo(cx, cy);
             ctx.strokeStyle = 'white';
             ctx.lineWidth = 2;
             ctx.setLineDash([]);
             ctx.globalAlpha = 0.5;
             ctx.stroke();
        }
    });

  }, [
    data, 
    effectiveLatchedNodes, 
    activeCursors, 
    settings.canvasSize, 
    settings.buttonSpacingScale, 
    settings.buttonSizeScale,
    settings.buttonShape,
    settings.colors,
    settings.isVoiceLeadingEnabled,
    settings.voiceLeadingStrength,
    settings.isVoiceLeadingAnimationEnabled,
    settings.voiceLeadingGlowAmount,
    settings.latchedZoomScale,
    settings.rainbowOffset,
    settings.rainbowSaturation,
    settings.isRainbowModeEnabled,
    settings.isColoredIlluminationEnabled
  ]);

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM (Retained for lookup performance) ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State (Restored to useState)
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio Sync ---
  // Calculates the "Effective" latched set (Manual + Chords)
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Handle Chord Retriggering
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing (Note On/Off)
  // This runs whenever effectiveLatchedNodes changes
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      // Note On
      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      // Note Off
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching (Shell Limit Check)
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        // Fix: Explicit typing to avoid 'unknown' inference issues
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        // Update Cursor State
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        // Update Latch State
        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    // Update Cursor Position
    setActiveCursors(prev => {
        // Fix: Explicit generic type to avoid spread error
        const next = new Map<number, ActiveCursor>(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    // Pitch Bend Logic
    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    // Drag Latching (Latch Mode only)
    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     // Check shell limit
                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);

        const cursor = activeCursors.get(e.pointerId)!;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Canvas Rendering ---
  // Re-runs whenever data or visual state changes
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true }); // Important for background
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const size = settings.canvasSize;

    if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
        canvas.width = size * dpr;
        canvas.height = size * dpr;
        ctx.scale(dpr, dpr);
    }

    // Viewport Culling
    let viewX = 0, viewY = 0, viewW = size, viewH = size;
    if (scrollContainerRef.current) {
        viewX = scrollContainerRef.current.scrollLeft;
        viewY = scrollContainerRef.current.scrollTop;
        viewW = scrollContainerRef.current.clientWidth;
        viewH = scrollContainerRef.current.clientHeight;
    }
    const pad = 100;

    ctx.clearRect(viewX, viewY, viewW, viewH);

    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;
    const baseRadius = (60 * settings.buttonSizeScale) / 2;
    const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
    const colorCache = settings.colors;

    ctx.lineCap = 'round';

    // Helper: Identify Active Nodes for Voice Leading
    const activeNodesList = settings.isVoiceLeadingEnabled ? data.nodes.filter(n => effectiveLatchedNodes.has(n.id)) : [];
    const isVoiceLeading = settings.isVoiceLeadingEnabled && activeNodesList.length > 0;
    const allowedMaxIndex = settings.latchShellLimit - 2;

    // --- DRAW LINES ---
    for (const line of data.lines) {
        const x1 = line.x1 * spacing + centerOffset;
        const y1 = line.y1 * spacing + centerOffset;
        const x2 = line.x2 * spacing + centerOffset;
        const y2 = line.y2 * spacing + centerOffset;

        if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
            Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
            continue;
        }

        const active1 = effectiveLatchedNodes.has(line.sourceId);
        const active2 = effectiveLatchedNodes.has(line.targetId);
        const limitColor = colorCache[line.limit] || '#666';

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);

        if (active1 && active2) {
            // Active Line
            ctx.lineWidth = 5;
            ctx.strokeStyle = limitColor;
            ctx.setLineDash([]);
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            // Glow effect
            if (settings.isVoiceLeadingAnimationEnabled) {
                 ctx.shadowColor = limitColor;
                 ctx.shadowBlur = settings.voiceLeadingGlowAmount * 10;
                 ctx.strokeStyle = 'white';
                 ctx.globalAlpha = 0.5;
                 ctx.lineWidth = 2;
                 ctx.stroke();
                 ctx.shadowBlur = 0;
            }
        } else {
            // Inactive Line
            ctx.lineWidth = line.limit === 1 ? 4 : 2;
            ctx.strokeStyle = limitColor;

            // Faded logic
            if (isVoiceLeading) {
                ctx.globalAlpha = 0.05; // Faint if focusing on voice leading
            } else {
                ctx.globalAlpha = 0.15; // Standard inactive
            }

            ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
            ctx.stroke();
        }
    }

    // --- DRAW NODES ---
    for (const node of data.nodes) {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;

        if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

        const isLatched = effectiveLatchedNodes.has(node.id);
        let isHovered = false;
        for (const c of activeCursors.values()) {
            if (c.originNodeId === node.id) { isHovered = true; break; }
        }

        const isActive = isLatched || isHovered;
        let scale = 1.0;
        let opacity = 0.95;

        // Visual filtering for Voice Leading
        if (isVoiceLeading) {
             if (isActive) {
                 scale = settings.latchedZoomScale;
                 opacity = 1.0;
             } else {
                 let isCompatible = false;
                 let minDist = Infinity;

                 for (const an of activeNodesList) {
                     // Quick check
                     if (Math.abs(an.x - node.x) > 2000) continue; 

                     let valid = true;
                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - an.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                         }
                     }

                     if (valid) {
                         isCompatible = true;
                         const d = getHarmonicDistance(node.coords, an.coords);
                         if (d < minDist) minDist = d;
                     }
                 }

                 if (!isCompatible) {
                     opacity = 0.1; scale = 0.5; // Faded
                 } else {
                     const visibility = Math.max(0.2, 1 - (minDist * settings.voiceLeadingStrength));
                     scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                     opacity = visibility;
                 }
             }
        } else {
            scale = isActive ? settings.latchedZoomScale : 1.0;
            opacity = isActive ? 1.0 : 0.95;
        }

        const radius = baseRadius * scale;
        const cTop = colorCache[node.limitTop] || '#666';
        const cBottom = colorCache[node.limitBottom] || '#666';

        ctx.globalAlpha = opacity;
        ctx.beginPath();
        if (isDiamond) {
            ctx.moveTo(x, y - radius);
            ctx.lineTo(x + radius, y);
            ctx.lineTo(x, y + radius);
            ctx.lineTo(x - radius, y);
            ctx.closePath();
        } else {
            ctx.arc(x, y, radius, 0, Math.PI * 2);
        }

        const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
        grad.addColorStop(0.45, cTop);
        grad.addColorStop(0.55, cBottom);
        ctx.fillStyle = grad;
        ctx.fill();

        // Outline
        if (settings.isColoredIlluminationEnabled && isActive) {
             const rainbowPeriod = PITCH_SCALE * spacing;
             const phase = (y % rainbowPeriod) / rainbowPeriod;
             const hue = (settings.rainbowOffset + phase * 360) % 360;
             const sat = settings.isRainbowModeEnabled ? settings.rainbowSaturation : 100;
             ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
             ctx.lineWidth = 4;
             ctx.stroke();
        } else if (isActive) {
             ctx.strokeStyle = 'white';
             ctx.lineWidth = 3;
             ctx.stroke();
        }

        // Text
        if (scale > 0.6) {
            ctx.fillStyle = 'white';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            // Scale font slightly with node, but keep legible limits
            const fontSize = Math.max(9, Math.min(14, 11 * scale));
            ctx.font = `bold ${fontSize}px sans-serif`; 

            ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
            ctx.beginPath();
            ctx.moveTo(x - (radius * 0.4), y);
            ctx.lineTo(x + (radius * 0.4), y);
            ctx.lineWidth = 1;
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.stroke();
            ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
        }
    }

    // --- DRAW CURSORS ---
    activeCursors.forEach(c => {
        const node = data.nodes.find(n => n.id === c.originNodeId);
        if(node) {
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;

             let cx = 0, cy = 0;
             if (scrollContainerRef.current) {
                 const r = scrollContainerRef.current.getBoundingClientRect();
                 cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                 cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
             }

             ctx.beginPath();
             ctx.moveTo(nx, ny);
             ctx.lineTo(cx, cy);
             ctx.strokeStyle = 'white';
             ctx.lineWidth = 2;
             ctx.setLineDash([]);
             ctx.globalAlpha = 0.5;
             ctx.stroke();
        }
    });

  }, [
    data, 
    effectiveLatchedNodes, 
    activeCursors, 
    settings.canvasSize, 
    settings.buttonSpacingScale, 
    settings.buttonSizeScale,
    settings.buttonShape,
    settings.colors,
    settings.isVoiceLeadingEnabled,
    settings.voiceLeadingStrength,
    settings.isVoiceLeadingAnimationEnabled,
    settings.voiceLeadingGlowAmount,
    settings.latchedZoomScale,
    settings.rainbowOffset,
    settings.rainbowSaturation,
    settings.isRainbowModeEnabled,
    settings.isColoredIlluminationEnabled
  ]);

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (Source of Truth for Animation)
  // We sync React State -> Refs so the animation loop can read latest data without re-binding
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Filter Hidden Limits - Nodes
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of settings.hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    // Filter Hidden Limits - Lines
    const visibleLines = result.lines.filter(l => !settings.hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    setActiveCursors(prev => {
        const next = new Map<number, ActiveCursor>(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursors.get(e.pointerId)!;
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const lineDash = [0, 40];

    const render = (time: number) => {
        // READ LATEST DATA FROM REFS
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Viewport Culling
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // Prepare active node list for voice leading checks
        // We filter from the CURRENT data nodes based on what is latched
        const activeNodesList = currentSettings.isVoiceLeadingEnabled 
            ? currentData.nodes.filter(n => currentLatched.has(n.id)) 
            : [];
        const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0;
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        // DRAW LINES
        for (const line of currentData.lines) {
            // Note: currentData.lines is ALREADY filtered by hiddenLimits in the data generation useEffect.

            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Line
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive Line
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;

                if (isVoiceLeading) {
                    ctx.globalAlpha = 0.05; 
                } else {
                    ctx.globalAlpha = 0.15;
                }

                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (isVoiceLeading) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.1; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                const fontSize = Math.max(9, Math.min(14, 11 * scale));
                ctx.font = `bold ${fontSize}px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (Source of Truth for Animation)
  // We sync React State -> Refs so the animation loop can read latest data without re-binding
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    const result = generateLattice(settings, depthOrigins);

    // Explicitly cast to number[] to handle potential type inference issues
    const hiddenLimits = settings.hiddenLimits as number[];

    // Filter Hidden Limits - Nodes
    const visibleNodes = result.nodes.filter(n => {
        for (const limit of hiddenLimits) {
            const idx = LIMIT_TO_INDEX[limit];
            if (idx !== undefined && n.coords[idx] !== 0) return false;
        }
        return true;
    });

    // Filter Hidden Limits - Lines
    const visibleLines = result.lines.filter(l => !hiddenLimits.includes(l.limit));

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    visibleNodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: visibleNodes, lines: visibleLines });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    setActiveCursors(prev => {
        const next = new Map<number, ActiveCursor>(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursors.get(e.pointerId)!;
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const lineDash = [0, 40];

    const render = (time: number) => {
        // READ LATEST DATA FROM REFS
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Viewport Culling
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // Prepare active node list for voice leading checks
        // We filter from the CURRENT data nodes based on what is latched
        const activeNodesList = currentSettings.isVoiceLeadingEnabled 
            ? currentData.nodes.filter(n => currentLatched.has(n.id)) 
            : [];
        const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0;
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        // DRAW LINES
        for (const line of currentData.lines) {
            // Note: currentData.lines is ALREADY filtered by hiddenLimits in the data generation useEffect.

            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Line
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive Line
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;

                if (isVoiceLeading) {
                    ctx.globalAlpha = 0.05; 
                } else {
                    ctx.globalAlpha = 0.15;
                }

                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (isVoiceLeading) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.1; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                const fontSize = Math.max(9, Math.min(14, 11 * scale));
                ctx.font = `bold ${fontSize}px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (Source of Truth for Animation)
  // We sync React State -> Refs so the animation loop can read latest data without re-binding
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    // Optimization: Create effective settings where hidden limits have 0 depth.
    // This prevents generating thousands of unused nodes (Lag Fix) and ensures lines don't exist (Visual Fix).
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; // Explicit cast for safety

    hiddenLimits.forEach(limit => {
        // We zero out the depth for hidden limits so the BFS doesn't expand them.
        // This is the most efficient way to handle the "lag" issue.
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    // Create a Set of visible node IDs for fast line validation
    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    // Filter Lines
    // 1. Must not be in hiddenLimits (redundant with depth=0 but good for safety)
    // 2. Must connect two nodes that actually exist in the visible set
    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    result.nodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [
      settings.limitDepths, 
      settings.limitComplexities, 
      settings.hiddenLimits, // Trigger on visibility change
      settings.latticeAspectRatio, 
      depthOrigins, 
      settings.buttonSpacingScale, 
      settings.canvasSize
  ]);

  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes(prev => {
        const next = new Map(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    setActiveCursors(prev => {
        const next = new Map<number, ActiveCursor>(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursors.get(e.pointerId)!;
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const lineDash = [0, 40];

    const render = (time: number) => {
        // READ LATEST DATA FROM REFS
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Viewport Culling
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // Prepare active node list for voice leading checks
        const activeNodesList = currentSettings.isVoiceLeadingEnabled 
            ? currentData.nodes.filter(n => currentLatched.has(n.id)) 
            : [];
        const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0;
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        // DRAW LINES
        for (const line of currentData.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Line
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive Line
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;

                if (isVoiceLeading) {
                    ctx.globalAlpha = 0.05; 
                } else {
                    ctx.globalAlpha = 0.15;
                }

                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (isVoiceLeading) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.1; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                const fontSize = Math.max(9, Math.min(14, 11 * scale));
                ctx.font = `bold ${fontSize}px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (Source of Truth for Animation)
  // We sync React State -> Refs so the animation loop can read latest data without re-binding
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    // Optimization: Create effective settings where hidden limits have 0 depth.
    // This prevents generating thousands of unused nodes (Lag Fix) and ensures lines don't exist (Visual Fix).
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; // Explicit cast for safety

    hiddenLimits.forEach(limit => {
        // We zero out the depth for hidden limits so the BFS doesn't expand them.
        // This is the most efficient way to handle the "lag" issue.
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    // Create a Set of visible node IDs for fast line validation
    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    // Filter Lines
    // 1. Must not be in hiddenLimits (redundant with depth=0 but good for safety)
    // 2. Must connect two nodes that actually exist in the visible set
    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    result.nodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [
      settings.limitDepths, 
      settings.limitComplexities, 
      settings.hiddenLimits, // Trigger on visibility change
      settings.latticeAspectRatio, 
      depthOrigins, 
      settings.buttonSpacingScale, 
      settings.canvasSize
  ]);

  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    setActiveCursors(prev => {
        const next = new Map<number, ActiveCursor>(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursors.get(e.pointerId)!;
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const lineDash = [0, 40];

    const render = (time: number) => {
        // READ LATEST DATA FROM REFS
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Viewport Culling
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const flowOffset = currentSettings.isVoiceLeadingAnimationEnabled 
            ? -(time / 1000 * currentSettings.voiceLeadingAnimationSpeed * 40) % 40 
            : 0;

        ctx.lineCap = 'round';

        // Prepare active node list for voice leading checks
        const activeNodesList = currentSettings.isVoiceLeadingEnabled 
            ? currentData.nodes.filter(n => currentLatched.has(n.id)) 
            : [];
        const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0;
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        // DRAW LINES
        for (const line of currentData.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Line
                ctx.lineWidth = 5;
                ctx.strokeStyle = limitColor;
                ctx.setLineDash([]);
                ctx.globalAlpha = 1.0;
                ctx.stroke();

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                     ctx.lineWidth = 3 * (1 + currentSettings.voiceLeadingGlowAmount);
                     ctx.strokeStyle = 'white';
                     ctx.setLineDash(lineDash);
                     ctx.lineDashOffset = currentSettings.voiceLeadingReverseDir ? -flowOffset : flowOffset;
                     ctx.globalAlpha = 0.8;
                     ctx.shadowColor = limitColor;
                     ctx.shadowBlur = currentSettings.voiceLeadingGlowAmount * 10;
                     ctx.stroke();
                     ctx.shadowBlur = 0;
                     ctx.shadowColor = 'transparent';
                }
            } else {
                // Inactive Line
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;

                if (isVoiceLeading) {
                    ctx.globalAlpha = 0.05; 
                } else {
                    ctx.globalAlpha = 0.15;
                }

                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (isVoiceLeading) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.1; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            if (currentSettings.isColoredIlluminationEnabled && isActive) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                const fontSize = Math.max(9, Math.min(14, 11 * scale));
                ctx.font = `bold ${fontSize}px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// --- SPATIAL HASH SYSTEM ---
class SpatialHash {
  private cellSize: number;
  private cells: Map<string, LatticeNode[]>;

  constructor(cellSize: number) {
    this.cellSize = cellSize;
    this.cells = new Map();
  }

  key(x: number, y: number) {
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);
    return `${cx},${cy}`;
  }

  insert(node: LatticeNode, x: number, y: number) {
    const k = this.key(x, y);
    if (!this.cells.has(k)) this.cells.set(k, []);
    this.cells.get(k)!.push(node);
  }

  query(x: number, y: number): LatticeNode[] {
    const results: LatticeNode[] = [];
    const cx = Math.floor(x / this.cellSize);
    const cy = Math.floor(y / this.cellSize);

    for (let i = -1; i <= 1; i++) {
      for (let j = -1; j <= 1; j++) {
        const k = `${cx + i},${cy + j}`;
        const cell = this.cells.get(k);
        if (cell) {
          for (let n = 0; n < cell.length; n++) {
            results.push(cell[n]);
          }
        }
      }
    }
    return results;
  }

  clear() {
    this.cells.clear();
  }
}

const PITCH_SCALE = 200;
const LIMIT_TO_INDEX: {[key: number]: number} = { 3: 0, 5: 1, 7: 2, 11: 3, 13: 4 };

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [spatialHash] = useState(() => new SpatialHash(150)); 

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (Source of Truth for Animation)
  // We sync React State -> Refs so the animation loop can read latest data without re-binding
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  useEffect(() => {
    // Optimization: Create effective settings where hidden limits have 0 depth.
    // This prevents generating thousands of unused nodes (Lag Fix) and ensures lines don't exist (Visual Fix).
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; // Explicit cast for safety

    hiddenLimits.forEach(limit => {
        // We zero out the depth for hidden limits so the BFS doesn't expand them.
        // This is the most efficient way to handle the "lag" issue.
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    // Create a Set of visible node IDs for fast line validation
    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    // Filter Lines
    // 1. Must not be in hiddenLimits (redundant with depth=0 but good for safety)
    // 2. Must connect two nodes that actually exist in the visible set
    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    // Rebuild Spatial Hash
    spatialHash.clear();
    const centerOffset = settings.canvasSize / 2;
    const spacing = settings.buttonSpacingScale;

    result.nodes.forEach(node => {
        const x = node.x * spacing + centerOffset;
        const y = node.y * spacing + centerOffset;
        spatialHash.insert(node, x, y);
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [
      settings.limitDepths, 
      settings.limitComplexities, 
      settings.hiddenLimits, // Trigger on visibility change
      settings.latticeAspectRatio, 
      depthOrigins, 
      settings.buttonSpacingScale, 
      settings.canvasSize
  ]);

  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, data.nodes, settings.baseFrequency]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) audioEngine.stopVoice(`node-${nodeId}`);
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const candidates = spatialHash.query(x, y);
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const radius = (60 * settings.buttonSizeScale) / 2;
      const radiusSq = radius * radius;

      let hitNode: LatticeNode | null = null;
      for (const node of candidates) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const dx = x - nx;
          const dy = y - ny;
          if (dx*dx + dy*dy < radiusSq) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
        onLimitInteraction(hitNode.maxPrime);
        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked || !activeCursors.has(e.pointerId)) return;

    setActiveCursors(prev => {
        const next = new Map<number, ActiveCursor>(prev);
        const cursor = next.get(e.pointerId);
        if (cursor) {
            next.set(e.pointerId, { ...cursor, currentX: e.clientX, currentY: e.clientY });
        }
        return next;
    });

    const cursor = activeCursors.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
    }

    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const candidates = spatialHash.query(cx, cy);
         const centerOffset = settings.canvasSize / 2;
         const spacing = settings.buttonSpacingScale;
         const radius = (60 * settings.buttonSizeScale) / 2;
         const radiusSq = radius * radius;

         for (const node of candidates) {
             if (node.id === cursor.originNodeId) continue;
             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < radiusSq) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);
                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursors.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        const cursor = activeCursors.get(e.pointerId)!;
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        // READ LATEST DATA FROM REFS
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        // Viewport Culling
        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }
        const pad = 100;

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        // Animation Phase for Voice Leading Lines (0 to 1)
        const animationSpeed = currentSettings.voiceLeadingAnimationSpeed || 2.0;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        // Prepare active node list for voice leading checks
        const activeNodesList = currentSettings.isVoiceLeadingEnabled 
            ? currentData.nodes.filter(n => currentLatched.has(n.id)) 
            : [];
        const isVoiceLeading = currentSettings.isVoiceLeadingEnabled && activeNodesList.length > 0;
        const allowedMaxIndex = currentSettings.latchShellLimit - 2;

        // DRAW LINES
        for (const line of currentData.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < viewX - pad || Math.min(x1, x2) > viewX + viewW + pad ||
                Math.max(y1, y2) < viewY - pad || Math.min(y1, y2) > viewY + viewH + pad) {
                continue;
            }

            const active1 = currentLatched.has(line.sourceId);
            const active2 = currentLatched.has(line.targetId);
            const limitColor = colorCache[line.limit] || '#666';

            // Draw Base Line
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);

            if (active1 && active2) {
                // Active Line - Solid, Bright, Glowing
                ctx.lineWidth = 5;
                ctx.setLineDash([]); // Ensure solid

                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                    // Create Moving Gradient Beam
                    const grad = ctx.createLinearGradient(x1, y1, x2, y2);

                    // Creates a moving "white hot" center that loops
                    // We add stops based on flowPhase. 
                    // To handle wrapping cleanly with a simple linear gradient is tricky, 
                    // so we use a "pulse" that moves 0->1.
                    const p = flowPhase;

                    // Clamp to safe range [0, 1] for addColorStop
                    // We simulate a wide beam passing through
                    // Stops: [0..p-0.2] Color -> [p] White -> [p+0.2..1] Color

                    const startStop = Math.max(0, p - 0.2);
                    const endStop = Math.min(1, p + 0.2);

                    grad.addColorStop(0, limitColor);
                    if (startStop > 0) grad.addColorStop(startStop, limitColor);
                    grad.addColorStop(p, 'white');
                    if (endStop < 1) grad.addColorStop(endStop, limitColor);
                    grad.addColorStop(1, limitColor);

                    ctx.strokeStyle = grad;
                    ctx.shadowColor = limitColor;
                    ctx.shadowBlur = 15 * currentSettings.voiceLeadingGlowAmount;
                    ctx.globalAlpha = 1.0;
                } else {
                    // Static Active Line
                    ctx.strokeStyle = limitColor;
                    ctx.globalAlpha = 1.0;
                    ctx.shadowBlur = 0;
                }

                ctx.stroke();

                // Reset shadow for next operations
                ctx.shadowBlur = 0;
                ctx.shadowColor = 'transparent';

            } else {
                // Inactive Line
                ctx.lineWidth = line.limit === 1 ? 4 : 2;
                ctx.strokeStyle = limitColor;

                if (isVoiceLeading) {
                    ctx.globalAlpha = 0.05; 
                } else {
                    ctx.globalAlpha = 0.15;
                }

                ctx.setLineDash(line.limit === 1 ? [5, 5] : []);
                ctx.stroke();
            }
        }

        // DRAW NODES
        for (const node of currentData.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < viewX - pad || x > viewX + viewW + pad || y < viewY - pad || y > viewY + viewH + pad) continue;

            const isLatched = currentLatched.has(node.id);
            let isHovered = false;
            for (const c of currentCursors.values()) {
                if (c.originNodeId === node.id) { isHovered = true; break; }
            }

            const isActive = isLatched || isHovered;
            let scale = 1.0;
            let opacity = 0.95;

            if (isVoiceLeading) {
                 if (isActive) {
                     scale = currentSettings.latchedZoomScale;
                     opacity = 1.0;
                 } else {
                     let isCompatible = false;
                     let minDist = Infinity;

                     for (const an of activeNodesList) {
                         if (Math.abs(an.x - node.x) > 2000) continue; 

                         let valid = true;
                         if (currentSettings.latchShellLimit === 1) {
                             if (getHarmonicDistance(node.coords, an.coords) > 0) valid = false;
                         } else {
                             for(let i=0; i<node.coords.length; i++) {
                                 const diff = Math.abs(node.coords[i] - an.coords[i]);
                                 if (diff > 0 && i > allowedMaxIndex) { valid = false; break; }
                             }
                         }

                         if (valid) {
                             isCompatible = true;
                             const d = getHarmonicDistance(node.coords, an.coords);
                             if (d < minDist) minDist = d;
                         }
                     }

                     if (!isCompatible) {
                         opacity = 0.1; scale = 0.5;
                     } else {
                         const visibility = Math.max(0.2, 1 - (minDist * currentSettings.voiceLeadingStrength));
                         scale = Math.max(0.5, 0.5 + (visibility * 0.5));
                         opacity = visibility;
                     }
                 }
            } else {
                scale = isActive ? currentSettings.latchedZoomScale : 1.0;
                opacity = isActive ? 1.0 : 0.95;
            }

            const radius = baseRadius * scale;
            const cTop = colorCache[node.limitTop] || '#666';
            const cBottom = colorCache[node.limitBottom] || '#666';

            ctx.globalAlpha = opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
                ctx.closePath();
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            // "Selection Aura" - Rainbow Outline on Active Nodes
            if (isActive && currentSettings.isColoredIlluminationEnabled) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 // Calculate hue based on Y position (Pitch)
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;

                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
            } else if (isActive) {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
            }

            // Text Rendering
            if (scale > 0.6) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                const fontSize = Math.max(9, Math.min(14, 11 * scale));
                ctx.font = `bold ${fontSize}px sans-serif`; 

                ctx.fillText(node.n.toString(), x, y - (radius * 0.3));
                ctx.beginPath();
                ctx.moveTo(x - (radius * 0.4), y);
                ctx.lineTo(x + (radius * 0.4), y);
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.stroke();
                ctx.fillText(node.d.toString(), x, y + (radius * 0.4));
            }
        }

        // Draw User Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (c.currentX - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (c.currentY - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.setLineDash([]);
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); // Run once on mount

  // Rainbow Background Style
  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import { AppSettings, ButtonShape, ChordDefinition, LimitColorMap, OscillatorConfig, SynthPreset, WaveformType } from './types';

export const DEFAULT_COLORS: LimitColorMap = {
  1: '#EF4444', // Red (Unity)
  3: '#EAB308', // Yellow (3-Limit)
  5: '#3B82F6', // Blue (5-Limit)
  7: '#22C55E', // Green (7-Limit)
  11: '#A855F7', // Purple (11-Limit)
  13: '#F97316', // Orange (13-Limit)
};

// Generate empty chord slots A-Z + 6 more to make 32
const generateChordSlots = (): ChordDefinition[] => {
  const slots: ChordDefinition[] = [];
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ123456";
  for (let i = 0; i < 32; i++) {
    slots.push({
      id: alphabet[i],
      label: alphabet[i],
      color: '#3B82F6', // Default blue
      nodes: [],
      visible: false,
      position: { x: 0, y: 0 } // Positions will be managed dynamically if 0,0
    });
  }
  return slots;
};

// UI Dimensions Constants
export const MARGIN_3MM = 10; 
export const GAP_5MM = 20;
export const SCROLLBAR_WIDTH = 12; 

// Helper to get defaults
const getDefaults = () => {
    // Check for window existence for SSR safety
    const w = typeof window !== 'undefined' ? window.innerWidth : 1000;
    const h = typeof window !== 'undefined' ? window.innerHeight : 800;

    // Component Dimensions Estimates
    const LAYERS_HEIGHT = 310; 
    const LAYERS_WIDTH = 90; 

    // Top Bar Bottom
    const TOP_BAR_BOTTOM = MARGIN_3MM + 40; 
    // Bottom Bar Top: Height - (80px Panic + 10px Margin + 12px Scroll)
    const BOTTOM_BAR_TOP = h - (80 + MARGIN_3MM + SCROLLBAR_WIDTH);

    // Calculate vertical center for Layers
    const verticalCenterY = TOP_BAR_BOTTOM + ((BOTTOM_BAR_TOP - TOP_BAR_BOTTOM) / 2) - (LAYERS_HEIGHT / 2);

    // Panic Position (Bottom Right)
    const panicX = w - 80 - MARGIN_3MM - SCROLLBAR_WIDTH;
    const panicY = h - 80 - MARGIN_3MM - SCROLLBAR_WIDTH;

    return {
        volume: { 
            x: (w / 2) - 80, // Centered (Width 160)
            y: MARGIN_3MM 
        },
        panic: { 
            x: panicX, 
            y: panicY 
        },
        off: {
            x: panicX,
            y: panicY - 80 - GAP_5MM // Placed above Panic with 5mm gap
        },
        center: { 
            // 48px width
            x: MARGIN_3MM, 
            y: h - 48 - MARGIN_3MM - SCROLLBAR_WIDTH 
        },
        depth: { 
            // 48px width + 12px gap from Center
            x: MARGIN_3MM + 60, 
            y: h - 48 - MARGIN_3MM - SCROLLBAR_WIDTH 
        },
        chords: { 
            // 60px offset from Depth
            x: MARGIN_3MM + 120, 
            y: h - 48 - MARGIN_3MM - SCROLLBAR_WIDTH 
        },
        layers: { 
            // Positioned to avoid scrollbar overlap (Right Edge)
            x: w - LAYERS_WIDTH - MARGIN_3MM - SCROLLBAR_WIDTH, 
            // Equidistant between Settings (Top) and Off (Bottom)
            y: Math.max(TOP_BAR_BOTTOM, verticalCenterY) 
        }
    };
};

