class MidiService {
    private access: WebMidi.MIDIAccess | null = null;
    private output: WebMidi.MIDIOutput | null = null;
    private initialized = false;

    // Channel Management for Polyphonic Pitch Bend (MPE-style)
    // We rotate through channels 1-16 to allow each note to have its own bend.
    private activeChannels: Map<string, number> = new Map(); // NoteID -> Channel
    private nextChannel = 0; // 0-15 (corresponding to Ch 1-16)

    constructor() {}

    public async init(): Promise<boolean> {
        if (this.initialized) return true;

        if (!navigator.requestMIDIAccess) {
            console.warn("Web MIDI API not supported");
            return false;
        }

        try {
            this.access = await navigator.requestMIDIAccess();
            this.initialized = true;
            return true;
        } catch (e) {
            console.error("Failed to access MIDI", e);
            return false;
        }
    }

    public getOutputs(): MidiDevice[] {
        if (!this.access) return [];
        const devices: MidiDevice[] = [];
        this.access.outputs.forEach(output => {
            devices.push({
                id: output.id,
                name: output.name || `MIDI Output ${output.id}`
            });
        });
        return devices;
    }

    public setOutput(id: string | null) {
        if (!this.access || !id) {
            this.output = null;
            return;
        }
        this.output = this.access.outputs.get(id) || null;
    }

    // --- MIDI MESSAGES ---

    public sendNoteOn(id: string, ratio: number, baseFreq: number, bendRange: number = 2) {
        if (!this.output) return;

        // Calculate MIDI Note & Pitch Bend
        // MIDI Note 69 = A4 = 440Hz
        const freq = baseFreq * ratio;
        const midiFloat = 69 + 12 * Math.log2(freq / 440);

        const noteNumber = Math.round(midiFloat);
        const bendSemitones = midiFloat - noteNumber;

        // Map semitones to Pitch Bend (14-bit: 0-16383, Center 8192)
        // Range defined in settings (e.g. +/- 2, 12, 24, 48)
        const normalizedBend = bendSemitones / bendRange; // -1 to 1 range relative to full bend width
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        // Allocate Channel
        const channel = this.allocateChannel(id);
        const chByte = 0x90 | channel; // Note On
        const pbByte = 0xE0 | channel; // Pitch Bend

        // Send Pitch Bend FIRST so note starts at correct pitch
        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;
        this.output.send([pbByte, lsb, msb]);

        // Send Note On
        // Velocity fixed at 100 for now
        this.output.send([chByte, noteNumber, 100]);
    }

    public sendNoteOff(id: string) {
        if (!this.output) return;

        const channel = this.activeChannels.get(id);
        if (channel === undefined) return;

        // Note: We don't track the exact note number here, which MIDI requires for NoteOff.
        // In a robust implementation, we'd store the note number too.
        // However, for monophonic-per-channel (MPE style), sending All Notes Off or 
        // strictly tracking note numbers is needed. 
        // For now, we will assume the synth handles Note Off matching or we need to track it.
        // CHANGE: We need to store Note Number to send correct Note Off.
        // Refactoring activeChannels to store { channel, note }.

        // Since we didn't store it in the simplified version, let's just send Note Off 
        // for ALL notes on that channel (a bit hacky but safe for MPE) 
        // OR better: Update state to track it.
        // Let's rely on the fact that we use the channel rotation. 
        // Actually, we should really track the note number.
        // Let's upgrade activeChannels map in next step if needed. 
        // For now, let's assume valid MPE synths handle Note Off 
        // but standard MIDI requires the note number.
        // Re-calculate note? No, ratio might have changed (glide).
        // Let's implement a simple tracking.
    }

    // Improved Send with Tracking
    private activeNotes: Map<string, { channel: number, note: number }> = new Map();

    public noteOn(id: string, ratio: number, baseFreq: number, bendRange: number) {
        if (!this.output) return;

        const freq = baseFreq * ratio;
        const midiFloat = 69 + 12 * Math.log2(freq / 440);
        const noteNumber = Math.round(midiFloat);
        const bendSemitones = midiFloat - noteNumber;

        const normalizedBend = bendSemitones / bendRange; 
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        // Channel
        let channel = this.nextChannel;
        this.nextChannel = (this.nextChannel + 1) % 16; 

        this.activeNotes.set(id, { channel, note: noteNumber });

        // Pitch Bend
        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;
        this.output.send([0xE0 | channel, lsb, msb]);

        // Note On
        this.output.send([0x90 | channel, noteNumber, 100]);
    }

    public noteOff(id: string) {
        if (!this.output) return;
        const data = this.activeNotes.get(id);
        if (!data) return;

        this.output.send([0x80 | data.channel, data.note, 0]);
        this.activeNotes.delete(id);
    }

    public pitchBend(id: string, ratio: number, baseFreq: number, bendRange: number) {
        if (!this.output) return;
        const data = this.activeNotes.get(id);
        if (!data) return;

        // Current target note
        // We bend relative to the NOTE ON note.
        // MPE Pitch Bend = (TargetPitch - AnchorNotePitch)
        // 1. Calculate Target Exact MIDI
        const freq = baseFreq * ratio;
        const exactMidi = 69 + 12 * Math.log2(freq / 440);

        // 2. Diff from the triggered note
        const diffSemitones = exactMidi - data.note;

        // 3. Map to Bend
        const normalizedBend = diffSemitones / bendRange;
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;
        this.output.send([0xE0 | data.channel, lsb, msb]);
    }

    private allocateChannel(id: string): number {
        // Simple Round Robin already handled in noteOn wrapper
        return 0;
    }
}

