// --- DSP WORKLET CODE ---
const WORKLET_CODE = `
// --- DSP UTILS ---
const TWO_PI = 2 * Math.PI;

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    // 0 <= t < 1
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  // cutoff in Hz, res (Q) 0..inf
  process(input, cutoff, res, sampleRate) {
    // Pre-warp cutoff for stability
    let f = 2.0 * Math.sin(Math.PI * cutoff / sampleRate);
    // Clamp f to prevent instability at high frequencies
    if (f > 0.9) f = 0.9;

    // Damping factor
    const q = 1.0 / (res + 0.001); 

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    return this.low; // Returning Lowpass by default for this synth
  }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; // idle, attack, decay, sustain, release
    this.value = 0.0;
    this.velocity = 0.0;
    this.releaseLevel = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
        this.releaseLevel = this.value;
    }
  }

  process(config, dt) {
    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        // Linear Attack
        const attRate = 1.0 / (config.attack + 0.001);
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        // Exponential approach to Sustain
        const decRate = 1.0 / (config.decay + 0.001);
        // Lerp towards sustain
        this.value += (config.sustain - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = config.sustain;
        return this.value * this.velocity;

      case 'release':
        // Exponential release
        const relRate = 1.0 / (config.release + 0.001);
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = Math.random(); // Randomize phase to avoid stacking peaks
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  process(freq, type, dt) {
    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        sample = Math.sin(TWO_PI * this.phase);
        break;

      case 'triangle':
        // Naive triangle
        let t = -1.0 + (2.0 * this.phase);
        sample = 2.0 * (Math.abs(t) - 0.5);
        break;

      case 'sawtooth':
        // PolyBLEP Saw
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;

      case 'square':
        // PolyBLEP Square
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
    }

    return sample;
  }
}

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; // For LRU stealing
    this.releaseTime = 0; 

    // 3 Oscillators
    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhase = 0.0;
  }

  trigger(id, freq) {
    this.id = id;
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; // AudioWorklet Global
    this.envs.forEach(env => env.trigger());
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  // Returns max envelope value to determine "quietness"
  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  process(preset) {
    if (!this.active) return 0.0;

    // Smooth Glide (0.002 = ~25ms)
    if (Math.abs(this.targetFreq - this.baseFreq) > 0.001) {
      this.baseFreq += (this.targetFreq - this.baseFreq) * 0.002; 
    } else {
      this.baseFreq = this.targetFreq;
    }

    let allIdle = true;
    this.envs.forEach((env, i) => {
        const config = preset['osc' + (i+1)];
        if (config && config.enabled) {
            if (env.stage !== 'idle') allIdle = false;
        }
    });

    if (allIdle) {
      this.active = false;
      return 0.0;
    }

    let voiceMix = 0.0;
    const dt = 1.0 / this.sampleRate;

    for (let i = 0; i < 3; i++) {
        const config = preset['osc' + (i+1)];
        if (!config || !config.enabled) continue;

        const envVal = this.envs[i].process(config, dt);
        if (envVal < 0.0001) continue;

        // LFO
        let lfoVal = 0.0;
        if (config.lfoTarget !== 'none') {
            this.lfoPhase += config.lfoRate * dt;
            if (this.lfoPhase >= 1.0) this.lfoPhase -= 1.0;
            lfoVal = Math.sin(TWO_PI * this.lfoPhase);
        }

        let modPitch = 0, modFilter = 0, modAmp = 1.0;
        if (config.lfoTarget === 'pitch') modPitch = lfoVal * config.lfoDepth;
        if (config.lfoTarget === 'filter') modFilter = lfoVal * config.lfoDepth * 20;
        if (config.lfoTarget === 'tremolo') modAmp = 1.0 - (lfoVal * (config.lfoDepth / 100) * 0.5);

        const cents = config.coarseDetune + config.fineDetune;
        const detuneMult = Math.pow(2, cents / 1200.0);
        const oscFreq = (this.baseFreq + modPitch) * detuneMult;

        let signal = this.oscs[i].process(oscFreq, config.waveform, dt);

        let cutoff = config.filterCutoff + modFilter;
        if (cutoff < 20) cutoff = 20;
        if (cutoff > 20000) cutoff = 20000;

        signal = this.filters[i].process(signal, cutoff, config.filterResonance, this.sampleRate);
        voiceMix += signal * config.gain * envVal * modAmp;
    }

    return voiceMix;
  }
}

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.voices = [];
    // Max polyphony capacity (can be limited dynamically)
    for(let i=0; i<32; i++) {
        this.voices.push(new Voice(sampleRate));
    }

    this.preset = null;
    this.maxPolyphony = 10; 

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'preset') {
        this.preset = msg.data;
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => { v.active = false; v.envs.forEach(e => e.stage = 'idle'); });
      }
    };
  }

  triggerVoice(id, freq) {
    // 1. Check for retrigger
    const existing = this.voices.find(v => v.id === id && v.active);
    if (existing) {
        existing.trigger(id, freq);
        return;
    }

    // 2. Find free voice within limit
    let activeCount = 0;
    let freeVoice = null;

    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active) {
            activeCount++;
        } else if (!freeVoice) {
            freeVoice = this.voices[i];
        }
    }

    // 3. Allocation / Stealing Strategy
    let candidate = null;

    if (activeCount < this.maxPolyphony && freeVoice) {
        candidate = freeVoice;
    } else {
        // STEAL STRATEGY:
        // Priority 1: Released voices (Envelope decaying) -> Steal lowest volume
        // Priority 2: Oldest sustained voice

        let bestReleased = null;
        let lowestLevel = Infinity;

        let oldestSustained = null;
        let oldestTime = Infinity;

        // Only scan active voices
        for (let i = 0; i < this.voices.length; i++) {
             const v = this.voices[i];
             if (!v.active) continue;

             // Is Released? (All enabled envs in release stage)
             // Simple check: releaseTime > 0 implies we called release()
             if (v.releaseTime > v.startTime) {
                 const lvl = v.getLevel();
                 if (lvl < lowestLevel) {
                     lowestLevel = lvl;
                     bestReleased = v;
                 }
             } else {
                 // Sustained
                 if (v.startTime < oldestTime) {
                     oldestTime = v.startTime;
                     oldestSustained = v;
                 }
             }
        }

        if (bestReleased) candidate = bestReleased;
        else if (oldestSustained) candidate = oldestSustained;
        else candidate = this.voices[0]; // Fallback
    }

    if (candidate) {
        candidate.trigger(id, freq);
    }
  }

  releaseVoice(id) {
    // Find all voices with this ID (rare but possible if stolen rapidly)
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    const voice = this.voices.find(v => v.id === id && v.active);
    if (voice) {
        voice.targetFreq = freq;
    }
  }

  process(inputs, outputs, parameters) {
    if (!this.preset) return true;

    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];

    if (!channelL) return true;

    // Zero out
    channelL.fill(0);
    if (channelR) channelR.fill(0);

    const masterGain = this.preset.gain || 1.0;
    const len = channelL.length;

    // Mix active voices
    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (v.active) {
            for (let s = 0; s < len; s++) {
                channelL[s] += v.process(this.preset);
            }
        }
    }

    // Master Gain & Stereo
    for (let s = 0; s < len; s++) {
        channelL[s] *= masterGain;
        if (channelR) channelR[s] = channelL[s];
    }

    return true;
  }
}

registerProcessor('synth-processor', PrismaProcessor);
