            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

const lightenColor = (color: string, amount: number) => {
    if (color.startsWith('#') && color.length === 7) {
        const r = parseInt(color.slice(1, 3), 16);
        const g = parseInt(color.slice(3, 5), 16);
        const b = parseInt(color.slice(5, 7), 16);

        const nr = Math.round(r + (255 - r) * amount);
        const ng = Math.round(g + (255 - g) * amount);
        const nb = Math.round(b + (255 - b) * amount);

        return `#${((1 << 24) + (nr << 16) + (ng << 8) + nb).toString(16).slice(1)}`;
    }
    return color;
};

const PITCH_SCALE = 200;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (to avoid stale closures)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  // Memoize dependency string to prevent object-identity churn
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          origins: depthOrigins
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  useEffect(() => {
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; 

    hiddenLimits.forEach(limit => {
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [generationDeps, settings.buttonSpacingScale, settings.canvasSize]);

  // --- Static Canvas Rendering (Caching) ---
  // Visual Dependencies that require a redraw of the static lattice
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: settings.canvasSize
  }), [
      settings.buttonSizeScale,
      settings.buttonSpacingScale,
      settings.colors,
      settings.limitVisuals,
      settings.buttonShape,
      settings.nodeTextSizeScale,
      settings.showFractionBar,
      settings.canvasSize
  ]);

  // Track the last drawn state hash to prevent spurious redraws
  const lastDrawnHash = useRef<string>("");

  useEffect(() => {
      // Hash includes data length to catch graph changes + visual settings
      const currentHash = `${data.nodes.length}-${data.lines.length}-${visualDeps}`;

      if (lastDrawnHash.current === currentHash && staticCanvasRef.current) {
          return; // Skip redraw if nothing material changed
      }
      lastDrawnHash.current = currentHash;

      if (!staticCanvasRef.current) {
          staticCanvasRef.current = document.createElement('canvas');
      }

      const sCanvas = staticCanvasRef.current;
      const sCtx = sCanvas.getContext('2d', { alpha: true });
      if (!sCtx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = settings.canvasSize;

      // Only resize if dimensions actually differ to avoid clearing canvas context unexpectedly
      if (sCanvas.width !== size * dpr || sCanvas.height !== size * dpr) {
          sCanvas.width = size * dpr;
          sCanvas.height = size * dpr;
      } else {
          // If size matches, we still need to clear for the redraw
          sCtx.setTransform(1, 0, 0, 1, 0, 0);
          sCtx.clearRect(0, 0, sCanvas.width, sCanvas.height);
      }

      sCtx.setTransform(1, 0, 0, 1, 0, 0);
      sCtx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      // 1. Draw Lines
      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(
              line.x1 * spacing + centerOffset, 
              line.y1 * spacing + centerOffset, 
              line.x2 * spacing + centerOffset, 
              line.y2 * spacing + centerOffset
          );
      }

      sCtx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          sCtx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              sCtx.moveTo(coords[i], coords[i+1]);
              sCtx.lineTo(coords[i+2], coords[i+3]);
          }
          sCtx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          sCtx.strokeStyle = color;
          sCtx.globalAlpha = 0.15 * visualSettings.opacity; 

          if (limit === 1) sCtx.setLineDash([5, 5]);
          else sCtx.setLineDash([]);
          sCtx.stroke();
      }
      sCtx.setLineDash([]); 

      // 2. Draw Nodes
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          sCtx.globalAlpha = 0.95 * limitOpacity;
          sCtx.beginPath();
          if (isDiamond) {
              sCtx.moveTo(x, y - radius);
              sCtx.lineTo(x + radius, y);
              sCtx.lineTo(x, y + radius);
              sCtx.lineTo(x - radius, y);
          } else {
              sCtx.arc(x, y, radius, 0, Math.PI * 2);
          }
          sCtx.closePath();

          const grad = sCtx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          sCtx.fillStyle = grad;
          sCtx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              sCtx.fillStyle = 'white';
              sCtx.textAlign = 'center';
              sCtx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              sCtx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              sCtx.fillText(node.n.toString(), x, y - (radius * spacingY));

              if (settings.showFractionBar) {
                  sCtx.beginPath();
                  sCtx.moveTo(x - (radius * 0.4), y);
                  sCtx.lineTo(x + (radius * 0.4), y);
                  sCtx.lineWidth = 1;
                  sCtx.strokeStyle = `rgba(255,255,255,${0.5 * limitOpacity})`;
                  sCtx.stroke();
              }
              sCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }

  }, [data, visualDeps]); // Dependencies are now highly stable


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !canvasRef.current) return;
      e.preventDefault();
      const rect = canvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      let hitNode: LatticeNode | null = null;

      for (const node of data.nodes) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
          const r = baseRadius * vis.size;

          if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;
          const dx = x - nx;
          const dy = y - ny;

          if (dx*dx + dy*dy < r*r) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);

        const newEffective = new Map(effectiveLatchedRef.current);
        if (settings.isLatchModeEnabled) {
             if (newEffective.has(hitNode.id)) newEffective.delete(hitNode.id);
             else newEffective.set(hitNode.id, hitNode.id);
        } else {
             if (!newEffective.has(hitNode.id)) newEffective.set(hitNode.id, hitNode.id);
        }
        effectiveLatchedRef.current = newEffective;

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) {
             onLimitInteraction(hitNode.maxPrime);
        }

        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
         if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
    }

    if (settings.isLatchModeEnabled && canvasRef.current) {
         const canvasRect = canvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const spacing = settings.buttonSpacingScale;
         const centerOffset = settings.canvasSize / 2;
         const baseRadius = (60 * settings.buttonSizeScale) / 2;

         for (const node of data.nodes) {
             if (node.id === cursor.originNodeId) continue;

             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;

             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const r = baseRadius * vis.size;

             if (cx < nx - r || cx > nx + r || cy < ny - r || cy > ny + r) continue;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < r*r) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);

                         const eff = new Map(effectiveLatchedRef.current);
                         eff.set(node.id, cursor.originNodeId);
                         effectiveLatchedRef.current = eff;

                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);

        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        cursorPositionsRef.current.delete(e.pointerId);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
             const eff = new Map(effectiveLatchedRef.current);
             eff.delete(cursor.originNodeId);
             effectiveLatchedRef.current = eff;
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const staticCanvas = staticCanvasRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        ctx.clearRect(viewX, viewY, viewW, viewH);

        // 1. BLIT STATIC CACHE (The Base Lattice)
        if (staticCanvas && staticCanvas.width > 0) {
            ctx.save();
            ctx.setTransform(1, 0, 0, 1, 0, 0);
            ctx.drawImage(staticCanvas, 0, 0);
            ctx.restore();
        }

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        // 2. DYNAMIC HIGHLIGHTS (Active Nodes & Lines)
        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        const activeLines: LatticeLine[] = [];
        for (const line of currentData.lines) {
            if (currentLatched.has(line.sourceId) && currentLatched.has(line.targetId)) {
                activeLines.push(line);
            }
        }

        // Draw Active Line Glows
        ctx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 5;

            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                const startStop = Math.max(0, p - 0.2);
                const endStop = Math.min(1, p + 0.2);
                const pulseColor = lightenColor(limitColor, 0.33);

                grad.addColorStop(0, limitColor);
                if (startStop > 0) grad.addColorStop(startStop, limitColor);
                grad.addColorStop(p, pulseColor);
                if (endStop < 1) grad.addColorStop(endStop, limitColor);
                grad.addColorStop(1, limitColor);

                ctx.strokeStyle = grad;
                ctx.shadowColor = limitColor;
                ctx.shadowBlur = 15 * currentSettings.voiceLeadingGlowAmount;
            } else {
                ctx.strokeStyle = limitColor;
                ctx.shadowBlur = 0;
            }

            ctx.stroke();
            ctx.shadowBlur = 0;
            ctx.shadowColor = 'transparent';
        }

        // Draw Active Node Highlights (Zoomed state)
        for (const node of currentData.nodes) {
             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const isLatched = currentLatched.has(node.id);
             let isHovered = false;
             if (currentCursors.size > 0) {
                 for (const c of currentCursors.values()) {
                    if (c.originNodeId === node.id) { isHovered = true; break; }
                 }
             }

             if (isLatched || isHovered) {
                const cTop = colorCache[node.limitTop] || '#666';
                const cBottom = colorCache[node.limitBottom] || '#666';

                const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const zoomScale = currentSettings.latchedZoomScale;
                const radius = baseRadius * limitScale * zoomScale;

                ctx.globalAlpha = 1.0; 
                ctx.beginPath();
                if (isDiamond) {
                    ctx.moveTo(x, y - radius);
                    ctx.lineTo(x + radius, y);
                    ctx.lineTo(x, y + radius);
                    ctx.lineTo(x - radius, y);
                } else {
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                }
                ctx.closePath();

                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();

                if (currentSettings.isColoredIlluminationEnabled) {
                     const rainbowPeriod = PITCH_SCALE * spacing;
                     const phase = (y % rainbowPeriod) / rainbowPeriod;
                     const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                     const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                     ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                     ctx.lineWidth = 4;
                     ctx.stroke();
                } else {
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 3;
                     ctx.stroke();
                }

                const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
                if (combinedScale > 0.4) {
                    ctx.fillStyle = 'white';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                    ctx.font = `bold ${fontSize}px sans-serif`; 
                    const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                    ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                    if (currentSettings.showFractionBar) {
                        ctx.beginPath();
                        ctx.moveTo(x - (radius * 0.4), y);
                        ctx.lineTo(x + (radius * 0.4), y);
                        ctx.lineWidth = 1;
                        ctx.strokeStyle = 'white';
                        ctx.stroke();
                    }
                    ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
                }
             }
        }

        // Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const pos = cursorPositionsRef.current.get(c.pointerId);
                 if (!pos) return;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={canvasRef}
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

const lightenColor = (color: string, amount: number) => {
    if (color.startsWith('#') && color.length === 7) {
        const r = parseInt(color.slice(1, 3), 16);
        const g = parseInt(color.slice(3, 5), 16);
        const b = parseInt(color.slice(5, 7), 16);

        const nr = Math.round(r + (255 - r) * amount);
        const ng = Math.round(g + (255 - g) * amount);
        const nb = Math.round(b + (255 - b) * amount);

        return `#${((1 << 24) + (nr << 16) + (ng << 8) + nb).toString(16).slice(1)}`;
    }
    return color;
};

const PITCH_SCALE = 200;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); // Background (Nodes/Lines)
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); // Foreground (Interaction/Glows)

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (to avoid stale closures)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          origins: depthOrigins
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  useEffect(() => {
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; 

    hiddenLimits.forEach(limit => {
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [generationDeps, settings.buttonSpacingScale, settings.canvasSize]);

  // --- STATIC CANVAS RENDERER ---
  // Only runs when data or visuals change. Absolutely positioned behind interaction layer.
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: settings.canvasSize
  }), [
      settings.buttonSizeScale,
      settings.buttonSpacingScale,
      settings.colors,
      settings.limitVisuals,
      settings.buttonShape,
      settings.nodeTextSizeScale,
      settings.showFractionBar,
      settings.canvasSize
  ]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = settings.canvasSize;

      // Resize
      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      // Clear and Reset
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      // 1. Draw Lines
      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(
              line.x1 * spacing + centerOffset, 
              line.y1 * spacing + centerOffset, 
              line.x2 * spacing + centerOffset, 
              line.y2 * spacing + centerOffset
          );
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          // Lines are always a bit faint to let nodes pop
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      // 2. Draw Nodes (Idle State)
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          // Full visibility for static nodes to prevent "dimming" look
          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              const nStr = node.n.toString();
              const dStr = node.d.toString();

              ctx.fillText(nStr, x, y - (radius * spacingY));

              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(dStr, x, y + (radius * spacingY));
          }
      }

  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      let hitNode: LatticeNode | null = null;

      for (const node of data.nodes) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
          const r = baseRadius * vis.size;

          if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;
          const dx = x - nx;
          const dy = y - ny;

          if (dx*dx + dy*dy < r*r) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);

        const newEffective = new Map(effectiveLatchedRef.current);
        if (settings.isLatchModeEnabled) {
             if (newEffective.has(hitNode.id)) newEffective.delete(hitNode.id);
             else newEffective.set(hitNode.id, hitNode.id);
        } else {
             if (!newEffective.has(hitNode.id)) newEffective.set(hitNode.id, hitNode.id);
        }
        effectiveLatchedRef.current = newEffective;

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) {
             onLimitInteraction(hitNode.maxPrime);
        }

        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
         if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
    }

    if (settings.isLatchModeEnabled && dynamicCanvasRef.current) {
         const canvasRect = dynamicCanvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const spacing = settings.buttonSpacingScale;
         const centerOffset = settings.canvasSize / 2;
         const baseRadius = (60 * settings.buttonSizeScale) / 2;

         for (const node of data.nodes) {
             if (node.id === cursor.originNodeId) continue;

             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;

             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const r = baseRadius * vis.size;

             if (cx < nx - r || cx > nx + r || cy < ny - r || cy > ny + r) continue;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < r*r) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);

                         const eff = new Map(effectiveLatchedRef.current);
                         eff.set(node.id, cursor.originNodeId);
                         effectiveLatchedRef.current = eff;

                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);

        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        cursorPositionsRef.current.delete(e.pointerId);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
             const eff = new Map(effectiveLatchedRef.current);
             eff.delete(cursor.originNodeId);
             effectiveLatchedRef.current = eff;
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        // Only clear dynamic layer
        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        // 2. DYNAMIC HIGHLIGHTS (Active Nodes & Lines)
        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        const activeLines: LatticeLine[] = [];
        for (const line of currentData.lines) {
            if (currentLatched.has(line.sourceId) && currentLatched.has(line.targetId)) {
                activeLines.push(line);
            }
        }

        // Draw Active Line Glows
        ctx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 5;

            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                const startStop = Math.max(0, p - 0.2);
                const endStop = Math.min(1, p + 0.2);
                const pulseColor = lightenColor(limitColor, 0.33);

                grad.addColorStop(0, limitColor);
                if (startStop > 0) grad.addColorStop(startStop, limitColor);
                grad.addColorStop(p, pulseColor);
                if (endStop < 1) grad.addColorStop(endStop, limitColor);
                grad.addColorStop(1, limitColor);

                ctx.strokeStyle = grad;
                ctx.shadowColor = limitColor;
                ctx.shadowBlur = 15 * currentSettings.voiceLeadingGlowAmount;
            } else {
                ctx.strokeStyle = limitColor;
                ctx.shadowBlur = 0;
            }

            ctx.stroke();
            ctx.shadowBlur = 0;
            ctx.shadowColor = 'transparent';
        }

        // Draw Active Node Highlights (Zoomed state)
        for (const node of currentData.nodes) {
             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const isLatched = currentLatched.has(node.id);
             let isHovered = false;
             if (currentCursors.size > 0) {
                 for (const c of currentCursors.values()) {
                    if (c.originNodeId === node.id) { isHovered = true; break; }
                 }
             }

             if (isLatched || isHovered) {
                const cTop = colorCache[node.limitTop] || '#666';
                const cBottom = colorCache[node.limitBottom] || '#666';

                const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const zoomScale = currentSettings.latchedZoomScale;
                const radius = baseRadius * limitScale * zoomScale;

                ctx.globalAlpha = 1.0; 
                ctx.beginPath();
                if (isDiamond) {
                    ctx.moveTo(x, y - radius);
                    ctx.lineTo(x + radius, y);
                    ctx.lineTo(x, y + radius);
                    ctx.lineTo(x - radius, y);
                } else {
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                }
                ctx.closePath();

                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();

                if (currentSettings.isColoredIlluminationEnabled) {
                     const rainbowPeriod = PITCH_SCALE * spacing;
                     const phase = (y % rainbowPeriod) / rainbowPeriod;
                     const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                     const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                     ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                     ctx.lineWidth = 4;
                     ctx.stroke();
                } else {
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 3;
                     ctx.stroke();
                }

                const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
                if (combinedScale > 0.4) {
                    ctx.fillStyle = 'white';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                    ctx.font = `bold ${fontSize}px sans-serif`; 
                    const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                    ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                    if (currentSettings.showFractionBar) {
                        ctx.beginPath();
                        ctx.moveTo(x - (radius * 0.4), y);
                        ctx.lineTo(x + (radius * 0.4), y);
                        ctx.lineWidth = 1;
                        ctx.strokeStyle = 'white';
                        ctx.stroke();
                    }
                    ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
                }
             }
        }

        // Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const pos = cursorPositionsRef.current.get(c.pointerId);
                 if (!pos) return;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 1: Static Background */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           {/* Layer 2: Dynamic Interaction */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

const PITCH_SCALE = 200;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); // Background (Nodes/Lines)
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); // Foreground (Interaction/Glows)

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Refs for Render Loop (to avoid stale closures)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        return data.nodes.filter(n => effectiveLatchedNodes.has(n.id));
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          origins: depthOrigins
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  useEffect(() => {
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; 

    hiddenLimits.forEach(limit => {
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [generationDeps, settings.buttonSpacingScale, settings.canvasSize]);

  // --- STATIC CANVAS RENDERER ---
  // Only runs when data or visuals change. Absolutely positioned behind interaction layer.
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: settings.canvasSize
  }), [
      settings.buttonSizeScale,
      settings.buttonSpacingScale,
      settings.colors,
      settings.limitVisuals,
      settings.buttonShape,
      settings.nodeTextSizeScale,
      settings.showFractionBar,
      settings.canvasSize
  ]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = settings.canvasSize;

      // Resize
      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      // Clear and Reset
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      // 1. Draw Lines
      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(
              line.x1 * spacing + centerOffset, 
              line.y1 * spacing + centerOffset, 
              line.x2 * spacing + centerOffset, 
              line.y2 * spacing + centerOffset
          );
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          // Lines are always a bit faint to let nodes pop
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      // 2. Draw Nodes (Idle State)
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          // Full visibility for static nodes to prevent "dimming" look
          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              const nStr = node.n.toString();
              const dStr = node.d.toString();

              ctx.fillText(nStr, x, y - (radius * spacingY));

              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(dStr, x, y + (radius * spacingY));
          }
      }

  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = data.nodes.find(dn => dn.id === n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = data.nodes.find(n => n.id === nodeId);
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, data.nodes, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;
        const visibleNodeMap = new Map<string, LatticeNode>(data.nodes.map(n => [n.id, n]));

        next.forEach((originId, nodeId) => {
            const node = visibleNodeMap.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = visibleNodeMap.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, data.nodes]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      let hitNode: LatticeNode | null = null;

      for (const node of data.nodes) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
          const r = baseRadius * vis.size;

          if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;
          const dx = x - nx;
          const dy = y - ny;

          if (dx*dx + dy*dy < r*r) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);

        const newEffective = new Map(effectiveLatchedRef.current);
        if (settings.isLatchModeEnabled) {
             if (newEffective.has(hitNode.id)) newEffective.delete(hitNode.id);
             else newEffective.set(hitNode.id, hitNode.id);
        } else {
             if (!newEffective.has(hitNode.id)) newEffective.set(hitNode.id, hitNode.id);
        }
        effectiveLatchedRef.current = newEffective;

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) {
             onLimitInteraction(hitNode.maxPrime);
        }

        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
         if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
    }

    if (settings.isLatchModeEnabled && dynamicCanvasRef.current) {
         const canvasRect = dynamicCanvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const spacing = settings.buttonSpacingScale;
         const centerOffset = settings.canvasSize / 2;
         const baseRadius = (60 * settings.buttonSizeScale) / 2;

         for (const node of data.nodes) {
             if (node.id === cursor.originNodeId) continue;

             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;

             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const r = baseRadius * vis.size;

             if (cx < nx - r || cx > nx + r || cy < ny - r || cy > ny + r) continue;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < r*r) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     const originNode = data.nodes.find(n => n.id === cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);

                         const eff = new Map(effectiveLatchedRef.current);
                         eff.set(node.id, cursor.originNodeId);
                         effectiveLatchedRef.current = eff;

                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);

        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        cursorPositionsRef.current.delete(e.pointerId);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
             const eff = new Map(effectiveLatchedRef.current);
             eff.delete(cursor.originNodeId);
             effectiveLatchedRef.current = eff;
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentData = dataRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        // Only clear dynamic layer
        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        // 2. DYNAMIC HIGHLIGHTS (Active Nodes & Lines)
        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        const activeLines: LatticeLine[] = [];
        for (const line of currentData.lines) {
            if (currentLatched.has(line.sourceId) && currentLatched.has(line.targetId)) {
                activeLines.push(line);
            }
        }

        // Draw Active Lines (Base + Animated Overlay)
        ctx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            // Pass 1: Solid Base Line (Prevents Flickering)
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            ctx.stroke();

            // Pass 2: Animated Pulse Overlay
            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                // Additive Pulse Gradient (Transparent -> White -> Transparent)
                grad.addColorStop(0, 'rgba(255,255,255,0)');

                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);

                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.8)');
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');

                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.strokeStyle = grad;
                ctx.lineWidth = 6;
                ctx.shadowColor = limitColor;
                ctx.shadowBlur = 15 * currentSettings.voiceLeadingGlowAmount;
                ctx.globalCompositeOperation = 'screen'; // Additive blend
                ctx.stroke();

                // Reset State
                ctx.globalCompositeOperation = 'source-over';
                ctx.shadowBlur = 0;
                ctx.shadowColor = 'transparent';
            }
        }

        // Draw Active Node Highlights (Zoomed state)
        for (const node of currentData.nodes) {
             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const isLatched = currentLatched.has(node.id);
             let isHovered = false;
             if (currentCursors.size > 0) {
                 for (const c of currentCursors.values()) {
                    if (c.originNodeId === node.id) { isHovered = true; break; }
                 }
             }

             if (isLatched || isHovered) {
                const cTop = colorCache[node.limitTop] || '#666';
                const cBottom = colorCache[node.limitBottom] || '#666';

                const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const zoomScale = currentSettings.latchedZoomScale;
                const radius = baseRadius * limitScale * zoomScale;

                ctx.globalAlpha = 1.0; 
                ctx.beginPath();
                if (isDiamond) {
                    ctx.moveTo(x, y - radius);
                    ctx.lineTo(x + radius, y);
                    ctx.lineTo(x, y + radius);
                    ctx.lineTo(x - radius, y);
                } else {
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                }
                ctx.closePath();

                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();

                if (currentSettings.isColoredIlluminationEnabled) {
                     const rainbowPeriod = PITCH_SCALE * spacing;
                     const phase = (y % rainbowPeriod) / rainbowPeriod;
                     const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                     const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                     ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                     ctx.lineWidth = 4;
                     ctx.stroke();
                } else {
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 3;
                     ctx.stroke();
                }

                const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
                if (combinedScale > 0.4) {
                    ctx.fillStyle = 'white';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                    ctx.font = `bold ${fontSize}px sans-serif`; 
                    const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                    ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                    if (currentSettings.showFractionBar) {
                        ctx.beginPath();
                        ctx.moveTo(x - (radius * 0.4), y);
                        ctx.lineTo(x + (radius * 0.4), y);
                        ctx.lineWidth = 1;
                        ctx.strokeStyle = 'white';
                        ctx.stroke();
                    }
                    ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
                }
             }
        }

        // Cursors
        currentCursors.forEach(c => {
            const node = currentData.nodes.find(n => n.id === c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const pos = cursorPositionsRef.current.get(c.pointerId);
                 if (!pos) return;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 1: Static Background */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           {/* Layer 2: Dynamic Interaction */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

const PITCH_SCALE = 200;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); // Background (Nodes/Lines)
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); // Foreground (Interaction/Glows)

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Optimization: Memoized Lookups
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Optimization: Pre-calculate active lines to avoid O(L) scan in render loop
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    if (latched.size > 0) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) {
                active.push(line);
            }
        }
    }
    return active;
  }, [data.lines, effectiveLatchedNodes]);

  // Refs for Render Loop (to avoid stale closures)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        // Use map for O(1) lookup
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          origins: depthOrigins
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  useEffect(() => {
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; 

    hiddenLimits.forEach(limit => {
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [generationDeps, settings.buttonSpacingScale, settings.canvasSize]);

  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: settings.canvasSize
  }), [
      settings.buttonSizeScale,
      settings.buttonSpacingScale,
      settings.colors,
      settings.limitVisuals,
      settings.buttonShape,
      settings.nodeTextSizeScale,
      settings.showFractionBar,
      settings.canvasSize
  ]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = settings.canvasSize;

      // Resize
      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      // Clear and Reset
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      // 1. Draw Lines
      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(
              line.x1 * spacing + centerOffset, 
              line.y1 * spacing + centerOffset, 
              line.x2 * spacing + centerOffset, 
              line.y2 * spacing + centerOffset
          );
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          // Lines are always a bit faint to let nodes pop
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      // 2. Draw Nodes (Idle State)
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          // Full visibility for static nodes to prevent "dimming" look
          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              const nStr = node.n.toString();
              const dStr = node.d.toString();

              ctx.fillText(nStr, x, y - (radius * spacingY));

              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(dStr, x, y + (radius * spacingY));
          }
      }

  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);
    const nodes = nodeMap;

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); // O(1) Lookup
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;

        // Use memoized map for Lookups
        const nodes = nodeMap;

        next.forEach((originId, nodeId) => {
            const node = nodes.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = nodes.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, nodeMap]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      let hitNode: LatticeNode | null = null;

      // Hit testing still iterates all nodes (spatial index would be better but this is likely acceptable for <2000 nodes)
      for (const node of data.nodes) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
          const r = baseRadius * vis.size;

          if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;
          const dx = x - nx;
          const dy = y - ny;

          if (dx*dx + dy*dy < r*r) {
              hitNode = node;
              break; 
          }
      }

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);

        const newEffective = new Map(effectiveLatchedRef.current);
        if (settings.isLatchModeEnabled) {
             if (newEffective.has(hitNode.id)) newEffective.delete(hitNode.id);
             else newEffective.set(hitNode.id, hitNode.id);
        } else {
             if (!newEffective.has(hitNode.id)) newEffective.set(hitNode.id, hitNode.id);
        }
        effectiveLatchedRef.current = newEffective;

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) {
             onLimitInteraction(hitNode.maxPrime);
        }

        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
         if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
    }

    if (settings.isLatchModeEnabled && dynamicCanvasRef.current) {
         const canvasRect = dynamicCanvasRef.current.getBoundingClientRect();
         const cx = e.clientX - canvasRect.left;
         const cy = e.clientY - canvasRect.top;

         const spacing = settings.buttonSpacingScale;
         const centerOffset = settings.canvasSize / 2;
         const baseRadius = (60 * settings.buttonSizeScale) / 2;

         for (const node of data.nodes) {
             if (node.id === cursor.originNodeId) continue;

             const nx = node.x * spacing + centerOffset;
             const ny = node.y * spacing + centerOffset;

             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const r = baseRadius * vis.size;

             if (cx < nx - r || cx > nx + r || cy < ny - r || cy > ny + r) continue;
             const dx = cx - nx;
             const dy = cy - ny;

             if (dx*dx + dy*dy < r*r) {
                 setManualLatchedNodes(prev => {
                     if (prev.has(node.id)) return prev;

                     // Optimization: Use Node Map
                     const originNode = nodeMapRef.current.get(cursor.originNodeId);
                     if (!originNode) return prev;

                     const allowedMaxIndex = settings.latchShellLimit - 2;
                     let isAllowed = true;

                     if (settings.latchShellLimit === 1) {
                         if (getHarmonicDistance(node.coords, originNode.coords) > 0) isAllowed = false;
                     } else {
                         for(let i=0; i<node.coords.length; i++) {
                             const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                             if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                         }
                     }

                     if (isAllowed) {
                         const next = new Map(prev);
                         next.set(node.id, cursor.originNodeId);

                         const eff = new Map(effectiveLatchedRef.current);
                         eff.set(node.id, cursor.originNodeId);
                         effectiveLatchedRef.current = eff;

                         setLastTouchedNode({ coords: node.coords, octave: node.octave });
                         return next;
                     }
                     return prev;
                 });
             }
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);

        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        cursorPositionsRef.current.delete(e.pointerId);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
             const eff = new Map(effectiveLatchedRef.current);
             eff.delete(cursor.originNodeId);
             effectiveLatchedRef.current = eff;
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        // Only clear dynamic layer
        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        // OPTIMIZATION: Use pre-calculated Active Lines
        ctx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            // Pass 1: Solid Base Line
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            ctx.stroke();

            // Pass 2: Animated Pulse Overlay
            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.8)');
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.strokeStyle = grad;
                ctx.lineWidth = 6;
                ctx.shadowColor = limitColor;
                ctx.shadowBlur = 15 * currentSettings.voiceLeadingGlowAmount;
                ctx.globalCompositeOperation = 'screen'; 
                ctx.stroke();

                ctx.globalCompositeOperation = 'source-over';
                ctx.shadowBlur = 0;
                ctx.shadowColor = 'transparent';
            }
        }

        // OPTIMIZATION: Iterate ONLY active nodes
        const activeNodeIds = new Set<string>();
        currentLatched.forEach((_, id) => activeNodeIds.add(id));
        currentCursors.forEach(c => activeNodeIds.add(c.originNodeId));

        for (const id of activeNodeIds) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;
             const radius = baseRadius * limitScale * zoomScale;

             ctx.globalAlpha = 1.0; 
             ctx.beginPath();
             if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
             } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
             }
             ctx.closePath();

             const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             ctx.fillStyle = grad;
             ctx.fill();

             if (currentSettings.isColoredIlluminationEnabled) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
             } else {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
             }

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = 'white';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // Cursors (Draw Lines connecting cursor to node)
        currentCursors.forEach(c => {
            const node = nodeMapRef.current.get(c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const pos = cursorPositionsRef.current.get(c.pointerId);
                 if (!pos) return;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 1: Static Background */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           {/* Layer 2: Dynamic Interaction */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, GenerationOrigin, ButtonShape } from '../types';
import { generateLattice, getHarmonicDistance } from '../services/LatticeService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string; 
}

// Spatial Grid Constants
const GRID_CELL_SIZE = 100; // Pixel size of spatial buckets

const PITCH_SCALE = 200;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); // Background (Nodes/Lines)
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); // Foreground (Interaction/Glows)

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });

  // Optimization: Memoized Lookups & Spatial Grid
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  // Spatial Index for O(1) Hit Testing
  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;

          // Determine grid cell
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;

          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);

          // Add to neighbors to handle edge overlaps (simple approach: add to 3x3 block if near edge, 
          // but for simplicity we'll just check neighbors in hit test)
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, settings.canvasSize]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());
  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Optimization: Pre-calculate active lines to avoid O(L) scan in render loop
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    if (latched.size > 0) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) {
                active.push(line);
            }
        }
    }
    return active;
  }, [data.lines, effectiveLatchedNodes]);

  // Refs for Render Loop (to avoid stale closures)
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const spatialGridRef = useRef(spatialGrid);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);

  // Generation State
  const [depthOrigins, setDepthOrigins] = useState<GenerationOrigin[]>([{coords: [0,0,0,0,0], octave: 0}]);
  const [lastTouchedNode, setLastTouchedNode] = useState<GenerationOrigin | null>(null);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => {
        if (settings.centerResetsDepth) {
            setDepthOrigins([{coords: [0,0,0,0,0], octave: 0}]);
            setLastTouchedNode(null);
        }
        centerScroll();
    },
    increaseDepth: () => {
        if (lastTouchedNode) {
            setDepthOrigins(prev => {
                const exists = prev.some(o => 
                    o.octave === lastTouchedNode.octave &&
                    o.coords.every((val, i) => val === lastTouchedNode.coords[i])
                );
                if (exists) return prev;
                return [...prev, { coords: [...lastTouchedNode.coords], octave: lastTouchedNode.octave }];
            });
        }
    },
    getLatchedNodes: () => {
        // Use map for O(1) lookup
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = settings.canvasSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    if (!hasCentered && scrollContainerRef.current) {
        centerScroll();
        setHasCentered(true);
    }
  }, [settings.canvasSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          origins: depthOrigins
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, depthOrigins]);

  useEffect(() => {
    const effectiveSettings = { ...settings, limitDepths: { ...settings.limitDepths } };
    const hiddenLimits = settings.hiddenLimits as number[]; 

    hiddenLimits.forEach(limit => {
        if (limit in effectiveSettings.limitDepths) {
            effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        }
    });

    const result = generateLattice(effectiveSettings, depthOrigins);

    const visibleNodeIds = new Set(result.nodes.map(n => n.id));

    const visibleLines = result.lines.filter(l => {
        if (hiddenLimits.includes(l.limit)) return false;
        if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
        return true;
    });

    setData({ nodes: result.nodes, lines: visibleLines });
  }, [generationDeps, settings.buttonSpacingScale, settings.canvasSize]);

  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: settings.canvasSize
  }), [
      settings.buttonSizeScale,
      settings.buttonSpacingScale,
      settings.colors,
      settings.limitVisuals,
      settings.buttonShape,
      settings.nodeTextSizeScale,
      settings.showFractionBar,
      settings.canvasSize
  ]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = settings.canvasSize;

      // Resize
      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      // Clear and Reset
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      // 1. Draw Lines
      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(
              line.x1 * spacing + centerOffset, 
              line.y1 * spacing + centerOffset, 
              line.x2 * spacing + centerOffset, 
              line.y2 * spacing + centerOffset
          );
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          // Lines are always a bit faint to let nodes pop
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      // 2. Draw Nodes (Idle State)
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          // Full visibility for static nodes to prevent "dimming" look
          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              const nStr = node.n.toString();
              const dStr = node.d.toString();

              ctx.fillText(nStr, x, y - (radius * spacingY));

              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(dStr, x, y + (radius * spacingY));
          }
      }

  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);
    const nodes = nodeMap;

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); // O(1) Lookup
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  // Reactive Delatching
  useEffect(() => {
    setManualLatchedNodes((prev: Map<string, string>) => {
        const next = new Map<string, string>(prev);
        let changed = false;

        // Use memoized map for Lookups
        const nodes = nodeMap;

        next.forEach((originId, nodeId) => {
            const node = nodes.get(nodeId);
            if (!node) { next.delete(nodeId); changed = true; return; }

            if (originId !== nodeId) {
                 const originNode = nodes.get(originId);
                 if (!originNode) { next.delete(nodeId); changed = true; return; }

                 const allowedMaxIndex = settings.latchShellLimit - 2; 
                 let isAllowed = true;
                 if (settings.latchShellLimit === 1) {
                     const dist = getHarmonicDistance(node.coords, originNode.coords);
                     if (dist > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<node.coords.length; i++) {
                        const diff = Math.abs(node.coords[i] - originNode.coords[i]);
                        if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }
                 if (!isAllowed) { next.delete(nodeId); changed = true; }
            }
        });
        return changed ? next : prev;
    });
  }, [settings.latchShellLimit, nodeMap]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper for Hit Testing using Spatial Grid
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = settings.canvasSize / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      // Check current cell and immediate neighbors (to handle nodes on edges)
      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * vis.size;

                  if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) {
                      return node;
                  }
              }
          }
      }
      return null;
  };

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      // O(1) Hit Test
      const hitNode = getHitNode(e.clientX, e.clientY);

      if (hitNode) {
        (e.target as HTMLElement).setPointerCapture(e.pointerId);

        const newEffective = new Map(effectiveLatchedRef.current);
        if (settings.isLatchModeEnabled) {
             if (newEffective.has(hitNode.id)) newEffective.delete(hitNode.id);
             else newEffective.set(hitNode.id, hitNode.id);
        } else {
             if (!newEffective.has(hitNode.id)) newEffective.set(hitNode.id, hitNode.id);
        }
        effectiveLatchedRef.current = newEffective;

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) {
             onLimitInteraction(hitNode.maxPrime);
        }

        setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode!.id
            });
            return next;
        });

        setManualLatchedNodes(prev => {
            const next = new Map(prev);
            if (settings.isLatchModeEnabled) {
                if (next.has(hitNode!.id)) next.delete(hitNode!.id);
                else next.set(hitNode!.id, hitNode!.id);
            } else {
                if (!next.has(hitNode!.id)) next.set(hitNode!.id, hitNode!.id);
            }
            return next;
        });

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    if (settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = settings.canvasSize / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
         const relY = canvasY - centerOffset;
         const effectivePitchScale = PITCH_SCALE * settings.buttonSpacingScale;
         const bentRatio = Math.pow(2, -relY / effectivePitchScale);

         audioEngine.glideVoice(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, 0.05);
         if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
    }

    if (settings.isLatchModeEnabled && dynamicCanvasRef.current) {
         // Optimized Hit Test for Drag Latching
         // We only care about nodes under the finger, not checking 2000 nodes for distance
         const hitNode = getHitNode(e.clientX, e.clientY);

         if (hitNode && hitNode.id !== cursor.originNodeId) {
             setManualLatchedNodes(prev => {
                 if (prev.has(hitNode.id)) return prev;

                 const originNode = nodeMapRef.current.get(cursor.originNodeId);
                 if (!originNode) return prev;

                 const allowedMaxIndex = settings.latchShellLimit - 2;
                 let isAllowed = true;

                 if (settings.latchShellLimit === 1) {
                     if (getHarmonicDistance(hitNode.coords, originNode.coords) > 0) isAllowed = false;
                 } else {
                     for(let i=0; i<hitNode.coords.length; i++) {
                         const diff = Math.abs(hitNode.coords[i] - originNode.coords[i]);
                         if (diff > 0 && i > allowedMaxIndex) { isAllowed = false; break; }
                     }
                 }

                 if (isAllowed) {
                     const next = new Map(prev);
                     next.set(hitNode.id, cursor.originNodeId);

                     const eff = new Map(effectiveLatchedRef.current);
                     eff.set(hitNode.id, cursor.originNodeId);
                     effectiveLatchedRef.current = eff;

                     setLastTouchedNode({ coords: hitNode.coords, octave: hitNode.octave });
                     return next;
                 }
                 return prev;
             });
         }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        audioEngine.stopVoice(`cursor-${e.pointerId}`);
        if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);

        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        cursorPositionsRef.current.delete(e.pointerId);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });

        if (!settings.isLatchModeEnabled) {
             setManualLatchedNodes(prev => {
                 const next = new Map(prev);
                 next.delete(cursor.originNodeId);
                 return next;
             });
             const eff = new Map(effectiveLatchedRef.current);
             eff.delete(cursor.originNodeId);
             effectiveLatchedRef.current = eff;
        }
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentCursors = activeCursorsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;

        const size = currentSettings.canvasSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        // Only clear dynamic layer
        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = currentSettings.canvasSize / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        // --- DRAW ACTIVE LINES ---
        // Optimization: Removed shadowBlur and Composite changes.
        // Used multi-pass stroking for glow effect instead.

        ctx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            // Base Line (Solid)
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            // Animated Pulse Overlay (Manual Glow)
            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                // Simple white pulse gradient
                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); // 70% opacity white
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.strokeStyle = grad;

                // Draw wide faint stroke (simulates blur)
                ctx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                ctx.globalAlpha = 0.3; // Low opacity for "glow" look
                ctx.stroke();

                // Draw core hot stroke
                ctx.lineWidth = 4;
                ctx.globalAlpha = 1.0;
                ctx.stroke();
            }
        }

        // --- DRAW ACTIVE NODES ---
        const activeNodeIds = new Set<string>();
        currentLatched.forEach((_, id) => activeNodeIds.add(id));
        currentCursors.forEach(c => activeNodeIds.add(c.originNodeId));

        for (const id of activeNodeIds) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;
             const radius = baseRadius * limitScale * zoomScale;

             ctx.globalAlpha = 1.0; 
             ctx.beginPath();
             if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
             } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
             }
             ctx.closePath();

             const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             ctx.fillStyle = grad;
             ctx.fill();

             if (currentSettings.isColoredIlluminationEnabled) {
                 const rainbowPeriod = PITCH_SCALE * spacing;
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
             } else {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
             }

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = 'white';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // Cursors (Draw Lines connecting cursor to node)
        currentCursors.forEach(c => {
            const node = nodeMapRef.current.get(c.originNodeId);
            if(node) {
                 const nx = node.x * spacing + centerOffset;
                 const ny = node.y * spacing + centerOffset;
                 const pos = cursorPositionsRef.current.get(c.pointerId);
                 if (!pos) return;

                 let cx = 0, cy = 0;
                 if (scrollContainerRef.current) {
                     const r = scrollContainerRef.current.getBoundingClientRect();
                     cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                     cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                 }

                 ctx.beginPath();
                 ctx.moveTo(nx, ny);
                 ctx.lineTo(cx, cy);
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 2;
                 ctx.globalAlpha = 0.5;
                 ctx.stroke();
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowBackgroundFixed = (() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        const rainbowPeriod = PITCH_SCALE * settings.buttonSpacingScale;
        for (let i = 0; i <= steps; i++) {
            const pct = i / steps;
            const px = pct * rainbowPeriod;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${px.toFixed(1)}px`);
        }
        return `repeating-linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  })();

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: settings.canvasSize, 
                height: settings.canvasSize,
                background: rainbowBackgroundFixed,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 1: Static Background */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           {/* Layer 2: Dynamic Interaction */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />
        </div>
    </div>
  );
});

export default TonalityDiamond;

import { SynthPreset, WaveformType, OscillatorConfig, AppSettings } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET } from '../constants';

// --- DSP WORKLET CODE ---
const WORKLET_CODE = `
// --- DSP UTILS ---
const TWO_PI = 2 * Math.PI;

// Safe Default Config
const DUMMY_OSC_CONFIG = {
    enabled: false,
    waveform: 'sine',
    coarseDetune: 0,
    fineDetune: 0,
    gain: 0,
    attack: 0.1,
    decay: 0.1,
    sustain: 0,
    release: 0.1,
    filterCutoff: 20000,
    filterResonance: 0,
    lfoRate: 1,
    lfoDepth: 0,
    lfoTarget: 'none'
};

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate) {
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.42));
    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);

    // Stability Fix: Map resonance input (0..N) to Q factor safely.
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    return this.low; 
  }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  reset() {
      this.phase = 0.0;
  }

  process(freq, type, dt) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        sample = Math.sin(TWO_PI * this.phase);
        break;
      case 'triangle':
        let t = -1.0 + (2.0 * this.phase);
        sample = 2.0 * (Math.abs(t) - 0.5);
        break;
      case 'sawtooth':
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;
      case 'square':
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
    }

    return sample;
  }
}

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0; 

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  trigger(id, freq) {
    this.id = id;
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0; 

    // CRITICAL: Reset phase on trigger to prevent transient clicks
    this.oscs.forEach(osc => osc.reset());

    // CRITICAL: Reset envelopes to 0 before triggering to prevent clicks if stealing a loud voice
    this.envs.forEach(env => {
        env.reset();
        env.trigger();
    });

    this.filters.forEach(f => f.reset());
    this.lfoPhases.fill(0.0);
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
  }

  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  process(oscConfigs, matrix, dt) {
    if (!this.active) return 0.0;

    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
      this.baseFreq += diff * 0.005; 
    } else {
      this.baseFreq = this.targetFreq;
    }

    let anyEnvActive = false;

    // 1. Compute Sources
    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        const envVal = this.envs[i].process(config, dt);
        this.envVals[i] = envVal;
        if (this.envs[i].stage !== 'idle') anyEnvActive = true;

        const rate = (config.lfoRate !== undefined) ? config.lfoRate : 0.0;
        this.lfoPhases[i] += rate * dt;
        if (this.lfoPhases[i] >= 1.0) this.lfoPhases[i] -= 1.0;
        this.lfoVals[i] = Math.sin(TWO_PI * this.lfoPhases[i]);
    }

    if (!anyEnvActive) {
      this.active = false;
      return 0.0;
    }

    let modP1=0, modP2=0, modP3=0;
    let modC1=0, modC2=0, modC3=0;
    let modG1=0, modG2=0, modG3=0;
    let modR1=0, modR2=0, modR3=0;

    const mLen = matrix.length;
    for(let i=0; i<mLen; i++) {
        const row = matrix[i];
        if (!row.enabled) continue;

        let srcVal = 0;
        switch(row.source) {
            case 'lfo1': srcVal = this.lfoVals[0]; break;
            case 'lfo2': srcVal = this.lfoVals[1]; break;
            case 'lfo3': srcVal = this.lfoVals[2]; break;
            case 'env1': srcVal = this.envVals[0]; break;
            case 'env2': srcVal = this.envVals[1]; break;
            case 'env3': srcVal = this.envVals[2]; break;
        }

        const amt = srcVal * (Number.isFinite(row.amount) ? row.amount : 0);

        switch(row.target) {
            case 'osc1_pitch': modP1 += amt; break;
            case 'osc1_cutoff': modC1 += amt; break;
            case 'osc1_gain': modG1 += amt; break;
            case 'osc1_res': modR1 += amt; break;
            case 'osc2_pitch': modP2 += amt; break;
            case 'osc2_cutoff': modC2 += amt; break;
            case 'osc2_gain': modG2 += amt; break;
            case 'osc2_res': modR2 += amt; break;
            case 'osc3_pitch': modP3 += amt; break;
            case 'osc3_cutoff': modC3 += amt; break;
            case 'osc3_gain': modG3 += amt; break;
            case 'osc3_res': modR3 += amt; break;
        }
    }

    let voiceMix = 0.0;

    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        if (!config.enabled) continue;

        const envVal = this.envVals[i];
        if (envVal < 0.0001) continue;

        let lfoVal = this.lfoVals[i];
        const lfoDepth = config.lfoDepth || 0;
        let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;

        if (config.lfoTarget === 'pitch') hardPitch = lfoVal * lfoDepth;
        else if (config.lfoTarget === 'filter') hardFilter = lfoVal * lfoDepth * 20;
        else if (config.lfoTarget === 'tremolo') hardAmp = 1.0 - (lfoVal * (lfoDepth * 0.005));

        let modPitch=0, modCutoff=0, modGain=0, modRes=0;
        if (i===0) { modPitch=modP1; modCutoff=modC1; modGain=modG1; modRes=modR1; }
        else if (i===1) { modPitch=modP2; modCutoff=modC2; modGain=modG2; modRes=modR2; }
        else { modPitch=modP3; modCutoff=modC3; modGain=modG3; modRes=modR3; }

        const cents = config.coarseDetune + config.fineDetune + hardPitch + (modPitch * 1200);
        const detuneMult = Math.pow(2, cents / 1200.0);
        const oscFreq = this.baseFreq * detuneMult;

        let signal = this.oscs[i].process(oscFreq, config.waveform, dt);

        let cutoff = config.filterCutoff + hardFilter + (modCutoff * 5000);
        let res = config.filterResonance + (modRes * 10);
        if (res < 0) res = 0;

        signal = this.filters[i].process(signal, cutoff, res, this.sampleRate);

        const gainMod = Math.max(0, 1.0 + modGain); 
        const finalGain = config.gain * envVal * hardAmp * gainMod;

        voiceMix += signal * finalGain;
    }

    return voiceMix;
  }
}

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.voices = [];
    // Initialize ample voice pool to allow for release tails overlap
    for(let i=0; i<32; i++) {
        this.voices.push(new Voice(sampleRate));
    }

    this.preset = null;
    this.maxPolyphony = 10; 
    this.oscConfigs = [DUMMY_OSC_CONFIG, DUMMY_OSC_CONFIG, DUMMY_OSC_CONFIG];
    this.modMatrix = [];

    // DC Blocker State
    this.xm1 = 0;
    this.ym1 = 0;

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'preset') {
        this.updatePreset(msg.data);
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => v.hardStop());
      }
    };
  }

  updatePreset(data) {
      this.preset = data;
      this.oscConfigs = [
          { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) },
          { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) },
          { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) }
      ];
      this.modMatrix = (data.modMatrix || []).map(row => ({
          ...row,
          amount: (Number.isFinite(row.amount) ? row.amount : 0) / 100.0
      }));
  }

  triggerVoice(id, freq) {
    // 1. Retrigger existing if active
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].trigger(id, freq);
            return;
        }
    }

    // 2. Count "Musically Held" voices (Active AND Not Released)
    let heldCount = 0;
    let physicallyFree = null;
    let quietestHeld = null;
    let minHeldLevel = 1000.0;
    let quietestVoice = null; // For hard steal fallback
    let minLevel = 1000.0;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];

        if (!v.active) {
            if (!physicallyFree) physicallyFree = v;
            continue;
        }

        const level = v.getLevel();
        if (level < minLevel) {
            minLevel = level;
            quietestVoice = v;
        }

        // Check if held (releaseTime === 0 implies note is held)
        if (v.releaseTime === 0) {
            heldCount++;
            if (level < minHeldLevel) {
                minHeldLevel = level;
                quietestHeld = v;
            }
        }
    }

    // 3. Soft Steal Strategy
    // If we reached the musical polyphony limit, force the oldest/quietest HELD note into release phase.
    // This allows it to fade out naturally using one of the extra physical voices, rather than being cut off.
    if (heldCount >= this.maxPolyphony && quietestHeld) {
        quietestHeld.release();
    }

    // 4. Voice Allocation
    if (physicallyFree) {
        physicallyFree.trigger(id, freq);
    } else if (quietestVoice) {
        // Fallback: Hard Steal if all 32 physical voices are busy (very rare)
        quietestVoice.trigger(id, freq);
    }
  }

  releaseVoice(id) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
             this.voices[i].targetFreq = freq;
        }
    }
  }

  process(inputs, outputs, parameters) {
    if (!this.preset) return true;

    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];

    if (!channelL) return true;

    const len = channelL.length;
    const dt = 1.0 / sampleRate;

    for (let s = 0; s < len; s++) {
        let sampleMix = 0.0;

        for (let i = 0; i < this.voices.length; i++) {
            const v = this.voices[i];
            if (v.active) {
                const val = v.process(this.oscConfigs, this.modMatrix, dt);
                if (Number.isFinite(val)) {
                    sampleMix += val;
                } else {
                    v.hardStop();
                }
            }
        }

        // 1. Aggressive Gain Staging (Headroom)
        // With up to 3 oscillators per voice and polyphony, we must attenuate before clipper
        sampleMix *= 0.1; 

        // 2. Soft Clipper (Tanh)
        sampleMix = Math.tanh(sampleMix * 0.7);

        // 3. DC Blocker
        const x = sampleMix;
        const y = x - this.xm1 + 0.995 * this.ym1;
        this.xm1 = x;
        this.ym1 = y;

        channelL[s] = y;
    }

    const masterGain = this.preset.gain;
    if (channelR) {
        for (let s = 0; s < len; s++) {
            channelL[s] *= masterGain;
            channelR[s] = channelL[s];
        }
    } else {
        for (let s = 0; s < len; s++) {
            channelL[s] *= masterGain;
        }
    }

    return true;
  }
}

