// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  while (b !== 0) {
    let t = b;
    b = a % b;
    a = t;
  }
  return a;
};

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

// Helper to calculate the absolute ratio of a coordinate set starting from 1/1
const calculateRatioFromCoords = (coords: number[]): Fraction => {
    let ratio = new Fraction(1, 1);

    PRIMES.forEach((prime, idx) => {
        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
        const val = coords[idx];
        if (val === 0) return;

        for(let i=0; i < Math.abs(val); i++) {
             if (val > 0) ratio = ratio.mul(pRat).normalize();
             else {
                 const invRatio = new Fraction(pRat.d, pRat.n);
                 ratio = ratio.mul(invRatio).normalize();
             }
        }
    });
    return ratio;
};

// Helper to determine the "Prime Limit" of a coordinate set (highest prime used)
const getCoordLimit = (coords: number[]): number => {
    for (let i = 4; i >= 0; i--) {
        if (coords[i] !== 0) return PRIMES[i];
    }
    return 1;
};

export const generateLattice = (settings: AppSettings, generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const nodesMap: Map<string, LatticeNode> = new Map();

  // Density Tracker: count[prime_limit][shell_distance][octave_index]
  // We use a string key for the map: `${limit}-${shell}-${octave}`
  const densityCounts = new Map<string, number>();

  // Effective Canvas Size Logic (handled in UI primarily, but we use scope for boundaries here)
  // Horizontal scope determines X-Axis bounds relative to origin 
  // Vertical scope determines Y-Axis (Octave) bounds relative to origin
  const xLimit = settings.horizontalScope * 120; // 120px approx per "unit" of scope
  const yLimit = settings.verticalScope * 250; // 250px approx per octave/vertical unit

  // Iterate through each origin and generate a local lattice cluster
  generationOrigins.forEach(origin => {
      const originFrac = calculateRatioFromCoords(origin.coords);
      const originKey = origin.coords.join(',');

      // BFS Queue
      const queue: { coords: number[], ratio: Fraction, shell: number }[] = [];
      const visited = new Set<string>();

      queue.push({ coords: origin.coords, ratio: originFrac, shell: 0 });
      visited.add(originKey);

      // We use a high max node count to let the geometric bounds do the culling
      const MAX_LOCAL_NODES = 4000;
      let processedCount = 0;

      // Calculate X/Y for Origin to relativize
      let originX = 0;
      originX += origin.coords[0] * X_VECTORS[3];
      originX += origin.coords[1] * X_VECTORS[5];
      originX += origin.coords[2] * X_VECTORS[7];
      originX += origin.coords[3] * X_VECTORS[11];
      originX += origin.coords[4] * X_VECTORS[13];
      originX = originX * (1.0 / settings.latticeAspectRatio);

      while (queue.length > 0 && processedCount < MAX_LOCAL_NODES) {
        const current = queue.shift()!;
        processedCount++;
        const { coords, ratio, shell } = current;

        // 1. Calculate Spatial Position of this Prime-Space Coordinate
        let rawX = 0;
        rawX += coords[0] * X_VECTORS[3];
        rawX += coords[1] * X_VECTORS[5];
        rawX += coords[2] * X_VECTORS[7];
        rawX += coords[3] * X_VECTORS[11];
        rawX += coords[4] * X_VECTORS[13];
        rawX = rawX * (1.0 / settings.latticeAspectRatio);

        // Check Horizontal Scope (Visual Bounding Box)
        if (Math.abs(rawX - originX) > xLimit) continue;

        // 2. Vertical Expansion (Octaves)
        // We generate octaves around the origin's octave
        // Range is determined by vertical scope
        const octaveRange = Math.ceil(settings.verticalScope); 

        for (let oct = origin.octave - octaveRange; oct <= origin.octave + octaveRange; oct++) {
             // Calculate Y position relative to origin octave
             const PITCH_SCALE = 200;
             // We can approximate Y distance simply by octave difference for culling purposes
             const yDist = Math.abs((oct - origin.octave) * PITCH_SCALE);

             if (yDist > yLimit) continue;

             const shiftedRatio = ratio.shiftOctave(oct);
             const absoluteRatio = shiftedRatio.n / shiftedRatio.d;
             const id = `${coords.join(',')}:${oct}`;

             if (!nodesMap.has(id)) {
                 // Determine Limit for Density Check
                 const limitTop = getMaxPrime(shiftedRatio.n);
                 const limitBottom = getMaxPrime(shiftedRatio.d);
                 const maxPrime = Math.max(limitTop, limitBottom); // Actual mathematical limit

                 // For density tracking, we use the coordinate limit (structural limit) or math limit
                 // The user sliders are for 3, 5, 7, 11, 13.
                 // We treat 1-limit (unison/octaves) as always allowed or grouped with 3.
                 const checkLimit = maxPrime <= 2 ? 3 : maxPrime; 

                 // Density Check
                 const densityKey = `${checkLimit}-${shell}-${oct}`;
                 const currentCount = densityCounts.get(densityKey) || 0;
                 const maxAllowed = settings.limitDensity[checkLimit as 3|5|7|11|13] || 10;

                 if (currentCount < maxAllowed) {
                     densityCounts.set(densityKey, currentCount + 1);

                     const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

                     nodesMap.set(id, {
                        id,
                        coords: coords,
                        ratio: absoluteRatio,
                        n: shiftedRatio.n,
                        d: shiftedRatio.d,
                        label: `${shiftedRatio.n}/${shiftedRatio.d}`,
                        x: rawX,
                        y,
                        limitTop,
                        limitBottom,
                        maxPrime,
                        octave: oct
                     });
                 }
             }
        }

        // 3. Expand BFS
        PRIMES.forEach((prime, idx) => {
          // Use a fixed hard depth limit to prevent infinite loops, 
          // but rely on Scope (visual bounds) for the actual shape.
          const SAFE_HARD_LIMIT = 12; 

          [1, -1].forEach(dir => {
            const nextPos = [...coords];
            nextPos[idx] += dir;

            if (Math.abs(nextPos[idx] - origin.coords[idx]) > SAFE_HARD_LIMIT) return;

            const posKey = nextPos.join(',');

            if (!visited.has(posKey)) {
                visited.add(posKey);

                const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                let nextRatio: Fraction;
                if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
                else {
                    const invRatio = new Fraction(pRat.d, pRat.n);
                    nextRatio = ratio.mul(invRatio).normalize();
                }

                queue.push({ coords: nextPos, ratio: nextRatio, shell: shell + 1 });
            }
          });
        });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      // Harmonic Neighbors (Lateral)
      PRIMES.forEach((prime, idx) => {
          // Visual/Structural check: don't draw lines if density culled the target
          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const coordKey = neighborCoords.join(',');

          const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

          for(let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);

              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / basePrimeRatio;
                  const log2 = Math.log2(test);

                  if (Math.abs(log2 - Math.round(log2)) < 0.001) {
                      lines.push({
                        id: `${node.id}-${target.id}`,
                        x1: node.x,
                        y1: node.y,
                        x2: target.x,
                        y2: target.y,
                        limit: prime,
                        sourceId: node.id,
                        targetId: target.id
                      });
                  }
              }
          }
      });

      // Vertical Octave Connections
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1, 
              sourceId: node.id,
              targetId: octUpNode.id
          });
      }
  });

  return { nodes, lines };
};

import { useState, useEffect } from 'react';
import { AppSettings, SynthPreset } from '../types';
import { DEFAULT_SETTINGS, DEFAULT_PRESET } from '../constants';

// --- STORE EVENT BUS ---
type Listener = () => void;

class PrismaStore {
  private listeners: Set<Listener> = new Set();

  private _settings: AppSettings;
  private _preset: SynthPreset;

  constructor() {
    // Load Settings
    const savedSettingsStr = localStorage.getItem('prismatonal_settings');
    let savedSettings: any = savedSettingsStr ? JSON.parse(savedSettingsStr) : {};

    // MIGRATION: Check if old keys exist (limitDepths) and migrate to new structure
    if (savedSettings.limitDepths) {
        // We just reset to defaults for simplicity when migrating to a new major logic structure
        // to avoid undefined behavior with new Scope logic.
        // Users can re-configure.
        savedSettings = { ...DEFAULT_SETTINGS };
    }

    this._settings = { ...DEFAULT_SETTINGS, ...savedSettings };

    // Safety merge for nested UI Positions and Density
    this._settings.uiPositions = { ...DEFAULT_SETTINGS.uiPositions, ...(this._settings.uiPositions || {}) };
    this._settings.limitDensity = { ...DEFAULT_SETTINGS.limitDensity, ...(this._settings.limitDensity || {}) };

    // Ensure scope exists
    if (!this._settings.horizontalScope) this._settings.horizontalScope = DEFAULT_SETTINGS.horizontalScope;
    if (!this._settings.verticalScope) this._settings.verticalScope = DEFAULT_SETTINGS.verticalScope;

    // Load Preset
    const savedPreset = localStorage.getItem('prismatonal_preset');
    this._preset = savedPreset ? JSON.parse(savedPreset) : DEFAULT_PRESET;
  }

  // --- GETTERS ---
  get settings() { return this._settings; }
  get preset() { return this._preset; }

  // --- ACTIONS ---
  updateSettings(partial: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) {
    if (typeof partial === 'function') {
      this._settings = partial(this._settings);
    } else {
      this._settings = { ...this._settings, ...partial };
    }
    localStorage.setItem('prismatonal_settings', JSON.stringify(this._settings));
    this.notify();
  }

  setPreset(newPreset: SynthPreset) {
    this._preset = newPreset;
    localStorage.setItem('prismatonal_preset', JSON.stringify(this._preset));
    this.notify();
  }

  updatePresetGlobal(key: keyof SynthPreset, value: any) {
    this._preset = { ...this._preset, [key]: value };
    localStorage.setItem('prismatonal_preset', JSON.stringify(this._preset));
    this.notify();
  }

  // --- SUBSCRIPTION ---
  subscribe(listener: Listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const store = new PrismaStore();

// --- REACT HOOK ---
export function useStore() {
  // We use a simple tick to force re-render when store notifies
  const [_, setTick] = useState(0);

  useEffect(() => {
    return store.subscribe(() => setTick(t => t + 1));
  }, []);

  return {
    settings: store.settings,
    preset: store.preset,
    updateSettings: store.updateSettings.bind(store),
    setPreset: store.setPreset.bind(store),
    updatePresetGlobal: store.updatePresetGlobal.bind(store)
  };
}

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  while (b !== 0) {
    let t = b;
    b = a % b;
    a = t;
  }
  return a;
};

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

// Helper to calculate the absolute ratio of a coordinate set starting from 1/1
const calculateRatioFromCoords = (coords: number[]): Fraction => {
    let ratio = new Fraction(1, 1);

    PRIMES.forEach((prime, idx) => {
        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
        const val = coords[idx];
        if (val === 0) return;

        for(let i=0; i < Math.abs(val); i++) {
             if (val > 0) ratio = ratio.mul(pRat).normalize();
             else {
                 const invRatio = new Fraction(pRat.d, pRat.n);
                 ratio = ratio.mul(invRatio).normalize();
             }
        }
    });
    return ratio;
};

export const generateLattice = (settings: AppSettings, generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const nodesMap: Map<string, LatticeNode> = new Map();
  const densityCounts = new Map<string, number>();

  // Scope Definitions
  const MAX_SHELL = Math.max(1, settings.horizontalScope); // Horizontal Scope = BFS Depth
  const OCTAVE_RANGE = Math.max(0, Math.floor(settings.verticalScope)); // Vertical Scope = Octave Range (+/-)

  // Use Set for O(1) lookup of hidden limits
  const hiddenSet = new Set(settings.hiddenLimits);

  generationOrigins.forEach(origin => {
      const originFrac = calculateRatioFromCoords(origin.coords);
      const originKey = origin.coords.join(',');

      // BFS Queue: [Coordinates, Ratio, DistanceFromOrigin]
      const queue: { coords: number[], ratio: Fraction, shell: number }[] = [];
      const visited = new Set<string>();

      queue.push({ coords: origin.coords, ratio: originFrac, shell: 0 });
      visited.add(originKey);

      // Safety Brake
      const MAX_ITERATIONS = 10000;
      let iterations = 0;

      while (queue.length > 0 && iterations < MAX_ITERATIONS) {
        const current = queue.shift()!;
        iterations++;
        const { coords, ratio, shell } = current;

        // 1. Calculate Spatial X (for visualization, not culling anymore)
        let rawX = 0;
        rawX += coords[0] * X_VECTORS[3];
        rawX += coords[1] * X_VECTORS[5];
        rawX += coords[2] * X_VECTORS[7];
        rawX += coords[3] * X_VECTORS[11];
        rawX += coords[4] * X_VECTORS[13];
        rawX = rawX * (1.0 / settings.latticeAspectRatio);

        // 2. Vertical Expansion (Octaves)
        // Generate a "column" of octaves for this valid coordinate
        for (let octOffset = -OCTAVE_RANGE; octOffset <= OCTAVE_RANGE; octOffset++) {
             const oct = origin.octave + octOffset;

             // Calculate Y
             const PITCH_SCALE = 200;
             const shiftedRatio = ratio.shiftOctave(oct);
             const absoluteRatio = shiftedRatio.n / shiftedRatio.d;
             const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

             const id = `${coords.join(',')}:${oct}`;

             if (!nodesMap.has(id)) {
                 const limitTop = getMaxPrime(shiftedRatio.n);
                 const limitBottom = getMaxPrime(shiftedRatio.d);
                 const maxPrime = Math.max(limitTop, limitBottom); 
                 const effectivePrime = maxPrime <= 2 ? 1 : maxPrime;

                 // CRITICAL: Strict Hidden Limit Check
                 if (effectivePrime > 1 && hiddenSet.has(effectivePrime)) {
                     continue; 
                 }

                 // Density Check
                 // We group 1-limit (octaves) with 3-limit for density purposes usually, 
                 // or give them a free pass. Let's give octaves a pass.
                 if (effectivePrime > 1) {
                     const densityKey = `${effectivePrime}-${shell}-${oct}`;
                     const currentCount = densityCounts.get(densityKey) || 0;
                     const maxAllowed = settings.limitDensity[effectivePrime as 3|5|7|11|13] || 10;

                     if (currentCount >= maxAllowed) continue;
                     densityCounts.set(densityKey, currentCount + 1);
                 }

                 nodesMap.set(id, {
                    id,
                    coords: coords,
                    ratio: absoluteRatio,
                    n: shiftedRatio.n,
                    d: shiftedRatio.d,
                    label: `${shiftedRatio.n}/${shiftedRatio.d}`,
                    x: rawX,
                    y,
                    limitTop,
                    limitBottom,
                    maxPrime,
                    octave: oct
                 });
             }
        }

        // 3. Expand BFS (if within Scope)
        if (shell < MAX_SHELL) {
            PRIMES.forEach((prime, idx) => {
                // CRITICAL: Do not traverse dimensions of hidden limits
                if (hiddenSet.has(prime)) return;

                [1, -1].forEach(dir => {
                    const nextPos = [...coords];
                    nextPos[idx] += dir;
                    const posKey = nextPos.join(',');

                    if (!visited.has(posKey)) {
                        visited.add(posKey);

                        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                        let nextRatio: Fraction;
                        if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
                        else {
                            const invRatio = new Fraction(pRat.d, pRat.n);
                            nextRatio = ratio.mul(invRatio).normalize();
                        }

                        // Increment shell distance
                        queue.push({ coords: nextPos, ratio: nextRatio, shell: shell + 1 });
                    }
                });
            });
        }
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  // Create Lines only between existing nodes
  // This implicitly handles hidden limits (if node doesn't exist, no line connects to it)
  nodes.forEach(node => {
      // Harmonic Neighbors (Lateral)
      PRIMES.forEach((prime, idx) => {
          if (hiddenSet.has(prime)) return;

          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const coordKey = neighborCoords.join(',');

          const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

          // Check connections across adjacent octaves to handle spiral effects if visually close,
          // but strictly speaking lattice lines are usually within same octave or direct vertical.
          // For simplicity and cleanliness, we check node.octave +/- 1
          for(let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);

              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / basePrimeRatio;
                  // Allow for floating point variance in ratio check
                  if (Math.abs(Math.log2(test)) < 0.01) { 
                      lines.push({
                        id: `${node.id}-${target.id}`,
                        x1: node.x,
                        y1: node.y,
                        x2: target.x,
                        y2: target.y,
                        limit: prime,
                        sourceId: node.id,
                        targetId: target.id
                      });
                  }
              }
          }
      });

      // Vertical Octave Connections (1-Limit)
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1, 
              sourceId: node.id,
              targetId: octUpNode.id
          });
      }
  });

  // Z-Sort for rendering order
  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  return { nodes, lines };
};

import React, { useRef, useState, useEffect } from 'react';
import { AppSettings, ButtonShape, ChordDefinition } from '../types';
import { DEFAULT_COLORS } from '../constants';
import { midiService, MidiDevice } from '../services/MidiService';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'behavior' | 'color' | 'midi'>('general');
  const [midiDevices, setMidiDevices] = useState<MidiDevice[]>([]);

  // Init MIDI list when opening MIDI tab
  useEffect(() => {
    if (isOpen && activeTab === 'midi') {
        midiService.init().then(success => {
            if (success) {
                setMidiDevices(midiService.getOutputs());
            }
        });
    }
