// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  while (b !== 0) {
    let t = b;
    b = a % b;
    a = t;
  }
  return a;
};

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    // Simplify again to keep numbers clean
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

// X-Axis projection vectors (Harmonic Width)
const X_VECTORS = {
  3: 100,
  5: 30,  
  7: 20,
  11: -20,
  13: -30,
};

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];

  // Standard lattice distance logic
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }

  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }

  return hexDist + otherDist;
};

// Helper to calculate the absolute ratio of a coordinate set starting from 1/1
const calculateRatioFromCoords = (coords: number[]): Fraction => {
    let ratio = new Fraction(1, 1);

    PRIMES.forEach((prime, idx) => {
        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
        const val = coords[idx];
        if (val === 0) return;

        for(let i=0; i < Math.abs(val); i++) {
             if (val > 0) ratio = ratio.mul(pRat).normalize();
             else {
                 const invRatio = new Fraction(pRat.d, pRat.n);
                 ratio = ratio.mul(invRatio).normalize();
             }
        }
    });
    return ratio;
};

export const generateLattice = (settings: AppSettings, generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]): { nodes: LatticeNode[], lines: LatticeLine[] } => {
  const nodesMap: Map<string, LatticeNode> = new Map();
  const densityCounts = new Map<string, number>();

  // Scope Definitions
  const ITERATION_LIMIT = Math.max(1, settings.horizontalScope); // Max iterations per axis
  const OCTAVE_RANGE = Math.max(0, Math.floor(settings.verticalScope)); // Octave Range (+/-)

  // Use Set for O(1) lookup of hidden limits
  const hiddenSet = new Set(settings.hiddenLimits);

  generationOrigins.forEach(origin => {
      const originFrac = calculateRatioFromCoords(origin.coords);
      const originKey = origin.coords.join(',');

      // BFS Queue: [Coordinates, Ratio, ShellDistance]
      // Shell distance is tracked for Density purposes, but not for strict bounding anymore
      const queue: { coords: number[], ratio: Fraction, shell: number }[] = [];
      const visited = new Set<string>();

      queue.push({ coords: origin.coords, ratio: originFrac, shell: 0 });
      visited.add(originKey);

      // Safety Brake (Increased for hypercube generation)
      const MAX_ITERATIONS = 15000;
      let iterations = 0;

      while (queue.length > 0 && iterations < MAX_ITERATIONS) {
        const current = queue.shift()!;
        iterations++;
        const { coords, ratio, shell } = current;

        // 1. Calculate Spatial X (for visualization)
        let rawX = 0;
        rawX += coords[0] * X_VECTORS[3];
        rawX += coords[1] * X_VECTORS[5];
        rawX += coords[2] * X_VECTORS[7];
        rawX += coords[3] * X_VECTORS[11];
        rawX += coords[4] * X_VECTORS[13];
        rawX = rawX * (1.0 / settings.latticeAspectRatio);

        // 2. Vertical Expansion (Octaves)
        // Generate a "column" of octaves for this valid coordinate
        for (let octOffset = -OCTAVE_RANGE; octOffset <= OCTAVE_RANGE; octOffset++) {
             const oct = origin.octave + octOffset;

             // Calculate Y
             const PITCH_SCALE = 200;
             const shiftedRatio = ratio.shiftOctave(oct);
             const absoluteRatio = shiftedRatio.n / shiftedRatio.d;
             const y = -(Math.log2(absoluteRatio) * PITCH_SCALE);

             const id = `${coords.join(',')}:${oct}`;

             if (!nodesMap.has(id)) {
                 const limitTop = getMaxPrime(shiftedRatio.n);
                 const limitBottom = getMaxPrime(shiftedRatio.d);
                 const maxPrime = Math.max(limitTop, limitBottom); 
                 const effectivePrime = maxPrime <= 2 ? 1 : maxPrime;

                 // CRITICAL: Strict Hidden Limit Check - Cull node if it belongs to a hidden limit
                 if (effectivePrime > 1 && hiddenSet.has(effectivePrime)) {
                     continue; 
                 }

                 // Density Check
                 if (effectivePrime > 1) {
                     const densityKey = `${effectivePrime}-${shell}-${oct}`;
                     const currentCount = densityCounts.get(densityKey) || 0;
                     const maxAllowed = settings.limitDensity[effectivePrime as 3|5|7|11|13] || 10;

                     if (currentCount >= maxAllowed) continue;
                     densityCounts.set(densityKey, currentCount + 1);
                 }

                 nodesMap.set(id, {
                    id,
                    coords: coords,
                    ratio: absoluteRatio,
                    n: shiftedRatio.n,
                    d: shiftedRatio.d,
                    label: `${shiftedRatio.n}/${shiftedRatio.d}`,
                    x: rawX,
                    y,
                    limitTop,
                    limitBottom,
                    maxPrime,
                    octave: oct
                 });
             }
        }

        // 3. Expand BFS
        PRIMES.forEach((prime, idx) => {
            // CRITICAL: Do not traverse dimensions of hidden limits
            if (hiddenSet.has(prime)) return;

            [1, -1].forEach(dir => {
                const nextPos = [...coords];
                nextPos[idx] += dir;

                // BOUNDARY CHECK: Coordinate Bound (Iterations per limit)
                // We check if the NEW coordinate on this specific axis exceeds the limit relative to origin
                if (Math.abs(nextPos[idx] - origin.coords[idx]) > ITERATION_LIMIT) return;

                const posKey = nextPos.join(',');

                if (!visited.has(posKey)) {
                    visited.add(posKey);

                    const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                    let nextRatio: Fraction;
                    if (dir === 1) nextRatio = ratio.mul(pRat).normalize();
                    else {
                        const invRatio = new Fraction(pRat.d, pRat.n);
                        nextRatio = ratio.mul(invRatio).normalize();
                    }

                    queue.push({ coords: nextPos, ratio: nextRatio, shell: shell + 1 });
                }
            });
        });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  // Create Lines only between existing nodes
  nodes.forEach(node => {
      // Harmonic Neighbors (Lateral)
      PRIMES.forEach((prime, idx) => {
          if (hiddenSet.has(prime)) return;

          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const coordKey = neighborCoords.join(',');

          const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;

          for(let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);

              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / basePrimeRatio;
                  if (Math.abs(Math.log2(test)) < 0.01) { 
                      lines.push({
                        id: `${node.id}-${target.id}`,
                        x1: node.x,
                        y1: node.y,
                        x2: target.x,
                        y2: target.y,
                        limit: prime,
                        sourceId: node.id,
                        targetId: target.id
                      });
                  }
              }
          }
      });

      // Vertical Octave Connections (1-Limit)
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({
              id: `${node.id}-oct-${node.octave}`,
              x1: node.x,
              y1: node.y,
              x2: octUpNode.x,
              y2: octUpNode.y,
              limit: 1, 
              sourceId: node.id,
              targetId: octUpNode.id
          });
      }
  });

  // Z-Sort for rendering order
  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  return { nodes, lines };
};

import React, { useRef, useState, useEffect } from 'react';
import { AppSettings, ButtonShape, ChordDefinition } from '../types';
import { DEFAULT_COLORS } from '../constants';
import { midiService, MidiDevice } from '../services/MidiService';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'behavior' | 'color' | 'midi'>('general');
  const [midiDevices, setMidiDevices] = useState<MidiDevice[]>([]);

  // Init MIDI list when opening MIDI tab
  useEffect(() => {
    if (isOpen && activeTab === 'midi') {
        midiService.init().then(success => {
            if (success) {
                setMidiDevices(midiService.getOutputs());
            }
        });
    }
  }, [isOpen, activeTab]);

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleScopeChange = (key: 'horizontalScope' | 'verticalScope', val: number) => {
      // Auto-expand canvas based on scope
      // Base size 1000, add 300px per scope unit as coordinate bounds generate wider lattices
      const maxScope = Math.max(
          key === 'horizontalScope' ? val : settings.horizontalScope,
          key === 'verticalScope' ? val : settings.verticalScope
      );

      const newCanvasSize = Math.min(4000, Math.max(1000, 1000 + (maxScope * 300)));

      updateSettings({
          ...settings,
          [key]: val,
          canvasSize: newCanvasSize
      });
  };

  const handleLimitDensityChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitDensity: {
        ...settings.limitDensity,
        [limit]: val
      }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

  const handleLimitVisualChange = (limit: number, key: 'size' | 'opacity', val: number) => {
      const current = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };
      updateSettings({
          ...settings,
          limitVisuals: {
              ...settings.limitVisuals,
              [limit]: { ...current, [key]: val }
          }
      });
  };

  const updateChord = (index: number, field: keyof ChordDefinition, value: any) => {
      const newChords = [...settings.savedChords];
      newChords[index] = { ...newChords[index], [field]: value };
      updateSettings({ ...settings, savedChords: newChords });
  };

  const resetColors = () => {
    updateSettings({ ...settings, colors: { ...DEFAULT_COLORS } });
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const pairLimitColors = () => {
     const ratios: {[key: number]: number} = {
         1: 1,
         3: 1.5,
         5: 1.25,
         7: 7/8,
         11: 11/8,
         13: 13/8
     };

     const newColors = { ...settings.colors };
     const offset = settings.rainbowOffset;

     Object.keys(ratios).forEach(k => {
         const key = parseInt(k);
         const ratio = ratios[key];
         const shift = -Math.log2(ratio) * 360;
         let hue = (offset + shift) % 360;
         if (hue < 0) hue += 360;

         newColors[key] = hslToHex(hue, 70, 60); 
     });

     updateSettings({ ...settings, colors: newColors });
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-[200] flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-800 rounded-xl w-[95%] max-w-4xl max-h-[90vh] overflow-hidden text-slate-200 shadow-2xl border border-slate-700 flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-slate-700 bg-slate-800">
          <h2 className="text-2xl font-bold text-white">Lattice Configuration</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white px-3 py-1 bg-slate-700 rounded transition">Close</button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-700 bg-slate-900/50">
           <button 
             onClick={() => setActiveTab('general')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'general' ? 'text-blue-400 border-b-2 border-blue-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Dimensions
           </button>
           <button 
             onClick={() => setActiveTab('behavior')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'behavior' ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Behavior & Chords
           </button>
           <button 
             onClick={() => setActiveTab('color')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'color' ? 'text-pink-400 border-b-2 border-pink-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Visuals & Color
           </button>
           <button 
             onClick={() => setActiveTab('midi')}
