import { AppSettings, ButtonShape, ChordDefinition } from '../types';
import { DEFAULT_COLORS } from '../constants';
import { midiService, MidiDevice } from '../services/MidiService';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings }) => {
  const [activeTab, setActiveTab] = useState<'general' | 'behavior' | 'color' | 'midi'>('general');
  const [midiDevices, setMidiDevices] = useState<MidiDevice[]>([]);

  // Init MIDI list when opening MIDI tab
  useEffect(() => {
    if (isOpen && activeTab === 'midi') {
        midiService.init().then(success => {
            if (success) {
                setMidiDevices(midiService.getOutputs());
            }
        });
    }
  }, [isOpen, activeTab]);

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleScopeChange = (key: 'horizontalScope' | 'verticalScope', val: number) => {
      // Auto-expand canvas based on scope ONLY if AutoFit is DISABLED
      const updates: Partial<AppSettings> = { [key]: val };

      if (!settings.isAutoFitCanvas) {
        const maxScope = Math.max(
            key === 'horizontalScope' ? val : settings.horizontalScope,
            key === 'verticalScope' ? val : settings.verticalScope
        );

        // Base size 1000, add 300px per scope unit
        const newCanvasSize = Math.min(4000, Math.max(1000, 1000 + (maxScope * 300)));
        updates.canvasSize = newCanvasSize;
      }

      updateSettings({ ...settings, ...updates });
  };

  const handleLimitDensityChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitDensity: {
        ...settings.limitDensity,
        [limit]: val
      }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

  const handleLimitVisualChange = (limit: number, key: 'size' | 'opacity', val: number) => {
      const current = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };
      updateSettings({
          ...settings,
          limitVisuals: {
              ...settings.limitVisuals,
              [limit]: { ...current, [key]: val }
          }
      });
  };

  const updateChord = (index: number, field: keyof ChordDefinition, value: any) => {
      const newChords = [...settings.savedChords];
      newChords[index] = { ...newChords[index], [field]: value };
      updateSettings({ ...settings, savedChords: newChords });
  };

  const resetColors = () => {
    updateSettings({ ...settings, colors: { ...DEFAULT_COLORS } });
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const pairLimitColors = () => {
     const ratios: {[key: number]: number} = {
         1: 1,
         3: 1.5,
         5: 1.25,
         7: 7/8,
         11: 11/8,
         13: 13/8
     };

     const newColors = { ...settings.colors };
     const offset = settings.rainbowOffset;

     Object.keys(ratios).forEach(k => {
         const key = parseInt(k);
         const ratio = ratios[key];
         const shift = -Math.log2(ratio) * 360;
         let hue = (offset + shift) % 360;
         if (hue < 0) hue += 360;

         newColors[key] = hslToHex(hue, 70, 60); 
     });

     updateSettings({ ...settings, colors: newColors });
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-[200] flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-800 rounded-xl w-[95%] max-w-4xl max-h-[90vh] overflow-hidden text-slate-200 shadow-2xl border border-slate-700 flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-slate-700 bg-slate-800">
          <h2 className="text-2xl font-bold text-white">Lattice Configuration</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white px-3 py-1 bg-slate-700 rounded transition">Close</button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-700 bg-slate-900/50">
           <button 
             onClick={() => setActiveTab('general')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'general' ? 'text-blue-400 border-b-2 border-blue-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Dimensions
           </button>
           <button 
             onClick={() => setActiveTab('behavior')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'behavior' ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Behavior & Chords
           </button>
           <button 
             onClick={() => setActiveTab('color')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'color' ? 'text-pink-400 border-b-2 border-pink-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             Visuals & Color
           </button>
           <button 
             onClick={() => setActiveTab('midi')}
             className={`flex-1 py-3 font-semibold transition ${activeTab === 'midi' ? 'text-green-400 border-b-2 border-green-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}
           >
             MIDI
           </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto flex-1 bg-slate-800">

            {/* --- General Tab --- */}
            {activeTab === 'general' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-300">
                  <div className="space-y-6">
                      <h3 className="font-semibold text-blue-400 border-b border-slate-700 pb-1">Lattice Scope</h3>

                      <div>
                          <label className="block text-sm font-semibold mb-2">Base Frequency (1/1)</label>
                          <div className="flex items-center gap-4">
                              <input 
                                  type="range" min="20" max="15000" step="1" 
                                  value={settings.baseFrequency}
                                  onChange={(e) => handleChange('baseFrequency', parseFloat(e.target.value))}
                                  className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                              />
                              <span className="text-sm font-mono min-w-[5ch]">{settings.baseFrequency}Hz</span>
                          </div>
                      </div>

                      <div className="bg-slate-900/40 p-4 rounded border border-slate-700/50 space-y-4">
                          <div>
                              <label className="flex justify-between text-sm font-semibold mb-2">
                                  <span>Horizontal Scope (Iterations)</span>
                                  <span>{settings.horizontalScope}</span>
                              </label>
                              <input 
                                  type="range" min="1" max="12" step="1" 
                                  value={settings.horizontalScope}
                                  onChange={(e) => handleScopeChange('horizontalScope', parseInt(e.target.value))}
                                  className="w-full h-2 bg-blue-600/30 rounded-lg appearance-none cursor-pointer"
                              />
                              <span className="text-[10px] text-slate-500">Max steps allowed from origin for each limit axis</span>
                          </div>

                          <div>
                              <label className="flex justify-between text-sm font-semibold mb-2">
                                  <span>Vertical Scope (Octave Range)</span>
                                  <span>+/- {settings.verticalScope}</span>
                              </label>
                              <input 
                                  type="range" min="0" max="6" step="1" 
                                  value={settings.verticalScope}
                                  onChange={(e) => handleScopeChange('verticalScope', parseInt(e.target.value))}
                                  className="w-full h-2 bg-green-600/30 rounded-lg appearance-none cursor-pointer"
                              />
                              <span className="text-[10px] text-slate-500">Number of octaves above and below center</span>
                          </div>

                          {/* Auto-Fit Controls */}
                          <div className="pt-2 border-t border-slate-700/50 space-y-3">
                              <label className="flex items-center space-x-3 cursor-pointer">
                                  <input 
                                    type="checkbox" 
                                    checked={settings.isAutoFitCanvas} 
                                    onChange={(e) => handleChange('isAutoFitCanvas', e.target.checked)}
                                    className="w-4 h-4 rounded border-slate-600 text-blue-500 focus:ring-blue-500"
                                  />
                                  <div>
                                      <span className="text-xs font-bold text-white block">Auto-Fit Canvas to Screen</span>
                                      <span className="text-[10px] text-slate-400">Dynamically matches canvas size to window size. Disables manual resizing.</span>
                                  </div>
                              </label>

                              <div className={`${settings.isAutoFitCanvas ? 'opacity-50 pointer-events-none' : ''}`}>
                                  <div className="flex justify-between text-[10px] text-slate-400 mb-1">
                                      <span>Manual Canvas Size</span>
                                      <span className="font-mono text-slate-300">{settings.canvasSize}px</span>
                                  </div>
                                  <input 
                                      type="range" min="1000" max="6000" step="100" 
                                      value={settings.canvasSize}
                                      disabled={settings.isAutoFitCanvas}
                                      onChange={(e) => handleChange('canvasSize', parseInt(e.target.value))}
                                      className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer"
                                  />
                              </div>
                          </div>
                      </div>

                       <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3">
                          <label className="block text-sm font-semibold text-slate-300">Node Density</label>
                          <p className="text-[10px] text-slate-500 mb-2">
                              Allowed nodes per octave per shell iteration. Lower values create a "mossy" spread with fewer nodes in dense areas.
                          </p>

                          {[3, 5, 7, 11, 13].map(limit => (
                              <div key={`dens-${limit}`} className="flex items-center gap-3">
                                  <span className="w-16 text-xs font-bold text-slate-400">{limit}-Limit</span>
                                  <input 
                                      type="range" min="1" max="10" step="1" 
                                      value={settings.limitDensity[limit as 3|5|7|11|13]}
                                      onChange={(e) => handleLimitDensityChange(limit as any, parseInt(e.target.value))}
                                      className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                                  />
                                  <span className="text-[10px] font-mono w-4 text-right">{settings.limitDensity[limit as 3|5|7|11|13]}</span>
                              </div>
                          ))}
                      </div>
                  </div>

                  <div className="space-y-6">
                      <h3 className="font-semibold text-blue-400 border-b border-slate-700 pb-1">Display</h3>

                       <div className="mb-4">
                        <label className="flex items-center space-x-3 cursor-pointer p-3 bg-slate-700/50 rounded-lg border border-yellow-500/30 hover:bg-slate-700/80 transition">
                            <input 
                                type="checkbox" 
                                checked={settings.uiUnlocked} 
                                onChange={(e) => handleChange('uiUnlocked', e.target.checked)} 
                                className="w-5 h-5 rounded border-slate-600 text-yellow-500 focus:ring-yellow-500" 
                            />
                            <div>
                                <span className={`font-bold block ${settings.uiUnlocked ? 'text-yellow-400' : 'text-slate-300'}`}>
                                    Unlock UI elements
                                </span>
                                <span className="text-[10px] text-slate-400">Enable dragging of buttons and controls</span>
                            </div>
                        </label>
                       </div>

                      <div>
                          <label className="block text-sm font-semibold mb-2">Global Button Spacing ({settings.buttonSpacingScale.toFixed(1)}x)</label>
                          <input 
                              type="range" min="0.5" max="5.0" step="0.1" 
                              value={settings.buttonSpacingScale}
                              onChange={(e) => handleChange('buttonSpacingScale', parseFloat(e.target.value))}
                              className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                          />
                      </div>
                      <div>
                          <label className="block text-sm mb-1">Global Button Size ({settings.buttonSizeScale.toFixed(1)}x)</label>
                          <input 
                              type="range" min="0.5" max="2.0" step="0.1" 
                              value={settings.buttonSizeScale}
                              onChange={(e) => handleChange('buttonSizeScale', parseFloat(e.target.value))}
                              className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                          />
                      </div>

                      <div className="bg-slate-900/30 p-3 rounded border border-slate-700/50">
                          <label className="block text-xs font-bold text-slate-400 mb-2 uppercase">Node Text</label>
                          <div className="space-y-3">
                              <div>
                                  <label className="flex justify-between text-xs mb-1">
                                      <span>Text Size</span>
                                      <span>{settings.nodeTextSizeScale.toFixed(2)}x</span>
                                  </label>
                                  <input 
                                      type="range" min="0.5" max="2.0" step="0.05" 
                                      value={settings.nodeTextSizeScale}
                                      onChange={(e) => handleChange('nodeTextSizeScale', parseFloat(e.target.value))}
                                      className="w-full h-2 bg-slate-600 rounded-lg appearance-none cursor-pointer"
                                  />
                              </div>
                              <label className="flex items-center space-x-2 cursor-pointer">
                                  <input 
                                    type="checkbox" 
                                    checked={settings.showFractionBar} 
                                    onChange={(e) => handleChange('showFractionBar', e.target.checked)}
                                    className="rounded border-slate-600 bg-slate-700"
                                  />
                                  <span className="text-xs text-slate-300">Show Fraction Bar</span>
                              </label>
                          </div>
                      </div>

                       <div>
                           <label className="block text-sm mb-1">Button Shape</label>
                           <div className="flex gap-2">
                             <button 
                               onClick={() => handleChange('buttonShape', ButtonShape.CIRCLE)}
                               className={`px-3 py-1 rounded ${settings.buttonShape === ButtonShape.CIRCLE ? 'bg-blue-600' : 'bg-slate-700'}`}
                             >Circle</button>
                             <button 
                               onClick={() => handleChange('buttonShape', ButtonShape.DIAMOND)}
                               className={`px-3 py-1 rounded ${settings.buttonShape === ButtonShape.DIAMOND ? 'bg-blue-600' : 'bg-slate-700'}`}
                             >Diamond</button>
                           </div>
                      </div>
                  </div>
              </div>
            )}

            {/* ... Other Tabs remain identical ... */}
            {activeTab === 'behavior' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-300">
                <div className="space-y-6">
                   <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Interactions</h3>

                   <div>
                       <label className="flex items-center space-x-2 mb-2 p-2 bg-slate-900/50 rounded border border-teal-500/30">
                          <input type="checkbox" checked={settings.isLatchModeEnabled} onChange={(e) => handleChange('isLatchModeEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-teal-500 focus:ring-teal-500" />
                          <span className="font-semibold text-teal-300">Latch Mode</span>
                      </label>
                      <div className={`transition-opacity pl-4 border-l-2 border-slate-700 ${settings.isLatchModeEnabled ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                          <label className="block text-xs mb-1 text-slate-400">Harmonic Reach (Latch & Visuals)</label>
                          <div className="flex gap-2 items-center">
                              <input 
                                  type="range" min="1" max="6" step="1" 
                                  value={settings.latchShellLimit}
                                  onChange={(e) => handleChange('latchShellLimit', parseInt(e.target.value))}
                                  className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                              />
                              <span className="text-xs font-mono">{settings.latchShellLimit}</span>
                          </div>
                          <p className="text-[10px] text-slate-500 mt-1">1=Octaves, 2=5th (3), 3=3rd (5), 4=7th...</p>
                      </div>
                  </div>

                  <div>
                    <label className="block text-sm font-semibold mb-2">Polyphony (Voices)</label>
                    <div className="flex items-center gap-4">
                        <input 
                            type="range" min="1" max="20" step="1" 
                            value={settings.polyphony}
                            onChange={(e) => handleChange('polyphony', parseInt(e.target.value))}
                            className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                        <span className="text-xl font-bold min-w-[2ch]">{settings.polyphony}</span>
                    </div>
                  </div>

                  <div className="text-sm">
                     <label className="flex items-center space-x-2 cursor-pointer">
                       <input type="checkbox" checked={settings.isPitchBendEnabled} onChange={(e) => handleChange('isPitchBendEnabled', e.target.checked)} className="w-4 h-4 rounded border-slate-600 text-indigo-500 focus:ring-indigo-500" />
                       <span>Enable Pitch Bend (Drag)</span>
                     </label>
                  </div>
                </div>

                <div className="space-y-6">
                    <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Visual Feedback</h3>

                    <div>
                        <label className="block text-sm font-semibold mb-2">Latched Zoom ({settings.latchedZoomScale.toFixed(1)}x)</label>
                        <input 
                            type="range" min="1.0" max="2.0" step="0.1" 
                            value={settings.latchedZoomScale}
                            onChange={(e) => handleChange('latchedZoomScale', parseFloat(e.target.value))}
                            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>

                    <div>
                        <label className="flex items-center space-x-2 mb-2 p-2 bg-slate-900/50 rounded border border-indigo-500/30">
                            <input type="checkbox" checked={settings.isVoiceLeadingEnabled} onChange={(e) => handleChange('isVoiceLeadingEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500 focus:ring-indigo-500" />
                            <span className="font-semibold text-indigo-300">Voice Leading Lines</span>
                        </label>
                        <div className={`space-y-4 pl-4 border-l-2 border-slate-700 transition-opacity ${settings.isVoiceLeadingEnabled ? 'opacity-100' : 'opacity-50 pointer-events-none'}`}>
                            <div>
                                <label className="flex items-center space-x-2 mb-2">
                                   <input type="checkbox" checked={settings.isVoiceLeadingAnimationEnabled} onChange={(e) => handleChange('isVoiceLeadingAnimationEnabled', e.target.checked)} className="w-4 h-4 rounded border-slate-600" />
                                   <span className="text-xs text-indigo-300">Animate Connections</span>
                                </label>
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                    <label className="flex items-center space-x-2 mb-2 cursor-pointer">
                                       <input type="checkbox" checked={settings.voiceLeadingReverseDir} onChange={(e) => handleChange('voiceLeadingReverseDir', e.target.checked)} className="w-4 h-4 rounded border-slate-600" />
                                       <span className="text-xs text-slate-300">Reverse Direction</span>
                                    </label>
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-xs mb-1 text-slate-400">Glow Width</label>
                                    <input 
                                        type="range" min="0.0" max="1.0" step="0.01" 
                                        value={settings.voiceLeadingGlowAmount}
                                        onChange={(e) => handleChange('voiceLeadingGlowAmount', parseFloat(e.target.value))}
                                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                                    />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-xs mb-1 text-slate-400">Speed</label>
                                    <input 
                                        type="range" min="0.5" max="5.0" step="0.5" 
                                        value={settings.voiceLeadingAnimationSpeed}
                                        onChange={(e) => handleChange('voiceLeadingAnimationSpeed', parseFloat(e.target.value))}
                                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                                    />
                                  </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="col-span-1 md:col-span-2 space-y-4 pt-6 mt-6 border-t border-slate-700">
                    <h3 className="font-semibold text-green-400 border-b border-slate-700 pb-1">Chords Configuration</h3>

                    <div className="flex gap-4">
                        <div className="flex-1">
                            <label className="block text-sm font-semibold mb-2">Chord Shortcut Size ({settings.chordShortcutSizeScale.toFixed(2)}x)</label>
                            <input 
                                type="range" min="0.33" max="1.0" step="0.01" 
                                value={settings.chordShortcutSizeScale}
                                onChange={(e) => handleChange('chordShortcutSizeScale', parseFloat(e.target.value))}
                                className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                            />
                        </div>
                        <div className="flex-1 flex flex-col justify-end space-y-2">
                            <label className="flex items-center space-x-2 cursor-pointer">
                               <input type="checkbox" checked={settings.chordsAlwaysRelatch} onChange={(e) => handleChange('chordsAlwaysRelatch', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-green-500 focus:ring-green-500" />
                               <span className="text-sm font-semibold text-slate-300">Chords always relatch all notes</span>
                            </label>
                        </div>
                    </div>

                    <div className="bg-slate-900/50 rounded-lg border border-slate-700 overflow-hidden">
                        <div className="grid grid-cols-[40px_40px_60px_100px_1fr] gap-2 p-2 bg-slate-800 text-xs font-bold text-slate-400 border-b border-slate-700">
                            <div className="text-center">Slot</div>
                            <div className="text-center">Show</div>
                            <div className="text-center">Color</div>
                            <div>Label</div>
                            <div>Nodes (Ratios)</div>
                        </div>
                        <div className="max-h-64 overflow-y-auto">
                            {settings.savedChords.map((chord, index) => (
                                <div key={chord.id} className="grid grid-cols-[40px_40px_60px_100px_1fr] gap-2 p-2 border-b border-slate-700/50 items-center hover:bg-slate-800/50 transition-colors">
                                    <div className="text-center font-mono font-bold text-slate-500">{chord.id}</div>
                                    <div className="text-center">
                                        <input 
                                            type="checkbox" 
                                            checked={chord.visible} 
                                            onChange={(e) => updateChord(index, 'visible', e.target.checked)}
                                            className="rounded border-slate-600 bg-slate-700 text-blue-500"
                                        />
                                    </div>
                                    <div className="flex justify-center">
                                        <input 
                                            type="color" 
                                            value={chord.color} 
                                            onChange={(e) => updateChord(index, 'color', e.target.value)}
                                            className="w-6 h-6 rounded cursor-pointer bg-transparent border-none"
                                        />
                                    </div>
                                    <div>
                                        <input 
                                            type="text" 
                                            value={chord.label} 
                                            onChange={(e) => updateChord(index, 'label', e.target.value)}
                                            className="w-full bg-transparent border-b border-slate-600 focus:border-blue-500 outline-none text-xs"
                                        />
                                    </div>
                                    <div className="text-xs text-slate-400 font-mono truncate">
                                        {chord.nodes.length > 0 
                                            ? chord.nodes.map(n => `${n.n}/${n.d}`).join(', ') 
                                            : <span className="text-slate-600 italic">Empty</span>
                                        }
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

              </div>
            )}

            {/* ... Color and MIDI Tabs same as before ... */}
            {activeTab === 'color' && (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-300">
                  <div className="space-y-6">
                      <h3 className="font-semibold text-pink-400 border-b border-slate-700 pb-1">Limit Appearance</h3>
                      {/* ... content ... */}
                      <div className="space-y-4">
                        {[1, 3, 5, 7, 11, 13].map(limit => {
                           const currentVis = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };
                           return (
                               <div key={limit} className="bg-slate-900/40 p-3 rounded flex flex-col gap-2">
                                 <div className="flex justify-between items-center">
                                     <div className="flex items-center gap-3">
                                         <input 
                                           type="color" 
                                           value={settings.colors[limit]} 
                                           onChange={(e) => handleColorChange(limit, e.target.value)}
                                           className="w-6 h-6 rounded cursor-pointer bg-transparent border-none"
                                         />
                                         <span className="text-sm font-bold">{limit}-Limit</span>
                                     </div>
                                 </div>

                                 <div className="grid grid-cols-2 gap-4">
                                     <div>
                                         <label className="flex justify-between text-xs text-slate-400 mb-1">
                                             <span>Size</span> <span>{currentVis.size.toFixed(2)}x</span>
                                         </label>
                                         <input 
                                             type="range" min="0.1" max="1.5" step="0.05"
                                             value={currentVis.size}
                                             onChange={(e) => handleLimitVisualChange(limit, 'size', parseFloat(e.target.value))}
                                             className="w-full h-1 bg-slate-600 rounded appearance-none"
                                         />
                                     </div>
                                     <div>
                                         <label className="flex justify-between text-xs text-slate-400 mb-1">
                                             <span>Opacity</span> <span>{(currentVis.opacity * 100).toFixed(0)}%</span>
                                         </label>
                                         <input 
                                             type="range" min="0.0" max="1.0" step="0.05"
                                             value={currentVis.opacity}
                                             onChange={(e) => handleLimitVisualChange(limit, 'opacity', parseFloat(e.target.value))}
                                             className="w-full h-1 bg-slate-600 rounded appearance-none"
                                         />
                                     </div>
                                 </div>
                               </div>
                           );
                        })}
                      </div>
                  </div>

                  <div className="space-y-6">
                      <h3 className="font-semibold text-pink-400 border-b border-slate-700 pb-1">Rainbow Mode</h3>

                      <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700">
                        <label className="flex items-center space-x-3 mb-4 cursor-pointer">
                            <input type="checkbox" checked={settings.isRainbowModeEnabled} onChange={(e) => handleChange('isRainbowModeEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-pink-500 focus:ring-pink-500" />
                            <span className="font-bold text-white">Enable Rainbow Background</span>
                        </label>

                        <div className={`space-y-4 ${settings.isRainbowModeEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none'} transition-opacity`}>
                            <div>
                                <label className="flex justify-between text-xs text-slate-400 mb-1">
                                    <span>Background Brightness</span>
                                    <span>{settings.rainbowBrightness}%</span>
                                </label>
                                <input 
                                    type="range" min="0" max="100" 
                                    value={settings.rainbowBrightness}
                                    onChange={(e) => handleChange('rainbowBrightness', parseInt(e.target.value))}
                                    className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer"
                                />
                            </div>
                            <div>
                                <label className="flex justify-between text-xs text-slate-400 mb-1">
                                    <span>Background Saturation</span>
                                    <span>{settings.rainbowSaturation}%</span>
                                </label>
                                <input 
                                    type="range" min="0" max="100" 
                                    value={settings.rainbowSaturation}
                                    onChange={(e) => handleChange('rainbowSaturation', parseInt(e.target.value))}
                                    className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer"
                                />
                            </div>
                            <div>
                                <label className="flex justify-between text-xs text-slate-400 mb-1">
                                    <span>Vertical Offset (Hue Shift)</span>
                                    <span>{settings.rainbowOffset}°</span>
                                </label>
                                <input 
                                    type="range" min="0" max="360" 
                                    value={settings.rainbowOffset}
                                    onChange={(e) => handleChange('rainbowOffset', parseInt(e.target.value))}
                                    className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer"
                                    style={{
                                        backgroundImage: 'linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)'
                                    }}
                                />
                            </div>
                        </div>
                      </div>

                       <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700 space-y-3">
                         <label className="flex items-center space-x-3 cursor-pointer">
                            <input type="checkbox" checked={settings.isColoredIlluminationEnabled} onChange={(e) => handleChange('isColoredIlluminationEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-pink-500 focus:ring-pink-500" />
                            <div>
                                <span className="font-bold text-white block">Colored Illumination</span>
                                <span className="text-xs text-slate-400">Node outline uses pitch-rainbow color when latched</span>
                            </div>
                        </label>

                        <button 
                            onClick={resetColors}
                            className="w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-xs font-bold text-white transition-colors border border-slate-500/50 mb-2"
                        >
                            Default Colors
                        </button>

                        <button 
                            onClick={pairLimitColors}
                            className="w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-xs font-bold text-white transition-colors border border-slate-500/50"
                        >
                            Pair Limit Colors with Background
                        </button>
                        <p className="text-[10px] text-slate-400 mt-1">Updates Limit Colors to match the background hue at 1/1, 3/2, 5/4, etc.</p>
                       </div>

                  </div>
               </div>
            )}

            {/* ... Midi Tab ... */}
             {activeTab === 'midi' && (
                <div className="space-y-8 animate-in fade-in duration-300">
                    <div className="space-y-6">
                        <h3 className="font-semibold text-green-400 border-b border-slate-700 pb-1">MIDI Configuration</h3>

                        <div className="p-4 bg-slate-900/50 rounded-lg border border-slate-700 space-y-4">
                            <label className="flex items-center space-x-3 cursor-pointer">
                                <input 
                                    type="checkbox" 
                                    checked={settings.midiEnabled} 
                                    onChange={(e) => handleChange('midiEnabled', e.target.checked)} 
                                    className="w-6 h-6 rounded border-slate-600 text-green-500 focus:ring-green-500" 
                                />
                                <div>
                                    <span className={`font-bold block ${settings.midiEnabled ? 'text-green-400' : 'text-slate-300'}`}>
                                        Enable MIDI Output
                                    </span>
                                    <span className="text-xs text-slate-400">Send notes to external synths/DAW</span>
                                </div>
                            </label>

                            <div className={`${settings.midiEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none'} transition-opacity space-y-4`}>
                                <div>
                                    <label className="block text-sm font-semibold mb-2">Output Device</label>
                                    <select 
                                        value={settings.midiOutputId || ''}
                                        onChange={(e) => {
                                            const id = e.target.value || null;
                                            handleChange('midiOutputId', id);
                                            midiService.setOutput(id);
                                        }}
                                        className="w-full bg-slate-700 border border-slate-600 rounded p-2 text-white"
                                    >
                                        <option value="">Select MIDI Output...</option>
                                        {midiDevices.map(device => (
                                            <option key={device.id} value={device.id}>{device.name}</option>
                                        ))}
                                    </select>
                                    {midiDevices.length === 0 && (
                                        <p className="text-[10px] text-orange-400 mt-1">No MIDI devices found. Check connection or browser permissions.</p>
                                    )}
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold mb-2">Pitch Bend Range (+/- Semitones)</label>
                                    <p className="text-[10px] text-slate-400 mb-2">
                                        Must match the setting on your external synth for accurate microtonality.
                                        MPE Synths usually default to 48 or 24.
                                    </p>
                                    <div className="flex gap-2">
                                        {[2, 12, 24, 48].map(range => (
                                            <button 
                                                key={range}
                                                onClick={() => handleChange('midiPitchBendRange', range)}
                                                className={`px-3 py-1 rounded text-xs font-bold border ${settings.midiPitchBendRange === range ? 'bg-green-600 border-green-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}
                                            >
                                                {range}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-4 bg-blue-900/20 rounded-lg border border-blue-700/30">
                             <h4 className="text-sm font-bold text-blue-300 mb-2">How it works (MPE Style)</h4>
                             <p className="text-xs text-slate-300 leading-relaxed">
                                PrismaTonal rotates through MIDI Channels 1-16 for every new note trigger. 
                                This allows each touch to have its own independent Pitch Bend message, enabling true polyphonic microtonality.
                                <br/><br/>
                                Ensure your external synth is in <strong>MPE Mode</strong> or set to <strong>Multi-Channel</strong> mode with the same patch loaded on all channels.
                             </p>
                        </div>
                    </div>
                </div>
            )}

        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine'; // Import singleton
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos } from './types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from './constants';

const App: React.FC = () => {
  const { settings, preset, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Audio Warmup: Pre-initialize audio context on any user interaction
  useEffect(() => {
    const warmup = () => {
        audioEngine.init();

        // Remove listeners once warmed up
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };
  }, []);

  // Sanitize UI Positions on Load to prevent off-screen elements
  // Also enforce initial Auto-Fit Canvas size
  useEffect(() => {
      const w = window.innerWidth;
      const h = window.innerHeight;

      updateSettings(prev => {
          const updates: Partial<AppSettings> = {};

          // 1. Check Auto-Fit
          if (prev.isAutoFitCanvas) {
             updates.canvasSize = Math.max(w, h);
          }

          // 2. Fix UI Positions
          const p = { ...prev.uiPositions };
          let changed = false;

          // Helper to check and clamp
          const checkAndFix = (key: keyof typeof p, width: number, height: number) => {
              let x = p[key].x;
              let y = p[key].y;

              const maxX = w - width - MARGIN_3MM;
              const maxY = h - height - MARGIN_3MM;
              const minX = MARGIN_3MM;
              const minY = MARGIN_3MM;

              // Clamp if out of bounds
              if (x > maxX) { x = maxX; changed = true; }
              if (x < minX) { x = minX; changed = true; }
              if (y > maxY) { y = maxY; changed = true; }
              if (y < minY) { y = minY; changed = true; }

              p[key] = { x, y };
          };

          checkAndFix('volume', 160, 40);
          checkAndFix('panic', 80, 80);
          checkAndFix('off', 80, 80);
          checkAndFix('center', 48, 48);
          checkAndFix('depth', 48, 48);
          checkAndFix('decreaseDepth', 48, 48);
          checkAndFix('chords', 300, 48); 
          checkAndFix('layers', 90, 310);

          if (changed) updates.uiPositions = p;

          return Object.keys(updates).length > 0 ? { ...prev, ...updates } : prev;
      });
  }, []); 

  // Resize Handler to snap UI elements to their anchors AND handle auto-canvas size
  const windowSize = useRef({ w: window.innerWidth, h: window.innerHeight });

  useEffect(() => {
    const handleResize = () => {
      const newW = window.innerWidth;
      const newH = window.innerHeight;
      const oldW = windowSize.current.w;
      const oldH = windowSize.current.h;

      updateSettings(prev => {
        const p = prev.uiPositions;
        const newPos = { ...p };

        // 1. Update UI Anchors
        newPos.panic = {
            x: newW - (oldW - p.panic.x),
            y: newH - (oldH - p.panic.y)
        };

        newPos.off = {
            x: newW - (oldW - p.off.x),
            y: newH - (oldH - p.off.y)
        };

        const volOffsetFromCenter = p.volume.x - (oldW / 2);
        newPos.volume = {
            x: (newW / 2) + volOffsetFromCenter,
            y: p.volume.y 
        };

        const updateBottomLeft = (key: 'center' | 'depth' | 'decreaseDepth' | 'chords') => {
             newPos[key] = {
                 x: p[key].x, 
                 y: newH - (oldH - p[key].y)
             };
        };
        updateBottomLeft('center');
        updateBottomLeft('depth');
        updateBottomLeft('decreaseDepth');
        updateBottomLeft('chords');

        newPos.layers = {
            x: newW - (oldW - p.layers.x),
            y: p.layers.y * (newH / oldH)
        };

        const updates: Partial<AppSettings> = { uiPositions: newPos };

        // 2. Handle Auto-Fit Canvas
        if (prev.isAutoFitCanvas) {
            updates.canvasSize = Math.max(newW, newH);
        }

        return { ...prev, ...updates };
      });

      windowSize.current = { w: newW, h: newH };
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [updateSettings]);

  // Init Engine updates
  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
  };

  const handleCenter = () => {
      diamondRef.current?.centerView();
  };

  const handleIncreaseDepth = () => {
      diamondRef.current?.increaseDepth();
  };

  const handleDecreaseDepth = () => {
      diamondRef.current?.decreaseDepth();
  };

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) {
               slotIndex = settings.savedChords.findIndex(c => !c.visible);
          }

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({
                  id: n.id,
                  n: n.n,
                  d: n.d
              }));

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };

              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => {
          if (prev.includes(id)) {
              return prev.filter(c => c !== id);
          } else {
              return [...prev, id];
          }
      });
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({
          ...prev,
          uiPositions: {
              ...prev.uiPositions,
              [key]: pos
          }
      }));
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Bar - Fixed Position */}
      <div 
        className="absolute w-full flex justify-between items-center z-40 pointer-events-none"
        style={{ 
            top: `${MARGIN_3MM}px`, 
            paddingLeft: `${MARGIN_3MM}px`,
            paddingRight: `${MARGIN_3MM + SCROLLBAR_WIDTH}px` 
        }}
      >
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Synth
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Settings
          </button>
        </div>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings} 
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
      />

      {/* Floating UI */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        onPanic={handlePanic}
        onOff={handleOff}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth}
        onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord}
        toggleChord={toggleChord}
        activeChordIds={activeChordIds}
        savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions}
        updatePosition={handleUiPositionUpdate}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={updateSettings}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={updateSettings}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        preset={preset}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface LimitVisualSetting {
    size: number;   // 0.1 to 2.0 (Multiplier of base size)
    opacity: number; // 0.0 to 1.0
}

export interface LimitVisualsMap {
    [key: number]: LimitVisualSetting;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface XYPos {
  x: number;
  y: number;
}

export interface AppSettings {
  // Scope Settings
  horizontalScope: number;
  verticalScope: number;

  // Density Settings (Nodes per shell per octave)
  limitDensity: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  isLatchModeEnabled: boolean;
  latchShellLimit: number; // 1 = Octaves, 2 = Fifths, etc.
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)

  isAutoFitCanvas: boolean; // New: Automatically size canvas to viewport
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)

  buttonShape: ButtonShape;
  colors: LimitColorMap;

  // Per-Limit Visuals (Size/Opacity)
  limitVisuals: LimitVisualsMap;

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // UI Relocation
  uiUnlocked: boolean;
  uiPositions: {
    volume: XYPos;
    panic: XYPos;
    off: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export interface SynthPreset {
  id: number;
  name: string;

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Effects (Global)
  reverbMix: number; // 0 to 1
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

