                                 <input type="range" min="0.01" max="1.0" step="0.01" value={preset.compressorRelease} onChange={(e) => updateGlobal('compressorRelease', parseFloat(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" />
